def _ptd_reject(reason):
    global _ptd_last_rejection
    _ptd_last_rejection = str(reason)
    return None


def _ptd_reset(reason=None):
    global _ptd_transaction, _ptd_last_rejection
    _ptd_transaction = None
    if reason is not None:
        _ptd_last_rejection = str(reason)


def _ptd_norm(value):
    text = "" if value is None else str(value)
    text = (
        text.replace("\u2019", "'")
        .replace("\u2018", "'")
        .replace("\u00e9", "e")
        .replace("\u00c9", "e")
    )
    return " ".join(text.strip().lower().split())


def _ptd_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _ptd_serial(value):
    serial = getattr(value, "serial", None)
    return serial if isinstance(serial, int) and serial > 0 else None


def _ptd_card_ref(card):
    if card is None:
        return None
    return (getattr(card, "id", None), _ptd_serial(card))


def _ptd_skill_key(skill):
    return (
        _ptd_norm(getattr(skill, "name", None)),
        _ptd_norm(getattr(skill, "text", None)),
    )


def _ptd_attack_key(attack):
    if attack is None:
        return None
    damage = getattr(attack, "damage", None)
    energies = getattr(attack, "energies", None)
    if (
        not isinstance(damage, int)
        or damage < 0
        or not isinstance(energies, (list, tuple))
        or any(_ptd_int(value) not in range(10) for value in energies)
    ):
        return None
    return (
        _ptd_norm(getattr(attack, "name", None)),
        _ptd_norm(getattr(attack, "text", None)),
        damage,
        tuple(_ptd_int(value) for value in energies),
    )


def _ptd_own_attack_mode(attack_id):
    attack = ALL_ATTACKS.get(attack_id)
    expected = _PTD_OWN_ATTACKS.get(attack_id)
    if attack is None or expected is None:
        return None
    key = _ptd_attack_key(attack)
    if key != expected[:4]:
        return None
    return expected[4]


def _ptd_opponent_attack_mode(attack_id):
    return _PTD_OPPONENT_ATTACKS.get(
        _ptd_attack_key(ALL_ATTACKS.get(attack_id))
    )


def _ptd_stage_signature(data):
    return (
        _ptd_norm(getattr(data, "name", None)),
        getattr(data, "hp", None),
        getattr(data, "retreatCost", None),
        _ptd_int(getattr(data, "energyType", None)),
        bool(getattr(data, "basic", False)),
        bool(getattr(data, "stage1", False)),
        bool(getattr(data, "stage2", False)),
        bool(getattr(data, "ex", False)),
        bool(getattr(data, "megaEx", False)),
        (
            None
            if getattr(data, "evolvesFrom", None) is None
            else _ptd_norm(getattr(data, "evolvesFrom", None))
        ),
        _ptd_int(getattr(data, "weakness", None)),
        _ptd_int(getattr(data, "resistance", None)),
        tuple(getattr(data, "attacks", None) or ()),
    )


def _ptd_skill_modes(data):
    modes = []
    for skill in tuple(getattr(data, "skills", None) or ()):
        key = _ptd_skill_key(skill)
        if key == (_PTD_RUN_AWAY_NAME, _PTD_RUN_AWAY_TEXT):
            modes.append(("SELF_RETURN_ALL_ATTACHED_AFTER_DRAW", 3))
        elif key in _PTD_PSYCHIC_DRAW:
            modes.append(("EVOLUTION_DRAW", _PTD_PSYCHIC_DRAW[key]))
        elif key in _PTD_OWN_SKILLS:
            modes.append((_PTD_OWN_SKILLS[key], 0))
        else:
            return None
    return tuple(modes)


def _ptd_pokemon_data_supported(data, allow_own=False):
    if data is None:
        return False
    card_id = getattr(data, "cardId", None)
    stage_count = sum(
        bool(getattr(data, name, False))
        for name in ("basic", "stage1", "stage2")
    )
    if (
        getattr(data, "cardType", None) != 0
        or not isinstance(getattr(data, "name", None), str)
        or not getattr(data, "name", "").strip()
        or not isinstance(getattr(data, "hp", None), int)
        or data.hp <= 0
        or not isinstance(getattr(data, "retreatCost", None), int)
        or data.retreatCost < 0
        or stage_count != 1
        or not isinstance(getattr(data, "ex", None), bool)
        or not isinstance(getattr(data, "megaEx", None), bool)
        or not isinstance(getattr(data, "tera", None), bool)
        or (data.ex and data.megaEx)
        or _ptd_int(getattr(data, "energyType", None)) not in range(10)
        or (
            _ptd_int(getattr(data, "weakness", None)) is not None
            and _ptd_int(getattr(data, "weakness", None)) not in range(1, 10)
        )
        or (
            _ptd_int(getattr(data, "resistance", None)) is not None
            and _ptd_int(getattr(data, "resistance", None)) not in range(1, 10)
        )
        or _ptd_skill_modes(data) is None
    ):
        return False
    if bool(data.basic) != (getattr(data, "evolvesFrom", None) is None):
        return False
    attack_ids = tuple(getattr(data, "attacks", None) or ())
    if not attack_ids:
        return False
    if allow_own and card_id in _PTD_OWN_CARD_ATTACK:
        if set(attack_ids) != _PTD_OWN_CARD_ATTACK[card_id]:
            return False
        return all(_ptd_own_attack_mode(attack_id) for attack_id in attack_ids)
    if any(
        attack_id not in ALL_ATTACKS
        or _ptd_opponent_attack_mode(attack_id) is None
        for attack_id in attack_ids
    ):
        return False
    expected = _PTD_REQUIRED_CARD_SIGNATURES.get(card_id)
    return expected is None or _ptd_stage_signature(data) == expected


def _ptd_metadata_row(data):
    if data is None:
        return None
    attacks = []
    for attack_id in tuple(getattr(data, "attacks", None) or ()):
        key = _ptd_attack_key(ALL_ATTACKS.get(attack_id))
        if key is None:
            return None
        attacks.append((attack_id, key))
    return (
        getattr(data, "cardId", None),
        _ptd_norm(getattr(data, "name", None)),
        getattr(data, "cardType", None),
        getattr(data, "retreatCost", None),
        getattr(data, "hp", None),
        _ptd_int(getattr(data, "weakness", None)),
        _ptd_int(getattr(data, "resistance", None)),
        _ptd_int(getattr(data, "energyType", None)),
        bool(getattr(data, "basic", False)),
        bool(getattr(data, "stage1", False)),
        bool(getattr(data, "stage2", False)),
        bool(getattr(data, "ex", False)),
        bool(getattr(data, "megaEx", False)),
        bool(getattr(data, "tera", False)),
        bool(getattr(data, "aceSpec", False)),
        _ptd_norm(getattr(data, "evolvesFrom", None)),
        tuple(_ptd_skill_key(skill) for skill in (data.skills or ())),
        tuple(attacks),
    )


def _ptd_metadata_digest(card_id):
    row = _ptd_metadata_row(CARD_DB.get(card_id))
    return None if row is None else _cum_digest(row)


def _ptd_exact_trainer(card_id, name, skill_text, ace_spec=False):
    data = CARD_DB.get(card_id)
    if data is None:
        return False
    skills = tuple(getattr(data, "skills", None) or ())
    return (
        _ptd_norm(getattr(data, "name", None)) == _ptd_norm(name)
        and bool(getattr(data, "aceSpec", False)) is bool(ace_spec)
        and len(skills) == 1
        and _ptd_norm(getattr(skills[0], "text", None))
        == _ptd_norm(skill_text)
    )


def _ptd_stadium_supported(obs):
    stadium = tuple(obs.current.stadium or ())
    if len(stadium) > 1:
        return False
    if not stadium:
        return True
    return (
        _ptd_serial(stadium[0]) is not None
        and stadium[0].id == FULL_METAL_LAB
        and _ptd_exact_trainer(
            FULL_METAL_LAB,
            "Full Metal Lab",
            (
                "{M} Pokemon (both yours and your opponent's) take 30 less "
                "damage from attacks from the opponent's Pokemon (after "
                "applying Weakness and Resistance)."
            ),
        )
    )


def _ptd_tool_supported(tool):
    return (
        tool is not None
        and _ptd_serial(tool) is not None
        and tool.id == HERO_CAPE
        and _ptd_exact_trainer(
            HERO_CAPE,
            "Hero's Cape",
            "The Pokemon this card is attached to gets +100 HP.",
            ace_spec=True,
        )
    )


def _ptd_basic_energy_supported(card, energy_type):
    data = CARD_DB.get(getattr(card, "id", None))
    return (
        card is not None
        and _ptd_serial(card) is not None
        and data is not None
        and getattr(data, "cardType", None) == 5
        and _ptd_norm(getattr(data, "name", None)).startswith("basic ")
        and not tuple(getattr(data, "skills", None) or ())
        and not tuple(getattr(data, "attacks", None) or ())
        and _ptd_int(getattr(data, "energyType", None)) == _ptd_int(energy_type)
    )


def _ptd_pokemon_fp(pokemon):
    if pokemon is None:
        return None
    return (
        pokemon.id,
        _ptd_serial(pokemon),
        pokemon.hp,
        getattr(pokemon, "maxHp", None),
        bool(getattr(pokemon, "appearThisTurn", False)),
        tuple(_ptd_int(value) for value in (pokemon.energies or ())),
        tuple(_ptd_card_ref(card) for card in (pokemon.energyCards or ())),
        tuple(_ptd_card_ref(card) for card in (pokemon.tools or ())),
        tuple(_ptd_card_ref(card) for card in (pokemon.preEvolution or ())),
    )


def _ptd_pokemon_supported(pokemon, allow_own=False):
    data = CARD_DB.get(getattr(pokemon, "id", None))
    tools = tuple(getattr(pokemon, "tools", None) or ())
    energies = tuple(getattr(pokemon, "energies", None) or ())
    energy_cards = tuple(getattr(pokemon, "energyCards", None) or ())
    expected_max_hp = (
        getattr(data, "hp", None)
        + 100 * sum(1 for tool in tools if getattr(tool, "id", None) == HERO_CAPE)
        if data is not None
        else None
    )
    return (
        pokemon is not None
        and _ptd_serial(pokemon) is not None
        and _ptd_pokemon_data_supported(data, allow_own=allow_own)
        and isinstance(pokemon.hp, int)
        and isinstance(getattr(pokemon, "maxHp", None), int)
        and 0 < pokemon.hp <= pokemon.maxHp
        and pokemon.maxHp == expected_max_hp
        and all(_ptd_tool_supported(tool) for tool in tools)
        and len(energies) == len(energy_cards)
        and all(
            _ptd_basic_energy_supported(card, energy_type)
            for card, energy_type in zip(energy_cards, energies)
        )
        and all(
            _ptd_serial(card) is not None
            for card in (getattr(pokemon, "preEvolution", None) or ())
        )
    )


def _ptd_board(player):
    return tuple(
        pokemon
        for pokemon in (
            tuple(player.active or ()) + tuple(player.bench or ())
        )
        if pokemon is not None
    )


def _ptd_board_fp(player):
    return tuple(sorted((_ptd_pokemon_fp(p) for p in _ptd_board(player)), key=repr))


def _ptd_conditions(player):
    values = tuple(
        getattr(player, name, None)
        for name in ("poisoned", "burned", "asleep", "paralyzed", "confused")
    )
    return values if all(isinstance(value, bool) for value in values) else None


def _ptd_card_multiset(cards):
    return tuple(sorted((_ptd_card_ref(card) for card in (cards or ())), key=repr))


def _ptd_prize_fp(prizes):
    return tuple(_ptd_card_ref(card) for card in (prizes or ()))


def _ptd_public_serials(obs):
    values = []
    for player in obs.current.players:
        for pokemon in _ptd_board(player):
            values.append(_ptd_serial(pokemon))
            values.extend(_ptd_serial(card) for card in (pokemon.energyCards or ()))
            values.extend(_ptd_serial(card) for card in (pokemon.tools or ()))
            values.extend(_ptd_serial(card) for card in (pokemon.preEvolution or ()))
        values.extend(_ptd_serial(card) for card in (player.discard or ()))
        if player.hand is not None:
            values.extend(_ptd_serial(card) for card in player.hand)
        values.extend(
            _ptd_serial(card) for card in (player.prize or ()) if card is not None
        )
    values.extend(_ptd_serial(card) for card in (obs.current.stadium or ()))
    return (
        None
        if any(serial is None for serial in values)
        or len(values) != len(set(values))
        else tuple(sorted(values))
    )


def _ptd_prize_value(pokemon):
    data = CARD_DB.get(getattr(pokemon, "id", None))
    if data is None or data.ex and data.megaEx:
        return None
    if bool(getattr(data, "megaEx", False)):
        return 3
    if bool(getattr(data, "ex", False)):
        return 2
    return 1


def _ptd_attack_payment(pokemon, attack_id):
    attack = ALL_ATTACKS.get(attack_id)
    if attack is None:
        return None
    costs = tuple(_ptd_int(value) for value in (attack.energies or ()))
    available = [
        (
            _ptd_int(energy_type),
            card.id,
            _ptd_serial(card),
        )
        for energy_type, card in zip(
            tuple(pokemon.energies or ()),
            tuple(pokemon.energyCards or ()),
        )
    ]
    selected = []
    for required in sorted(value for value in costs if value != 0):
        match = next(
            (
                index
                for index, row in enumerate(available)
                if row[0] == required
            ),
            None,
        )
        if match is None:
            return None
        selected.append(available.pop(match))
    colorless = sum(1 for value in costs if value == 0)
    if len(available) < colorless:
        return None
    selected.extend(available[:colorless])
    return tuple(sorted(selected))


def _ptd_reachable_payment(pokemon, attack_id):
    attack = ALL_ATTACKS.get(attack_id)
    if attack is None:
        return False
    costs = list(_ptd_int(value) for value in (attack.energies or ()))
    available = list(_ptd_int(value) for value in (pokemon.energies or ()))
    missing = 0
    for required in sorted(value for value in costs if value != 0):
        match = next(
            (index for index, value in enumerate(available) if value == required),
            None,
        )
        if match is None:
            missing += 1
        else:
            available.pop(match)
    colorless = sum(1 for value in costs if value == 0)
    missing += max(0, colorless - len(available))
    return missing <= 1


def _ptd_exact_own_damage(obs, attacker, attack_id, target):
    mode = _ptd_own_attack_mode(attack_id)
    attacker_data = CARD_DB.get(getattr(attacker, "id", None))
    target_data = CARD_DB.get(getattr(target, "id", None))
    if (
        mode is None
        or attacker_data is None
        or target_data is None
        or attack_id not in tuple(getattr(attacker_data, "attacks", None) or ())
        or not _ptd_pokemon_supported(attacker, allow_own=True)
        or not _ptd_pokemon_supported(target)
        or not _ptd_stadium_supported(obs)
    ):
        return None
    if mode == "RAGING_HAMMER":
        taken = attacker.maxHp - attacker.hp
        if taken < 0 or taken % 10:
            return None
        base = 80 + taken
    else:
        base = _PTD_OWN_ATTACKS[attack_id][2]
    attack_type = _ptd_int(getattr(attacker_data, "energyType", None))
    weakness = _ptd_int(getattr(target_data, "weakness", None))
    resistance = _ptd_int(getattr(target_data, "resistance", None))
    damage = base * 2 if weakness == attack_type else base
    if resistance == attack_type:
        damage = max(0, damage - 30)
    if (
        obs.current.stadium
        and obs.current.stadium[0].id == FULL_METAL_LAB
        and _ptd_int(getattr(target_data, "energyType", None)) == METAL_ENERGY
    ):
        damage = max(0, damage - 30)
    return damage


def _ptd_public_successor_ids(obs):
    opponent = opp_state(obs)
    public = set()
    for pokemon in _ptd_board(opponent):
        public.add(pokemon.id)
        public.update(card.id for card in (pokemon.preEvolution or ()))
    for card in opponent.discard or ():
        data = CARD_DB.get(card.id)
        if data is not None and getattr(data, "cardType", None) == 0:
            public.add(card.id)
    return frozenset(public)


def _ptd_successors(data, public_ids):
    if data is None:
        return None
    current_stage = (
        0 if data.basic else 1 if data.stage1 else 2 if data.stage2 else None
    )
    rows = []
    for card_id in sorted(public_ids):
        candidate = CARD_DB.get(card_id)
        if (
            candidate is None
            or _ptd_norm(getattr(candidate, "evolvesFrom", None))
            != _ptd_norm(getattr(data, "name", None))
        ):
            continue
        candidate_stage = (
            0
            if candidate.basic
            else 1
            if candidate.stage1
            else 2
            if candidate.stage2
            else None
        )
        if (
            candidate_stage != current_stage + 1
            or not _ptd_pokemon_data_supported(candidate)
        ):
            return None
        rows.append(candidate)
    return tuple(rows)


def _ptd_setup_gain(data, evolved, opponent_deck_count):
    modes = _ptd_skill_modes(data)
    if modes is None:
        return None
    gain = 0
    reset_class = None
    for mode, value in modes:
        if mode == "EVOLUTION_DRAW" and evolved:
            gain += min(value, max(0, opponent_deck_count - 1))
        elif (
            mode == "SELF_RETURN_ALL_ATTACHED_AFTER_DRAW"
            and opponent_deck_count > 1
        ):
            draw = min(value, opponent_deck_count - 1)
            gain += draw
            if draw > 0:
                reset_class = mode
    return gain, reset_class


def _ptd_projected_attack_damage(
    obs,
    attacker,
    attacker_data,
    attack_id,
    mode,
    our_active,
    own_attack_id,
    future_hand_count,
):
    our_data = CARD_DB.get(our_active.id)
    if our_data is None:
        return None
    if mode == "POWERFUL_HAND":
        return 20 * future_hand_count
    attack = ALL_ATTACKS.get(attack_id)
    if attack is None:
        return None
    damage = attack.damage
    attack_type = _ptd_int(getattr(attacker_data, "energyType", None))
    weakness = _ptd_int(getattr(our_data, "weakness", None))
    resistance = _ptd_int(getattr(our_data, "resistance", None))
    if own_attack_id == METAL_DEFENDER:
        weakness = None
    if (
        own_attack_id == COATED_ATTACK
        and bool(getattr(attacker_data, "basic", False))
    ):
        return 0
    if weakness == attack_type:
        damage *= 2
    if resistance == attack_type:
        damage = max(0, damage - 30)
    if (
        obs.current.stadium
        and obs.current.stadium[0].id == FULL_METAL_LAB
        and _ptd_int(getattr(our_data, "energyType", None)) == METAL_ENERGY
    ):
        damage = max(0, damage - 30)
    return damage


def _ptd_threat_envelope(
    obs,
    survivors,
    public_ids,
    own_attack_id,
):
    mine = my_state(obs)
    opponent = opp_state(obs)
    our_active = active_pokemon(obs)
    if (
        our_active is None
        or not _ptd_pokemon_supported(our_active, allow_own=True)
        or not isinstance(opponent.handCount, int)
        or opponent.handCount < 0
        or not isinstance(opponent.deckCount, int)
        or opponent.deckCount <= 0
    ):
        return None
    terminal_routes = 0
    lethal_routes = 0
    lock_routes = 0
    max_prizes = 0
    max_damage = 0
    ready_routes = 0
    max_setup = 0
    total_setup = 0
    route_rows = []
    for pokemon in survivors:
        data = CARD_DB.get(pokemon.id)
        if not _ptd_pokemon_supported(pokemon):
            return None
        evolutions = ()
        if not bool(getattr(pokemon, "appearThisTurn", False)):
            evolutions = _ptd_successors(data, public_ids)
            if evolutions is None:
                return None
        card_routes = [(data, False)] + [
            (evolution, True) for evolution in evolutions
        ]
        pokemon_best_setup = 0
        for route_data, evolved in card_routes:
            setup = _ptd_setup_gain(
                route_data,
                evolved,
                opponent.deckCount,
            )
            if setup is None:
                return None
            setup_gain, reset_class = setup
            pokemon_best_setup = max(pokemon_best_setup, setup_gain)
            max_setup = max(max_setup, setup_gain)
            future_hand = opponent.handCount + 1 + setup_gain
            for attack_id in tuple(getattr(route_data, "attacks", None) or ()):
                mode = _ptd_opponent_attack_mode(attack_id)
                if mode is None:
                    return None
                if not _ptd_reachable_payment(pokemon, attack_id):
                    continue
                damage = _ptd_projected_attack_damage(
                    obs,
                    pokemon,
                    route_data,
                    attack_id,
                    mode,
                    our_active,
                    own_attack_id,
                    future_hand,
                )
                if damage is None:
                    return None
                ready_routes += 1
                max_damage = max(max_damage, damage)
                lock = 1 if mode == "DIG" else 0
                lock_routes += lock
                prize = 0
                terminal = 0
                if damage >= our_active.hp:
                    lethal_routes += 1
                    prize = _ptd_prize_value(our_active)
                    if prize is None:
                        return None
                    max_prizes = max(max_prizes, prize)
                    terminal = int(
                        prize >= len(opponent.prize or ())
                        or not tuple(mine.bench or ())
                    )
                    terminal_routes += terminal
                route_rows.append(
                    (
                        pokemon.serial,
                        route_data.cardId,
                        attack_id,
                        mode,
                        damage,
                        prize,
                        terminal,
                        lock,
                        setup_gain,
                        reset_class,
                    )
                )
        total_setup += pokemon_best_setup
    vector = (
        terminal_routes,
        lock_routes,
        max_prizes,
        max_damage,
        ready_routes,
        max_setup,
    )
    return {
        "vector": vector,
        "terminal_routes": terminal_routes,
        "lethal_routes": lethal_routes,
        "lock_routes": lock_routes,
        "max_prizes": max_prizes,
        "max_damage": max_damage,
        "ready_routes": ready_routes,
        "max_setup": max_setup,
        "total_setup": total_setup,
        "routes": tuple(sorted(route_rows)),
    }


def _ptd_ephemeral_chip(obs, target, damage):
    if damage >= target.hp:
        return False
    data = CARD_DB.get(target.id)
    modes = _ptd_skill_modes(data) if data is not None else None
    return bool(
        modes is not None
        and ("SELF_RETURN_ALL_ATTACHED_AFTER_DRAW", 3) in modes
        and isinstance(opp_state(obs).deckCount, int)
        and opp_state(obs).deckCount > 1
    )


def _ptd_metadata_snapshot(obs, public_ids):
    ids = set(public_ids)
    for player in obs.current.players:
        for pokemon in _ptd_board(player):
            ids.add(pokemon.id)
            ids.update(card.id for card in (pokemon.energyCards or ()))
            ids.update(card.id for card in (pokemon.tools or ()))
            ids.update(card.id for card in (pokemon.preEvolution or ()))
    ids.update(card.id for card in (obs.current.stadium or ()))
    ids.add(BOSS)
    snapshot = []
    for card_id in sorted(ids):
        digest = _ptd_metadata_digest(card_id)
        if digest is None:
            return None
        snapshot.append((card_id, digest))
    return tuple(snapshot)


def _ptd_static_material(obs):
    mine = my_state(obs)
    opponent = opp_state(obs)
    return (
        _ptd_board_fp(mine),
        _ptd_board_fp(opponent),
        mine.deckCount,
        opponent.deckCount,
        _ptd_prize_fp(mine.prize),
        _ptd_prize_fp(opponent.prize),
        _ptd_card_multiset(opponent.discard),
        opponent.handCount,
        _ptd_conditions(mine),
        _ptd_conditions(opponent),
        tuple(_ptd_card_ref(card) for card in (obs.current.stadium or ())),
        bool(obs.current.stadiumPlayed),
        bool(obs.current.energyAttached),
        bool(obs.current.retreated),
    )


def _ptd_boss_options(obs, required_serial=None):
    rows = []
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.PLAY:
            continue
        card = option_card(obs, option)
        if (
            card is not None
            and card.id == BOSS
            and _ptd_serial(card) is not None
            and (required_serial is None or card.serial == required_serial)
        ):
            rows.append((position, card.serial))
    return rows


def _ptd_attack_options(obs, attack_id):
    return [
        position
        for position, option in enumerate(obs.select.option)
        if option.type == OptionType.ATTACK and option.attackId == attack_id
    ]


def _ptd_target_options(obs, target_serial):
    yi = obs.current.yourIndex
    rows = []
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.CARD:
            continue
        player_index = (
            option.playerIndex if option.playerIndex is not None else yi
        )
        card = option_card(obs, option)
        if (
            player_index == 1 - yi
            and card is not None
            and _ptd_serial(card) == target_serial
        ):
            rows.append(position)
    return rows


def _ptd_log_key(entry):
    return (
        _ptd_int(getattr(entry, "type", None)),
        getattr(entry, "playerIndex", None),
        getattr(entry, "cardId", None),
        getattr(entry, "serial", None),
        getattr(entry, "cardIdActive", None),
        getattr(entry, "serialActive", None),
        getattr(entry, "cardIdBench", None),
        getattr(entry, "serialBench", None),
        getattr(entry, "attackId", None),
    )


def _ptd_boss_confirmed(obs, transaction):
    return any(
        entry.type == LogType.PLAY
        and entry.playerIndex == transaction["seat"]
        and entry.cardId == BOSS
        and entry.serial == transaction["boss_serial"]
        for entry in obs.logs
    )


def _ptd_switch_confirmed(obs, transaction):
    return any(
        entry.type == LogType.SWITCH
        and entry.serialActive == transaction["original_active_serial"]
        and entry.serialBench == transaction["target_serial"]
        for entry in obs.logs
    )


def _ptd_attack_confirmed(obs, transaction):
    return any(
        entry.type == LogType.ATTACK
        and entry.playerIndex == transaction["seat"]
        and entry.cardId == transaction["attacker_id"]
        and entry.serial == transaction["attacker_serial"]
        and entry.attackId == transaction["attack_id"]
        for entry in obs.logs
    )


def _ptd_post_boss_material_valid(obs, transaction, switched):
    mine = my_state(obs)
    opponent = opp_state(obs)
    boss_ref = (BOSS, transaction["boss_serial"])
    expected_hand = list(transaction["mine_hand"])
    try:
        expected_hand.remove(boss_ref)
    except ValueError:
        return False
    expected_discard = transaction["mine_discard"] + (
        (boss_ref,) if switched else ()
    )
    if (
        obs.current.yourIndex != transaction["seat"]
        or obs.current.turn != transaction["turn"]
        or obs.current.result != -1
        or not obs.current.supporterPlayed
        or obs.current.turnActionCount
        != transaction["turn_action_count"] + (2 if switched else 1)
        or _ptd_card_multiset(mine.hand) != tuple(sorted(expected_hand, key=repr))
        or mine.handCount != transaction["mine_hand_count"] - 1
        or _ptd_card_multiset(mine.discard)
        != tuple(sorted(expected_discard, key=repr))
        or _ptd_static_material(obs) != transaction["static_material"]
        or _ptd_metadata_snapshot(obs, transaction["public_successor_ids"])
        != transaction["metadata_snapshot"]
    ):
        return False
    active = opp_active_pokemon(obs)
    if not switched:
        return (
            active is not None
            and active.serial == transaction["original_active_serial"]
            and _ptd_board_fp(opponent) == transaction["opponent_board"]
        )
    return (
        active is not None
        and active.serial == transaction["target_serial"]
        and _ptd_board_fp(opponent) == transaction["opponent_board"]
        and any(
            pokemon.serial == transaction["original_active_serial"]
            for pokemon in opponent.bench or ()
        )
    )


def _ptd_dominance_rows(
    obs,
    attacker,
    attack_id,
    original_active_serial,
    original_bench_serials,
    public_ids,
    boss_spent=False,
):
    opponent = opp_state(obs)
    board = {pokemon.serial: pokemon for pokemon in _ptd_board(opponent)}
    original_active = board.get(original_active_serial)
    if original_active is None:
        return None
    parent_damage = _ptd_exact_own_damage(
        obs, attacker, attack_id, original_active
    )
    parent_prize_value = _ptd_prize_value(original_active)
    if parent_damage is None or parent_prize_value is None:
        return None
    parent_ko = parent_damage >= original_active.hp
    ephemeral = _ptd_ephemeral_chip(obs, original_active, parent_damage)
    if not parent_ko and not ephemeral:
        return ()
    parent_immediate = parent_prize_value if parent_ko else 0
    parent_survivors = tuple(
        pokemon
        for serial, pokemon in sorted(board.items())
        if not (parent_ko and serial == original_active_serial)
    )
    parent_threat = _ptd_threat_envelope(
        obs, parent_survivors, public_ids, attack_id
    )
    if parent_threat is None:
        return None
    ko_targets = []
    for serial in original_bench_serials:
        target = board.get(serial)
        if target is None:
            return None
        damage = _ptd_exact_own_damage(obs, attacker, attack_id, target)
        prize = _ptd_prize_value(target)
        if damage is None or prize is None:
            return None
        if damage >= target.hp:
            ko_targets.append((target, damage, prize))
    if not ko_targets:
        return ()
    max_prize_route = max(prize for _, _, prize in ko_targets)
    rows = []
    for target, damage, prize in ko_targets:
        if prize < parent_immediate or prize < max_prize_route:
            continue
        certified_win = prize >= len(my_state(obs).prize or ())
        boss_count = sum(
            1 for card in (my_state(obs).hand or ()) if card.id == BOSS
        )
        reserve_required = (
            (0 if certified_win else 1)
            if boss_spent
            else (1 if certified_win else 2)
        )
        if boss_count < reserve_required:
            continue
        boss_survivors = tuple(
            pokemon
            for serial, pokemon in sorted(board.items())
            if serial != target.serial
        )
        boss_threat = _ptd_threat_envelope(
            obs, boss_survivors, public_ids, attack_id
        )
        if boss_threat is None:
            return None
        parent_vector = parent_threat["vector"]
        boss_vector = boss_threat["vector"]
        if (
            not all(
                boss_value <= parent_value
                for boss_value, parent_value in zip(
                    boss_vector, parent_vector
                )
            )
            or not any(
                boss_value < parent_value
                for boss_value, parent_value in zip(
                    boss_vector, parent_vector
                )
            )
            or (
                (
                    parent_threat["lethal_routes"] > 0
                    or parent_threat["lock_routes"] > 0
                )
                and (
                    boss_threat["lethal_routes"] > 0
                    or boss_threat["lock_routes"] > 0
                )
            )
        ):
            continue
        score = (
            100000
            * (
                parent_threat["terminal_routes"]
                - boss_threat["terminal_routes"]
            )
            + 10000
            * (parent_threat["lock_routes"] - boss_threat["lock_routes"])
            + 1000 * (prize - parent_immediate)
            + 100
            * (parent_threat["ready_routes"] - boss_threat["ready_routes"])
            + 30
            * (parent_threat["total_setup"] - boss_threat["total_setup"])
            + 20 * len(tuple(target.energyCards or ()))
            + 10 * len(tuple(target.tools or ()))
            + 10
            * (parent_threat["max_damage"] - boss_threat["max_damage"])
        )
        rows.append(
            {
                "target_serial": target.serial,
                "target_id": target.id,
                "target_fp": _ptd_pokemon_fp(target),
                "target_damage": damage,
                "target_prize": prize,
                "parent_damage": parent_damage,
                "parent_ko": parent_ko,
                "parent_ephemeral": ephemeral,
                "parent_persistent_damage": (
                    0 if ephemeral and not parent_ko else parent_damage
                ),
                "parent_immediate_prizes": parent_immediate,
                "parent_threat": parent_threat,
                "boss_threat": boss_threat,
                "score": score,
            }
        )
    return tuple(rows)


def _ptd_unique_winner(rows):
    if not rows:
        return None
    maximum = max(row["score"] for row in rows)
    winners = [row for row in rows if row["score"] == maximum]
    return winners[0] if len(winners) == 1 else None


def _ptd_build_certificate(obs, parent_action):
    global _ptd_last_rejection
    _ptd_last_rejection = None
    if (
        obs.current.result != -1
        or obs.select.context != SelectContext.MAIN
        or obs.select.effect is not None
        or obs.select.contextCard is not None
        or obs.select.minCount != 1
        or obs.select.maxCount != 1
        or _cum_active_transaction_owner is not None
        or any(_cum_rule_transaction(rule) is not None for rule in _CUM_RULES)
        or obs.current.supporterPlayed
        or not isinstance(parent_action, list)
        or len(parent_action) != 1
        or parent_action[0] not in range(len(obs.select.option))
    ):
        return _ptd_reject("activation_boundary")
    parent_option = obs.select.option[parent_action[0]]
    if (
        parent_option.type != OptionType.ATTACK
        or parent_option.attackId not in _PTD_OWN_ATTACKS
    ):
        return _ptd_reject("parent_not_exact_supported_attack")
    attack_id = parent_option.attackId
    attacker = active_pokemon(obs)
    mine = my_state(obs)
    opponent = opp_state(obs)
    conditions = (_ptd_conditions(mine), _ptd_conditions(opponent))
    boss_options = _ptd_boss_options(obs)
    if (
        attacker is None
        or attacker.id not in _PTD_OWN_CARD_ATTACK
        or attack_id not in _PTD_OWN_CARD_ATTACK[attacker.id]
        or not _ptd_pokemon_supported(attacker, allow_own=True)
        or _ptd_attack_payment(attacker, attack_id) is None
        or conditions[0] is None
        or conditions[1] is None
        or any(conditions[0])
        or any(conditions[1])
        or mine.hand is None
        or mine.handCount != len(mine.hand)
        or not boss_options
        or not _ptd_exact_trainer(
            BOSS,
            "Boss's Orders",
            "Switch in 1 of your opponent's Benched Pokemon to the Active Spot.",
        )
        or not _ptd_stadium_supported(obs)
        or _ptd_public_serials(obs) is None
        or not opponent.active
        or not opponent.bench
        or not isinstance(opponent.deckCount, int)
        or opponent.deckCount <= 0
        or _opp_last_attack_id == 75
        or (
            _opp_last_attack_id not in {None, MEGA_BRAVE}
            and _ptd_opponent_attack_mode(_opp_last_attack_id) is None
        )
        or (
            _opp_last_attack_id == MEGA_BRAVE
            and any(
                MEGA_BRAVE
                in tuple(
                    getattr(CARD_DB.get(pokemon.id), "attacks", None) or ()
                )
                for pokemon in _ptd_board(opponent)
            )
        )
    ):
        return _ptd_reject("incomplete_or_unsupported_public_state")
    if any(
        not _ptd_pokemon_supported(pokemon)
        for pokemon in _ptd_board(opponent)
    ):
        return _ptd_reject("unsupported_opponent_board")
    public_ids = _ptd_public_successor_ids(obs)
    metadata = _ptd_metadata_snapshot(obs, public_ids)
    if metadata is None:
        return _ptd_reject("metadata_snapshot_unknown")
    rows = _ptd_dominance_rows(
        obs,
        attacker,
        attack_id,
        opponent.active[0].serial,
        tuple(pokemon.serial for pokemon in opponent.bench),
        public_ids,
    )
    if rows is None:
        return _ptd_reject("threat_unknown")
    winner = _ptd_unique_winner(rows)
    if winner is None:
        return _ptd_reject(
            "no_unique_hard_dominating_target"
            if rows
            else "no_hard_dominating_target"
        )
    boss_serial = min(serial for _, serial in boss_options)
    boss_choice = min(
        position
        for position, serial in boss_options
        if serial == boss_serial
    )
    return {
        "stage": "BOSS_PLAY",
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "turn_action_count": obs.current.turnActionCount,
        "attacker_id": attacker.id,
        "attacker_serial": attacker.serial,
        "attacker_fp": _ptd_pokemon_fp(attacker),
        "attack_id": attack_id,
        "attack_payment": _ptd_attack_payment(attacker, attack_id),
        "attack_effect_mode": _ptd_own_attack_mode(attack_id),
        "boss_serial": boss_serial,
        "target_serial": winner["target_serial"],
        "target_id": winner["target_id"],
        "original_active_serial": opponent.active[0].serial,
        "original_bench_serials": tuple(
            pokemon.serial for pokemon in opponent.bench
        ),
        "winner": winner,
        "public_successor_ids": public_ids,
        "metadata_snapshot": metadata,
        "opponent_board": _ptd_board_fp(opponent),
        "static_material": _ptd_static_material(obs),
        "mine_hand": _ptd_card_multiset(mine.hand),
        "mine_hand_count": mine.handCount,
        "mine_discard": _ptd_card_multiset(mine.discard),
        "initial_option_multiset": _sat_option_multiset(obs),
        "stage_option_multiset": _sat_option_multiset(obs),
        "last_emitted_key": _sat_option_key(
            obs, obs.select.option[boss_choice]
        ),
        "initial_logs": tuple(_ptd_log_key(entry) for entry in obs.logs),
    }, boss_choice


def _ptd_revalidate_winner(obs, transaction):
    attacker = active_pokemon(obs)
    if (
        attacker is None
        or _ptd_pokemon_fp(attacker) != transaction["attacker_fp"]
        or _ptd_attack_payment(attacker, transaction["attack_id"])
        != transaction["attack_payment"]
        or _ptd_own_attack_mode(transaction["attack_id"])
        != transaction["attack_effect_mode"]
    ):
        return False
    rows = _ptd_dominance_rows(
        obs,
        attacker,
        transaction["attack_id"],
        transaction["original_active_serial"],
        transaction["original_bench_serials"],
        transaction["public_successor_ids"],
        boss_spent=True,
    )
    winner = None if rows is None else _ptd_unique_winner(rows)
    return (
        winner is not None
        and winner["target_serial"] == transaction["target_serial"]
        and winner["target_id"] == transaction["target_id"]
        and winner["target_fp"] == transaction["winner"]["target_fp"]
        and winner["parent_damage"] == transaction["winner"]["parent_damage"]
        and winner["target_damage"] == transaction["winner"]["target_damage"]
        and winner["parent_threat"]["vector"]
        == transaction["winner"]["parent_threat"]["vector"]
        and winner["boss_threat"]["vector"]
        == transaction["winner"]["boss_threat"]["vector"]
    )


def _ptd_choose(obs, parent_action):
    global _ptd_transaction
    transaction = _ptd_transaction
    if transaction is None:
        built = _ptd_build_certificate(obs, parent_action)
        if built is None:
            return None
        transaction, boss_choice = built
        _ptd_transaction = transaction
        return [boss_choice]
    if (
        obs.current.result != -1
        or obs.current.yourIndex != transaction["seat"]
        or obs.current.turn != transaction["turn"]
        or _ptd_attack_confirmed(obs, transaction)
    ):
        _ptd_reset("attack_confirmed_or_boundary")
        return None
    if transaction["stage"] == "BOSS_PLAY":
        if _ptd_boss_confirmed(obs, transaction):
            transaction["stage"] = "EXACT_TARGET_SERIAL"
            transaction["stage_option_multiset"] = _sat_option_multiset(obs)
        else:
            if (
                obs.current.turnActionCount != transaction["turn_action_count"]
                or obs.current.supporterPlayed
                or _ptd_static_material(obs) != transaction["static_material"]
                or _ptd_card_multiset(my_state(obs).hand)
                != transaction["mine_hand"]
                or _ptd_card_multiset(my_state(obs).discard)
                != transaction["mine_discard"]
                or _ptd_metadata_snapshot(
                    obs, transaction["public_successor_ids"]
                )
                != transaction["metadata_snapshot"]
                or _sat_option_multiset(obs)
                != transaction["stage_option_multiset"]
            ):
                _ptd_reset("pre_boss_mutation")
                return None
            choices = _ptd_boss_options(obs, transaction["boss_serial"])
            if not choices:
                _ptd_reset("boss_option_missing")
                return None
            return [min(position for position, _ in choices)]
    if transaction["stage"] == "EXACT_TARGET_SERIAL":
        if _ptd_switch_confirmed(obs, transaction):
            if (
                not _ptd_post_boss_material_valid(
                    obs, transaction, switched=True
                )
                or not _ptd_revalidate_winner(obs, transaction)
            ):
                _ptd_reset("post_switch_revalidation_failed")
                return None
            transaction["stage"] = "SAME_EXACT_ATTACK"
            transaction["stage_option_multiset"] = _sat_option_multiset(obs)
        else:
            if (
                not _ptd_post_boss_material_valid(
                    obs, transaction, switched=False
                )
                or _sat_option_multiset(obs)
                != transaction["stage_option_multiset"]
                or obs.select.context
                not in {SelectContext.SWITCH, SelectContext.TO_ACTIVE}
                or (
                    obs.select.effect is not None
                    and (
                        obs.select.effect.id != BOSS
                        or obs.select.effect.serial
                        != transaction["boss_serial"]
                    )
                )
            ):
                _ptd_reset("target_callback_mutation")
                return None
            choices = _ptd_target_options(obs, transaction["target_serial"])
            if not choices:
                _ptd_reset("target_option_missing_or_ambiguous")
                return None
            return [min(choices)]
    if transaction["stage"] == "SAME_EXACT_ATTACK":
        if (
            not _ptd_post_boss_material_valid(
                obs, transaction, switched=True
            )
            or not _ptd_revalidate_winner(obs, transaction)
            or _sat_option_multiset(obs) != transaction["stage_option_multiset"]
            or obs.select.context not in {SelectContext.MAIN, SelectContext.ATTACK}
        ):
            _ptd_reset("attack_callback_revalidation_failed")
            return None
        choices = _ptd_attack_options(obs, transaction["attack_id"])
        if not choices:
            _ptd_reset("same_attack_missing")
            return None
        return [min(choices)]
    _ptd_reset("unknown_stage")
    return None

# ---- CUMULATIVE_PUBLIC_ONE_TURN_TARGET_DOMINANCE_V1 ----
#
# ---- PUBLIC_NEXT_ATTACKER_CONTINUITY_SUITE_V1 -----------------------------
#
# Five independent public-state certificates are integrated below.  Each owns
# a separate transaction slot so the cumulative arbiter can preserve rank-2
# owner exclusivity and attribute proposals/rejections per mechanism.

_NAC_ROTATION_RULE_ID = "GENERAL_VISIBLE_COUNTERATTACK_READY_ROTATION_V1"
_NAC_IMMUNITY_RULE_ID = "IMMUNITY_AWARE_READY_NONEX_EVOLUTION_V1"
_NAC_CAPE_RULE_ID = "CAPE_BEFORE_IRREVERSIBLE_FUTURE_ANCHOR_V1"
_NAC_TURBO_RULE_ID = "TURBO_BEFORE_RETREAT_CONTINUITY_V1"
_NAC_EVOLUTION_RULE_ID = "SACRIFICIAL_ACTIVE_BENCH_EVOLUTION_ROUTING_V1"

_nacr_transaction = None
_nacr_last_rejection = None
_naci_transaction = None
_naci_last_rejection = None
_nacc_transaction = None
_nacc_last_rejection = None
_nact_transaction = None
_nact_last_rejection = None
_nace_transaction = None
_nace_last_rejection = None


def _nac_reset(prefix, reason):
    globals()[f"{prefix}_transaction"] = None
    globals()[f"{prefix}_last_rejection"] = str(reason)


def _nac_reject(prefix, reason):
    globals()[f"{prefix}_last_rejection"] = str(reason)
    return None


def _nacr_reset(reason=None):
    _nac_reset("_nacr", reason or "reset")


def _naci_reset(reason=None):
    _nac_reset("_naci", reason or "reset")


def _nacc_reset(reason=None):
    _nac_reset("_nacc", reason or "reset")


def _nact_reset(reason=None):
    _nac_reset("_nact", reason or "reset")


def _nace_reset(reason=None):
    _nac_reset("_nace", reason or "reset")


def _nac_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _nac_serial(value):
    serial = _nac_int(getattr(value, "serial", None))
    return serial if serial is not None and serial > 0 else None


def _nac_card_fp(card):
    if card is None:
        return None
    return (
        getattr(card, "id", None),
        _nac_serial(card),
        getattr(card, "playerIndex", None),
    )


def _nac_pokemon_fp(pokemon):
    if pokemon is None:
        return None
    return (
        getattr(pokemon, "id", None),
        _nac_serial(pokemon),
        getattr(pokemon, "hp", None),
        getattr(pokemon, "maxHp", None),
        bool(getattr(pokemon, "appearThisTurn", False)),
        tuple(_nac_int(value) for value in (pokemon.energies or ())),
        tuple(_nac_card_fp(card) for card in (pokemon.energyCards or ())),
        tuple(_nac_card_fp(card) for card in (pokemon.tools or ())),
        tuple(_nac_card_fp(card) for card in (pokemon.preEvolution or ())),
    )


def _nac_has_status(player):
    return any(
        bool(getattr(player, field, False))
        for field in ("poisoned", "burned", "asleep", "paralyzed", "confused")
    )


def _nac_strict_main(obs):
    return (
        obs is not None
        and obs.current is not None
        and obs.current.result == -1
        and obs.select is not None
        and obs.select.context == SelectContext.MAIN
        and obs.select.minCount == 1
        and obs.select.maxCount == 1
        and obs.select.contextCard is None
        and obs.select.effect is None
        and obs.current.looking is None
        and bool(obs.select.option)
    )


def _nac_find_own_pokemon(obs, serial):
    return next(
        (
            pokemon
            for pokemon in (my_state(obs).active or ()) + (my_state(obs).bench or ())
            if pokemon is not None and _nac_serial(pokemon) == serial
        ),
        None,
    )


def _nac_positions(
    obs,
    *,
    option_type=None,
    card_id=None,
    card_serial=None,
    target_serial=None,
    attack_id=None,
):
    rows = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        target = option_target(obs, option)
        if option_type is not None and option.type != option_type:
            continue
        if card_id is not None and getattr(card, "id", None) != card_id:
            continue
        if card_serial is not None and _nac_serial(card) != card_serial:
            continue
        if target_serial is not None and _nac_serial(target) != target_serial:
            continue
        if attack_id is not None and getattr(option, "attackId", None) != attack_id:
            continue
        rows.append(position)
    return rows


def _nac_card_positions(obs, serial):
    return [
        position
        for position, option in enumerate(obs.select.option)
        if _nac_serial(option_card(obs, option)) == serial
    ]


def _nac_parent_option(obs, parent_action):
    if (
        not isinstance(parent_action, list)
        or len(parent_action) != 1
        or parent_action[0] not in range(len(obs.select.option))
    ):
        return None
    return obs.select.option[parent_action[0]]


def _nac_exact_attack(attack_id, name, damage, energies, text):
    attack = ALL_ATTACKS.get(attack_id)
    return (
        attack is not None
        and getattr(attack, "name", None) == name
        and _nac_int(getattr(attack, "damage", None)) == damage
        and tuple(_nac_int(value) for value in (attack.energies or ())) == energies
        and getattr(attack, "text", None) == text
    )


def _nac_exact_skill(card_id, name, text):
    data = CARD_DB.get(card_id)
    skills = tuple(getattr(data, "skills", None) or ())
    return (
        data is not None
        and len(skills) == 1
        and (getattr(skills[0], "name", None) or "").strip() == name
        and getattr(skills[0], "text", None) == text
    )


def _nac_basic_metal(card):
    data = CARD_DB.get(getattr(card, "id", None))
    return (
        card is not None
        and card.id == METAL_ENERGY
        and _nac_serial(card) is not None
        and data is not None
        and _nac_int(getattr(data, "cardType", None)) == 5
        and _nac_int(getattr(data, "energyType", None)) == METAL_ENERGY
    )


def _nac_basic_metal_pokemon(pokemon, exact_count=None):
    energies = tuple(_nac_int(value) for value in (pokemon.energies or ()))
    cards = tuple(pokemon.energyCards or ())
    return (
        (exact_count is None or len(cards) == exact_count)
        and len(energies) == len(cards)
        and all(value == METAL_ENERGY for value in energies)
        and all(_nac_basic_metal(card) for card in cards)
        and len({_nac_serial(card) for card in cards}) == len(cards)
    )


def _nac_known_tool_only(pokemon, allowed=()):
    allowed = set(allowed)
    tools = tuple(pokemon.tools or ())
    return all(
        getattr(tool, "id", None) in allowed and _nac_serial(tool) is not None
        for tool in tools
    )


def _nac_identity_valid(obs, transaction, *, require_main=False):
    return (
        obs is not None
        and obs.current is not None
        and obs.current.result == -1
        and transaction.get("game_epoch") == globals().get("_cum_game_epoch")
        and obs.current.yourIndex == transaction["seat"]
        and obs.current.firstPlayer == transaction["first_player"]
        and obs.current.turn == transaction["turn"]
        and (not require_main or _nac_strict_main(obs))
    )


def _nac_option_semantic(obs, position):
    return (_sat_option_key(obs, obs.select.option[position]),)


def _nac_unique_semantic_position(obs, semantic):
    if semantic is None or len(semantic) != 1:
        return None
    matches = [
        position
        for position, option in enumerate(obs.select.option)
        if _sat_option_key(obs, option) == semantic[0]
    ]
    return matches[0] if len(matches) == 1 else None


def _nac_flat_payable_damage(obs, attacker, target):
    data = CARD_DB.get(getattr(attacker, "id", None))
    target_data = CARD_DB.get(getattr(target, "id", None))
    if (
        data is None
        or target_data is None
        or getattr(data, "skills", None)
        or not _nac_known_tool_only(attacker, (HERO_CAPE, 1173))
        or not _nac_known_tool_only(target, (HERO_CAPE,))
    ):
        return None
    values = []
    for attack_id in (getattr(data, "attacks", None) or ()):
        attack = ALL_ATTACKS.get(attack_id)
        if attack is None:
            return None
        text = getattr(attack, "text", None) or ""
        if text not in ("",):
            return None
        if not _h2_energy_ready_types(attacker.energies or (), attack_id):
            continue
        damage = _nac_int(getattr(attack, "damage", None))
        if damage is None or damage < 0:
            return None
        attack_type = _nac_int(getattr(data, "energyType", None))
        if attack_type == _nac_int(getattr(target_data, "weakness", None)):
            damage *= 2
        if attack_type == _nac_int(getattr(target_data, "resistance", None)):
            damage = max(0, damage - 30)
        if (
            obs.current.stadium
            and obs.current.stadium[0].id == FULL_METAL_LAB
            and _nac_int(getattr(target_data, "energyType", None)) == METAL_ENERGY
        ):
            damage = max(0, damage - 30)
        values.append((attack_id, damage))
    return tuple(values)


def _nac_public_deck_metal_floor(obs):
    """Lower bound from deck size and the exact 48-card non-Metal inventory."""
    mine = my_state(obs)
    visible = []
    visible.extend(card for card in (mine.hand or ()) if card is not None)
    visible.extend(card for card in (mine.discard or ()) if card is not None)
    visible.extend(card for card in (mine.prize or ()) if card is not None)
    for pokemon in (mine.active or ()) + (mine.bench or ()):
        if pokemon is None:
            continue
        visible.append(pokemon)
        visible.extend(card for card in (pokemon.preEvolution or ()) if card is not None)
        visible.extend(card for card in (pokemon.tools or ()) if card is not None)
        visible.extend(card for card in (pokemon.energyCards or ()) if card is not None)
    for card in (obs.current.stadium or ()):
        if card is not None and getattr(card, "playerIndex", None) == obs.current.yourIndex:
            visible.append(card)
    serials = [_nac_serial(card) for card in visible]
    if any(serial is None for serial in serials) or len(serials) != len(set(serials)):
        return None
    known_nonmetal = sum(getattr(card, "id", None) != METAL_ENERGY for card in visible)
    return max(0, mine.deckCount - (48 - known_nonmetal))


# -- 1. Cape before an irreversible future-anchor action --------------------

_NACC_CAPE = "CAPE_EMITTED"
_NACC_CONTINUATION = "CONTINUATION_EMITTED"


def _nacc_build(obs, parent_action):
    global _nacc_transaction, _nacc_last_rejection
    if not _nac_strict_main(obs):
        return _nac_reject("_nacc", "activation_boundary")
    parent_option = _nac_parent_option(obs, parent_action)
    if parent_option is None:
        return _nac_reject("_nacc", "parent_not_single")
    parent_card = option_card(obs, parent_option)
    is_lillie = (
        parent_option.type == OptionType.PLAY
        and getattr(parent_card, "id", None) == LILLIE
        and _nac_exact_skill(
            LILLIE,
            "Lillie's Determination",
            "Shuffle your hand into your deck. Then, draw 6 cards. If you have exactly 6 Prize cards remaining, draw 8 cards instead.",
        )
    )
    is_turbo = (
        parent_option.type == OptionType.ATTACK
        and parent_option.attackId == 965
        and _nac_exact_attack(
            965,
            "Turbo Flare",
            50,
            (0,),
            "Search your deck for up to 3 Basic Energy cards and attach them to your Benched Pokémon in any way you like. Then, shuffle your deck.",
        )
    )
    if not (is_lillie or is_turbo):
        return _nac_reject("_nacc", "parent_not_irreversible_anchor_route")
    active = active_pokemon(obs)
    if (
        active is None
        or active.id != CINDERACE
        or not _h2_energy_ready(active, 965)
        or _nac_has_status(my_state(obs))
        or _nac_has_status(opp_state(obs))
    ):
        return _nac_reject("_nacc", "cinderace_or_status_not_supported")
    turbo_positions = _nac_positions(
        obs, option_type=OptionType.ATTACK, attack_id=965
    )
    if len(turbo_positions) != 1:
        return _nac_reject("_nacc", "turbo_semantic_ambiguous")

    cape_rows = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        target = option_target(obs, option)
        if (
            option.type == OptionType.ATTACH
            and getattr(card, "id", None) == HERO_CAPE
            and _nac_serial(card) is not None
            and target is not None
            and target.id == DURALUDON
            and target in (my_state(obs).bench or ())
            and not (target.tools or ())
            and _nac_basic_metal_pokemon(target)
        ):
            cape_rows.append((position, card, target))
    cape_serials = {_nac_serial(card) for _, card, _ in cape_rows}
    if len(cape_serials) != 1:
        return _nac_reject("_nacc", "cape_missing_or_ambiguous")

    zero_rows = [
        row for row in cape_rows if len(row[2].energyCards or ()) == 0
    ]
    if is_lillie:
        if obs.current.supporterPlayed or len(zero_rows) != 1:
            return _nac_reject("_nacc", "lillie_anchor_not_unique")
        chosen = zero_rows[0]
        route = "LILLIE_THEN_TURBO_UNIQUE_ANCHOR"
    else:
        bench = [pokemon for pokemon in (my_state(obs).bench or ()) if pokemon]
        lines = [
            (index, pokemon)
            for index, pokemon in enumerate(bench)
            if pokemon.id == DURALUDON and _nac_basic_metal_pokemon(pokemon)
        ]
        if len(lines) < 3:
            return _nac_reject("_nacc", "turbo_plan_has_no_certified_last_reserve")
        primary = min(
            lines,
            key=lambda row: (
                -len(row[1].energyCards or ()),
                row[0],
                _nac_serial(row[1]),
            ),
        )[1]
        reserves = [
            row
            for row in zero_rows
            if _nac_serial(row[2]) != _nac_serial(primary)
        ]
        if not reserves:
            return _nac_reject("_nacc", "turbo_reserve_missing")
        # The deterministic Turbo allocator fills the earliest primary line.
        # The continuity anchor is the final remaining zero-energy reserve.
        reserves.sort(
            key=lambda row: (
                bench.index(row[2]),
                _nac_serial(row[2]),
            )
        )
        chosen = reserves[-1]
        route = "TURBO_PRIMARY_THEN_LAST_ZERO_RESERVE"
    position, cape_card, target = chosen
    if len(_nac_positions(
        obs,
        option_type=OptionType.ATTACH,
        card_id=HERO_CAPE,
        card_serial=_nac_serial(cape_card),
        target_serial=_nac_serial(target),
    )) != 1:
        return _nac_reject("_nacc", "cape_target_binding_ambiguous")
    parent_semantic = _nac_option_semantic(obs, parent_action[0])
    if _nac_unique_semantic_position(obs, parent_semantic) is None:
        return _nac_reject("_nacc", "parent_continuation_ambiguous")
    transaction = {
        "rule_id": _NAC_CAPE_RULE_ID,
        "stage": _NACC_CAPE,
        "game_epoch": globals().get("_cum_game_epoch"),
        "seat": obs.current.yourIndex,
        "first_player": obs.current.firstPlayer,
        "turn": obs.current.turn,
        "pre_action_count": obs.current.turnActionCount,
        "cape_serial": _nac_serial(cape_card),
        "target_serial": _nac_serial(target),
        "target_id": target.id,
        "target_hp": target.hp,
        "target_max_hp": target.maxHp,
        "target_energy": tuple(_nac_card_fp(card) for card in target.energyCards or ()),
        "parent_semantic": parent_semantic,
        "route": route,
    }
    _nacc_transaction = transaction
    _nacc_last_rejection = None
    return [position]


def _nacc_resume(obs):
    global _nacc_transaction
    transaction = _nacc_transaction
    if transaction is None:
        return None
    if not _nac_identity_valid(obs, transaction):
        _nacc_reset("identity_or_result_change")
        return None
    if transaction["stage"] == _NACC_CAPE:
        target = _nac_find_own_pokemon(obs, transaction["target_serial"])
        tools = tuple(getattr(target, "tools", None) or ()) if target else ()
        if (
            not _nac_strict_main(obs)
            or obs.current.turnActionCount != transaction["pre_action_count"] + 1
            or target is None
            or target.id != transaction["target_id"]
            or target.hp != transaction["target_hp"] + 100
            or target.maxHp != transaction["target_max_hp"] + 100
            or tuple(_nac_card_fp(card) for card in target.energyCards or ())
            != transaction["target_energy"]
            or len(tools) != 1
            or tools[0].id != HERO_CAPE
            or _nac_serial(tools[0]) != transaction["cape_serial"]
            or any(
                card.id == HERO_CAPE and _nac_serial(card) == transaction["cape_serial"]
                for card in (my_state(obs).hand or ())
            )
        ):
            _nacc_reset("cape_confirmation_or_cached_context_failed")
            return None
        position = _nac_unique_semantic_position(
            obs, transaction["parent_semantic"]
        )
        if position is None:
            _nacc_reset("cached_continuation_disappeared")
            return None
        transaction["stage"] = _NACC_CONTINUATION
        transaction["continuation_action_count"] = obs.current.turnActionCount
        return [position]
    _nacc_reset("continuation_emitted")
    return None


def _nacc_choose(obs, parent_action):
    if _nacc_transaction is not None:
        return _nacc_resume(obs)
    return _nacc_build(obs, parent_action)


# -- 2. Turbo before a nonterminal retreat/end ------------------------------

_NACT_ATTACH = "ATTACH_EMITTED"
_NACT_TURBO = "TURBO_EMITTED"
_NACT_ENERGY = "ENERGY_SELECTED"
_NACT_TARGET = "ENERGY_TARGETING"


def _nact_build(obs, parent_action):
    global _nact_transaction, _nact_last_rejection
    if not _nac_strict_main(obs):
        return _nac_reject("_nact", "activation_boundary")
    parent_option = _nac_parent_option(obs, parent_action)
    if parent_option is None or parent_option.type not in {
        OptionType.RETREAT,
        OptionType.END,
    }:
        return _nac_reject("_nact", "parent_not_retreat_or_end")
    active = active_pokemon(obs)
    opponent = opp_active_pokemon(obs)
    if (
        active is None
        or active.id != CINDERACE
        or opponent is None
        or _nac_has_status(my_state(obs))
        or _nac_has_status(opp_state(obs))
        or not _nac_basic_metal_pokemon(active, exact_count=1)
        or not _h2_energy_ready(active, 965)
        or not _nac_exact_attack(
            965,
            "Turbo Flare",
            50,
            (0,),
            "Search your deck for up to 3 Basic Energy cards and attach them to your Benched Pokémon in any way you like. Then, shuffle your deck.",
        )
    ):
        return _nac_reject("_nact", "active_turbo_certificate_failed")
    turbo_positions = _nac_positions(
        obs, option_type=OptionType.ATTACK, attack_id=965
    )
    if len(turbo_positions) != 1 or opponent.hp <= 50:
        return _nac_reject("_nact", "turbo_missing_or_terminal")
    incoming = _nac_flat_payable_damage(obs, opponent, active)
    if incoming is None or any(damage >= active.hp for _, damage in incoming):
        return _nac_reject("_nact", "retreat_is_board_saving_or_damage_unknown")

    hand_metals = [
        card for card in (my_state(obs).hand or ()) if _nac_basic_metal(card)
    ]
    if len(hand_metals) != 1:
        return _nac_reject("_nact", "hand_metal_not_unique")
    candidates = [
        pokemon
        for pokemon in (my_state(obs).bench or ())
        if (
            pokemon is not None
            and pokemon.id == DURALUDON
            and not (pokemon.tools or ())
            and _nac_basic_metal_pokemon(pokemon, exact_count=0)
        )
    ]
    if not candidates:
        return _nac_reject("_nact", "no_zero_energy_continuity_line")
    target = candidates[0]
    attach_positions = _nac_positions(
        obs,
        option_type=OptionType.ATTACH,
        card_id=METAL_ENERGY,
        card_serial=_nac_serial(hand_metals[0]),
        target_serial=_nac_serial(target),
    )
    needed = 2
    floor = _nac_public_deck_metal_floor(obs)
    if (
        len(attach_positions) != 1
        or floor is None
        or floor < needed
        or _h2_energy_ready(target, METAL_DEFENDER)
    ):
        return _nac_reject("_nact", "attach_binding_or_public_energy_floor_failed")
    transaction = {
        "rule_id": _NAC_TURBO_RULE_ID,
        "stage": _NACT_ATTACH,
        "game_epoch": globals().get("_cum_game_epoch"),
        "seat": obs.current.yourIndex,
        "first_player": obs.current.firstPlayer,
        "turn": obs.current.turn,
        "pre_action_count": obs.current.turnActionCount,
        "active_serial": _nac_serial(active),
        "target_serial": _nac_serial(target),
        "hand_metal_serial": _nac_serial(hand_metals[0]),
        "turbo_semantic": _nac_option_semantic(obs, turbo_positions[0]),
        "energy_needed": needed,
        "selected_energy_serials": (),
        "attached_count": 0,
        "deck_metal_floor": floor,
    }
    _nact_transaction = transaction
    _nact_last_rejection = None
    return [attach_positions[0]]


def _nact_resume(obs):
    global _nact_transaction
    transaction = _nact_transaction
    if transaction is None:
        return None
    if not _nac_identity_valid(obs, transaction):
        _nact_reset("identity_or_result_change")
        return None
    target = _nac_find_own_pokemon(obs, transaction["target_serial"])
    active = active_pokemon(obs)
    if target is None:
        _nact_reset("continuity_target_disappeared")
        return None
    stage = transaction["stage"]
    if stage == _NACT_ATTACH:
        if (
            not _nac_strict_main(obs)
            or obs.current.turnActionCount != transaction["pre_action_count"] + 1
            or active is None
            or _nac_serial(active) != transaction["active_serial"]
            or transaction["hand_metal_serial"]
            not in {_nac_serial(card) for card in (target.energyCards or ())}
            or len(target.energyCards or ()) != 1
            or any(
                _nac_serial(card) == transaction["hand_metal_serial"]
                for card in (my_state(obs).hand or ())
            )
        ):
            _nact_reset("manual_attach_confirmation_failed")
            return None
        position = _nac_unique_semantic_position(obs, transaction["turbo_semantic"])
        if position is None:
            _nact_reset("turbo_continuation_disappeared")
            return None
        transaction["stage"] = _NACT_TURBO
        return [position]
    if stage == _NACT_TURBO:
        metal_rows = []
        for position, option in enumerate(obs.select.option):
            card = option_card(obs, option)
            if option.type == OptionType.CARD and _nac_basic_metal(card):
                metal_rows.append((position, _nac_serial(card)))
        metal_rows.sort(key=lambda row: (row[1], row[0]))
        needed = transaction["energy_needed"]
        if (
            obs.select.minCount > needed
            or obs.select.maxCount < needed
            or len(metal_rows) < needed
            or active is None
            or _nac_serial(active) != transaction["active_serial"]
        ):
            _nact_reset("turbo_energy_search_not_exactly_completable")
            return None
        chosen = metal_rows[:needed]
        if len({serial for _, serial in chosen}) != needed:
            _nact_reset("turbo_energy_serial_ambiguity")
            return None
        transaction["selected_energy_serials"] = tuple(
            serial for _, serial in chosen
        )
        transaction["stage"] = _NACT_ENERGY
        return [position for position, _ in chosen]
    if stage in {_NACT_ENERGY, _NACT_TARGET}:
        selected = set(transaction["selected_energy_serials"])
        attached = sum(
            _nac_serial(card) in selected for card in (target.energyCards or ())
        )
        if attached >= transaction["energy_needed"]:
            if not _h2_energy_ready(target, METAL_DEFENDER):
                _nact_reset("allocation_finished_without_ready_attacker")
            else:
                _nact_reset("allocation_complete")
            return None
        positions = _nac_card_positions(obs, transaction["target_serial"])
        if len(positions) != 1 or attached != transaction["attached_count"]:
            _nact_reset("turbo_target_callback_ambiguous_or_mutated")
            return None
        transaction["attached_count"] = attached + 1
        transaction["stage"] = _NACT_TARGET
        return [positions[0]]
    _nact_reset("unknown_stage")
    return None


def _nact_choose(obs, parent_action):
    if _nact_transaction is not None:
        return _nact_resume(obs)
    return _nact_build(obs, parent_action)


# -- 3. Exact immunity conversion to ready non-ex Archaludon ----------------

_NAC_CRUSTLE_SKILL = (
    "Mysterious Rock Inn",
    "Prevent all damage done to this Pokémon by attacks from your opponent’s Pokémon {ex}.",
)


def _naci_crustle_immunity(obs):
    opponent = opp_active_pokemon(obs)
    if opponent is None:
        return False
    if opponent.id == 345:
        return (
            _nac_exact_skill(345, *_NAC_CRUSTLE_SKILL)
            and _nac_known_tool_only(opponent, (HERO_CAPE,))
        )
    # The public replay API exposes the just-Ascended card under its Dwebble
    # id until the next boundary.  This exact registry entry is deliberately
    # narrow and depends on the public Ascension attack plus transformed HP.
    return (
        opponent.id == 344
        and _opp_last_attack_id == 478
        and opponent.maxHp == 210
        and tuple(_nac_int(value) for value in opponent.energies or ())
        == (1, 1, 0)
        and len(opponent.tools or ()) == 1
        and opponent.tools[0].id == HERO_CAPE
        and _nac_serial(opponent.tools[0]) is not None
        and _nac_exact_attack(
            478,
            "Ascension",
            0,
            (0,),
            "Search your deck for a card that evolves from this Pokémon and put it onto this Pokémon to evolve it. Then, shuffle your deck.",
        )
        and _nac_exact_skill(345, *_NAC_CRUSTLE_SKILL)
    )


def _naci_choose(obs, parent_action):
    global _naci_transaction, _naci_last_rejection
    _naci_transaction = None
    if not _nac_strict_main(obs):
        return _nac_reject("_naci", "activation_boundary")
    parent_option = _nac_parent_option(obs, parent_action)
    if parent_option is None or parent_option.type != OptionType.END:
        return _nac_reject("_naci", "parent_not_unrelated_end")
    if (
        not _naci_crustle_immunity(obs)
        or _nac_has_status(my_state(obs))
        or _nac_has_status(opp_state(obs))
        or obs.current.stadium
    ):
        return _nac_reject("_naci", "immunity_registry_or_modifier_failed")
    if not _nac_exact_attack(
        COATED_ATTACK,
        "Coated Attack",
        120,
        (8, 8, 8),
        "During your opponent’s next turn, prevent all damage done to this Pokémon by attacks from Basic Pokémon.",
    ):
        return _nac_reject("_naci", "nonex_attack_metadata_changed")
    rows = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        target = option_target(obs, option)
        if (
            option.type == OptionType.EVOLVE
            and getattr(card, "id", None) == ARCHALUDON
            and _nac_serial(card) is not None
            and target is not None
            and target.id == DURALUDON
            and _nac_basic_metal_pokemon(target, exact_count=3)
            and not (target.tools or ())
            and _h2_energy_ready(target, COATED_ATTACK)
        ):
            rows.append((position, target))
    if len(rows) != 1:
        return _nac_reject("_naci", "ready_nonex_target_not_unique")
    target = rows[0][1]
    ex_rows = _nac_positions(
        obs,
        option_type=OptionType.EVOLVE,
        card_id=ARCHALUDON_EX,
        target_serial=_nac_serial(target),
    )
    if not ex_rows:
        return _nac_reject("_naci", "no_public_blocked_ex_alternative")
    _naci_last_rejection = None
    return [rows[0][0]]


# -- 4. General visible-counterattack ready rotation ------------------------

_NACR_RETREAT = "RETREAT_EMITTED"
_NACR_TARGET = "RETREAT_TARGET_EMITTED"
_NACR_ATTACK = "ATTACK_EMITTED"


def _nacr_starmie_damage_rows(obs, target):
    attacker = opp_active_pokemon(obs)
    if (
        attacker is None
        or attacker.id != 1031
        or not _nac_known_tool_only(attacker)
        or not _nac_known_tool_only(target)
        or not _nac_exact_attack(
            1487,
            "Jetting Blow",
            120,
            (3,),
            "This attack also does 50 damage to 1 of your opponent’s Benched Pokémon. (Don’t apply Weakness and Resistance for Benched Pokémon.)",
        )
        or not _nac_exact_attack(
            1488,
            "Nebula Beam",
            210,
            (0, 0, 0),
            "This attack’s damage isn’t affected by Weakness or Resistance, or by any effects on your opponent’s Active Pokémon.",
        )
    ):
        return None
    target_data = CARD_DB.get(target.id)
    rows = []
    for attack_id in (1487, 1488):
        if not _h2_energy_ready(attacker, attack_id):
            continue
        attack = ALL_ATTACKS[attack_id]
        damage = _nac_int(attack.damage)
        if attack_id == 1487:
            attack_type = _nac_int(CARD_DB[1031].energyType)
            if attack_type == _nac_int(target_data.weakness):
                damage *= 2
            if attack_type == _nac_int(target_data.resistance):
                damage = max(0, damage - 30)
            if (
                obs.current.stadium
                and obs.current.stadium[0].id == FULL_METAL_LAB
                and _nac_int(target_data.energyType) == METAL_ENERGY
            ):
                damage = max(0, damage - 30)
        rows.append((attack_id, damage))
    return tuple(rows)


def _nacr_text(value):
    return (
        (value or "")
        .casefold()
        .replace("pokémon", "pokemon")
        .replace("pokﾃｩmon", "pokemon")
        .replace("’", "'")
        .replace("窶冱", "'s")
        .replace("窶冲", "'t")
        .replace("\xa0", " ")
        .strip()
    )


def _nacr_skill_texts(card):
    data = CARD_DB.get(getattr(card, "id", None))
    if data is None:
        return None
    return tuple(
        _nacr_text(getattr(skill, "text", None))
        for skill in (getattr(data, "skills", None) or ())
    )


def _nacr_material_text(text):
    return any(
        token in text
        for token in (
            "damage",
            "weakness",
            "resistance",
            "attack cost",
            "attacks cost",
            "can't attack",
            "cannot attack",
            "knocked out",
            "prize card",
        )
    )


def _nacr_energy_supported(pokemon):
    cards = tuple(getattr(pokemon, "energyCards", None) or ())
    energies = tuple(_nac_int(value) for value in (pokemon.energies or ()))
    serials = tuple(_nac_serial(card) for card in cards)
    if (
        len(cards) != len(energies)
        or any(serial is None for serial in serials)
        or len(serials) != len(set(serials))
    ):
        return False
    for card, energy_type in zip(cards, energies):
        data = CARD_DB.get(getattr(card, "id", None))
        texts = _nacr_skill_texts(card)
        if (
            data is None
            or texts is None
            or _nac_int(getattr(data, "cardType", None)) not in {5, 6}
            or _nac_int(getattr(data, "energyType", None)) != energy_type
            or any(
                _nacr_material_text(
                    text.replace("damage is not an effect", "")
                )
                for text in texts
            )
        ):
            return False
    return True


def _nacr_paid_energy(pokemon, attack_id):
    attack = ALL_ATTACKS.get(attack_id)
    cost = tuple(
        _nac_int(value)
        for value in (getattr(attack, "energies", None) or ())
    )
    available = list(_nac_int(value) for value in (pokemon.energies or ()))
    if (
        attack is None
        or any(value is None or value < 0 for value in cost)
        or not _nacr_energy_supported(pokemon)
    ):
        return None
    for required in sorted(value for value in cost if value != 0):
        try:
            available.remove(required)
        except ValueError:
            return None
    if len(available) < sum(value == 0 for value in cost):
        return None
    return cost


def _nacr_owner_index(obs, pokemon):
    serial = _nac_serial(pokemon)
    if serial is None:
        return None
    matches = []
    for index, player in enumerate(obs.current.players):
        if any(
            candidate is not None and _nac_serial(candidate) == serial
            for candidate in tuple(player.active or ()) + tuple(player.bench or ())
        ):
            matches.append(index)
    return matches[0] if len(matches) == 1 else None


def _nacr_available_attack_rows(obs, attacker):
    data = CARD_DB.get(getattr(attacker, "id", None))
    if data is None or _nac_serial(attacker) is None:
        return None
    rows = [
        (attack_id, "PRINTED", _nac_serial(attacker), None)
        for attack_id in tuple(getattr(data, "attacks", None) or ())
    ]
    owner = _nacr_owner_index(obs, attacker)
    if owner not in (0, 1):
        return None
    memory_sources = []
    player = obs.current.players[owner]
    for source in tuple(player.active or ()) + tuple(player.bench or ()):
        if source is None:
            continue
        texts = _nacr_skill_texts(source)
        serial = _nac_serial(source)
        if texts is None or serial is None:
            return None
        if any(
            "each of your evolved pokemon can use any attack from its previous evolutions"
            in text
            and "necessary energy" in text
            for text in texts
        ):
            if not _h5v2_visible_serial_is_unique(obs, serial):
                return None
            memory_sources.append(serial)
    if memory_sources and tuple(getattr(attacker, "preEvolution", None) or ()):
        memory_source = min(memory_sources)
        for prior in tuple(attacker.preEvolution or ()):
            prior_data = CARD_DB.get(getattr(prior, "id", None))
            prior_serial = _nac_serial(prior)
            if (
                prior_data is None
                or prior_serial is None
                or not _h5v2_visible_serial_is_unique(obs, prior_serial)
            ):
                return None
            rows.extend(
                (
                    attack_id,
                    "VISIBLE_PREVIOUS_EVOLUTION",
                    prior_serial,
                    memory_source,
                )
                for attack_id in tuple(getattr(prior_data, "attacks", None) or ())
            )
    deduplicated = {}
    for row in rows:
        deduplicated.setdefault(row[0], row)
    return tuple(deduplicated[key] for key in sorted(deduplicated))


def _nacr_self_attack_locked(attacker, attack_id):
    if (
        _nac_serial(attacker) != _opp_last_attack_serial
        or attack_id != _opp_last_attack_id
    ):
        return False
    attack = ALL_ATTACKS.get(attack_id)
    if attack is None:
        return True
    text = _nacr_text(getattr(attack, "text", None))
    name = _nacr_text(getattr(attack, "name", None))
    return (
        "during your next turn" in text
        and ("can't use" in text or "cannot use" in text)
        and (
            "can't use attacks" in text
            or "cannot use attacks" in text
            or (name and name in text)
        )
    )


def _nacr_public_retreat_legality(obs, attacker, attack_effect):
    if attack_effect.get("opponent_cant_retreat"):
        return False
    opponent = opp_state(obs)
    if bool(getattr(opponent, "asleep", False)) or bool(
        getattr(opponent, "paralyzed", False)
    ):
        return False
    owner = _nacr_owner_index(obs, attacker)
    if owner not in (0, 1) or owner != 1 - obs.current.yourIndex:
        return None
    for source in tuple(opponent.active or ()) + tuple(opponent.bench or ()):
        if source is None:
            return None
        texts = _nacr_skill_texts(source)
        if texts is None:
            return None
        for text in texts:
            if "can't retreat" not in text and "cannot retreat" not in text:
                continue
            if (
                _nac_serial(source) == _nac_serial(attacker)
                and "this pokemon" in text
            ):
                return False
            return None
        for attached in tuple(source.tools or ()) + tuple(source.energyCards or ()):
            texts = _nacr_skill_texts(attached)
            if texts is None:
                return None
            if any(
                "can't retreat" in text or "cannot retreat" in text
                for text in texts
            ):
                if _nac_serial(source) == _nac_serial(attacker):
                    return False
                return None
    for stadium in tuple(obs.current.stadium or ()):
        texts = _nacr_skill_texts(stadium)
        if texts is None:
            return None
        if any(
            "can't retreat" in text or "cannot retreat" in text
            for text in texts
        ):
            return None
    data = CARD_DB.get(getattr(attacker, "id", None))
    cost = _nac_int(getattr(data, "retreatCost", None)) if data else None
    if cost is None or cost < 0 or not _nacr_energy_supported(attacker):
        return None
    return len(tuple(attacker.energies or ())) >= cost


def _nacr_stadium_reduction(obs, target):
    stadium = tuple(obs.current.stadium or ())
    if len(stadium) > 1:
        return None
    reduction = 0
    for card in stadium:
        texts = _nacr_skill_texts(card)
        data = CARD_DB.get(getattr(card, "id", None))
        if (
            texts is None
            or data is None
            or _nac_int(getattr(data, "cardType", None)) != 4
            or _nac_serial(card) is None
        ):
            return None
        for text in texts:
            if not _nacr_material_text(text):
                continue
            if (
                "take 30 less damage" in text
                and "weakness and resistance" in text
                and ("{m}" in text or "metal pokemon" in text)
            ):
                target_data = CARD_DB.get(getattr(target, "id", None))
                if target_data is None:
                    return None
                if _nac_int(target_data.energyType) == METAL_ENERGY:
                    reduction += 30
                continue
            return None
    return reduction


def _nacr_local_modifiers_supported(obs, attacker, target):
    involved = {_nac_serial(attacker), _nac_serial(target)}
    if None in involved:
        return False
    for player in obs.current.players:
        pokemon = tuple(player.active or ()) + tuple(player.bench or ())
        for card in pokemon:
            if card is None or CARD_DB.get(getattr(card, "id", None)) is None:
                return False
            texts = _nacr_skill_texts(card)
            if texts is None:
                return False
            for text in texts:
                if not _nacr_material_text(text):
                    continue
                local = "this pokemon" in text
                bench_only = (
                    "benched pokemon" in text and "active pokemon" not in text
                )
                if _nac_serial(card) in involved or not (local or bench_only):
                    return False
            for attached in tuple(card.tools or ()):
                attached_texts = _nacr_skill_texts(attached)
                attached_data = CARD_DB.get(getattr(attached, "id", None))
                if (
                    _nac_serial(attached) is None
                    or attached_texts is None
                    or attached_data is None
                    or _nac_int(getattr(attached_data, "cardType", None)) != 2
                    or any(_nacr_material_text(text) for text in attached_texts)
                ):
                    return False
            if not _nacr_energy_supported(card):
                return False
    return _nacr_stadium_reduction(obs, target) is not None


def _nacr_attack_effect(attack):
    text = _nacr_text(getattr(attack, "text", None))
    defense = ()
    opponent_cant_retreat = (
        ("during your opponent's next turn" in text or "during the next turn" in text)
        and (
            "defending pokemon can't retreat" in text
            or "defending pokemon cannot retreat" in text
            or "active pokemon can't retreat" in text
            or "active pokemon cannot retreat" in text
        )
    )
    next_turn = (
        "during your opponent's next turn" in text
        or "during the next turn" in text
    )
    if next_turn and "has no weakness" in text:
        defense = (("no_weakness", True),)
    elif (
        next_turn
        and "prevent all damage" in text
        and "basic pokemon" in text
    ):
        defense = (("prevent_basic_damage", True),)
    elif next_turn and any(
        token in text
        for token in ("damage", "weakness", "resistance", "attacks cost")
    ):
        return None
    if any(
        token in text
        for token in (
            "active pokemon is now poisoned",
            "active pokemon is now burned",
            "active pokemon is now asleep",
            "active pokemon is now paralyzed",
            "active pokemon is now confused",
            "active pokemon can't attack",
            "active pokemon cannot attack",
        )
    ):
        return None
    return {
        "text": text,
        "defense": defense,
        "opponent_cant_retreat": opponent_cant_retreat,
    }


def _nacr_attack_damage(
    obs,
    attacker,
    attack_id,
    target,
    *,
    projected_attacker_hp=None,
    defense=(),
):
    attacker_data = CARD_DB.get(getattr(attacker, "id", None))
    target_data = CARD_DB.get(getattr(target, "id", None))
    attack = ALL_ATTACKS.get(attack_id)
    effect = _nacr_attack_effect(attack) if attack is not None else None
    if (
        attacker_data is None
        or target_data is None
        or attack is None
        or effect is None
        or (
            (available_attacks := _nacr_available_attack_rows(obs, attacker))
            is None
        )
        or attack_id not in {row[0] for row in available_attacks}
        or _nacr_paid_energy(attacker, attack_id) is None
        or not _nacr_local_modifiers_supported(obs, attacker, target)
    ):
        return None
    text = effect["text"]
    if any(token in text for token in ("flip ", "coin", "at random", "randomly")):
        return None
    base = _nac_int(getattr(attack, "damage", None))
    hp = attacker.hp if projected_attacker_hp is None else projected_attacker_hp
    if base is None or base < 0 or hp <= 0:
        return None
    formula = "printed_fixed_damage"
    if (
        text.startswith("place ")
        and "damage counters on your opponent's active pokemon" in text
        and "for each card in your hand" in text
    ):
        try:
            counters = int(text.split()[1])
        except (IndexError, TypeError, ValueError):
            return None
        owner = _nacr_owner_index(obs, attacker)
        hand_count = (
            getattr(obs.current.players[owner], "handCount", None)
            if owner in (0, 1)
            else None
        )
        if not isinstance(hand_count, int) or hand_count < 0:
            return None
        damage = counters * 10 * hand_count
        formula = "hand_damage_counters"
    elif (
        "10 more damage for each damage counter on this pokemon" in text
    ):
        damage = base + max(0, attacker.maxHp - hp)
        formula = "self_damage_counters"
    else:
        if (
            "more damage" in text
            or "less damage" in text
            or "damage for each" in text
            or "damage times" in text
            or "does nothing" in text
            or (
                "damage counters" in text
                and "benched pokemon" not in text
            )
        ):
            return None
        damage = base
        ignore_all = (
            "damage isn't affected by weakness or resistance" in text
            and "effects on your opponent's active pokemon" in text
        )
        if not ignore_all:
            attacker_type = _nac_int(getattr(attacker_data, "energyType", None))
            weakness = _nac_int(getattr(target_data, "weakness", None))
            resistance = _nac_int(getattr(target_data, "resistance", None))
            if not dict(defense).get("no_weakness") and attacker_type == weakness:
                damage *= 2
            if attacker_type == resistance:
                damage = max(0, damage - 30)
            reduction = _nacr_stadium_reduction(obs, target)
            if reduction is None:
                return None
            damage = max(0, damage - reduction)
    if (
        dict(defense).get("prevent_basic_damage")
        and bool(getattr(attacker_data, "basic", False))
    ):
        damage = 0
    return {
        "attack_id": attack_id,
        "damage": damage,
        "effect_text": effect["text"],
        "defense": effect["defense"],
        "opponent_cant_retreat": effect["opponent_cant_retreat"],
        "formula": formula,
    }


def _nacr_bench_damage_proof(obs, attack, rotated_source):
    text = _nacr_text(getattr(attack, "text", None))
    if "benched pokemon" not in text:
        return {"damage": 0, "mode": "NONE"}
    damage_match = re.search(
        r"(?:also )?does (\d+) damage to "
        r"(?:\d+|1 of) your opponent's benched pokemon",
        text,
    )
    counter_match = re.search(
        r"(?:put|place) (\d+) damage counters? on "
        r"(?:\d+|1 of) your opponent's benched pokemon",
        text,
    )
    if damage_match is not None:
        damage = int(damage_match.group(1))
        mode = "FIXED_BENCH_DAMAGE"
    elif counter_match is not None:
        damage = 10 * int(counter_match.group(1))
        mode = "FIXED_BENCH_COUNTERS"
    elif "damage" in text or "damage counter" in text:
        return None
    else:
        return {"damage": 0, "mode": "NONE"}
    if damage < 0 or rotated_source is None:
        return None
    mine = my_state(obs)
    for source in tuple(mine.active or ()) + tuple(mine.bench or ()):
        if source is None:
            return None
        for card in (source,) + tuple(source.tools or ()) + tuple(
            source.energyCards or ()
        ):
            texts = _nacr_skill_texts(card)
            if texts is None:
                return None
            if any(
                "benched pokemon" in modifier
                and (
                    "damage" in modifier
                    or "damage counter" in modifier
                )
                for modifier in texts
            ):
                return None
    for stadium in tuple(obs.current.stadium or ()):
        texts = _nacr_skill_texts(stadium)
        if texts is None:
            return None
        if any(
            "benched pokemon" in modifier
            and ("damage" in modifier or "damage counter" in modifier)
            for modifier in texts
        ):
            return None
    return {"damage": damage, "mode": mode}


def _nacr_prize_value(pokemon):
    data = CARD_DB.get(getattr(pokemon, "id", None))
    texts = _nacr_skill_texts(pokemon)
    if data is None or texts is None or any("prize card" in text for text in texts):
        return None
    for tool in tuple(pokemon.tools or ()):
        tool_texts = _nacr_skill_texts(tool)
        if tool_texts is None or any("prize card" in text for text in tool_texts):
            return None
    if bool(getattr(data, "megaEx", False)):
        return 3
    if bool(getattr(data, "ex", False)):
        return 2
    return 1


def _nacr_attack_key(proof):
    if proof is None:
        return None
    return (
        proof["attack_id"],
        proof["damage"],
        proof["effect_text"],
        proof["defense"],
    )


def _nacr_reply_rows(
    obs,
    opponent_after_attack,
    current,
    backup,
    attack_effect,
    *,
    rotated_source=None,
):
    rotated_source = current if rotated_source is None else rotated_source
    if opponent_after_attack is not None:
        routes = [("SURVIVING_ACTIVE", opponent_after_attack)]
        retreat = _nacr_public_retreat_legality(
            obs, opponent_after_attack, attack_effect
        )
        if retreat is None:
            return None
        if retreat:
            routes.extend(
                ("BENCH_AFTER_PUBLIC_RETREAT", pokemon)
                for pokemon in (opp_state(obs).bench or ())
                if pokemon is not None
            )
    else:
        routes = [
            ("BENCH_PROMOTION_AFTER_KO", pokemon)
            for pokemon in (opp_state(obs).bench or ())
            if pokemon is not None
        ]
    rows = []
    for route, attacker in routes:
        data = CARD_DB.get(getattr(attacker, "id", None))
        serial = _nac_serial(attacker)
        attack_rows = _nacr_available_attack_rows(obs, attacker)
        if (
            data is None
            or serial is None
            or not _h5v2_visible_serial_is_unique(obs, serial)
            or not _nacr_energy_supported(attacker)
            or attack_rows is None
        ):
            return None
        projected_hp = attacker.hp
        for attack_id, origin, origin_serial, memory_source in attack_rows:
            if _nacr_paid_energy(attacker, attack_id) is None:
                continue
            if _nacr_self_attack_locked(attacker, attack_id):
                continue
            active_proof = _nacr_attack_damage(
                obs,
                attacker,
                attack_id,
                current,
                projected_attacker_hp=projected_hp,
                defense=attack_effect["defense"],
            )
            backup_proof = _nacr_attack_damage(
                obs,
                attacker,
                attack_id,
                backup,
                projected_attacker_hp=projected_hp,
                defense=attack_effect["defense"],
            )
            bench_proof = _nacr_bench_damage_proof(
                obs, ALL_ATTACKS.get(attack_id), rotated_source
            )
            if (
                active_proof is None
                or backup_proof is None
                or bench_proof is None
            ):
                return None
            rows.append(
                (
                    route,
                    serial,
                    attack_id,
                    origin,
                    origin_serial,
                    memory_source,
                    active_proof["damage"],
                    backup_proof["damage"],
                    bench_proof["damage"],
                    bench_proof["mode"],
                    active_proof["effect_text"],
                    active_proof["formula"],
                )
            )
    return tuple(sorted(rows, key=repr))


def _nacr_frozen_material(obs):
    return (
        _sat_material_fp(obs),
        tuple(len(player.prize or ()) for player in obs.current.players),
        bool(obs.current.supporterPlayed),
        bool(obs.current.energyAttached),
        bool(obs.current.stadiumPlayed),
        bool(obs.current.retreated),
        (_opp_last_attack_id, _opp_last_attack_serial),
    )


def _nacr_pokemon_structure(pokemon):
    if pokemon is None:
        return None
    return (
        getattr(pokemon, "id", None),
        _nac_serial(pokemon),
        getattr(pokemon, "hp", None),
        getattr(pokemon, "maxHp", None),
        bool(getattr(pokemon, "appearThisTurn", False)),
        tuple(_nac_card_fp(card) for card in (pokemon.tools or ())),
        tuple(_nac_card_fp(card) for card in (pokemon.preEvolution or ())),
    )


def _nacr_build(obs, parent_action):
    global _nacr_transaction, _nacr_last_rejection
    if not _nac_strict_main(obs):
        return _nac_reject("_nacr", "activation_boundary")
    parent_option = _nac_parent_option(obs, parent_action)
    if parent_option is None or parent_option.type != OptionType.ATTACK:
        return _nac_reject("_nacr", "parent_not_attack")
    attack_id = parent_option.attackId
    active = active_pokemon(obs)
    opponent = opp_active_pokemon(obs)
    if (
        active is None
        or active.id != ARCHALUDON_EX
        or opponent is None
        or opponent.id != 1031
        or _nac_has_status(my_state(obs))
        or _nac_has_status(opp_state(obs))
        or not _nac_basic_metal_pokemon(active, exact_count=3)
        or not _nac_known_tool_only(active)
        or not _h2_energy_ready(active, METAL_DEFENDER)
        or len(obs.current.stadium or ()) != 1
        or obs.current.stadium[0].id != FULL_METAL_LAB
        or not _nac_exact_skill(
            FULL_METAL_LAB,
            "Full Metal Lab",
            "{M} Pokémon (both yours and your opponent’s) take 30 less damage from attacks from the opponent’s Pokémon (after applying Weakness and Resistance).",
        )
    ):
        return _nac_reject("_nacr", "public_damage_state_not_supported")
    own_damage = _h2_metal_defender_damage(obs, opponent)
    if own_damage is None or own_damage >= opponent.hp:
        return _nac_reject("_nacr", "terminal_or_unknown_own_attack")
    active_rows = _nacr_starmie_damage_rows(obs, active)
    if not active_rows or not any(damage >= active.hp for _, damage in active_rows):
        return _nac_reject("_nacr", "active_not_in_visible_payable_ko_range")
    candidates = []
    for pokemon in (my_state(obs).bench or ()):
        if (
            pokemon is not None
            and pokemon.id == ARCHALUDON_EX
            and _nac_basic_metal_pokemon(pokemon, exact_count=3)
            and _nac_known_tool_only(pokemon)
            and _h2_energy_ready(pokemon, METAL_DEFENDER)
        ):
            rows = _nacr_starmie_damage_rows(obs, pokemon)
            if rows and all(damage < pokemon.hp for _, damage in rows):
                candidates.append(pokemon)
    if len(candidates) != 1:
        return _nac_reject("_nacr", "healthy_ready_backup_not_unique")
    retreat_positions = _nac_positions(obs, option_type=OptionType.RETREAT)
    attack_positions = _nac_positions(
        obs, option_type=OptionType.ATTACK, attack_id=METAL_DEFENDER
    )
    if len(retreat_positions) != 1 or len(attack_positions) != 1:
        return _nac_reject("_nacr", "retreat_or_attack_binding_ambiguous")
    transaction = {
        "rule_id": _NAC_ROTATION_RULE_ID,
        "stage": _NACR_RETREAT,
        "game_epoch": globals().get("_cum_game_epoch"),
        "seat": obs.current.yourIndex,
        "first_player": obs.current.firstPlayer,
        "turn": obs.current.turn,
        "active_serial": _nac_serial(active),
        "backup_serial": _nac_serial(candidates[0]),
        "backup_fp": _nac_pokemon_fp(candidates[0]),
        "opponent_fp": _nac_pokemon_fp(opponent),
        "attack_id": METAL_DEFENDER,
    }
    _nacr_transaction = transaction
    _nacr_last_rejection = None
    return [retreat_positions[0]]


def _nacr_build_general(obs, parent_action):
    global _nacr_transaction, _nacr_last_rejection
    if not _nac_strict_main(obs):
        return _nac_reject("_nacr", "activation_boundary")
    parent_option = _nac_parent_option(obs, parent_action)
    if parent_option is None or parent_option.type != OptionType.ATTACK:
        return _nac_reject("_nacr", "parent_not_attack")
    attack_id = parent_option.attackId
    active = active_pokemon(obs)
    opponent = opp_active_pokemon(obs)
    if (
        active is None
        or opponent is None
        or _nac_has_status(my_state(obs))
        or _nac_has_status(opp_state(obs))
        or _nac_serial(active) is None
        or _nac_serial(opponent) is None
        or not _h5v2_visible_serial_is_unique(obs, _nac_serial(active))
        or not _h5v2_visible_serial_is_unique(obs, _nac_serial(opponent))
    ):
        return _nac_reject("_nacr", "public_identity_or_status_not_supported")
    own_proof = _nacr_attack_damage(obs, active, attack_id, opponent)
    prize = _nacr_prize_value(opponent)
    if own_proof is None or prize is None:
        return _nac_reject("_nacr", "own_attack_or_prize_not_supported")
    own_ko = own_proof["damage"] >= opponent.hp
    immediate_prize = prize if own_ko else 0
    if own_ko and (
        immediate_prize >= len(my_state(obs).prize or ())
        or not (opp_state(obs).bench or ())
    ):
        return _nac_reject("_nacr", "terminal_or_game_winning_attack")
    retreat_positions = _nac_positions(obs, option_type=OptionType.RETREAT)
    attack_positions = _nac_positions(
        obs, option_type=OptionType.ATTACK, attack_id=attack_id
    )
    if len(retreat_positions) != 1 or len(attack_positions) != 1:
        return _nac_reject("_nacr", "retreat_or_attack_binding_ambiguous")
    candidates = []
    for pokemon in (my_state(obs).bench or ()):
        if pokemon is None or _nac_serial(pokemon) is None:
            continue
        proof = _nacr_attack_damage(obs, pokemon, attack_id, opponent)
        if _nacr_attack_key(proof) == _nacr_attack_key(own_proof):
            candidates.append((pokemon, proof))
    if len(candidates) != 1:
        return _nac_reject("_nacr", "same_attack_ready_backup_not_unique")
    backup = candidates[0][0]
    opponent_after_attack = copy.deepcopy(opponent) if not own_ko else None
    if opponent_after_attack is not None:
        opponent_after_attack.hp -= own_proof["damage"]
    replies = _nacr_reply_rows(
        obs,
        opponent_after_attack,
        active,
        backup,
        own_proof,
    )
    if replies is None:
        return _nac_reject("_nacr", "visible_reply_set_not_supported")
    if not any(row[6] >= active.hp for row in replies):
        return _nac_reject("_nacr", "current_active_survives_all_replies")
    if any(row[7] >= backup.hp for row in replies):
        return _nac_reject("_nacr", "backup_dies_to_visible_reply")
    if any(row[8] >= active.hp for row in replies):
        return _nac_reject("_nacr", "rotated_source_dies_to_bench_effect")
    transaction = {
        "rule_id": _NAC_ROTATION_RULE_ID,
        "stage": _NACR_RETREAT,
        "game_epoch": globals().get("_cum_game_epoch"),
        "seat": obs.current.yourIndex,
        "first_player": obs.current.firstPlayer,
        "turn": obs.current.turn,
        "active_serial": _nac_serial(active),
        "active_fp": _nac_pokemon_fp(active),
        "active_structure": _nacr_pokemon_structure(active),
        "backup_serial": _nac_serial(backup),
        "backup_fp": _nac_pokemon_fp(backup),
        "other_bench": tuple(sorted(
            (
                _nac_pokemon_fp(pokemon)
                for pokemon in (my_state(obs).bench or ())
                if pokemon is not None and _nac_serial(pokemon) != _nac_serial(backup)
            ),
            key=repr,
        )),
        "opponent_fp": _nac_pokemon_fp(opponent),
        "attack_id": attack_id,
        "attack_key": _nacr_attack_key(own_proof),
        "attack_ko": own_ko,
        "immediate_prize": immediate_prize,
        "prize_counts": tuple(
            len(player.prize or ()) for player in obs.current.players
        ),
        "opponent_board": _h5v2_board_fingerprint(opp_state(obs)),
        "reply_rows": replies,
        "reply_backup_rows": tuple(
            row[:6] + row[7:] for row in replies
        ),
        "frozen_material": _nacr_frozen_material(obs),
        "pre_action_count": obs.current.turnActionCount,
    }
    _nacr_transaction = transaction
    _nacr_last_rejection = None
    return [retreat_positions[0]]


def _nacr_resume(obs):
    global _nacr_transaction
    transaction = _nacr_transaction
    if transaction is None:
        return None
    if not _nac_identity_valid(obs, transaction):
        _nacr_reset("identity_or_result_change")
        return None
    stage = transaction["stage"]
    if stage == _NACR_RETREAT:
        positions = _nac_card_positions(obs, transaction["backup_serial"])
        if len(positions) != 1:
            _nacr_reset("retreat_target_missing_or_ambiguous")
            return None
        transaction["stage"] = _NACR_TARGET
        return [positions[0]]
    if stage == _NACR_TARGET:
        active = active_pokemon(obs)
        if (
            not _nac_strict_main(obs)
            or active is None
            or _nac_serial(active) != transaction["backup_serial"]
            or _nac_pokemon_fp(active) != transaction["backup_fp"]
            or not obs.current.retreated
            or _nac_pokemon_fp(opp_active_pokemon(obs)) != transaction["opponent_fp"]
            or not _h2_energy_ready(active, transaction["attack_id"])
        ):
            _nacr_reset("post_retreat_attack_state_failed")
            return None
        positions = _nac_positions(
            obs,
            option_type=OptionType.ATTACK,
            attack_id=transaction["attack_id"],
        )
        if len(positions) != 1:
            _nacr_reset("same_attack_disappeared")
            return None
        transaction["stage"] = _NACR_ATTACK
        return [positions[0]]
    _nacr_reset("attack_emitted")
    return None


def _nacr_post_retreat_valid(obs, transaction):
    active = active_pokemon(obs)
    opponent = opp_active_pokemon(obs)
    old_active = _nac_find_own_pokemon(obs, transaction["active_serial"])
    other_bench = tuple(sorted(
        (
            _nac_pokemon_fp(pokemon)
            for pokemon in (my_state(obs).bench or ())
            if pokemon is not None
            and _nac_serial(pokemon) != transaction["active_serial"]
        ),
        key=repr,
    ))
    if (
        not _nac_strict_main(obs)
        or active is None
        or opponent is None
        or _nac_serial(active) != transaction["backup_serial"]
        or _nac_pokemon_fp(active) != transaction["backup_fp"]
        or _nac_pokemon_fp(opponent) != transaction["opponent_fp"]
        or _nacr_pokemon_structure(old_active) != transaction["active_structure"]
        or other_bench != transaction["other_bench"]
        or not obs.current.retreated
        or obs.current.turnActionCount != transaction["pre_action_count"] + 1
        or tuple(len(player.prize or ()) for player in obs.current.players)
        != transaction["prize_counts"]
        or _h5v2_board_fingerprint(opp_state(obs))
        != transaction["opponent_board"]
    ):
        return False
    proof = _nacr_attack_damage(
        obs, active, transaction["attack_id"], opponent
    )
    if _nacr_attack_key(proof) != transaction["attack_key"]:
        return False
    own_ko = proof["damage"] >= opponent.hp
    immediate_prize = (
        _nacr_prize_value(opponent) if own_ko else 0
    )
    if (
        own_ko != transaction["attack_ko"]
        or immediate_prize != transaction["immediate_prize"]
        or (
            own_ko
            and (
                immediate_prize >= len(my_state(obs).prize or ())
                or not (opp_state(obs).bench or ())
            )
        )
    ):
        return False
    opponent_after_attack = copy.deepcopy(opponent) if not own_ko else None
    if opponent_after_attack is not None:
        opponent_after_attack.hp -= proof["damage"]
    replies = _nacr_reply_rows(
        obs,
        opponent_after_attack,
        active,
        active,
        proof,
        rotated_source=old_active,
    )
    if (
        replies is None
        or any(row[7] >= active.hp for row in replies)
        or any(row[8] >= old_active.hp for row in replies)
    ):
        return False
    return tuple(
        row[:6] + row[7:] for row in replies
    ) == transaction["reply_backup_rows"]


def _nacr_resume_general(obs):
    global _nacr_transaction
    transaction = _nacr_transaction
    if transaction is None:
        return None
    if not _nac_identity_valid(obs, transaction):
        _nacr_reset("identity_or_result_change")
        return None
    stage = transaction["stage"]
    if stage == _NACR_RETREAT:
        if (
            _nacr_frozen_material(obs) != transaction["frozen_material"]
            or obs.select.context not in {
                SelectContext.SWITCH,
                SelectContext.TO_ACTIVE,
            }
        ):
            _nacr_reset("retreat_callback_material_changed")
            return None
        positions = _nac_card_positions(obs, transaction["backup_serial"])
        if len(positions) != 1:
            _nacr_reset("retreat_target_missing_or_ambiguous")
            return None
        transaction["stage"] = _NACR_TARGET
        return [positions[0]]
    if stage == _NACR_TARGET:
        current = active_pokemon(obs)
        if (
            current is not None
            and _nac_serial(current) == transaction["active_serial"]
            and obs.select.context in {
                SelectContext.SWITCH,
                SelectContext.TO_ACTIVE,
            }
            and _nacr_frozen_material(obs) == transaction["frozen_material"]
        ):
            positions = _nac_card_positions(obs, transaction["backup_serial"])
            if len(positions) == 1:
                return [positions[0]]
            _nacr_reset("duplicate_retreat_target_ambiguous")
            return None
        if not _nacr_post_retreat_valid(obs, transaction):
            _nacr_reset("post_retreat_attack_state_failed")
            return None
        positions = _nac_positions(
            obs,
            option_type=OptionType.ATTACK,
            attack_id=transaction["attack_id"],
        )
        if len(positions) != 1:
            _nacr_reset("same_attack_disappeared")
            return None
        transaction["stage"] = _NACR_ATTACK
        return [positions[0]]
    if stage == _NACR_ATTACK:
        if not _nacr_post_retreat_valid(obs, transaction):
            _nacr_reset("attack_retry_revalidation_failed")
            return None
        positions = _nac_positions(
            obs,
            option_type=OptionType.ATTACK,
            attack_id=transaction["attack_id"],
        )
        if len(positions) == 1:
            return [positions[0]]
        _nacr_reset("attack_retry_ambiguous")
        return None
    _nacr_reset("unknown_stage")
    return None


_nacr_build = _nacr_build_general
_nacr_resume = _nacr_resume_general


def _nacr_choose(obs, parent_action):
    if _nacr_transaction is not None:
        return _nacr_resume_general(obs)
    return _nacr_build_general(obs, parent_action)


# -- 5. Preserve a one-prize active pivot by routing the ex evolution --------

_NACE_EVOLVE = "EVOLUTION_EMITTED"
_NACE_YES = "ALLOY_YES_EMITTED"
_NACE_ENERGY = "ALLOY_ENERGY_SELECTED"
_NACE_TARGET = "ALLOY_TARGET_EMITTED"


def _nace_exact_discard_metals(obs):
    return [
        card for card in (my_state(obs).discard or ()) if _nac_basic_metal(card)
    ]


def _nace_build(obs, parent_action):
    global _nace_transaction, _nace_last_rejection
    if not _nac_strict_main(obs):
        return _nac_reject("_nace", "activation_boundary")
    parent_option = _nac_parent_option(obs, parent_action)
    parent_card = option_card(obs, parent_option) if parent_option else None
    parent_target = option_target(obs, parent_option) if parent_option else None
    active = active_pokemon(obs)
    if (
        parent_option is None
        or parent_option.type != OptionType.EVOLVE
        or getattr(parent_card, "id", None) != ARCHALUDON_EX
        or parent_target is None
        or active is None
        or _nac_serial(parent_target) != _nac_serial(active)
        or active.id != DURALUDON
        or not _nac_basic_metal_pokemon(active, exact_count=0)
        or active.tools
        or _nac_has_status(my_state(obs))
        or _nac_has_status(opp_state(obs))
        or any(
            option.type in {OptionType.RETREAT, OptionType.ATTACK}
            for option in obs.select.option
        )
    ):
        return _nac_reject("_nace", "parent_not_stranded_active_ex_evolution")
    if not _nac_exact_skill(
        ARCHALUDON_EX,
        "Assemble Alloy",
        "When you play this Pokémon from your hand to evolve 1 of your Pokémon during your turn, you may attach up to 2 Basic {M} Energy cards from your discard pile to your {M} Pokémon in any way you like.",
    ):
        return _nac_reject("_nace", "assemble_alloy_metadata_changed")
    metals = _nace_exact_discard_metals(obs)
    if len(metals) != 1:
        return _nac_reject("_nace", "discard_metal_proof_not_exact")
    if len(active.energyCards or ()) + len(metals) >= 3:
        return _nac_reject("_nace", "active_evolution_becomes_attack_ready")
    candidates = [
        pokemon
        for pokemon in (my_state(obs).bench or ())
        if (
            pokemon is not None
            and pokemon.id == DURALUDON
            and not pokemon.tools
            and _nac_basic_metal_pokemon(pokemon, exact_count=1)
            and len(pokemon.energyCards or ()) + len(metals) == 2
        )
    ]
    if len(candidates) != 1:
        return _nac_reject("_nace", "nearer_ready_bench_route_not_unique")
    target = candidates[0]
    active_serials = {
        _nac_serial(option_card(obs, option))
        for option in obs.select.option
        if (
            option.type == OptionType.EVOLVE
            and getattr(option_card(obs, option), "id", None) == ARCHALUDON_EX
            and _nac_serial(option_target(obs, option)) == _nac_serial(active)
        )
    }
    bench_serials = {
        _nac_serial(option_card(obs, option))
        for option in obs.select.option
        if (
            option.type == OptionType.EVOLVE
            and getattr(option_card(obs, option), "id", None) == ARCHALUDON_EX
            and _nac_serial(option_target(obs, option)) == _nac_serial(target)
        )
    }
    shared_serials = sorted(
        serial for serial in active_serials & bench_serials if serial is not None
    )
    if not shared_serials:
        return _nac_reject("_nace", "bench_evolution_binding_ambiguous")
    evolution_serial = shared_serials[0]
    positions = _nac_positions(
        obs,
        option_type=OptionType.EVOLVE,
        card_id=ARCHALUDON_EX,
        card_serial=evolution_serial,
        target_serial=_nac_serial(target),
    )
    if len(positions) != 1:
        return _nac_reject("_nace", "bench_evolution_binding_ambiguous")
    transaction = {
        "rule_id": _NAC_EVOLUTION_RULE_ID,
        "stage": _NACE_EVOLVE,
        "game_epoch": globals().get("_cum_game_epoch"),
        "seat": obs.current.yourIndex,
        "first_player": obs.current.firstPlayer,
        "turn": obs.current.turn,
        "active_serial": _nac_serial(active),
        "target_serial": _nac_serial(target),
        "evolution_serial": evolution_serial,
        "metal_serial": _nac_serial(metals[0]),
    }
    _nace_transaction = transaction
    _nace_last_rejection = None
    return [positions[0]]


def _nace_evolved_target(obs, transaction):
    pokemon = _nac_find_own_pokemon(obs, transaction["evolution_serial"])
    return (
        pokemon
        if (
            pokemon is not None
            and pokemon.id == ARCHALUDON_EX
            and any(
                card.id == DURALUDON
                and _nac_serial(card) == transaction["target_serial"]
                for card in (pokemon.preEvolution or ())
            )
        )
        else None
    )


def _nace_resume(obs):
    global _nace_transaction
    transaction = _nace_transaction
    if transaction is None:
        return None
    if not _nac_identity_valid(obs, transaction):
        _nace_reset("identity_or_result_change")
        return None
    evolved = _nace_evolved_target(obs, transaction)
    stage = transaction["stage"]
    if stage == _NACE_EVOLVE:
        yes = _nac_positions(obs, option_type=OptionType.YES)
        no = _nac_positions(obs, option_type=OptionType.NO)
        if evolved is None or len(yes) != 1 or len(no) != 1:
            _nace_reset("bench_evolution_or_alloy_prompt_failed")
            return None
        transaction["stage"] = _NACE_YES
        return [yes[0]]
    if stage == _NACE_YES:
        positions = _nac_card_positions(obs, transaction["metal_serial"])
        if (
            evolved is None
            or len(positions) != 1
            or obs.select.minCount > 1
            or obs.select.maxCount < 1
        ):
            _nace_reset("alloy_energy_binding_failed")
            return None
        transaction["stage"] = _NACE_ENERGY
        return [positions[0]]
    if stage == _NACE_ENERGY:
        positions = _nac_card_positions(obs, transaction["evolution_serial"])
        if evolved is None or len(positions) != 1:
            _nace_reset("alloy_target_binding_failed")
            return None
        transaction["stage"] = _NACE_TARGET
        return [positions[0]]
    if stage == _NACE_TARGET:
        evolved = _nace_evolved_target(obs, transaction)
        if (
            evolved is None
            or transaction["metal_serial"]
            not in {_nac_serial(card) for card in (evolved.energyCards or ())}
        ):
            _nace_reset("alloy_attachment_not_confirmed")
        else:
            _nace_reset("alloy_route_complete")
        return None
    _nace_reset("unknown_stage")
    return None


def _nace_choose(obs, parent_action):
    if _nace_transaction is not None:
        return _nace_resume(obs)
    return _nace_build(obs, parent_action)


