def _pan_serial(card):
    serial = getattr(card, "serial", None)
    return serial if isinstance(serial, int) and serial > 0 else None


def _pan_visible_serials_complete(obs):
    serials = []
    for card in _h5v2_visible_cards(obs):
        serial = _pan_serial(card)
        if serial is None:
            return False
        serials.append(serial)
    return len(serials) == len(set(serials))


def _pan_energy_type(card):
    card_id = getattr(card, "id", None)
    if card_id in _H5V2_SAFE_ENERGY_IDS:
        return card_id
    if card_id == _PAN_TELEPATH_PSYCHIC_ENERGY:
        data = CARD_DB.get(card_id)
        skills = tuple(getattr(data, "skills", None) or ()) if data else ()
        if (
            data is None
            or getattr(data, "energyType", None) != 5
            or len(skills) != 1
            or getattr(skills[0], "name", None)
            != "Telepath Psychic Energy"
            or getattr(skills[0], "text", None)
            != (
                "As long as this card is attached to a Pokémon, it "
                "provides {P} Energy.\nWhen you attach this card from "
                "your hand to a {P} Pokémon, search your deck for up "
                "to 2 Basic {P} Pokémon and put them onto your Bench. "
                "Then, shuffle your deck."
            )
        ):
            return None
        return 5
    return None


def _pan_energy_rows(obs, pokemon, player_index):
    cards = getattr(pokemon, "energyCards", None)
    energies = getattr(pokemon, "energies", None)
    if cards is None or energies is None:
        return None
    cards = tuple(cards)
    energies = tuple(energies)
    if len(cards) != len(energies):
        return None
    rows = []
    seen = set()
    for card, energy_type in zip(cards, energies):
        serial = _pan_serial(card)
        public_type = _pan_energy_type(card)
        if (
            card is None
            or serial is None
            or serial in seen
            or getattr(card, "playerIndex", None) != player_index
            or public_type is None
            or public_type != energy_type
            or not _h5v2_visible_serial_is_unique(obs, serial)
        ):
            return None
        seen.add(serial)
        rows.append((serial, card.id, energy_type))
    return tuple(rows)


def _pan_pay_attack(energy_rows, attack):
    cost = _h5v2_attack_cost(attack)
    if cost is None:
        return None
    available = list(energy_rows)
    paid = []
    for required in sorted(value for value in cost if value != 0):
        match = next(
            (
                index
                for index, row in enumerate(available)
                if row[2] == required
            ),
            None,
        )
        if match is None:
            return ()
        paid.append(available.pop(match))
    colorless = sum(1 for value in cost if value == 0)
    if len(available) < colorless:
        return ()
    paid.extend(available[:colorless])
    return tuple(paid)


def _pan_conditions(player):
    return (
        bool(player.poisoned),
        bool(player.burned),
        bool(player.asleep),
        bool(player.paralyzed),
        bool(player.confused),
    )


def _pan_public_board_supported(obs):
    for player_index, player in enumerate(obs.current.players):
        pokemon = (
            ([player.active[0]] if player.active else [])
            + list(player.bench or ())
        )
        for card in pokemon:
            if (
                card is None
                or CARD_DB.get(card.id) is None
                or _pan_energy_rows(obs, card, player_index) is None
            ):
                return False
            tools = getattr(card, "tools", None)
            if tools is None:
                return False
            for tool in tools:
                if (
                    tool is None
                    or tool.id != HERO_CAPE
                    or getattr(tool, "playerIndex", None) != player_index
                    or _pan_serial(tool) is None
                    or not _h5v2_visible_serial_is_unique(obs, tool.serial)
                ):
                    return False
            texts = _h5v2_skill_texts(card)
            if texts is None:
                return False
            for text in texts:
                if any(
                    token in text
                    for token in (
                        "prize",
                        "damage",
                        "weakness",
                        "resistance",
                        "attack cost",
                        "attacks cost",
                        "can't attack",
                        "cannot attack",
                    )
                ):
                    return False
    stadium = tuple(obs.current.stadium or ())
    return (
        len(stadium) == 1
        and stadium[0].id == FULL_METAL_LAB
        and _pan_serial(stadium[0]) is not None
        and _h5v2_visible_serial_is_unique(obs, stadium[0].serial)
    )


def _pan_projected_archaludon(obs, active):
    duraludon = CARD_DB.get(DURALUDON)
    archaludon = CARD_DB.get(ARCHALUDON)
    tools = getattr(active, "tools", None)
    if (
        duraludon is None
        or archaludon is None
        or getattr(duraludon, "hp", None) != 130
        or getattr(archaludon, "hp", None) != 180
        or getattr(active, "maxHp", None) != 230
        or not isinstance(getattr(active, "hp", None), int)
        or active.hp <= 0
        or active.hp > active.maxHp
        or tools is None
        or len(tools) != 1
    ):
        return None
    tool = tools[0]
    if (
        getattr(tool, "id", None) != HERO_CAPE
        or getattr(tool, "playerIndex", None) != obs.current.yourIndex
        or _pan_serial(tool) is None
        or not _h5v2_visible_serial_is_unique(obs, tool.serial)
    ):
        return None
    damage = active.maxHp - active.hp
    projected_max_hp = 280
    projected_hp = projected_max_hp - damage
    if damage < 0 or damage % 10 or projected_hp <= 0:
        return None
    return {
        "damage": damage,
        "max_hp": projected_max_hp,
        "hp": projected_hp,
        "tool": (tool.id, tool.serial),
    }


def _pan_direct_damage(obs, attacker, attack_id):
    attacker_data = CARD_DB.get(getattr(attacker, "id", None))
    target_data = CARD_DB.get(ARCHALUDON)
    attack = ALL_ATTACKS.get(attack_id)
    if (
        attacker_data is None
        or target_data is None
        or attack is None
        or attack_id
        not in _PAN_SUPPORTED_SUCCESSOR_ATTACKS.get(
            getattr(attacker, "id", None), ()
        )
    ):
        return None
    text = getattr(attack, "text", None)
    base = getattr(attack, "damage", None)
    if not isinstance(text, str) or not isinstance(base, int) or base < 0:
        return None
    lowered = text.lower()
    if any(
        token in lowered for token in ("flip ", "coin", "random", "at random")
    ):
        return None
    if text:
        if (
            attack_id != RAGING_HAMMER
            or text != _PAN_SUPPORTED_DIRECT_ATTACK_TEXT[RAGING_HAMMER]
        ):
            return None
        damage = getattr(attacker, "maxHp", 0) - getattr(attacker, "hp", 0)
        if damage < 0 or damage % 10:
            return None
        base += damage
    attacker_type = getattr(attacker_data, "energyType", None)
    weakness = getattr(target_data, "weakness", None)
    resistance = getattr(target_data, "resistance", None)
    weakness = getattr(weakness, "value", weakness)
    resistance = getattr(resistance, "value", resistance)
    result = base * 2 if weakness == attacker_type else base
    if resistance == attacker_type:
        result = max(0, result - 30)
    stadium = tuple(obs.current.stadium or ())
    if (
        len(stadium) == 1
        and stadium[0].id == FULL_METAL_LAB
        and getattr(target_data, "energyType", None) == METAL_ENERGY
    ):
        result = max(0, result - 30)
    is_basic = bool(getattr(attacker_data, "basic", False))
    return {
        "attack_id": attack_id,
        "printed_damage": base,
        "unprotected_damage": result,
        "effective_damage": 0 if is_basic else result,
        "coated_prevention_applied": is_basic,
    }


def _pan_source_target_damage(obs, attacker_id, attack_id, target):
    attacker_data = CARD_DB.get(attacker_id)
    target_data = CARD_DB.get(getattr(target, "id", None))
    attack = ALL_ATTACKS.get(attack_id)
    active = active_pokemon(obs)
    if (
        attacker_data is None
        or target_data is None
        or attack is None
        or active is None
        or attack_id
        not in tuple(getattr(attacker_data, "attacks", None) or ())
        or not _pan_public_board_supported(obs)
        or not _h5v2_persistent_effects_supported()
    ):
        return None
    if attack_id == 223:
        base = 30
    elif attack_id == RAGING_HAMMER:
        damage = damage_on(active)
        if damage < 0 or damage % 10:
            return None
        base = 80 + damage
    elif attack_id == COATED_ATTACK:
        base = 120
    else:
        return None
    attacker_type = getattr(attacker_data, "energyType", None)
    weakness = getattr(target_data, "weakness", None)
    resistance = getattr(target_data, "resistance", None)
    weakness = getattr(weakness, "value", weakness)
    resistance = getattr(resistance, "value", resistance)
    result = base * 2 if weakness == attacker_type else base
    if resistance == attacker_type:
        result = max(0, result - 30)
    if (
        obs.current.stadium
        and obs.current.stadium[0].id == FULL_METAL_LAB
        and getattr(target_data, "energyType", None) == METAL_ENERGY
    ):
        result = max(0, result - 30)
    return result


def _pan_successor_envelope(obs, projected_hp):
    if (
        not isinstance(projected_hp, int)
        or projected_hp <= 0
        or any(_pan_conditions(opp_state(obs)))
        or not _h5v2_static_cards_supported()
        or not _pan_public_board_supported(obs)
        or not _h5v2_persistent_effects_supported()
    ):
        return None
    coated = ALL_ATTACKS.get(COATED_ATTACK)
    if (
        coated is None
        or getattr(coated, "damage", None) != 120
        or tuple(getattr(coated, "energies", None) or ())
        != (METAL_ENERGY, METAL_ENERGY, METAL_ENERGY)
        or (getattr(coated, "text", "") or "")
        != (
            "During your opponent’s next turn, prevent all damage done "
            "to this Pokémon by attacks from Basic Pokémon."
        )
    ):
        return None
    proof = []
    ready_count = 0
    opponent_index = 1 - obs.current.yourIndex
    for pokemon in tuple(opp_state(obs).bench or ()):
        data = CARD_DB.get(getattr(pokemon, "id", None))
        serial = _pan_serial(pokemon)
        tools = getattr(pokemon, "tools", None)
        prior = getattr(pokemon, "preEvolution", None)
        if (
            pokemon is None
            or data is None
            or serial is None
            or not _h5v2_visible_serial_is_unique(obs, serial)
            or tools is None
            or tuple(tools) != ()
            or prior is None
            or not _h5v2_attack_legality_supported(pokemon)
            or not isinstance(getattr(pokemon, "hp", None), int)
            or not isinstance(getattr(pokemon, "maxHp", None), int)
            or pokemon.hp <= 0
            or pokemon.hp > pokemon.maxHp
            or pokemon.maxHp != getattr(data, "hp", None)
            or (pokemon.maxHp - pokemon.hp) % 10
        ):
            return None
        for card in prior:
            if (
                card is None
                or getattr(card, "playerIndex", None) != opponent_index
                or _pan_serial(card) is None
                or not _h5v2_visible_serial_is_unique(obs, card.serial)
            ):
                return None
        energy_rows = _pan_energy_rows(obs, pokemon, opponent_index)
        attack_ids = getattr(data, "attacks", None)
        if energy_rows is None or attack_ids is None:
            return None
        payable = []
        for attack_id in tuple(attack_ids):
            attack = ALL_ATTACKS.get(attack_id)
            if attack is None:
                return None
            paid = _pan_pay_attack(energy_rows, attack)
            if paid is None:
                return None
            if not paid and tuple(getattr(attack, "energies", None) or ()):
                continue
            damage = _pan_direct_damage(obs, pokemon, attack_id)
            if damage is None:
                return None
            damage["paid_energy"] = paid
            if damage["effective_damage"] >= projected_hp:
                return None
            if (
                bool(getattr(data, "basic", False))
                and damage["unprotected_damage"] >= projected_hp
            ):
                return None
            payable.append(damage)
        if payable:
            ready_count += 1
        proof.append(
            {
                "serial": serial,
                "card_id": pokemon.id,
                "basic": bool(getattr(data, "basic", False)),
                "energy": energy_rows,
                "payable_attacks": tuple(payable),
                "maximum_effective_damage": max(
                    (
                        row["effective_damage"]
                        for row in payable
                    ),
                    default=None,
                ),
                "maximum_unprotected_damage": max(
                    (
                        row["unprotected_damage"]
                        for row in payable
                    ),
                    default=None,
                ),
            }
        )
    if ready_count < 1:
        return None
    return {
        "projected_hp": projected_hp,
        "ready_count": ready_count,
        "successors": tuple(proof),
    }


def _pan_public_key(obs):
    active = active_pokemon(obs)
    return {
        "game_epoch": _cum_game_epoch,
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "action_count": obs.current.turnActionCount,
        "energy_attached": bool(obs.current.energyAttached),
        "active_id": getattr(active, "id", None),
        "active_serial": _pan_serial(active),
        "energy_serials": tuple(
            _pan_serial(card)
            for card in (getattr(active, "energyCards", None) or ())
        ),
    }


def _pan_observe_attachment(obs):
    global _pan_attachment_evidence
    previous = _pan_previous_public
    current = _pan_public_key(obs)
    if (
        previous is None
        or previous["game_epoch"] != current["game_epoch"]
        or previous["seat"] != current["seat"]
        or previous["turn"] != current["turn"]
    ):
        _pan_attachment_evidence = None
        return
    matches = [
        entry
        for entry in obs.logs
        if (
            entry.type == LogType.ATTACH
            and entry.playerIndex == current["seat"]
            and entry.cardId == METAL_ENERGY
            and _pan_serial(entry) is not None
            and entry.cardIdTarget == DURALUDON
            and entry.serialTarget == current["active_serial"]
        )
    ]
    if (
        len(matches) != 1
        or previous["energy_attached"]
        or not current["energy_attached"]
        or previous["active_id"] != DURALUDON
        or current["active_id"] != DURALUDON
        or previous["active_serial"] != current["active_serial"]
    ):
        return
    energy_serial = matches[0].serial
    before = tuple(previous["energy_serials"])
    after = tuple(current["energy_serials"])
    if (
        energy_serial in before
        or energy_serial not in after
        or len(after) != len(before) + 1
        or sorted(after) != sorted(before + (energy_serial,))
    ):
        return
    _pan_attachment_evidence = {
        "game_epoch": current["game_epoch"],
        "seat": current["seat"],
        "turn": current["turn"],
        "active_serial": current["active_serial"],
        "energy_serial": energy_serial,
        "observed_action_count": current["action_count"],
    }


def _pan_attachment_valid(obs, active):
    evidence = _pan_attachment_evidence
    energy_serials = tuple(
        _pan_serial(card)
        for card in (getattr(active, "energyCards", None) or ())
    )
    return (
        evidence is not None
        and evidence["game_epoch"] == _cum_game_epoch
        and evidence["seat"] == obs.current.yourIndex
        and evidence["turn"] == obs.current.turn
        and evidence["active_serial"] == _pan_serial(active)
        and evidence["energy_serial"] in energy_serials
        and evidence["observed_action_count"] <= obs.current.turnActionCount
        and bool(obs.current.energyAttached)
    )


def _pan_main_context(obs):
    return (
        obs.current.result == -1
        and obs.select.context == SelectContext.MAIN
        and obs.select.effect is None
        and obs.select.contextCard is None
        and obs.select.minCount == 1
        and obs.select.maxCount == 1
    )


def _pan_source_target_valid(obs, target):
    opponent_index = 1 - obs.current.yourIndex
    data = CARD_DB.get(_PAN_SOURCE_TARGET)
    tools = getattr(target, "tools", None) if target else None
    prior = getattr(target, "preEvolution", None) if target else None
    energy = (
        _pan_energy_rows(obs, target, opponent_index)
        if target is not None
        else None
    )
    return (
        target is not None
        and data is not None
        and target.id == _PAN_SOURCE_TARGET
        and _pan_serial(target) is not None
        and _h5v2_visible_serial_is_unique(obs, target.serial)
        and target.hp == 110
        and target.maxHp == 140
        and getattr(data, "hp", None) == 140
        and not bool(getattr(target, "appearThisTurn", True))
        and tools is not None
        and tuple(tools) == ()
        and prior is not None
        and len(prior) == 1
        and prior[0].id == _PAN_SOURCE_TARGET_BASIC
        and getattr(prior[0], "playerIndex", None) == opponent_index
        and _pan_serial(prior[0]) is not None
        and _h5v2_visible_serial_is_unique(obs, prior[0].serial)
        and energy is not None
        and tuple(row[2] for row in energy) == (5,)
        and tuple(row[1] for row in energy) == (5,)
        and _h5v2_prize_value(target) == 1
    )


def _pan_build_certificate(obs, parent_action):
    if (
        not _pan_main_context(obs)
        or not _pan_visible_serials_complete(obs)
        or detect_matchup(obs) == "ogerpon"
        or final_prize_nonex_no_backup(obs)
    ):
        return None, "PUBLIC_OR_PRECEDENCE_GATE"
    mine = my_state(obs)
    opponent = opp_state(obs)
    active = active_pokemon(obs)
    target = opp_active_pokemon(obs)
    if (
        active is None
        or target is None
        or active.id != DURALUDON
        or bool(getattr(active, "appearThisTurn", True))
        or _pan_serial(active) is None
        or not _h5v2_visible_serial_is_unique(obs, active.serial)
        or any(_pan_conditions(mine))
        or any(_pan_conditions(opponent))
        or not _pan_source_target_valid(obs, target)
        or not _pan_attachment_valid(obs, active)
        or not _pan_public_board_supported(obs)
        or not _h5v2_persistent_effects_supported()
    ):
        return None, "ACTIVE_TARGET_OR_ATTACHMENT_GATE"
    active_energy = _pan_energy_rows(obs, active, obs.current.yourIndex)
    projected = _pan_projected_archaludon(obs, active)
    if (
        active_energy is None
        or tuple(row[1] for row in active_energy)
        != (METAL_ENERGY, METAL_ENERGY, METAL_ENERGY)
        or tuple(row[2] for row in active_energy)
        != (METAL_ENERGY, METAL_ENERGY, METAL_ENERGY)
        or projected is None
        or _h5v2_prize_value(active) != 1
    ):
        return None, "ACTIVE_RESOURCE_OR_HP_GATE"
    stadium = tuple(obs.current.stadium or ())
    if (
        len(stadium) != 1
        or stadium[0].id != FULL_METAL_LAB
        or _pan_serial(stadium[0]) is None
        or not _h5v2_visible_serial_is_unique(obs, stadium[0].serial)
    ):
        return None, "STADIUM_GATE"
    if not _h5v2_parent_is_inherited_raging(obs, parent_action):
        return None, "PARENT_NOT_RAGING_HAMMER"
    attack_options = _h5v2_attack_options(obs)
    if (
        len(attack_options) != 2
        or sorted(attack_id for _, attack_id in attack_options)
        != [223, RAGING_HAMMER]
        or len(_h5v2_attack_options(obs, RAGING_HAMMER)) != 1
    ):
        return None, "INHERITED_ATTACK_OPTIONS_GATE"
    inherited_routes = tuple(
        (
            attack_id,
            _pan_source_target_damage(obs, DURALUDON, attack_id, target),
        )
        for attack_id in (223, RAGING_HAMMER)
    )
    if (
        any(damage is None for _, damage in inherited_routes)
        or any(damage >= target.hp for _, damage in inherited_routes)
        or _h5v2_boss_options(obs)
    ):
        return None, "EQUAL_OR_HIGHER_ROUTE_GATE"
    active_evolutions = [
        option
        for option in obs.select.option
        if (
            option.type == OptionType.EVOLVE
            and option.inPlayArea == AreaType.ACTIVE
            and _pan_serial(option_target(obs, option)) == active.serial
        )
    ]
    if (
        len(active_evolutions) != 1
        or getattr(option_card(obs, active_evolutions[0]), "id", None)
        != ARCHALUDON
    ):
        return None, "ALTERNATIVE_EVOLUTION_ROUTE"
    evolution_options = _h5v2_evolution_options(
        obs, ARCHALUDON, active.serial
    )
    if len(evolution_options) != 1:
        return None, "EVOLUTION_NOT_UNIQUE"
    evolution_position, evolution_serial = evolution_options[0]
    evolution_card = option_card(obs, obs.select.option[evolution_position])
    if (
        evolution_card is None
        or getattr(evolution_card, "playerIndex", None)
        != obs.current.yourIndex
        or not _h5v2_visible_serial_is_unique(obs, evolution_serial)
        or _h5v2_prize_value(evolution_card) != 1
    ):
        return None, "EVOLUTION_PUBLIC_GATE"
    coated_damage = _pan_source_target_damage(
        obs, ARCHALUDON, COATED_ATTACK, target
    )
    if coated_damage != 120 or coated_damage < target.hp:
        return None, "COATED_DAMAGE_GATE"
    successor = _pan_successor_envelope(obs, projected["hp"])
    if successor is None:
        return None, "SAFE_SUCCESSOR_ENVELOPE"
    expected_hand = list(_h5v2_hand_fingerprint(mine))
    try:
        expected_hand.remove((ARCHALUDON, evolution_serial))
    except ValueError:
        return None, "EVOLUTION_NOT_IN_HAND"
    evolution_semantic = _cum_action_semantic(obs, [evolution_position])
    parent_semantic = _cum_action_semantic(obs, parent_action)
    if evolution_semantic is None or parent_semantic is None:
        return None, "OPTION_SEMANTIC_GATE"
    maximum_reply = max(
        (
            row["maximum_effective_damage"]
            for row in successor["successors"]
            if row["maximum_effective_damage"] is not None
        ),
        default=0,
    )
    return {
        "rule_id": _PAN_RULE_ID,
        "stage": "EVOLUTION_EMITTED",
        "game_epoch": _cum_game_epoch,
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "turn_action_count": obs.current.turnActionCount,
        "prizes": (
            len(mine.prize or ()),
            len(opponent.prize or ()),
        ),
        "active": _h5v2_pokemon_fingerprint(active),
        "active_serial": active.serial,
        "active_energy": active_energy,
        "active_damage": projected["damage"],
        "projected_max_hp": projected["max_hp"],
        "projected_hp": projected["hp"],
        "target": _h5v2_pokemon_fingerprint(target),
        "target_serial": target.serial,
        "target_prize": 1,
        "opponent_board": _h5v2_board_fingerprint(opponent),
        "mine_bench": _h5v2_bench_fingerprint(mine),
        "hand": _h5v2_hand_fingerprint(mine),
        "expected_post_evolution_hand": tuple(expected_hand),
        "stadium": _h5v2_stadium_fingerprint(obs),
        "public_modifiers": _h5v2_public_modifiers(obs),
        "supporter_played": bool(obs.current.supporterPlayed),
        "energy_attached": bool(obs.current.energyAttached),
        "retreated": bool(obs.current.retreated),
        "attachment_evidence": copy.deepcopy(_pan_attachment_evidence),
        "evolution_serial": evolution_serial,
        "evolution_semantic": evolution_semantic,
        "parent_semantic": parent_semantic,
        "coated_damage": coated_damage,
        "successor_envelope": successor,
        "source_snapshot": _cum_public_snapshot_id(obs),
        "current_attacker": (active.id, active.serial),
        "attack": COATED_ATTACK,
        "prize_route": (1,),
        "next_attacker": (ARCHALUDON, evolution_serial),
        "reserved_metal": tuple(row[0] for row in active_energy),
        "reserved_boss": BOSS,
        "maximum_supported_public_reply": maximum_reply,
        "terminal": False,
    }, None


def _pan_pre_evolution_valid(obs, parent_action, transaction):
    mine = my_state(obs)
    opponent = opp_state(obs)
    active = active_pokemon(obs)
    target = opp_active_pokemon(obs)
    successor = _pan_successor_envelope(obs, transaction["projected_hp"])
    return (
        _pan_main_context(obs)
        and _pan_visible_serials_complete(obs)
        and transaction["game_epoch"] == _cum_game_epoch
        and transaction["seat"] == obs.current.yourIndex
        and transaction["turn"] == obs.current.turn
        and transaction["turn_action_count"] == obs.current.turnActionCount
        and (
            len(mine.prize or ()),
            len(opponent.prize or ()),
        ) == transaction["prizes"]
        and _h5v2_pokemon_fingerprint(active) == transaction["active"]
        and _h5v2_pokemon_fingerprint(target) == transaction["target"]
        and _h5v2_board_fingerprint(opponent)
        == transaction["opponent_board"]
        and _h5v2_bench_fingerprint(mine) == transaction["mine_bench"]
        and _h5v2_hand_fingerprint(mine) == transaction["hand"]
        and _h5v2_stadium_fingerprint(obs) == transaction["stadium"]
        and _h5v2_public_modifiers(obs) == transaction["public_modifiers"]
        and bool(obs.current.supporterPlayed)
        == transaction["supporter_played"]
        and bool(obs.current.energyAttached)
        == transaction["energy_attached"]
        and bool(obs.current.retreated) == transaction["retreated"]
        and _pan_attachment_valid(obs, active)
        and _pan_attachment_evidence == transaction["attachment_evidence"]
        and _h5v2_parent_is_inherited_raging(obs, parent_action)
        and successor == transaction["successor_envelope"]
        and _cum_bind_semantic(obs, transaction["evolution_semantic"])
        is not None
    )


def _pan_evolution_log_valid(obs, transaction):
    matches = [
        entry
        for entry in obs.logs
        if (
            entry.type == LogType.EVOLVE
            and entry.playerIndex == transaction["seat"]
            and entry.cardId == ARCHALUDON
            and entry.serial == transaction["evolution_serial"]
            and entry.cardIdTarget == DURALUDON
            and entry.serialTarget == transaction["active_serial"]
        )
    ]
    return len(matches) == 1


def _pan_evolved_valid(obs, transaction):
    mine = my_state(obs)
    opponent = opp_state(obs)
    active = active_pokemon(obs)
    target = opp_active_pokemon(obs)
    if (
        not _pan_main_context(obs)
        or not _pan_visible_serials_complete(obs)
        or active is None
        or target is None
        or active.id != ARCHALUDON
        or active.serial != transaction["evolution_serial"]
        or obs.current.turnActionCount
        != transaction["turn_action_count"] + 1
        or (
            len(mine.prize or ()),
            len(opponent.prize or ()),
        ) != transaction["prizes"]
        or _h5v2_pokemon_fingerprint(target) != transaction["target"]
        or _h5v2_board_fingerprint(opponent)
        != transaction["opponent_board"]
        or _h5v2_bench_fingerprint(mine) != transaction["mine_bench"]
        or _h5v2_hand_fingerprint(mine)
        != transaction["expected_post_evolution_hand"]
        or _h5v2_stadium_fingerprint(obs) != transaction["stadium"]
        or _h5v2_public_modifiers(obs) != transaction["public_modifiers"]
        or bool(obs.current.supporterPlayed)
        != transaction["supporter_played"]
        or bool(obs.current.energyAttached)
        != transaction["energy_attached"]
        or bool(obs.current.retreated) != transaction["retreated"]
        or getattr(active, "maxHp", None) != transaction["projected_max_hp"]
        or getattr(active, "hp", None) != transaction["projected_hp"]
        or damage_on(active) != transaction["active_damage"]
        or _h5v2_prize_value(active) != 1
        or not _pan_evolution_log_valid(obs, transaction)
    ):
        return False
    energy = _pan_energy_rows(obs, active, transaction["seat"])
    tools = tuple(
        _h5v2_card_fingerprint(card)
        for card in (getattr(active, "tools", None) or ())
    )
    prior = tuple(getattr(active, "preEvolution", None) or ())
    if (
        energy != transaction["active_energy"]
        or tools != (transaction["active"][7][0],)
        or len(prior) != 1
        or prior[0].id != DURALUDON
        or prior[0].serial != transaction["active_serial"]
        or getattr(prior[0], "playerIndex", None) != transaction["seat"]
        or _pan_attachment_evidence != transaction["attachment_evidence"]
    ):
        return False
    successor = _pan_successor_envelope(obs, transaction["projected_hp"])
    attacks = _h5v2_attack_options(obs)
    coated_damage = _pan_source_target_damage(
        obs, ARCHALUDON, COATED_ATTACK, target
    )
    return (
        successor == transaction["successor_envelope"]
        and len(attacks) == 1
        and attacks[0][1] == COATED_ATTACK
        and coated_damage == transaction["coated_damage"]
        and coated_damage >= target.hp
        and not _h5v2_boss_options(obs)
    )


def _pan_attack_confirmed(obs, transaction):
    return any(
        entry.type == LogType.ATTACK
        and entry.playerIndex == transaction["seat"]
        and entry.attackId == COATED_ATTACK
        and entry.serial == transaction["evolution_serial"]
        for entry in obs.logs
    )


def _pan_clear(reason, clear_attachment=False):
    global _pan_transaction, _pan_attachment_evidence
    global _pan_last_rejection, _pan_last_certificate
    _pan_transaction = None
    _pan_last_rejection = reason
    _pan_last_certificate = None
    if clear_attachment:
        _pan_attachment_evidence = None


def _pan_reset(reason):
    global _pan_previous_public
    _pan_clear(reason, clear_attachment=True)
    _pan_previous_public = None


def _pan_boundary(obs):
    transaction = _pan_transaction
    if obs.current.result != -1:
        return "result_boundary"
    if transaction is not None and (
        transaction["game_epoch"] != _cum_game_epoch
        or transaction["seat"] != obs.current.yourIndex
        or transaction["turn"] != obs.current.turn
    ):
        return "transaction_boundary"
    previous = _pan_previous_public
    if previous is not None and (
        previous["game_epoch"] != _cum_game_epoch
        or previous["seat"] != obs.current.yourIndex
        or previous["turn"] != obs.current.turn
    ):
        return "observation_boundary"
    return None


def _pan_observation_prepass(obs):
    global _pan_previous_public
    boundary = _pan_boundary(obs)
    if boundary is not None:
        _pan_clear(boundary, clear_attachment=True)
        _pan_previous_public = None
    _pan_observe_attachment(obs)
    _pan_previous_public = _pan_public_key(obs)


def _pan_resume(obs, parent_action):
    global _pan_transaction, _pan_last_rejection, _pan_last_certificate
    transaction = _pan_transaction
    if transaction is None:
        _pan_last_rejection = "NO_ACTIVE_TRANSACTION"
        return None
    stage_before = transaction["stage"]
    _pan_last_certificate = copy.deepcopy(transaction)
    if _pan_attack_confirmed(obs, transaction):
        _pan_clear("ATTACK_CONFIRMED")
        return parent_action
    active = active_pokemon(obs)
    if stage_before == "EVOLUTION_EMITTED":
        if (
            active is not None
            and active.id == ARCHALUDON
            and active.serial == transaction["evolution_serial"]
        ):
            if not _pan_evolved_valid(obs, transaction):
                _pan_clear("POST_EVOLUTION_ACTUAL_STATE_FAILURE")
                return parent_action
            transaction["stage"] = "EVOLVED_CONFIRMED"
            attack_options = _h5v2_attack_options(obs, COATED_ATTACK)
            if len(attack_options) != 1:
                _pan_clear("POST_EVOLUTION_ATTACK_BINDING_FAILURE")
                return parent_action
            attack = [attack_options[0][0]]
            if not _cum_valid_action(obs, attack):
                _pan_clear("POST_EVOLUTION_ATTACK_INVALID")
                return parent_action
            transaction["stage"] = "ATTACK_EMITTED"
            _pan_last_certificate = copy.deepcopy(transaction)
            _pan_last_rejection = None
            return attack
        if not _pan_pre_evolution_valid(obs, parent_action, transaction):
            _pan_clear("PRE_EVOLUTION_ROLLBACK")
            return parent_action
        action = _cum_bind_semantic(obs, transaction["evolution_semantic"])
        if action is None:
            _pan_clear("PRE_EVOLUTION_BINDING_FAILURE")
            return parent_action
        _pan_last_rejection = None
        return action
    if stage_before == "ATTACK_EMITTED":
        _pan_clear("NOVEL_CALLBACK_AFTER_ATTACK_EMISSION")
        return parent_action
    _pan_clear("UNKNOWN_STAGE")
    return parent_action


def _pan_choose(obs, parent_action):
    global _pan_transaction, _pan_last_rejection, _pan_last_certificate
    if _pan_transaction is not None:
        return _pan_resume(obs, parent_action)
    certificate, rejection = _pan_build_certificate(obs, parent_action)
    _pan_last_rejection = rejection
    _pan_last_certificate = None
    if certificate is None:
        return None
    action = _cum_bind_semantic(obs, certificate["evolution_semantic"])
    if action is None or not _cum_valid_action(obs, action):
        _pan_last_rejection = "EVOLUTION_BINDING_FAILURE"
        return None
    _pan_transaction = certificate
    _pan_last_certificate = copy.deepcopy(certificate)
    return action


