_NMR_RULE_ID = "PUBLIC_NORMAL_MODE_EQUAL_TWO_PRIZE_ACTIVE_RACE_ATTACK_FIRST_V1"
_NMR_CONTRACT_SHA = (
    "54E4571236FD636D9C646F5906204B3922E4CD5DF8B758EB852AF71EC9C7547F"
)
_NMR_SOURCE_SHA = (
    "C15CA505A9B7D9BC5DEE58D74647FD9C702EDBA3CC040CB43A6308293D61CC82"
)
_NMR_SOURCE_REPLAY_SHA = (
    "ED58D8FB1B7E8D7E0C4603AB5DC86DAC569185D66C192FD5CB39E98765A46282"
)
_NMR_SAFE_TARGET_IDS = frozenset((DURALUDON, CINDERACE))
_nmr_transaction = None
_nmr_last_rejection = None
_nmr_last_certificate = None


def _nmr_serial(card):
    return None if card is None else getattr(card, "serial", None)


def _nmr_visible_serial_unique(obs, serial):
    return (
        serial is not None
        and sum(
            1
            for card in _h6_visible_cards(obs)
            if _nmr_serial(card) == serial
        )
        == 1
    )


def _nmr_exact_energy_cards(obs, pokemon, player_index, expected):
    cards = getattr(pokemon, "energyCards", None)
    aggregate = getattr(pokemon, "energies", None)
    if cards is None or aggregate is None:
        return False
    cards = tuple(cards)
    aggregate = tuple(aggregate)
    expected = tuple(expected)
    serials = tuple(_nmr_serial(card) for card in cards)
    return (
        aggregate == expected
        and len(cards) == len(expected)
        and all(
            card is not None
            and getattr(card, "id", None) == energy_id
            and getattr(card, "playerIndex", None) == player_index
            and _nmr_visible_serial_unique(obs, _nmr_serial(card))
            for card, energy_id in zip(cards, expected)
        )
        and len(set(serials)) == len(serials)
    )


def _nmr_exact_archaludon_active(obs, pokemon, player_index):
    data = CARD_DB.get(ARCHALUDON_EX)
    tools = getattr(pokemon, "tools", None) if pokemon is not None else None
    pre_evolution = (
        getattr(pokemon, "preEvolution", None)
        if pokemon is not None
        else None
    )
    return (
        pokemon is not None
        and data is not None
        and getattr(pokemon, "id", None) == ARCHALUDON_EX
        and _nmr_visible_serial_unique(obs, _nmr_serial(pokemon))
        and getattr(data, "hp", None) == 300
        and bool(getattr(data, "ex", False))
        and not bool(getattr(data, "megaEx", False))
        and tuple(getattr(data, "attacks", None) or ()) == (METAL_DEFENDER,)
        and getattr(pokemon, "hp", None) == 300
        and getattr(pokemon, "maxHp", None) == 300
        and tools is not None
        and tuple(tools) == ()
        and pre_evolution is not None
        and len(pre_evolution) == 1
        and getattr(pre_evolution[0], "id", None) == DURALUDON
        and getattr(pre_evolution[0], "playerIndex", None) == player_index
        and _nmr_visible_serial_unique(obs, _nmr_serial(pre_evolution[0]))
        and _nmr_exact_energy_cards(
            obs,
            pokemon,
            player_index,
            (METAL_ENERGY, METAL_ENERGY, METAL_ENERGY),
        )
    )


def _nmr_exact_safe_boss_target(obs, pokemon, player_index):
    if (
        pokemon is None
        or getattr(pokemon, "id", None) not in _NMR_SAFE_TARGET_IDS
        or not _nmr_visible_serial_unique(obs, _nmr_serial(pokemon))
        or _h6_prize_value(pokemon) != 1
        or getattr(pokemon, "tools", None) is None
        or tuple(getattr(pokemon, "tools", ())) != ()
        or getattr(pokemon, "preEvolution", None) is None
        or tuple(getattr(pokemon, "preEvolution", ())) != ()
        or not _nmr_exact_energy_cards(
            obs, pokemon, player_index, (METAL_ENERGY,)
        )
    ):
        return None
    data = CARD_DB.get(pokemon.id)
    if data is None or getattr(pokemon, "maxHp", None) != getattr(
        data, "hp", None
    ):
        return None
    if pokemon.id == DURALUDON:
        if (
            getattr(pokemon, "hp", None) != 130
            or tuple(getattr(data, "attacks", None) or ()) != (223, 224)
            or getattr(ALL_ATTACKS.get(223), "damage", None) != 30
            or tuple(getattr(ALL_ATTACKS.get(223), "energies", None) or ())
            != (METAL_ENERGY,)
            or (getattr(ALL_ATTACKS.get(223), "text", None) or "") != ""
            or getattr(ALL_ATTACKS.get(RAGING_HAMMER), "damage", None) != 80
            or tuple(
                getattr(ALL_ATTACKS.get(RAGING_HAMMER), "energies", None)
                or ()
            )
            != (METAL_ENERGY, METAL_ENERGY, 0)
        ):
            return None
        return ("DURALUDON", pokemon.serial, pokemon.hp, (METAL_ENERGY,))
    attack = ALL_ATTACKS.get(965)
    skills = tuple(getattr(data, "skills", None) or ())
    if (
        getattr(pokemon, "hp", None) != 110
        or getattr(pokemon, "maxHp", None) != 160
        or tuple(getattr(data, "attacks", None) or ()) != (965,)
        or len(skills) != 1
        or getattr(skills[0], "name", None) != " Explosiveness"
        or getattr(attack, "damage", None) != 50
        or tuple(getattr(attack, "energies", None) or ()) != (0,)
        or getattr(attack, "text", None)
        != (
            "Search your deck for up to 3 Basic Energy cards and attach them "
            "to your Benched Pokémon in any way you like. Then, shuffle your "
            "deck."
        )
    ):
        return None
    return ("CINDERACE", pokemon.serial, pokemon.hp, (METAL_ENERGY,))


def _nmr_parent_boss_and_attack_options(obs, parent_action):
    if not isinstance(parent_action, list) or len(parent_action) != 1:
        return None, None, "PARENT_NOT_UNIQUE_SINGLE_ACTION"
    boss_positions = []
    attack_positions = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        if (
            option.type == OptionType.PLAY
            and card is not None
            and getattr(card, "id", None) == BOSS
        ):
            boss_positions.append(position)
        if (
            option.type == OptionType.ATTACK
            and getattr(option, "attackId", None) == METAL_DEFENDER
        ):
            attack_positions.append(position)
    if len(boss_positions) != 1:
        return None, None, "BOSS_ABSENT_OR_DUPLICATED"
    if parent_action != boss_positions:
        return None, None, "DIRECT_PARENT_NOT_UNIQUE_BOSS"
    if len(attack_positions) != 1:
        return None, None, "METAL_DEFENDER_ABSENT_OR_DUPLICATED"
    return boss_positions[0], attack_positions[0], None


def _nmr_build_certificate(obs, parent_action):
    if (
        obs.current.result != -1
        or obs.select.context != SelectContext.MAIN
        or obs.current.supporterPlayed
    ):
        return None, "NOT_CLEAR_ORDINARY_MAIN"
    mine = my_state(obs)
    opponent = opp_state(obs)
    if (
        mine is None
        or opponent is None
        or len(mine.prize or ()) != 2
        or len(opponent.prize or ()) != 2
    ):
        return None, "PRIZES_NOT_EXACTLY_TWO_EACH"
    if (
        len(mine.active or ()) != 1
        or len(opponent.active or ()) != 1
        or _h6_conditions(mine) != (False,) * 5
        or _h6_conditions(opponent) != (False,) * 5
    ):
        return None, "ACTIVE_OR_STATUS_INCOMPLETE"
    active = mine.active[0]
    opposing_active = opponent.active[0]
    if not _nmr_exact_archaludon_active(
        obs, active, obs.current.yourIndex
    ) or not _nmr_exact_archaludon_active(
        obs, opposing_active, 1 - obs.current.yourIndex
    ):
        return None, "ACTIVE_PUBLIC_CERTIFICATE_FAILED"
    stadium = tuple(obs.current.stadium or ())
    if (
        len(stadium) != 1
        or stadium[0].id != FULL_METAL_LAB
        or not _nmr_visible_serial_unique(obs, _nmr_serial(stadium[0]))
        or not _h6_static_cards_supported()
        or _h6_card_text(FULL_METAL_LAB) != _H6_FULL_METAL_LAB_TEXT
        or _opp_last_attack_id not in (None, METAL_DEFENDER)
    ):
        return None, "STADIUM_OR_CONTINUOUS_EFFECT_UNSUPPORTED"
    boss_position, attack_position, option_error = (
        _nmr_parent_boss_and_attack_options(obs, parent_action)
    )
    if option_error is not None:
        return None, option_error
    damage = _h1_metal_defender_damage(obs, opposing_active)
    if (
        damage != 190
        or damage >= opposing_active.hp
        or damage * 2 < opposing_active.hp
        or not _h1_energy_ready(active, METAL_DEFENDER)
    ):
        return None, "NOT_EXACT_TWO_HIT_ACTIVE_RACE"
    opposing_data = CARD_DB.get(opposing_active.id)
    payable_returns = []
    for attack_id in tuple(getattr(opposing_data, "attacks", None) or ()):
        if not _h1_energy_ready(opposing_active, attack_id):
            continue
        return_damage = _h1_attack_damage_to_archaludon(
            obs, opposing_active, attack_id
        )
        if return_damage is None or return_damage >= active.hp:
            return None, "RETURN_ATTACK_NOT_CERTIFIED_SURVIVABLE"
        payable_returns.append((attack_id, return_damage))
    if payable_returns != [(METAL_DEFENDER, 190)]:
        return None, "RETURN_ATTACK_SET_UNSUPPORTED"
    target_rows = [
        _nmr_exact_safe_boss_target(
            obs, pokemon, 1 - obs.current.yourIndex
        )
        for pokemon in (opponent.bench or ())
    ]
    if (
        len(target_rows) != 2
        or any(row is None for row in target_rows)
        or {row[0] for row in target_rows}
        != {"DURALUDON", "CINDERACE"}
    ):
        return None, "BOSS_TARGET_THREAT_OR_COMPLETENESS_GATE_FAILED"
    certificate = {
        "policy": _NMR_RULE_ID,
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "action_count": obs.current.turnActionCount,
        "prizes": (2, 2),
        "active": (active.id, active.serial, active.hp),
        "opposing_active": (
            opposing_active.id,
            opposing_active.serial,
            opposing_active.hp,
        ),
        "stadium": (FULL_METAL_LAB, stadium[0].serial),
        "boss_position_semantic": _sat_option_key(
            obs, obs.select.option[boss_position]
        ),
        "attack_position_semantic": _sat_option_key(
            obs, obs.select.option[attack_position]
        ),
        "current_attacker": (active.id, active.serial),
        "attack": METAL_DEFENDER,
        "target": (opposing_active.id, opposing_active.serial),
        "prize_route": (2, 2),
        "next_attacker": (active.id, active.serial),
        "reserved_metal": (),
        "reserved_boss": BOSS,
        "current_damage": damage,
        "two_hit_ko": True,
        "return_attacks": payable_returns,
        "maximum_supported_public_reply": max(
            row[1] for row in payable_returns
        ),
        "survival_hp": active.hp - max(
            row[1] for row in payable_returns
        ),
        "boss_targets": tuple(sorted(target_rows, key=repr)),
        "terminal": False,
    }
    return (attack_position, certificate), None


def _nmr_choose(obs, parent_action):
    global _nmr_last_rejection, _nmr_last_certificate
    proposal, rejection = _nmr_build_certificate(obs, parent_action)
    _nmr_last_rejection = rejection
    _nmr_last_certificate = None
    if proposal is None:
        return None
    attack_position, certificate = proposal
    action = [attack_position]
    if not _cum_valid_action(obs, action):
        _nmr_last_rejection = "ATTACK_BINDING_INVALID"
        return None
    _nmr_last_certificate = certificate
    return action


def _nmr_reset(reason):
    global _nmr_transaction, _nmr_last_rejection, _nmr_last_certificate
    _nmr_transaction = None
    _nmr_last_rejection = reason
    _nmr_last_certificate = None


# The frozen component blocks above contain no component agent wrapper.  This
# is the sole arbitration layer.  It evaluates clear components against the
# same public snapshot and cached exact-parent action, restores their namespace
# state after proposal construction, then commits only the precedence winner.

