def _cum_jsonable(value):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {
            str(key): _cum_jsonable(item)
            for key, item in sorted(value.items(), key=lambda row: repr(row[0]))
        }
    if isinstance(value, (list, tuple)):
        return [_cum_jsonable(item) for item in value]
    if isinstance(value, set):
        return sorted((_cum_jsonable(item) for item in value), key=repr)
    enum_value = getattr(value, "value", None)
    if isinstance(enum_value, (str, int, float, bool)):
        return enum_value
    return repr(value)


def _cum_digest(value):
    encoded = json.dumps(
        _cum_jsonable(value),
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest().upper()


def _cum_action_semantic(obs, selected):
    if selected is None:
        return None
    if not isinstance(selected, list):
        return None
    if any(
        not isinstance(position, int)
        or position < 0
        or position >= len(obs.select.option)
        for position in selected
    ):
        return None
    return tuple(
        _sat_option_key(obs, obs.select.option[position])
        for position in selected
    )


def _cum_valid_action(obs, selected):
    return (
        isinstance(selected, list)
        and obs.select.minCount <= len(selected) <= obs.select.maxCount
        and len(selected) == len(set(selected))
        and all(
            isinstance(position, int)
            and 0 <= position < len(obs.select.option)
            for position in selected
        )
    )


def _cum_bind_semantic(obs, semantic):
    if semantic is None:
        return None
    selected = []
    used = set()
    for key in semantic:
        matches = [
            position
            for position, option in enumerate(obs.select.option)
            if position not in used and _sat_option_key(obs, option) == key
        ]
        if not matches:
            return None
        position = min(matches)
        selected.append(position)
        used.add(position)
    return selected if _cum_valid_action(obs, selected) else None


def _cum_emergency_action(obs):
    required = max(0, min(obs.select.minCount, len(obs.select.option)))
    allowed = max(required, min(obs.select.maxCount, len(obs.select.option)))
    count = required if required <= allowed else allowed
    return list(range(count))


def _cum_public_snapshot_id(obs):
    material = (
        _cum_game_epoch,
        _sat_material_fp(obs),
        _sat_context_fp(obs),
        _sat_option_multiset(obs),
    )
    prefix = (
        f"{_cum_game_epoch}:{obs.current.yourIndex}:"
        f"{obs.current.turn}:{obs.current.turnActionCount}"
    )
    return f"{prefix}:{_cum_digest(material)[:20]}"


def _cum_rule_transaction(rule):
    if rule["rule_id"] == PUBLIC_BOSS_LEDGER_RULE_ID:
        return _public_boss_ledger.get("transaction")
    return globals().get(rule["transaction"])


def _cum_observe_boss_prepass(obs):
    global _cum_active_transaction_owner, _cum_owner_meta
    global _cum_boss_ledger_snapshot, _cum_boss_ledger_ready
    global _cum_boss_confirmed_now
    previous_fingerprint = copy.deepcopy(
        _public_boss_ledger.get("last_fingerprint")
    )
    snapshot, fingerprint, ready, _ = _observe_public_ledger(obs)
    duplicate_observation = (
        fingerprint is not None and fingerprint == previous_fingerprint
    )
    detached = None
    if snapshot is not None:
        detached = copy.deepcopy(snapshot)
        detached["ledger_cards"] = copy.deepcopy(
            _public_boss_ledger["cards"]
        )
        detached["ledger_fingerprint"] = copy.deepcopy(fingerprint)
    confirmed_now = (
        not duplicate_observation
        and _public_boss_ledger.get("transaction") is None
        and bool(_public_boss_ledger["events"])
        and _public_boss_ledger["events"][-1].get("kind")
        == "TRANSACTION_CONFIRMED"
        and _public_boss_ledger["events"][-1].get("turn")
        == obs.current.turn
        and _public_boss_ledger["events"][-1].get("action_count")
        == obs.current.turnActionCount
    )
    if confirmed_now:
        if _cum_active_transaction_owner != PUBLIC_BOSS_LEDGER_RULE_ID:
            raise RuntimeError("boss_confirmation_without_matching_owner")
        _cum_active_transaction_owner = None
        _cum_owner_meta = None
        _cum_counters["boss_confirmations"] += 1
    transaction = _public_boss_ledger.get("transaction")
    if (
        transaction is not None
        and _cum_active_transaction_owner != PUBLIC_BOSS_LEDGER_RULE_ID
    ):
        raise RuntimeError("boss_transaction_without_matching_owner")
    if (
        _cum_active_transaction_owner == PUBLIC_BOSS_LEDGER_RULE_ID
        and transaction is None
        and not confirmed_now
    ):
        raise RuntimeError("stale_boss_owner")
    _cum_boss_ledger_snapshot = detached
    _cum_boss_ledger_ready = bool(ready and detached is not None)
    _cum_boss_confirmed_now = bool(confirmed_now)
    return detached, bool(ready), bool(confirmed_now)


def _cum_stage(transaction):
    if transaction is None:
        return "CLEAR"
    if isinstance(transaction, dict):
        return str(transaction.get("stage", "ACTIVE"))
    return "ACTIVE"


def _cum_capture_prefix(prefix):
    captured = {}
    for name, value in tuple(globals().items()):
        if not name.startswith(prefix) or callable(value):
            continue
        try:
            captured[name] = copy.deepcopy(value)
        except Exception:
            captured[name] = value
    return captured


def _cum_restore_prefix(prefix, captured):
    current = [
        name
        for name, value in tuple(globals().items())
        if name.startswith(prefix) and not callable(value)
    ]
    for name in current:
        if name not in captured:
            globals().pop(name, None)
    for name, value in captured.items():
        globals()[name] = copy.deepcopy(value)


def _cum_component_boundary(rule_id, obs):
    if rule_id == "H2_CERTIFIED_LAST_PRIZE_STRETCHER_METAL_BOSS":
        _h2_observation_boundary(obs)
    elif rule_id == "H1_CERTIFIED_ENDGAME_ALAKAZAM_BOSS":
        _h1_observation_boundary(obs)
    elif rule_id == (
        "H3_CERTIFIED_LONE_CINDERACE_ULTRA_BALL_TURBO_FLARE_LINE_FORMATION"
    ):
        _h3_observation_boundary(obs)


def _cum_sat_choose(obs, parent_action):
    global _sat_transaction
    if _sat_transaction is not None:
        return _sat_resume(obs)
    parent_selected, score_by_position, scored = _sat_parent_scored_choice(obs)
    if _cum_action_semantic(obs, parent_selected) != _cum_action_semantic(
        obs, parent_action
    ):
        raise RuntimeError("search_aware_parent_cache_disagreed")
    certificate = _sat_build_certificate(
        obs,
        parent_selected,
        score_by_position,
        scored,
    )
    if certificate is None:
        return None
    _sat_transaction = certificate
    _sat_stats["starts"] += 1
    action = _sat_bind_action(obs, certificate)
    if action is None:
        _sat_clear("initial_ultra_rebind_failed")
        return None
    return action


def _cum_hero_choose(obs, parent_action):
    global _hero_transaction
    if _hero_transaction is not None:
        return _hero_resume_transaction(obs)
    parent_selected, parent_scores, parent_sorted = _hero_parent_scored_choice(obs)
    if _cum_action_semantic(obs, parent_selected) != _cum_action_semantic(
        obs, parent_action
    ):
        raise RuntimeError("hero_parent_cache_disagreed")
    certificate = _hero_build_certificate(
        obs,
        parent_selected,
        parent_scores,
        parent_sorted,
    )
    if certificate is None:
        return None
    _hero_transaction = certificate
    _hero_telemetry["accepts"] += 1
    _hero_telemetry["stage_transitions"]["CLEAR->CAPE_EMITTED"] += 1
    positions = _hero_positions_for_key(obs, certificate["cape_key"])
    if not positions:
        _hero_clear("cape_rebind_failed")
        return None
    return [min(positions)]


def _cum_component_choose(rule, obs, parent_action):
    rule_id = rule["rule_id"]
    _cum_component_boundary(rule_id, obs)
    if rule_id == "H2_CERTIFIED_LAST_PRIZE_STRETCHER_METAL_BOSS":
        return _h2_choose(obs)
    if rule_id == "SEARCH_AWARE_ACTIVE_TERMINAL_BEFORE_NONTERMINAL_BOSS_V1":
        return _cum_sat_choose(obs, parent_action)
    if rule_id == "H1_CERTIFIED_ENDGAME_ALAKAZAM_BOSS":
        return _h1_choose(obs)
    if rule_id == _NMR_RULE_ID:
        return _nmr_choose(obs, parent_action)
    if rule_id == _PAN_RULE_ID:
        return _pan_choose(obs, parent_action)
    if rule_id == "H5_V2_PUBLIC_LETHAL_ACTIVE_NO_READY_SUCCESSOR":
        return _h5v2_choose(obs, parent_action)
    if rule_id == "H4_PUBLIC_MEGA_BRAVE_SELF_LOCK_VETO_V1":
        if _h4_transaction is not None:
            return _h4_choose(obs)
        witness = _h4_parent_attack_witness(obs, parent_action)
        if witness is None:
            return None
        return _h4_choose(obs, witness)
    if rule_id == _NAC_ROTATION_RULE_ID:
        return _nacr_choose(obs, parent_action)
    if rule_id == _NAC_IMMUNITY_RULE_ID:
        return _naci_choose(obs, parent_action)
    if rule_id == _NAC_CAPE_RULE_ID:
        return _nacc_choose(obs, parent_action)
    if rule_id == _NAC_TURBO_RULE_ID:
        return _nact_choose(obs, parent_action)
    if rule_id == _NAC_EVOLUTION_RULE_ID:
        return _nace_choose(obs, parent_action)
    if rule_id == "H6_UNIQUE_ACTIVE_METAL_DEFENDER_CONTINUITY_RESERVATION":
        return _h6_choose(obs, parent_action)
    if rule_id == "HERO_CAPE_CURRENT_PAYABLE_SAME_ATTACK_SURVIVAL":
        return _cum_hero_choose(obs, parent_action)
    if rule_id == (
        "H3_CERTIFIED_LONE_CINDERACE_ULTRA_BALL_TURBO_FLARE_LINE_FORMATION"
    ):
        return _h3_choose(obs)
    if rule_id == _PTD_RULE_ID:
        return _ptd_choose(obs, parent_action)
    if rule_id == PUBLIC_BOSS_LEDGER_RULE_ID:
        return None
    raise RuntimeError(f"unknown_rule:{rule_id}")


def _cum_component_rejection(rule, state_after, caught):
    if caught is not None:
        return f"caught_exception:{type(caught).__name__}"
    if rule["rule_id"] == "SEARCH_AWARE_ACTIVE_TERMINAL_BEFORE_NONTERMINAL_BOSS_V1":
        return str(state_after.get("_sat_last_rejection") or "certificate_not_satisfied")
    if rule["rule_id"] == _PTD_RULE_ID:
        return str(state_after.get("_ptd_last_rejection") or "certificate_not_satisfied")
    if rule["rule_id"] == _NMR_RULE_ID:
        return str(state_after.get("_nmr_last_rejection") or "certificate_not_satisfied")
    if rule["rule_id"] == _PAN_RULE_ID:
        return str(state_after.get("_pan_last_rejection") or "certificate_not_satisfied")
    rejection_name = {
        _NAC_ROTATION_RULE_ID: "_nacr_last_rejection",
        _NAC_IMMUNITY_RULE_ID: "_naci_last_rejection",
        _NAC_CAPE_RULE_ID: "_nacc_last_rejection",
        _NAC_TURBO_RULE_ID: "_nact_last_rejection",
        _NAC_EVOLUTION_RULE_ID: "_nace_last_rejection",
    }.get(rule["rule_id"])
    if rejection_name is not None:
        return str(
            state_after.get(rejection_name) or "certificate_not_satisfied"
        )
    return "certificate_not_satisfied"


def _cum_evaluate_boss_clear(rule, obs, parent_action):
    before_ledger = copy.deepcopy(_public_boss_ledger)
    before_components = {
        row["rule_id"]: _cum_capture_prefix(row["prefix"])
        for row in _CUM_RULES
        if row["rule_id"] != PUBLIC_BOSS_LEDGER_RULE_ID
    }
    before_resolver = (
        _cum_active_transaction_owner,
        copy.deepcopy(_cum_owner_meta),
        _cum_last_snapshot_id,
        copy.deepcopy(_cum_last_final_semantic),
        _cum_last_attribution,
    )
    caught = None
    proposal_result = None
    rejection_reason = "PASSIVE_LEDGER_NOT_READY"
    if _cum_boss_ledger_ready and _cum_boss_ledger_snapshot is not None:
        try:
            proposal_result, rejection_reason = _propose_public_boss_guard(
                copy.deepcopy(obs),
                copy.deepcopy(parent_action),
                copy.deepcopy(_cum_boss_ledger_snapshot),
            )
        except Exception as error:
            caught = error
    after_components = {
        row["rule_id"]: _cum_capture_prefix(row["prefix"])
        for row in _CUM_RULES
        if row["rule_id"] != PUBLIC_BOSS_LEDGER_RULE_ID
    }
    after_resolver = (
        _cum_active_transaction_owner,
        copy.deepcopy(_cum_owner_meta),
        _cum_last_snapshot_id,
        copy.deepcopy(_cum_last_final_semantic),
        _cum_last_attribution,
    )
    if (
        before_ledger != _public_boss_ledger
        or before_components != after_components
        or before_resolver != after_resolver
    ):
        caught = RuntimeError("boss_proposal_speculative_mutation")
        proposal_result = None
        rejection_reason = "SPECULATIVE_MUTATION_FAIL_CLOSED"
    action = None
    transaction = None
    commit_state = None
    access = None
    plan = None
    if caught is None and proposal_result is not None:
        action, plan, access = proposal_result
        transaction = {
            "stage": "AWAIT_EXACT_DISCARD_CONFIRMATION",
            "boss": plan["boss"],
            "replacement": plan["replacement"],
            "metal": plan["metal"],
            "source_fingerprint": copy.deepcopy(
                _cum_boss_ledger_snapshot["ledger_fingerprint"]
            ),
            "source_turn": obs.current.turn,
            "source_action_count": obs.current.turnActionCount,
        }
        commit_state = {
            "transaction": transaction,
            "action": list(action),
            "last_action_semantics": [
                plan["replacement"],
                plan["metal"],
            ],
            "event": {
                "turn": obs.current.turn,
                "action_count": obs.current.turnActionCount,
                "boss": list(plan["boss"]),
                "replacement": list(plan["replacement"]),
                "metal": list(plan["metal"]),
                "bridge": list(plan["bridge"]),
                "attacker": list(plan["attacker"]),
                "attack_id": plan["attack_id"],
                "bench_capacity": plan["bench_capacity"],
                "deck_count": plan["deck_count"],
                "public_discarded_boss_serials": access["discarded"],
                "held_access_before": access["held_access_before"],
                "held_access_after": access["held_access_after"],
            },
            "parent_guard_semantics": _boss_guard_action_semantics(
                obs, parent_action
            ),
            "final_guard_semantics": _boss_guard_action_semantics(obs, action),
        }
    action_semantic = _cum_action_semantic(obs, action)
    parent_semantic = _cum_action_semantic(obs, parent_action)
    eligible = (
        caught is None
        and transaction is not None
        and action_semantic is not None
        and _cum_valid_action(obs, action)
        and action_semantic != parent_semantic
    )
    public_plan = None
    if eligible:
        public_plan = {
            "current_attacker": plan["attacker"],
            "attack": plan["attack_id"],
            "target": "UNIQUE_VISIBLE_HIGHER_PRIZE_BENCH",
            "prize_route": "PRESERVE_LAST_BOSS",
            "next_attacker": plan["bridge"],
            "reserved_metal": plan["metal"],
            "reserved_boss": plan["boss"],
            "maximum_supported_public_reply": None,
            "terminal": False,
        }
    return {
        "rule_id": rule["rule_id"],
        "source_hash": rule["source_hash"],
        "contract_hash": rule["contract_hash"],
        "eligible": eligible,
        "rejection_reason": (
            None
            if eligible
            else (
                f"caught_exception:{type(caught).__name__}"
                if caught is not None
                else str(rejection_reason or "certificate_not_satisfied")
            )
        ),
        "desired_action": action_semantic if eligible else None,
        "precedence_rank": rule["rank"],
        "certificate_digest": (
            _cum_digest(transaction) if eligible else None
        ),
        "public_plan_payload": public_plan,
        "state_after": commit_state if eligible else None,
        "transaction_id": None,
        "stage_before": _cum_stage(_cum_rule_transaction(rule)),
        "stage_after": _cum_stage(transaction),
        "emitted": False,
        "confirmed": False,
        "duplicate_or_retry": False,
        "suppressed_by": None,
        "rollback_reason": None,
        "caught_exception": (
            None
            if caught is None
            else {
                "type": type(caught).__name__,
                "message": str(caught),
            }
        ),
        "boss_access": (
            None
            if not eligible
            else {
                "held_access_before": access["held_access_before"],
                "held_access_after": access["held_access_after"],
                "public_discarded_boss_serials": list(access["discarded"]),
                "boss": list(plan["boss"]),
                "replacement": list(plan["replacement"]),
                "metal": list(plan["metal"]),
            }
        ),
    }


def _cum_evaluate_clear(rule, obs, parent_action):
    if rule["rule_id"] == PUBLIC_BOSS_LEDGER_RULE_ID:
        return _cum_evaluate_boss_clear(rule, obs, parent_action)
    before_state = _cum_capture_prefix(rule["prefix"])
    before_transaction = copy.deepcopy(_cum_rule_transaction(rule))
    caught = None
    action = None
    try:
        action = _cum_component_choose(rule, copy.deepcopy(obs), parent_action)
    except Exception as error:
        caught = error
    after_state = _cum_capture_prefix(rule["prefix"])
    after_transaction = copy.deepcopy(
        after_state.get(rule["transaction"])
    )
    action_semantic = _cum_action_semantic(obs, action)
    parent_semantic = _cum_action_semantic(obs, parent_action)
    eligible = (
        caught is None
        and action_semantic is not None
        and _cum_valid_action(obs, action)
        and (
            after_transaction is not None
            or action_semantic != parent_semantic
        )
    )
    certificate = after_transaction
    if certificate is None:
        certificate = after_state.get(
            f"{rule['prefix']}last_certificate"
        )
    proposal = {
        "rule_id": rule["rule_id"],
        "source_hash": rule["source_hash"],
        "contract_hash": rule["contract_hash"],
        "eligible": eligible,
        "rejection_reason": (
            None
            if eligible
            else _cum_component_rejection(rule, after_state, caught)
        ),
        "desired_action": action_semantic if eligible else None,
        "precedence_rank": rule["rank"],
        "certificate_digest": (
            _cum_digest(certificate)
            if eligible and certificate is not None
            else None
        ),
        "public_plan_payload": (
            copy.deepcopy(certificate)
            if eligible and isinstance(certificate, dict)
            else None
        ),
        "state_after": after_state if eligible else None,
        "transaction_id": None,
        "stage_before": _cum_stage(before_transaction),
        "stage_after": _cum_stage(after_transaction),
        "emitted": False,
        "confirmed": False,
        "duplicate_or_retry": False,
        "suppressed_by": None,
        "rollback_reason": None,
        "caught_exception": (
            None
            if caught is None
            else {
                "type": type(caught).__name__,
                "message": str(caught),
            }
        ),
    }
    _cum_restore_prefix(rule["prefix"], before_state)
    return proposal


def _cum_evaluate_all_clear(obs, parent_action, exclude=None):
    exclude = set(exclude or ())
    excluded_by_owner = set(exclude)
    exclude.update(_cum_diagnostic_disabled_rules)
    return [
        (
            {
                "rule_id": rule["rule_id"],
                "source_hash": rule["source_hash"],
                "contract_hash": rule["contract_hash"],
                "eligible": False,
                "rejection_reason": (
                    "active_transaction_owner"
                    if rule["rule_id"] in excluded_by_owner
                    else "diagnostic_rule_disabled"
                ),
                "desired_action": None,
                "precedence_rank": rule["rank"],
                "certificate_digest": None,
                "public_plan_payload": None,
                "state_after": None,
                "transaction_id": None,
                "stage_before": _cum_stage(_cum_rule_transaction(rule)),
                "stage_after": _cum_stage(_cum_rule_transaction(rule)),
                "emitted": False,
                "confirmed": False,
                "duplicate_or_retry": False,
                "suppressed_by": None,
                "rollback_reason": None,
                "caught_exception": None,
            }
            if rule["rule_id"] in exclude
            else _cum_evaluate_clear(rule, obs, parent_action)
        )
        for rule in _CUM_RULES
    ]


def _cum_parent_rank1_terminal(obs, parent_action):
    if len(parent_action) != 1:
        return False
    option = obs.select.option[parent_action[0]]
    mine = my_state(obs)
    opposing = opp_state(obs)
    if not mine.prize or not opposing.active:
        return False
    if option.type == OptionType.ATTACK:
        damage = _h2_fixed_attack_damage(
            obs,
            opposing.active[0],
            getattr(option, "attackId", None),
        )
        prize_value = _h2_visible_prize_value(opposing.active[0])
        return (
            damage is not None
            and damage >= opposing.active[0].hp
            and (
                (prize_value is not None and prize_value >= len(mine.prize))
                or not opposing.bench
            )
        )
    card = option_card(obs, option)
    if (
        option.type != OptionType.PLAY
        or card is None
        or card.id != BOSS
        or obs.current.supporterPlayed
    ):
        return False
    attack_ids = [
        getattr(candidate, "attackId", None)
        for candidate in obs.select.option
        if candidate.type == OptionType.ATTACK
    ]
    targets = []
    for target in opposing.bench or ():
        prize_value = _h2_visible_prize_value(target)
        if prize_value is None or prize_value < len(mine.prize):
            continue
        if any(
            (
                (damage := _h2_fixed_attack_damage(obs, target, attack_id))
                is not None
                and damage >= target.hp
            )
            for attack_id in attack_ids
        ):
            targets.append((_h2_serial(target), target.id))
    return len(targets) == 1


def _cum_resolve_clear_proposals(proposals, parent_rank1=False):
    eligible = [proposal for proposal in proposals if proposal["eligible"]]
    if parent_rank1:
        return {
            "winner": "exact_historical_silver",
            "reason": "rank1_exact_parent_terminal",
            "eligible": eligible,
            "unknown": False,
        }
    if not eligible:
        return {
            "winner": "exact_historical_silver",
            "reason": "rank20_exact_parent",
            "eligible": [],
            "unknown": False,
        }
    ranks = [proposal.get("precedence_rank") for proposal in eligible]
    if (
        any(rank not in _CUM_EXPECTED_RANKS for rank in ranks)
        or len(ranks) != len(set(ranks))
    ):
        return {
            "winner": "exact_historical_silver",
            "reason": "unknown_or_equal_rank_collision_fail_closed",
            "eligible": eligible,
            "unknown": True,
        }
    winner = min(eligible, key=lambda proposal: proposal["precedence_rank"])
    return {
        "winner": winner["rule_id"],
        "reason": f"rank{winner['precedence_rank']}_total_order",
        "eligible": eligible,
        "unknown": False,
    }


def _cum_resolve_owner_collisions(
    owner,
    owner_semantic,
    irreversible,
    known_suppressed,
    proposals,
):
    known = set(known_suppressed or ())
    suppressed = []
    for proposal in proposals:
        if proposal["rule_id"] == owner or not proposal["eligible"]:
            continue
        same_action = proposal["desired_action"] == owner_semantic
        already_known = proposal["rule_id"] in known
        if not same_action and not already_known and irreversible:
            return {
                "rollback_rule": proposal["rule_id"],
                "suppressed": suppressed,
                "known_suppressed": tuple(
                    rule_id
                    for rule_id in _CUM_RULE_ORDER
                    if rule_id in known
                ),
                "reason": "new_different_post_irreversible",
            }
        suppressed.append(proposal["rule_id"])
        known.add(proposal["rule_id"])
    return {
        "rollback_rule": None,
        "suppressed": suppressed,
        "known_suppressed": tuple(
            rule_id for rule_id in _CUM_RULE_ORDER if rule_id in known
        ),
        "reason": "rank2_active_owner",
    }


def _cum_nonclear_rules():
    return [
        rule["rule_id"]
        for rule in _CUM_RULES
        if _cum_rule_transaction(rule) is not None
    ]


def _cum_owner_state_sane():
    nonclear = _cum_nonclear_rules()
    if _cum_active_transaction_owner is None:
        return _cum_owner_meta is None and not nonclear
    return (
        _cum_owner_meta is not None
        and nonclear == [_cum_active_transaction_owner]
    )


def _cum_reset_components(reason):
    global _sat_game_epoch, _hero_game_epoch
    _h2_reset()
    _sat_clear(reason)
    _h1_reset()
    _nmr_reset(reason)
    _pan_reset(reason)
    _h5v2_reset()
    _h4_reset()
    _nacr_reset(reason)
    _naci_reset(reason)
    _nacc_reset(reason)
    _nact_reset(reason)
    _nace_reset(reason)
    _h6_reset()
    _hero_clear(reason)
    _h3_reset()
    _ptd_reset(reason)


def _cum_clear_all(reason):
    global _cum_active_transaction_owner, _cum_owner_meta
    _cum_reset_components(reason)
    _cum_active_transaction_owner = None
    _cum_owner_meta = None
    _cum_counters[f"clear:{reason}"] += 1


def _cum_clear_all_and_ledger(reason):
    _cum_clear_all(reason)
    _reset_public_boss_ledger(reason)


def _cum_commit_proposal(proposal, snapshot_id, suppressed):
    global _cum_active_transaction_owner, _cum_owner_meta
    global _cum_transaction_counter
    rule = _CUM_RULE_BY_ID[proposal["rule_id"]]
    if rule["rule_id"] == PUBLIC_BOSS_LEDGER_RULE_ID:
        if (
            _public_boss_ledger.get("transaction") is not None
            or _cum_active_transaction_owner is not None
        ):
            _cum_clear_all_and_ledger("boss_commit_on_nonclear_state")
            return False
        commit_state = proposal["state_after"]
        _public_boss_ledger["transaction"] = copy.deepcopy(
            commit_state["transaction"]
        )
        _public_boss_ledger["last_action"] = list(commit_state["action"])
        _public_boss_ledger["last_action_semantics"] = copy.deepcopy(
            commit_state["last_action_semantics"]
        )
        _ledger_event(
            "GUARD_EMITTED", **copy.deepcopy(commit_state["event"])
        )
        _set_boss_guard_resolution(
            None,
            owner=PUBLIC_BOSS_LEDGER_RULE_ID,
            suppression_reason=None,
            parent_semantics=copy.deepcopy(
                commit_state["parent_guard_semantics"]
            ),
            final_semantics=copy.deepcopy(
                commit_state["final_guard_semantics"]
            ),
            proposal=True,
        )
    else:
        _cum_restore_prefix(rule["prefix"], proposal["state_after"])
    transaction = _cum_rule_transaction(rule)
    _cum_transaction_counter += 1
    transaction_id = (
        f"{_cum_game_epoch}:{_cum_transaction_counter}:"
        f"{proposal['rule_id']}:{snapshot_id}"
    )
    proposal["transaction_id"] = transaction_id
    if transaction is not None:
        _cum_active_transaction_owner = proposal["rule_id"]
        _cum_owner_meta = {
            "transaction_id": transaction_id,
            "arm_snapshot_id": snapshot_id,
            "suppressed_at_arm": tuple(
                row["rule_id"] for row in suppressed if row["eligible"]
            ),
            "known_suppressed": tuple(
                row["rule_id"] for row in suppressed if row["eligible"]
            ),
            "irreversible": False,
            "last_action": proposal["desired_action"],
        }
    nonclear = _cum_nonclear_rules()
    if len(nonclear) > 1 or (
        transaction is not None and nonclear != [proposal["rule_id"]]
    ):
        _cum_clear_all_and_ledger("two_owner_state")
        return False
    return True


def _cum_telemetry_proposal(proposal):
    return {
        key: _cum_jsonable(value)
        for key, value in proposal.items()
        if key != "state_after"
    }


def _cum_emit_telemetry(
    obs,
    *,
    snapshot_id,
    parent_semantic,
    proposals,
    owner_before,
    owner_after,
    winner,
    reason,
    final_semantic,
    attribution,
    suppressed,
    rollback_reason=None,
    duplicate_or_reset_state=None,
    invalid_or_emergency_fallback=False,
    option_binding="BOUND",
    state_clear_result=None,
    caught_exceptions=None,
):
    global _cum_last_telemetry
    winner_proposal = next(
        (
            proposal
            for proposal in proposals
            if proposal.get("rule_id") == winner
        ),
        None,
    )
    if winner_proposal is not None:
        winning_rank = winner_proposal.get("precedence_rank")
    elif winner == "exact_historical_silver":
        winning_rank = 20
    elif winner in {"engine_emergency", "engine_empty_options", "engine_deck_request"}:
        winning_rank = 0
    else:
        winning_rank = 2 if owner_after is not None else None
    row = {
        "rule_id": _CUM_RULE_ID,
        "integration_contract_hash": _CUM_INTEGRATION_CONTRACT_SHA,
        "admission_hash": _CUM_ADMISSION_SHA,
        "user_policy_hash": _CUM_USER_POLICY_SHA,
        "direct_parent_hash": _CUM_DIRECT_PARENT_SHA,
        "repair_source_hash": _CUM_REPAIR_SOURCE_SHA,
        "repair_contract_hash": _CUM_REPAIR_CONTRACT_SHA,
        "verification_spec_hash": _CUM_VERIFICATION_SPEC_SHA,
        "snapshot_id": snapshot_id,
        "plan_id": f"{snapshot_id}:{winner}",
        "rank": winning_rank,
        "game_epoch": _cum_game_epoch,
        "seat": None if obs is None else obs.current.yourIndex,
        "turn": None if obs is None else obs.current.turn,
        "action_count": None if obs is None else obs.current.turnActionCount,
        "context": (
            None if obs is None or obs.select is None
            else _sat_enum(obs.select.context)
        ),
        "exact_parent_action": _cum_jsonable(parent_semantic),
        "eligible_rule_ids": [
            proposal["rule_id"]
            for proposal in proposals
            if proposal["eligible"]
        ],
        "proposed_actions_by_rule": {
            proposal["rule_id"]: _cum_jsonable(proposal["desired_action"])
            for proposal in proposals
            if proposal["eligible"]
        },
        "proposals": [
            _cum_telemetry_proposal(proposal) for proposal in proposals
        ],
        "active_owner_before": owner_before,
        "active_owner_after": owner_after,
        "active_transaction_owner": owner_after,
        "collision_set": [
            proposal["rule_id"]
            for proposal in proposals
            if proposal["eligible"]
        ],
        "winning_rule_id": winner,
        "public_plan_payload": _cum_jsonable(
            None
            if winner_proposal is None
            else winner_proposal.get("public_plan_payload")
        ),
        "suppressed_rule_ids": list(suppressed),
        "precedence_reason": reason,
        "rollback_reason": rollback_reason,
        "caught_exceptions": _cum_jsonable(caught_exceptions or []),
        "final_action": _cum_jsonable(final_semantic),
        "attribution_owner": attribution,
        "duplicate_or_reset_state": duplicate_or_reset_state,
        "invalid_or_emergency_fallback": bool(invalid_or_emergency_fallback),
        "option_binding_result": option_binding,
        "state_clear_result": state_clear_result,
        "boss_ledger": {
            "ready": bool(_cum_boss_ledger_ready),
            "confirmed_now": bool(_cum_boss_confirmed_now),
            "transaction_stage": _cum_stage(
                _public_boss_ledger.get("transaction")
            ),
            "last_reset_reason": _public_boss_ledger.get(
                "last_reset_reason"
            ),
        },
    }
    _cum_last_telemetry = row
    _cum_telemetry_pending.append(copy.deepcopy(row))
    _cum_counters["callbacks"] += 1
    if rollback_reason:
        _cum_counters[f"rollback:{rollback_reason}"] += 1
    return row


def drain_cumulative_telemetry():
    rows = copy.deepcopy(_cum_telemetry_pending)
    _cum_telemetry_pending.clear()
    return rows


def _cum_cache_final(snapshot_id, semantic, attribution):
    global _cum_last_snapshot_id, _cum_last_final_semantic
    global _cum_last_attribution
    _cum_last_snapshot_id = snapshot_id
    _cum_last_final_semantic = copy.deepcopy(semantic)
    _cum_last_attribution = attribution


def _cum_retry_if_identical(obs, snapshot_id):
    if (
        _cum_active_transaction_owner is None
        or _cum_last_snapshot_id != snapshot_id
        or _cum_last_final_semantic is None
    ):
        return None
    action = _cum_bind_semantic(obs, _cum_last_final_semantic)
    if action is None:
        return None
    proposals = copy.deepcopy(
        (_cum_last_telemetry or {}).get("proposals", [])
    )
    for proposal in proposals:
        proposal["duplicate_or_retry"] = True
        proposal["emitted"] = (
            proposal["rule_id"] == _cum_active_transaction_owner
        )
        proposal["state_after"] = None
    _cum_emit_telemetry(
        obs,
        snapshot_id=snapshot_id,
        parent_semantic=(_cum_last_telemetry or {}).get("exact_parent_action"),
        proposals=proposals,
        owner_before=_cum_active_transaction_owner,
        owner_after=_cum_active_transaction_owner,
        winner=_cum_active_transaction_owner,
        reason="rank2_identical_retry_cached_without_parent_call",
        final_semantic=_cum_last_final_semantic,
        attribution=_cum_active_transaction_owner,
        suppressed=(_cum_last_telemetry or {}).get("suppressed_rule_ids", []),
        duplicate_or_reset_state="IDENTICAL_RETRY",
    )
    _cum_counters["identical_retries"] += 1
    return action


def _cum_reresolve_after_pan_clear(
    obs,
    parent_action,
    parent_semantic,
    snapshot_id,
    proposals,
):
    global _cum_active_transaction_owner, _cum_owner_meta
    global _pan_last_telemetry
    _cum_active_transaction_owner = None
    _cum_owner_meta = None
    pan_row = next(
        row for row in proposals if row["rule_id"] == _PAN_RULE_ID
    )
    pan_row["eligible"] = False
    pan_row["desired_action"] = None
    pan_row["rejection_reason"] = (
        _pan_last_rejection or "owner_completed_or_invalid"
    )
    pan_row["emitted"] = False
    pan_row["rollback_reason"] = "actual_state_reresolution"
    resolution = _cum_resolve_clear_proposals(proposals)
    eligible = resolution["eligible"]
    winner_id = resolution["winner"]
    if winner_id == "exact_historical_silver":
        _pan_last_telemetry = {
            "reason": _pan_last_rejection,
            "parent_action": _cum_jsonable(parent_semantic),
            "final_action": _cum_jsonable(parent_semantic),
            "actual_state_reresolved": True,
        }
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=_PAN_RULE_ID,
            owner_after=None,
            winner=winner_id,
            reason="post_evolution_actual_state_reresolved_to_general",
            final_semantic=parent_semantic,
            attribution=winner_id,
            suppressed=[],
            rollback_reason="pan_owner_cleared_actual_state",
            state_clear_result="PAN_CLEAR_GENERAL_RECOMPUTED",
        )
        _cum_cache_final(snapshot_id, parent_semantic, winner_id)
        return parent_action, None, proposals
    winner = next(
        proposal for proposal in eligible
        if proposal["rule_id"] == winner_id
    )
    suppressed = [
        proposal for proposal in eligible
        if proposal["rule_id"] != winner_id
    ]
    for proposal in suppressed:
        proposal["suppressed_by"] = winner_id
    winner["emitted"] = True
    if not _cum_commit_proposal(winner, snapshot_id, suppressed):
        _cum_cache_final(
            snapshot_id, parent_semantic, "exact_historical_silver"
        )
        return parent_action, None, proposals
    bound = _cum_bind_semantic(obs, winner["desired_action"])
    if bound is None:
        _cum_clear_all("pan_reresolution_binding_failed")
        _cum_cache_final(
            snapshot_id, parent_semantic, "exact_historical_silver"
        )
        return parent_action, None, proposals
    _cum_emit_telemetry(
        obs,
        snapshot_id=snapshot_id,
        parent_semantic=parent_semantic,
        proposals=proposals,
        owner_before=_PAN_RULE_ID,
        owner_after=_cum_active_transaction_owner,
        winner=winner_id,
        reason="post_evolution_actual_state_reresolved_component",
        final_semantic=winner["desired_action"],
        attribution=winner_id,
        suppressed=[proposal["rule_id"] for proposal in suppressed],
        rollback_reason="pan_owner_cleared_actual_state",
        state_clear_result="PAN_CLEAR_GENERAL_RECOMPUTED",
    )
    _pan_last_telemetry = {
        "reason": _pan_last_rejection,
        "parent_action": _cum_jsonable(parent_semantic),
        "final_action": _cum_jsonable(winner["desired_action"]),
        "actual_state_reresolved": True,
    }
    _cum_cache_final(snapshot_id, winner["desired_action"], winner_id)
    return bound, winner_id, proposals


def _cum_resume_owner(obs, parent_action, parent_semantic, snapshot_id):
    global _cum_active_transaction_owner, _cum_owner_meta
    owner = _cum_active_transaction_owner
    rule = _CUM_RULE_BY_ID.get(owner)
    if rule is None or _cum_rule_transaction(rule) is None:
        _cum_clear_all("stale_owner")
        return None, "stale_owner", []

    competitor_proposals = _cum_evaluate_all_clear(
        obs,
        parent_action,
        exclude={owner},
    )
    before_transaction = copy.deepcopy(_cum_rule_transaction(rule))
    before_stage = _cum_stage(before_transaction)
    caught = None
    owner_action = None
    try:
        owner_action = _cum_component_choose(rule, copy.deepcopy(obs), parent_action)
    except Exception as error:
        caught = error
    after_transaction = copy.deepcopy(_cum_rule_transaction(rule))
    after_stage = _cum_stage(after_transaction)
    owner_semantic = _cum_action_semantic(obs, owner_action)
    confirmed = (
        before_transaction != after_transaction
        and before_transaction is not None
    )
    owner_proposal = {
        "rule_id": owner,
        "source_hash": rule["source_hash"],
        "contract_hash": rule["contract_hash"],
        "eligible": caught is None and owner_semantic is not None,
        "rejection_reason": (
            None
            if caught is None and owner_semantic is not None
            else (
                f"caught_exception:{type(caught).__name__}"
                if caught is not None
                else "owner_cleared_or_no_action"
            )
        ),
        "desired_action": owner_semantic,
        "precedence_rank": 2,
        "certificate_digest": (
            None
            if after_transaction is None
            else _cum_digest(after_transaction)
        ),
        "public_plan_payload": (
            copy.deepcopy(after_transaction)
            if isinstance(after_transaction, dict)
            else None
        ),
        "state_after": None,
        "transaction_id": (
            None if _cum_owner_meta is None
            else _cum_owner_meta["transaction_id"]
        ),
        "stage_before": before_stage,
        "stage_after": after_stage,
        "emitted": owner_semantic is not None,
        "confirmed": confirmed,
        "duplicate_or_retry": not confirmed,
        "suppressed_by": None,
        "rollback_reason": None,
        "caught_exception": (
            None
            if caught is None
            else {
                "type": type(caught).__name__,
                "message": str(caught),
            }
        ),
    }
    proposals = []
    for candidate_rule in _CUM_RULES:
        if candidate_rule["rule_id"] == owner:
            proposals.append(owner_proposal)
        else:
            proposals.append(
                next(
                    proposal
                    for proposal in competitor_proposals
                    if proposal["rule_id"] == candidate_rule["rule_id"]
                )
            )

    if caught is not None:
        _cum_clear_all("owner_exception")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=owner,
            owner_after=None,
            winner="exact_historical_silver",
            reason="owner_exception_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason="owner_exception",
            state_clear_result="ALL_CLEAR",
            caught_exceptions=[owner_proposal["caught_exception"]],
        )
        return parent_action, None, proposals

    if (
        owner == _PAN_RULE_ID
        and caught is None
        and after_transaction is None
    ):
        return _cum_reresolve_after_pan_clear(
            obs,
            parent_action,
            parent_semantic,
            snapshot_id,
            proposals,
        )

    if owner_semantic is None or after_transaction is None:
        _cum_clear_all("owner_completed_or_invalid")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=owner,
            owner_after=None,
            winner="exact_historical_silver",
            reason="owner_completed_or_invalid_delegate_actual_parent",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason="owner_completed_or_invalid",
            state_clear_result="ALL_CLEAR",
        )
        return parent_action, None, proposals

    if confirmed:
        _cum_owner_meta["irreversible"] = True
    collision = _cum_resolve_owner_collisions(
        owner,
        owner_semantic,
        _cum_owner_meta.get("irreversible"),
        _cum_owner_meta.get("known_suppressed", ()),
        proposals,
    )
    suppressed = collision["suppressed"]
    collision_failure = collision["rollback_rule"]
    for proposal in proposals:
        if proposal["rule_id"] in suppressed:
            proposal["suppressed_by"] = owner
    if collision_failure is not None:
        next(
            proposal
            for proposal in proposals
            if proposal["rule_id"] == collision_failure
        )["rollback_reason"] = "new_different_post_irreversible"
        _cum_clear_all("new_different_post_irreversible")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=owner,
            owner_after=None,
            winner="exact_historical_silver",
            reason="unknown_post_irreversible_collision_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=suppressed,
            rollback_reason=(
                f"new_different_post_irreversible:{collision_failure}"
            ),
            state_clear_result="ALL_CLEAR",
        )
        return parent_action, None, proposals

    _cum_owner_meta["known_suppressed"] = collision["known_suppressed"]
    _cum_owner_meta["last_action"] = owner_semantic
    bound = _cum_bind_semantic(obs, owner_semantic)
    if bound is None:
        _cum_clear_all("owner_option_binding_failed")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=owner,
            owner_after=None,
            winner="exact_historical_silver",
            reason="owner_binding_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=suppressed,
            rollback_reason="owner_option_binding_failed",
            option_binding="FAILED",
            state_clear_result="ALL_CLEAR",
        )
        return parent_action, None, proposals
    _cum_emit_telemetry(
        obs,
        snapshot_id=snapshot_id,
        parent_semantic=parent_semantic,
        proposals=proposals,
        owner_before=owner,
        owner_after=owner,
        winner=owner,
        reason="rank2_active_transaction_owner",
        final_semantic=owner_semantic,
        attribution=owner,
        suppressed=suppressed,
    )
    _cum_cache_final(snapshot_id, owner_semantic, owner)
    return bound, owner, proposals


def choose_options(obs):
    global _cum_callback_parent_action, _cum_callback_parent_semantic
    global _cum_boss_ledger_snapshot, _cum_boss_ledger_ready
    global _cum_boss_confirmed_now
    _cum_callback_parent_action = None
    _cum_callback_parent_semantic = None
    owner_before = _cum_active_transaction_owner
    snapshot_id = _cum_public_snapshot_id(obs)

    retry = _cum_retry_if_identical(obs, snapshot_id)
    if retry is not None:
        return retry

    _cum_boss_ledger_snapshot = None
    _cum_boss_ledger_ready = False
    _cum_boss_confirmed_now = False
    parent_action = _cum_parent_choose_options(copy.deepcopy(obs))
    if not _cum_valid_action(obs, parent_action):
        _cum_clear_all_and_ledger("invalid_parent_action")
        emergency = _cum_emergency_action(obs)
        emergency_semantic = _cum_action_semantic(obs, emergency)
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=None,
            proposals=[],
            owner_before=owner_before,
            owner_after=None,
            winner="engine_emergency",
            reason="rank0_invalid_parent_action",
            final_semantic=emergency_semantic,
            attribution="engine_emergency",
            suppressed=[],
            rollback_reason="invalid_parent_action",
            invalid_or_emergency_fallback=True,
            state_clear_result="ALL_CLEAR",
        )
        _cum_cache_final(snapshot_id, emergency_semantic, "engine_emergency")
        return emergency
    parent_semantic = _cum_action_semantic(obs, parent_action)
    _cum_callback_parent_action = copy.deepcopy(parent_action)
    _cum_callback_parent_semantic = copy.deepcopy(parent_semantic)

    try:
        _pan_observation_prepass(obs)
        _cum_observe_boss_prepass(obs)
    except Exception as error:
        reason = "integrated_prepass_fail_closed:" + type(error).__name__
        _cum_clear_all_and_ledger(reason)
        guard_semantics = _boss_guard_action_semantics(obs, parent_action)
        _set_boss_guard_resolution(
            obs,
            owner="EXACT_HISTORICAL_SILVER",
            suppression_reason="FAIL_CLOSED_EXACT_PARENT",
            parent_semantics=guard_semantics,
            final_semantics=guard_semantics,
            fail_closed_reason=reason,
        )
        fail_closed_proposals = _cum_evaluate_all_clear(
            obs, parent_action
        )
        for proposal in fail_closed_proposals:
            if proposal["eligible"]:
                proposal["suppressed_by"] = "exact_historical_silver"
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=fail_closed_proposals,
            owner_before=owner_before,
            owner_after=None,
            winner="exact_historical_silver",
            reason="rank19_public_observation_prepass_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason=reason,
            state_clear_result="ALL_CLEAR",
            caught_exceptions=[
                {"type": type(error).__name__, "message": str(error)}
            ],
        )
        _cum_cache_final(
            snapshot_id, parent_semantic, "exact_historical_silver"
        )
        return parent_action

    if not _cum_owner_state_sane():
        _cum_clear_all_and_ledger("ownership_sanity_failure")
        sanity_proposals = _cum_evaluate_all_clear(obs, parent_action)
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=sanity_proposals,
            owner_before=owner_before,
            owner_after=None,
            winner="exact_historical_silver",
            reason="ownership_sanity_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason="ownership_sanity_failure",
            state_clear_result="ALL_CLEAR",
        )
        _cum_cache_final(
            snapshot_id, parent_semantic, "exact_historical_silver"
        )
        return parent_action

    if obs.current.result != -1:
        _cum_clear_all("result_seen")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=[],
            owner_before=owner_before,
            owner_after=None,
            winner="exact_historical_silver",
            reason="rank0_result_reset",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            duplicate_or_reset_state="RESULT_RESET",
            state_clear_result="ALL_CLEAR",
        )
        _cum_cache_final(snapshot_id, parent_semantic, "exact_historical_silver")
        return parent_action

    parent_rank1 = _cum_parent_rank1_terminal(obs, parent_action)
    if parent_rank1:
        _cum_clear_all("rank1_exact_parent_terminal")
        proposals = _cum_evaluate_all_clear(obs, parent_action)
        for proposal in proposals:
            if proposal["eligible"]:
                proposal["suppressed_by"] = "exact_historical_silver"
        suppressed = [
            proposal["rule_id"]
            for proposal in proposals
            if proposal["eligible"]
        ]
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=owner_before,
            owner_after=None,
            winner="exact_historical_silver",
            reason="rank1_exact_parent_terminal",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=suppressed,
            state_clear_result="ALL_CLEAR",
        )
        _cum_cache_final(snapshot_id, parent_semantic, "exact_historical_silver")
        return parent_action

    if _cum_active_transaction_owner is not None:
        resumed, _, _ = _cum_resume_owner(
            obs,
            parent_action,
            parent_semantic,
            snapshot_id,
        )
        if resumed is not None:
            return resumed
        emergency = _cum_emergency_action(obs)
        emergency_semantic = _cum_action_semantic(obs, emergency)
        _cum_cache_final(snapshot_id, emergency_semantic, "engine_emergency")
        return emergency

    proposals = _cum_evaluate_all_clear(obs, parent_action)
    resolution = _cum_resolve_clear_proposals(proposals)
    eligible = resolution["eligible"]
    winner_id = resolution["winner"]
    if winner_id == "exact_historical_silver":
        if resolution["unknown"]:
            _cum_clear_all("unknown_clear_collision")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=None,
            owner_after=None,
            winner=winner_id,
            reason=resolution["reason"],
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason=(
                "unknown_clear_collision"
                if resolution["unknown"]
                else None
            ),
            state_clear_result=(
                "ALL_CLEAR" if resolution["unknown"] else "UNCHANGED_CLEAR"
            ),
        )
        _cum_cache_final(snapshot_id, parent_semantic, "exact_historical_silver")
        return parent_action

    winner = next(
        proposal for proposal in eligible if proposal["rule_id"] == winner_id
    )
    suppressed = [
        proposal for proposal in eligible if proposal["rule_id"] != winner_id
    ]
    for proposal in suppressed:
        proposal["suppressed_by"] = winner_id
    winner["emitted"] = True
    if not _cum_commit_proposal(winner, snapshot_id, suppressed):
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=None,
            owner_after=None,
            winner="exact_historical_silver",
            reason="two_owner_commit_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason="two_owner_commit",
            state_clear_result="ALL_CLEAR",
        )
        _cum_cache_final(snapshot_id, parent_semantic, "exact_historical_silver")
        return parent_action
    bound = _cum_bind_semantic(obs, winner["desired_action"])
    if bound is None:
        _cum_clear_all("winning_option_binding_failed")
        _cum_emit_telemetry(
            obs,
            snapshot_id=snapshot_id,
            parent_semantic=parent_semantic,
            proposals=proposals,
            owner_before=None,
            owner_after=None,
            winner="exact_historical_silver",
            reason="winning_binding_fail_closed",
            final_semantic=parent_semantic,
            attribution="exact_historical_silver",
            suppressed=[proposal["rule_id"] for proposal in suppressed],
            rollback_reason="winning_option_binding_failed",
            option_binding="FAILED",
            state_clear_result="ALL_CLEAR",
        )
        _cum_cache_final(snapshot_id, parent_semantic, "exact_historical_silver")
        return parent_action
    _cum_emit_telemetry(
        obs,
        snapshot_id=snapshot_id,
        parent_semantic=parent_semantic,
        proposals=proposals,
        owner_before=None,
        owner_after=_cum_active_transaction_owner,
        winner=winner_id,
        reason=resolution["reason"],
        final_semantic=winner["desired_action"],
        attribution=winner_id,
        suppressed=[proposal["rule_id"] for proposal in suppressed],
    )
    _cum_cache_final(snapshot_id, winner["desired_action"], winner_id)
    return bound


def _cum_reset_runtime(reason):
    global _cum_active_transaction_owner, _cum_owner_meta
    global _cum_last_snapshot_id, _cum_last_final_semantic
    global _cum_last_attribution, _cum_callback_parent_action
    global _cum_callback_parent_semantic
    global _cum_boss_ledger_snapshot, _cum_boss_ledger_ready
    global _cum_boss_confirmed_now
    _cum_reset_components(reason)
    _reset_public_boss_ledger(reason)
    _cum_active_transaction_owner = None
    _cum_owner_meta = None
    _cum_last_snapshot_id = None
    _cum_last_final_semantic = None
    _cum_last_attribution = None
    _cum_callback_parent_action = None
    _cum_callback_parent_semantic = None
    _cum_boss_ledger_snapshot = None
    _cum_boss_ledger_ready = False
    _cum_boss_confirmed_now = False


def agent(obs_dict):
    global _opp_last_attack_id, _opp_last_attack_serial, _cur_turn_logs
    global _cum_game_epoch, _sat_game_epoch, _hero_game_epoch
    global _h2_last_seat, _h2_last_turn
    global _h1_last_seat, _h1_last_turn
    global _h3_last_seat, _h3_last_turn
    obs = to_observation_class(obs_dict)
    if obs.select is None:
        owner_before = _cum_active_transaction_owner
        _opp_last_attack_id = None
        _opp_last_attack_serial = None
        _cur_turn_logs.clear()
        _cum_game_epoch += 1
        _sat_game_epoch += 1
        _hero_game_epoch += 1
        _cum_reset_runtime("deck_request")
        _h2_last_seat = None
        _h2_last_turn = None
        _h1_last_seat = None
        _h1_last_turn = None
        _h3_last_seat = None
        _h3_last_turn = None
        _cum_emit_telemetry(
            None,
            snapshot_id=f"{_cum_game_epoch}:DECK_REQUEST",
            parent_semantic=None,
            proposals=[],
            owner_before=owner_before,
            owner_after=None,
            winner="engine_deck_request",
            reason="rank0_deck_request_reset",
            final_semantic=None,
            attribution="engine_deck_request",
            suppressed=[],
            duplicate_or_reset_state="DECK_REQUEST",
            state_clear_result="ALL_CLEAR",
        )
        return read_deck_csv()
    _update_opp_attack_tracking(obs)
    if not obs.select.option:
        owner_before = _cum_active_transaction_owner
        _cum_clear_all_and_ledger("empty_options")
        _cum_emit_telemetry(
            obs,
            snapshot_id=_cum_public_snapshot_id(obs),
            parent_semantic=(),
            proposals=[],
            owner_before=owner_before,
            owner_after=None,
            winner="engine_empty_options",
            reason="rank0_empty_options",
            final_semantic=(),
            attribution="engine_empty_options",
            suppressed=[],
            duplicate_or_reset_state="EMPTY_OPTIONS",
            state_clear_result="ALL_CLEAR",
        )
        return []
    try:
        return choose_options(obs)
    except Exception as error:
        owner_before = _cum_active_transaction_owner
        _cum_clear_all_and_ledger("outer_exception")
        if _cum_callback_parent_action is not None:
            parent = copy.deepcopy(_cum_callback_parent_action)
        else:
            try:
                parent = _cum_parent_choose_options(copy.deepcopy(obs))
            except Exception:
                parent = _cum_emergency_action(obs)
        if not _cum_valid_action(obs, parent):
            parent = _cum_emergency_action(obs)
        semantic = _cum_action_semantic(obs, parent)
        _cum_emit_telemetry(
            obs,
            snapshot_id=_cum_public_snapshot_id(obs),
            parent_semantic=semantic,
            proposals=[],
            owner_before=owner_before,
            owner_after=None,
            winner="exact_historical_silver",
            reason="outer_exception_fail_closed",
            final_semantic=semantic,
            attribution="exact_historical_silver",
            suppressed=[],
            rollback_reason="outer_exception",
            invalid_or_emergency_fallback=True,
            state_clear_result="ALL_CLEAR",
            caught_exceptions=[
                {"type": type(error).__name__, "message": str(error)}
            ],
        )
        return parent


# ---- Parent-first public complete-turn fundamentals overlay v2 -------------
#
# This layer is intentionally appended after the complete frozen parent.  The
# captured parent remains the default and is evaluated exactly once for every
# callback.  The overlay owns only the narrow, public, purpose-bound
# transactions below; it never imports the rejected v1 planner.

_pfc_parent_agent = agent

_PFC_RULE_ID = "PARENT_FIRST_COMPLETE_TURN_FUNDAMENTALS_V2"
_PFC_CONTRACT_SHA256 = (
    "5430B984D9F68B77178A74ED72C29C63E5A1A08C703F89AB62334F6A5DD4B7A1"
)

_pfc_transaction = None
_pfc_search_watch = None
_pfc_parent_call_count = 0
_pfc_counters = Counter()
_pfc_last_telemetry = {
    "rule_id": _PFC_RULE_ID,
    "contract_sha256": _PFC_CONTRACT_SHA256,
    "parent_semantics": None,
    "candidate_semantics": None,
    "purpose": None,
    "gates": {},
    "certificate": None,
    "stage": "CLEAR",
    "bindings": {},
    "owner_before": None,
    "owner_after": None,
    "strict_improvement": None,
    "rejection_reason": "not_evaluated",
    "transition_confirmation": None,
    "duplicate_retry": False,
    "rollback": None,
    "exception": None,
    "emergency": False,
    "final_semantics": None,
}


def _pfc_serial(value):
    serial = getattr(value, "serial", None)
    return serial if isinstance(serial, int) and serial > 0 else None


def _pfc_semantics(obs, action):
    return _cum_action_semantic(obs, action)


def _pfc_parent_option(obs, parent_action):
    if (
        not isinstance(parent_action, list)
        or len(parent_action) != 1
        or not isinstance(parent_action[0], int)
        or parent_action[0] < 0
        or parent_action[0] >= len(obs.select.option)
    ):
        return None
    return obs.select.option[parent_action[0]]


def _pfc_emit_telemetry(
        obs,
        parent_action,
        *,
        candidate_action=None,
        purpose=None,
        gates=None,
        certificate=None,
        owner_before=None,
        owner_after=None,
        strict_improvement=None,
        rejection_reason=None,
        transition_confirmation=None,
        duplicate_retry=False,
        rollback=None,
        exception=None,
        emergency=False):
    global _pfc_last_telemetry
    parent_semantics = (
        None if obs is None else _pfc_semantics(obs, parent_action)
    )
    candidate_semantics = (
        None
        if obs is None or candidate_action is None
        else _pfc_semantics(obs, candidate_action)
    )
    final_semantics = (
        candidate_semantics
        if candidate_action is not None
        else parent_semantics
    )
    transaction = _pfc_transaction
    _pfc_last_telemetry = {
        "rule_id": _PFC_RULE_ID,
        "contract_sha256": _PFC_CONTRACT_SHA256,
        "parent_semantics": _cum_jsonable(parent_semantics),
        "candidate_semantics": _cum_jsonable(candidate_semantics),
        "purpose": purpose,
        "gates": _cum_jsonable(gates or {}),
        "certificate": _cum_jsonable(certificate),
        "stage": (
            "CLEAR"
            if transaction is None
            else transaction.get("stage", "ACTIVE")
        ),
        "bindings": _cum_jsonable(
            {} if transaction is None else transaction.get("bindings", {})
        ),
        "owner_before": owner_before,
        "owner_after": owner_after,
        "strict_improvement": strict_improvement,
        "rejection_reason": rejection_reason,
        "transition_confirmation": transition_confirmation,
        "duplicate_retry": bool(duplicate_retry),
        "rollback": rollback,
        "exception": exception,
        "emergency": bool(emergency),
        "final_semantics": _cum_jsonable(final_semantics),
    }


def _pfc_clear(reason):
    global _pfc_transaction, _pfc_search_watch
    if _pfc_transaction is not None:
        _pfc_counters[f"rollback:{reason}"] += 1
    _pfc_transaction = None
    _pfc_search_watch = None


def _pfc_hand(obs):
    hand = my_state(obs).hand
    if hand is None or my_state(obs).handCount != len(hand):
        return None
    if any(card is None or _pfc_serial(card) is None for card in hand):
        return None
    serials = [_pfc_serial(card) for card in hand]
    if len(serials) != len(set(serials)):
        return None
    return tuple(hand)


def _pfc_cards(cards, card_id):
    return tuple(
        card for card in (cards or ())
        if card is not None and getattr(card, "id", None) == card_id
    )


def _pfc_visible_serial_unique(obs, serial):
    if serial is None:
        return False
    return sum(
        1 for card in _h5v2_visible_cards(obs)
        if _pfc_serial(card) == serial
    ) == 1


def _pfc_fixed_card_semantics_supported():
    explorer = CARD_DB.get(EXPLORER)
    pad = CARD_DB.get(POKE_PAD)
    ultra = CARD_DB.get(ULTRA_BALL)
    duraludon = CARD_DB.get(DURALUDON)
    archaludon = CARD_DB.get(ARCHALUDON)
    archaludon_ex = CARD_DB.get(ARCHALUDON_EX)
    coated = ALL_ATTACKS.get(COATED_ATTACK)
    return bool(
        explorer is not None
        and tuple(
            (getattr(skill, "name", None), getattr(skill, "text", None))
            for skill in (getattr(explorer, "skills", None) or ())
        ) == ((
            "Explorer’s Guidance",
            "Look at the top 6 cards of your deck and put 2 of them into "
            "your hand. Discard the other cards.",
        ),)
        and pad is not None
        and tuple(
            getattr(skill, "text", None)
            for skill in (getattr(pad, "skills", None) or ())
        ) == (
            "Search your deck for a Pokémon that doesn’t have a Rule "
            "Box, reveal it, and put it into your hand. Then, shuffle your "
            "deck. (Pokémon {ex}, Pokémon {V}, etc. have Rule Boxes.)",
        )
        and ultra is not None
        and tuple(
            getattr(skill, "text", None)
            for skill in (getattr(ultra, "skills", None) or ())
        ) == (
            "You can use this card only if you discard 2 other cards from "
            "your hand.\n\nSearch your deck for a Pokémon, reveal it, "
            "and put it into your hand. Then, shuffle your deck.",
        )
        and duraludon is not None
        and getattr(duraludon, "basic", None) is True
        and getattr(duraludon, "hp", None) == 130
        and archaludon is not None
        and getattr(archaludon, "stage1", None) is True
        and getattr(archaludon, "ex", None) is False
        and getattr(archaludon, "evolvesFrom", None) == "Duraludon"
        and archaludon_ex is not None
        and getattr(archaludon_ex, "stage1", None) is True
        and getattr(archaludon_ex, "ex", None) is True
        and getattr(archaludon_ex, "evolvesFrom", None) == "Duraludon"
        and coated is not None
        and getattr(coated, "damage", None) == 120
        and tuple(getattr(coated, "energies", None) or ())
        == (METAL_ENERGY, METAL_ENERGY, METAL_ENERGY)
        and getattr(coated, "text", None) == (
            "During your opponent’s next turn, prevent all damage done "
            "to this Pokémon by attacks from Basic Pokémon."
        )
    )


def _pfc_status_allows_attack(obs):
    mine = my_state(obs)
    return not (
        bool(getattr(mine, "asleep", False))
        or bool(getattr(mine, "paralyzed", False))
        or bool(getattr(mine, "confused", False))
    )


def _pfc_can_pay(energies, attack_id):
    attack = ALL_ATTACKS.get(attack_id)
    if attack is None:
        return False
    available = [int(value) for value in energies]
    cost = [int(value) for value in (getattr(attack, "energies", None) or ())]
    for required in (value for value in cost if value != 0):
        try:
            position = available.index(required)
        except ValueError:
            return False
        available.pop(position)
    return len(available) >= sum(1 for value in cost if value == 0)


def _pfc_attack_damage(obs, attack_id):
    target = opp_active_pokemon(obs)
    if target is None:
        return None
    return _h2_fixed_attack_damage(obs, target, attack_id)


def _pfc_attack_route(obs, preferred_attack=None):
    active = active_pokemon(obs)
    opposing = opp_active_pokemon(obs)
    hand = _pfc_hand(obs)
    if (
        active is None
        or opposing is None
        or hand is None
        or active.id != DURALUDON
        or not _pfc_status_allows_attack(obs)
        or _pfc_serial(active) is None
        or not _pfc_visible_serial_unique(obs, _pfc_serial(active))
    ):
        return None
    legal = []
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.ATTACK:
            continue
        attack_id = getattr(option, "attackId", None)
        damage = _pfc_attack_damage(obs, attack_id)
        if damage is None:
            continue
        legal.append((position, attack_id, damage))
    if preferred_attack is not None:
        legal = [row for row in legal if row[1] == preferred_attack]
    if legal:
        position, attack_id, damage = max(
            legal, key=lambda row: (row[2], -row[1], -row[0])
        )
        return {
            "attack_id": attack_id,
            "attack_damage": damage,
            "attack_semantics_now": _pfc_semantics(obs, [position]),
            "attachment_serial": None,
            "attachment_card_id": None,
            "active_serial": _pfc_serial(active),
            "target_serial": _pfc_serial(opposing),
            "target_card_id": opposing.id,
            "target_hp": opposing.hp,
            "prize_result": (
                _h2_visible_prize_value(opposing)
                if damage >= opposing.hp else 0
            ),
        }
    if obs.current.energyAttached:
        return None
    metal_attachments = []
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.ATTACH:
            continue
        card = option_card(obs, option)
        target = option_target(obs, option)
        if (
            card is not None
            and card.id == METAL_ENERGY
            and _pfc_serial(card) is not None
            and target is not None
            and _pfc_serial(target) == _pfc_serial(active)
            and getattr(option, "inPlayArea", None) == AreaType.ACTIVE
        ):
            metal_attachments.append((position, card))
    if not metal_attachments:
        return None
    energies = tuple(int(value) for value in (active.energies or ()))
    payable = []
    for attack_id in tuple(getattr(CARD_DB.get(DURALUDON), "attacks", ()) or ()):
        if not _pfc_can_pay(energies + (METAL_ENERGY,), attack_id):
            continue
        damage = _pfc_attack_damage(obs, attack_id)
        if damage is None:
            continue
        payable.append((attack_id, damage))
    if preferred_attack is not None:
        payable = [row for row in payable if row[0] == preferred_attack]
    if not payable:
        return None
    attack_id, damage = max(payable, key=lambda row: (row[1], -row[0]))
    position, metal = min(
        metal_attachments, key=lambda row: (_pfc_serial(row[1]), row[0])
    )
    return {
        "attack_id": attack_id,
        "attack_damage": damage,
        "attack_semantics_now": None,
        "attachment_serial": _pfc_serial(metal),
        "attachment_card_id": metal.id,
        "attachment_semantics_now": _pfc_semantics(obs, [position]),
        "active_serial": _pfc_serial(active),
        "target_serial": _pfc_serial(opposing),
        "target_card_id": opposing.id,
        "target_hp": opposing.hp,
        "prize_result": (
            _h2_visible_prize_value(opposing)
            if damage >= opposing.hp else 0
        ),
    }


def _pfc_reserved_resources(obs, consumed=()):
    hand = _pfc_hand(obs)
    if hand is None:
        return None
    consumed = frozenset(consumed)
    rows = {
        "metal": [],
        "line_pieces": [],
        "boss": [],
        "recovery": [],
        "ace_spec": [],
    }
    for card in hand:
        serial = _pfc_serial(card)
        if serial in consumed:
            continue
        if card.id == METAL_ENERGY:
            rows["metal"].append(serial)
        if card.id in (DURALUDON, ARCHALUDON, ARCHALUDON_EX):
            rows["line_pieces"].append((card.id, serial))
        if card.id == BOSS:
            rows["boss"].append(serial)
        if card.id == NIGHT_STRETCHER:
            rows["recovery"].append(serial)
        data = CARD_DB.get(card.id)
        if data is not None and bool(getattr(data, "aceSpec", False)):
            rows["ace_spec"].append((card.id, serial))
    return {key: tuple(value) for key, value in rows.items()}


def _pfc_backup_certificate(obs, route, target_card):
    hand = _pfc_hand(obs)
    active = active_pokemon(obs)
    mine = my_state(obs)
    if (
        hand is None
        or active is None
        or active.id != DURALUDON
        or mine.bench
        or mine.benchMax <= 0
        or target_card is None
        or target_card.id != DURALUDON
        or _pfc_serial(target_card) is None
    ):
        return None
    attachment = route.get("attachment_serial")
    metal_hand = sorted(
        _pfc_serial(card)
        for card in hand
        if card.id == METAL_ENERGY
        and _pfc_serial(card) != attachment
    )
    ex_hand = sorted(
        _pfc_serial(card) for card in hand
        if card.id == ARCHALUDON_EX
    )
    discard_metal = sorted(
        _pfc_serial(card) for card in (mine.discard or ())
        if card is not None
        and card.id == METAL_ENERGY
        and _pfc_serial(card) is not None
    )
    if not metal_hand or not ex_hand or not discard_metal:
        return None
    return {
        "bench_serial": _pfc_serial(target_card),
        "forced_promotion_if_active_ko": True,
        "switch_route": "not_required_only_backup",
        "retreat_route": "not_required_for_forced_promotion",
        "payable_attack_route": {
            "attack_id": 223,
            "attack_name": "Hammer In",
            "manual_metal_serial": metal_hand[0],
            "payable_next_turn": True,
        },
        "ex_alloy_route": {
            "evolution_serial": ex_hand[0],
            "alloy_metal_serials": (discard_metal[0],),
            "manual_metal_serial": metal_hand[0],
            "evolution_legal_next_turn": True,
        },
    }


def _pfc_formation_certificate(
        obs,
        target_card,
        *,
        source_kind,
        source_serial=None,
        cost_cards=()):
    active = active_pokemon(obs)
    opposing = opp_active_pokemon(obs)
    route = _pfc_attack_route(obs)
    backup = _pfc_backup_certificate(obs, route or {}, target_card)
    if (
        not _pfc_fixed_card_semantics_supported()
        or active is None
        or opposing is None
        or route is None
        or backup is None
        or obs.current.result != -1
        or obs.select.context != SelectContext.MAIN
        or _h2_has_precedent_terminal(obs)
        or my_state(obs).deckCount <= 0
    ):
        return None
    consumed = tuple(_pfc_serial(card) for card in cost_cards)
    reserves = _pfc_reserved_resources(
        obs,
        consumed=consumed + (
            (route["attachment_serial"],)
            if route["attachment_serial"] is not None else ()
        ),
    )
    if reserves is None:
        return None
    return {
        "source_snapshot": _cum_public_snapshot_id(obs),
        "source_kind": source_kind,
        "source_serial": source_serial,
        "purpose": "CREATE_BASIC_BACKUP",
        "card_serials": {
            "basic_duraludon": _pfc_serial(target_card),
            "search_source": source_serial,
            "discard_costs": tuple(
                (card.id, _pfc_serial(card)) for card in cost_cards
            ),
            "manual_attachment": route["attachment_serial"],
            "active": route["active_serial"],
            "opposing_target": route["target_serial"],
        },
        "search": {
            "source": source_kind,
            "exact_costs": tuple(
                (card.id, _pfc_serial(card)) for card in cost_cards
            ),
            "acceptable_result_roles": ("BASIC_DURALUDON",),
            "target_card_id": DURALUDON,
            "target_serial": _pfc_serial(target_card),
            "whiff_continuation": {
                "attack_id": route["attack_id"],
                "attachment_serial": route["attachment_serial"],
                "same_attack_guaranteed": True,
            },
        },
        "evolution_target": backup["ex_alloy_route"]["evolution_serial"],
        "alloy_allocations": backup["ex_alloy_route"]["alloy_metal_serials"],
        "manual_attachment": {
            "energy_serial": route["attachment_serial"],
            "target_serial": route["active_serial"],
        },
        "attack": {
            "attacker_serial": route["active_serial"],
            "attack_id": route["attack_id"],
            "opposing_target_serial": route["target_serial"],
            "damage": route["attack_damage"],
            "ko": route["attack_damage"] >= route["target_hp"],
            "prize_result": route["prize_result"],
        },
        "end_active_serial": route["active_serial"],
        "accessible_backup": backup,
        "reserved": reserves,
        "contingencies": {
            "search_whiff": "fresh_parent_same_attack",
            "missing_bench_option": "fresh_parent_same_attack",
            "missing_attachment": "fresh_parent_from_actual_state",
            "missing_attack": "fresh_parent_from_actual_state",
            "reveal_dependent_choice": "only_exact_basic_duraludon",
        },
        "pareto_gates": {
            "known_steps_legal": True,
            "parent_attack_retained": True,
            "damage_no_worse": True,
            "prize_no_worse": True,
            "return_prize_no_better": True,
            "attachment_and_attack_accessible": True,
            "backup_executable": True,
            "ex_alloy_preserved": True,
            "boss_recovery_ace_preserved": True,
            "strict_improvement": "nonempty_executable_backup_prevents_board_out",
            "hidden_card_required": False,
        },
        "route": route,
    }


def _pfc_unique_option(obs, predicate):
    matches = [
        position for position, option in enumerate(obs.select.option)
        if predicate(position, option)
    ]
    return matches[0] if len(matches) == 1 else None


def _pfc_option_for_card_serial(obs, serial, option_types=None):
    option_types = None if option_types is None else frozenset(option_types)
    return _pfc_unique_option(
        obs,
        lambda _position, option: (
            (option_types is None or option.type in option_types)
            and (
                (card := option_card(obs, option)) is not None
                and _pfc_serial(card) == serial
            )
        ),
    )


def _pfc_option_for_attack(obs, attack_id):
    return _pfc_unique_option(
        obs,
        lambda _position, option: (
            option.type == OptionType.ATTACK
            and getattr(option, "attackId", None) == attack_id
        ),
    )


def _pfc_option_for_attachment(obs, energy_serial, target_serial):
    return _pfc_unique_option(
        obs,
        lambda _position, option: (
            option.type == OptionType.ATTACH
            and (
                (card := option_card(obs, option)) is not None
                and _pfc_serial(card) == energy_serial
            )
            and (
                (target := option_target(obs, option)) is not None
                and _pfc_serial(target) == target_serial
            )
        ),
    )


def _pfc_begin_transaction(
        obs,
        purpose,
        stage,
        certificate,
        bindings,
        action):
    global _pfc_transaction
    semantic = _pfc_semantics(obs, action)
    if semantic is None or _cum_bind_semantic(obs, semantic) is None:
        return False
    _pfc_transaction = {
        "owner": _PFC_RULE_ID,
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "purpose": purpose,
        "stage": stage,
        "certificate": copy.deepcopy(certificate),
        "bindings": copy.deepcopy(bindings),
        "last_snapshot": _cum_public_snapshot_id(obs),
        "last_semantic": copy.deepcopy(semantic),
        "last_action_count": obs.current.turnActionCount,
        "irreversible": True,
        "transition_history": (),
    }
    _pfc_counters["starts"] += 1
    return True


def _pfc_record_emission(obs, stage, action, transition):
    transaction = _pfc_transaction
    semantic = _pfc_semantics(obs, action)
    if transaction is None or semantic is None:
        return False
    transaction["stage"] = stage
    transaction["last_snapshot"] = _cum_public_snapshot_id(obs)
    transaction["last_semantic"] = copy.deepcopy(semantic)
    transaction["last_action_count"] = obs.current.turnActionCount
    transaction["transition_history"] = (
        tuple(transaction.get("transition_history", ())) + (transition,)
    )
    return True


def _pfc_attack_log_confirmed(obs, transaction):
    attack_id = transaction["bindings"].get("attack_id")
    attacker_serial = transaction["bindings"].get("active_serial")
    return any(
        entry.type == LogType.ATTACK
        and entry.playerIndex == transaction["seat"]
        and entry.attackId == attack_id
        and (
            attacker_serial is None
            or entry.serial == attacker_serial
            or entry.serial
            == transaction["bindings"].get("evolution_serial")
        )
        for entry in (obs.logs or ())
    )


def _pfc_transition_to_bench(obs, transaction):
    serial = transaction["bindings"]["basic_serial"]
    return any(
        pokemon is not None
        and pokemon.id == DURALUDON
        and _pfc_serial(pokemon) == serial
        for pokemon in (my_state(obs).bench or ())
    )


def _pfc_transition_to_hand(obs, transaction):
    serial = transaction["bindings"]["basic_serial"]
    return any(
        card.id == DURALUDON and _pfc_serial(card) == serial
        for card in (_pfc_hand(obs) or ())
    )


def _pfc_transition_attached(obs, transaction):
    active = active_pokemon(obs)
    serial = transaction["bindings"].get("attachment_serial")
    return (
        serial is None
        or (
            active is not None
            and any(
                _pfc_serial(card) == serial
                for card in (getattr(active, "energyCards", None) or ())
            )
        )
    )


def _pfc_transition_evolved(obs, transaction):
    active = active_pokemon(obs)
    evolution_serial = transaction["bindings"].get("evolution_serial")
    source_serial = transaction["bindings"].get("active_serial")
    return bool(
        active is not None
        and active.id == ARCHALUDON
        and _pfc_serial(active) == evolution_serial
        and any(
            _pfc_serial(card) == source_serial
            for card in (getattr(active, "preEvolution", None) or ())
        )
    )


def _pfc_resume_transaction(obs, parent_action):
    global _pfc_transaction
    transaction = _pfc_transaction
    if transaction is None:
        return None, None
    snapshot = _cum_public_snapshot_id(obs)
    if snapshot == transaction.get("last_snapshot"):
        rebound = _cum_bind_semantic(obs, transaction.get("last_semantic"))
        if rebound is None:
            _pfc_clear("duplicate_binding_failure")
            return parent_action, "duplicate_binding_failure"
        _pfc_counters["duplicates"] += 1
        return rebound, "duplicate_retry"
    if _pfc_attack_log_confirmed(obs, transaction):
        certificate = copy.deepcopy(transaction["certificate"])
        _pfc_counters["completions"] += 1
        _pfc_clear("complete")
        return parent_action, ("complete", certificate)
    if (
        obs.current.result != -1
        or obs.current.yourIndex != transaction["seat"]
        or obs.current.turn != transaction["turn"]
        or obs.current.turnActionCount
        != transaction.get("last_action_count", -1) + 1
    ):
        _pfc_clear("turn_seat_result_or_skipped_stage")
        return parent_action, "turn_seat_result_or_skipped_stage"
    stage = transaction["stage"]
    bindings = transaction["bindings"]
    if stage in ("PAD_SEARCH_EMITTED", "ULTRA_SEARCH_EMITTED"):
        if not _pfc_transition_to_hand(obs, transaction):
            _pfc_clear("search_transition_missing")
            return parent_action, "search_transition_missing"
        position = _pfc_option_for_card_serial(
            obs, bindings["basic_serial"], (OptionType.PLAY,)
        )
        if position is None:
            _pfc_clear("bench_binding_failure")
            return parent_action, "bench_binding_failure"
        action = [position]
        _pfc_record_emission(
            obs, "BENCH_EMITTED", action, "search_to_hand_confirmed"
        )
        return action, "search_to_hand_confirmed"
    if stage == "BENCH_EMITTED":
        if not _pfc_transition_to_bench(obs, transaction):
            _pfc_clear("bench_transition_missing")
            return parent_action, "bench_transition_missing"
        attachment_serial = bindings.get("attachment_serial")
        if attachment_serial is not None:
            position = _pfc_option_for_attachment(
                obs, attachment_serial, bindings["active_serial"]
            )
            if position is None:
                _pfc_clear("attachment_binding_failure")
                return parent_action, "attachment_binding_failure"
            action = [position]
            _pfc_record_emission(
                obs, "ATTACH_EMITTED", action, "bench_confirmed"
            )
            return action, "bench_confirmed"
        position = _pfc_option_for_attack(obs, bindings["attack_id"])
        if position is None:
            _pfc_clear("attack_binding_failure_after_bench")
            return parent_action, "attack_binding_failure_after_bench"
        action = [position]
        _pfc_record_emission(
            obs, "ATTACK_EMITTED", action, "bench_and_attack_recertified"
        )
        return action, "bench_and_attack_recertified"
    if stage == "ATTACH_EMITTED":
        if not _pfc_transition_attached(obs, transaction):
            _pfc_clear("attachment_transition_missing")
            return parent_action, "attachment_transition_missing"
        position = _pfc_option_for_attack(obs, bindings["attack_id"])
        if position is None:
            _pfc_clear("attack_binding_failure_after_attachment")
            return parent_action, "attack_binding_failure_after_attachment"
        action = [position]
        _pfc_record_emission(
            obs, "ATTACK_EMITTED", action, "attachment_and_attack_recertified"
        )
        return action, "attachment_and_attack_recertified"
    if stage == "NONEX_EVOLVE_EMITTED":
        if not _pfc_transition_evolved(obs, transaction):
            _pfc_clear("evolution_transition_missing")
            return parent_action, "evolution_transition_missing"
        position = _pfc_option_for_attack(obs, COATED_ATTACK)
        if position is None:
            _pfc_clear("coated_attack_binding_failure")
            return parent_action, "coated_attack_binding_failure"
        action = [position]
        active = active_pokemon(obs)
        bindings["active_serial"] = _pfc_serial(active)
        _pfc_record_emission(
            obs, "ATTACK_EMITTED", action, "evolution_and_attack_recertified"
        )
        return action, "evolution_and_attack_recertified"
    if stage == "ULTRA_PLAY_EMITTED":
        if (
            obs.select.context
            not in (
                SelectContext.DISCARD,
                SelectContext.DISCARD_CARD_OR_ATTACHED_CARD,
            )
            or getattr(obs.select, "effect", None) is None
            or getattr(obs.select.effect, "id", None) != ULTRA_BALL
            or _pfc_serial(obs.select.effect) != bindings["source_serial"]
        ):
            _pfc_clear("ultra_discard_callback_missing")
            return parent_action, "ultra_discard_callback_missing"
        positions = []
        for serial in bindings["discard_serials"]:
            position = _pfc_option_for_card_serial(
                obs, serial, (OptionType.CARD,)
            )
            if position is None:
                _pfc_clear("ultra_discard_binding_failure")
                return parent_action, "ultra_discard_binding_failure"
            positions.append(position)
        if len(set(positions)) != 2:
            _pfc_clear("ultra_discard_collision")
            return parent_action, "ultra_discard_collision"
        action = positions
        if not _cum_valid_action(obs, action):
            _pfc_clear("ultra_discard_invalid")
            return parent_action, "ultra_discard_invalid"
        _pfc_record_emission(
            obs, "ULTRA_DISCARD_EMITTED", action, "ultra_play_confirmed"
        )
        return action, "ultra_play_confirmed"
    if stage == "ULTRA_DISCARD_EMITTED":
        discard_serials = frozenset(
            _pfc_serial(card) for card in (my_state(obs).discard or ())
        )
        if not set(bindings["discard_serials"]).issubset(discard_serials):
            _pfc_clear("ultra_discard_transition_missing")
            return parent_action, "ultra_discard_transition_missing"
        if (
            obs.select.context != SelectContext.TO_HAND
            or getattr(obs.select, "effect", None) is None
            or getattr(obs.select.effect, "id", None) != ULTRA_BALL
        ):
            _pfc_clear("ultra_search_callback_missing")
            return parent_action, "ultra_search_callback_missing"
        position = _pfc_option_for_card_serial(
            obs, bindings["basic_serial"], (OptionType.CARD,)
        )
        if position is None:
            _pfc_clear("ultra_search_whiff")
            return parent_action, "ultra_search_whiff"
        action = [position]
        _pfc_record_emission(
            obs, "ULTRA_SEARCH_EMITTED", action, "ultra_costs_confirmed"
        )
        return action, "ultra_costs_confirmed"
    _pfc_clear("unknown_or_missing_callback")
    return parent_action, "unknown_or_missing_callback"


def _pfc_setup_exception(obs, parent_action):
    if obs.select.context != SelectContext.SETUP_BENCH_POKEMON:
        return None
    mine = my_state(obs)
    if mine.benchMax <= len(mine.bench or ()):
        return None
    if any(
        pokemon is not None and pokemon.id == DURALUDON
        for pokemon in (mine.bench or ())
    ):
        return [] if obs.select.minCount == 0 else None
    candidates = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        if (
            option.type == OptionType.CARD
            and card is not None
            and card.id == DURALUDON
            and _pfc_serial(card) is not None
        ):
            candidates.append((position, _pfc_serial(card)))
    if not candidates or obs.select.minCount > 1 or obs.select.maxCount < 1:
        return None
    position, _ = min(candidates, key=lambda row: (row[1], row[0]))
    action = [position]
    return action if _cum_valid_action(obs, action) else None


def _pfc_safe_ultra_costs(obs, ultra_serial, route):
    hand = _pfc_hand(obs)
    if hand is None:
        return None
    counts = Counter(card.id for card in hand)
    protected_ids = {
        DURALUDON,
        ARCHALUDON,
        ARCHALUDON_EX,
        BOSS,
        NIGHT_STRETCHER,
        HERO_CAPE,
    }
    protected_serials = {
        ultra_serial,
        route.get("attachment_serial"),
    }
    reserve_metal = [
        _pfc_serial(card) for card in hand
        if card.id == METAL_ENERGY
        and _pfc_serial(card) not in protected_serials
    ]
    if not reserve_metal:
        return None
    protected_serials.add(min(reserve_metal))
    candidates = []
    for card in hand:
        serial = _pfc_serial(card)
        data = CARD_DB.get(card.id)
        if (
            serial in protected_serials
            or card.id in protected_ids
            or (data is not None and bool(getattr(data, "aceSpec", False)))
            or (card.id in (EXPLORER, LILLIE) and counts[card.id] <= 1)
            or (card.id == METAL_ENERGY and counts[METAL_ENERGY] <= 2)
        ):
            continue
        priority = (
            0 if card.id == CINDERACE else
            1 if card.id == FULL_METAL_LAB and counts[card.id] > 1 else
            2 if card.id in (POKEGEAR, POKE_PAD) and counts[card.id] > 1 else
            3 if card.id in (EXPLORER, LILLIE) and counts[card.id] > 1 else
            4 if card.id == METAL_ENERGY and counts[card.id] > 2 else
            9
        )
        if priority < 9:
            candidates.append((priority, card.id, serial, card))
    candidates.sort(key=lambda row: (row[0], row[1], row[2]))
    if len(candidates) < 2:
        return None
    selected = tuple(row[3] for row in candidates[:2])
    if len({_pfc_serial(card) for card in selected}) != 2:
        return None
    return selected


def _pfc_exposed_deck_basic(obs):
    deck = getattr(obs.select, "deck", None)
    if not deck:
        return None
    candidates = [
        card for card in deck
        if card is not None
        and card.id == DURALUDON
        and _pfc_serial(card) is not None
    ]
    if not candidates:
        return None
    return min(candidates, key=lambda card: _pfc_serial(card))


def _pfc_build_direct_formation(obs, parent_action):
    parent_option = _pfc_parent_option(obs, parent_action)
    hand = _pfc_hand(obs)
    if (
        hand is None
        or parent_option is None
        or parent_option.type not in (OptionType.ATTACH, OptionType.ATTACK)
    ):
        return None
    target = min(
        _pfc_cards(hand, DURALUDON),
        key=lambda card: _pfc_serial(card),
        default=None,
    )
    if target is None:
        return None
    certificate = _pfc_formation_certificate(
        obs, target, source_kind="HAND"
    )
    if certificate is None:
        return None
    route = certificate["route"]
    if parent_option.type == OptionType.ATTACK:
        if getattr(parent_option, "attackId", None) != route["attack_id"]:
            return None
    else:
        parent_card = option_card(obs, parent_option)
        parent_target = option_target(obs, parent_option)
        if (
            parent_card is None
            or _pfc_serial(parent_card) != route["attachment_serial"]
            or parent_target is None
            or _pfc_serial(parent_target) != route["active_serial"]
        ):
            return None
    position = _pfc_option_for_card_serial(
        obs, _pfc_serial(target), (OptionType.PLAY,)
    )
    if position is None:
        return None
    action = [position]
    if _pfc_semantics(obs, action) == _pfc_semantics(obs, parent_action):
        return None
    return certificate, action


def _pfc_build_ultra_formation(obs, parent_action):
    parent_option = _pfc_parent_option(obs, parent_action)
    if (
        parent_option is None
        or parent_option.type not in (OptionType.ATTACH, OptionType.ATTACK)
    ):
        return None, "parent_complete_turn_uncertain"
    target = _pfc_exposed_deck_basic(obs)
    if target is None:
        return None, "ultra_target_serial_unavailable_before_play"
    route = _pfc_attack_route(obs)
    if route is None:
        return None, "current_attack_not_certified"
    ultra_options = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        if (
            option.type == OptionType.PLAY
            and card is not None
            and card.id == ULTRA_BALL
            and _pfc_serial(card) is not None
        ):
            ultra_options.append((position, card))
    if not ultra_options:
        return None, "no_ultra_play"
    position, ultra = min(
        ultra_options, key=lambda row: (_pfc_serial(row[1]), row[0])
    )
    costs = _pfc_safe_ultra_costs(obs, _pfc_serial(ultra), route)
    if costs is None:
        return None, "unsafe_ultra_costs"
    certificate = _pfc_formation_certificate(
        obs,
        target,
        source_kind="ULTRA_BALL",
        source_serial=_pfc_serial(ultra),
        cost_cards=costs,
    )
    if certificate is None:
        return None, "ultra_complete_turn_not_certified"
    return (certificate, [position], costs), None


def _pfc_arm_pad_watch(obs, parent_action):
    global _pfc_search_watch
    option = _pfc_parent_option(obs, parent_action)
    card = None if option is None else option_card(obs, option)
    if (
        option is None
        or option.type != OptionType.PLAY
        or card is None
        or card.id != POKE_PAD
        or _pfc_serial(card) is None
        or active_pokemon(obs) is None
        or active_pokemon(obs).id != DURALUDON
        or my_state(obs).bench
    ):
        return False
    route = _pfc_attack_route(obs)
    if route is None:
        return False
    # A watch is not a proposal or an owner.  It records only public state and
    # becomes a proposal after a concrete Basic Duraludon serial is revealed.
    _pfc_search_watch = {
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "last_action_count": obs.current.turnActionCount,
        "source_serial": _pfc_serial(card),
        "source_snapshot": _cum_public_snapshot_id(obs),
        "active_fp": _sat_pokemon_fp(active_pokemon(obs)),
        "opponent_fp": _sat_pokemon_fp(opp_active_pokemon(obs)),
        "route": copy.deepcopy(route),
    }
    return True


def _pfc_resume_pad_watch(obs, parent_action):
    global _pfc_search_watch
    watch = _pfc_search_watch
    if watch is None:
        return None, None
    if (
        obs.current.yourIndex != watch["seat"]
        or obs.current.turn != watch["turn"]
        or obs.current.turnActionCount != watch["last_action_count"] + 1
        or obs.select.context != SelectContext.TO_HAND
        or getattr(obs.select, "effect", None) is None
        or obs.select.effect.id != POKE_PAD
        or _pfc_serial(obs.select.effect) != watch["source_serial"]
        or _sat_pokemon_fp(active_pokemon(obs)) != watch["active_fp"]
        or _sat_pokemon_fp(opp_active_pokemon(obs)) != watch["opponent_fp"]
        or my_state(obs).bench
    ):
        _pfc_search_watch = None
        return parent_action, "pad_watch_transition_failure"
    duraludon_options = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        if (
            option.type == OptionType.CARD
            and card is not None
            and card.id == DURALUDON
            and _pfc_serial(card) is not None
        ):
            duraludon_options.append((position, card))
    if not duraludon_options:
        _pfc_search_watch = None
        return parent_action, "pad_whiff_safe_parent"
    position, target = min(
        duraludon_options, key=lambda row: (_pfc_serial(row[1]), row[0])
    )
    # Rebuild against a MAIN-shaped copy so all complete-turn gates are
    # rechecked from the actual post-reveal public state without assuming a
    # draw.  The route itself was certified before the Pad was played.
    route = watch["route"]
    backup = _pfc_backup_certificate(obs, route, target)
    if backup is None:
        _pfc_search_watch = None
        return parent_action, "pad_backup_not_executable"
    reserves = _pfc_reserved_resources(
        obs,
        consumed=(
            (route["attachment_serial"],)
            if route["attachment_serial"] is not None else ()
        ),
    )
    if reserves is None:
        _pfc_search_watch = None
        return parent_action, "pad_reserves_unavailable"
    certificate = {
        "source_snapshot": watch["source_snapshot"],
        "source_kind": "POKE_PAD",
        "source_serial": watch["source_serial"],
        "purpose": "CREATE_BASIC_BACKUP",
        "card_serials": {
            "basic_duraludon": _pfc_serial(target),
            "search_source": watch["source_serial"],
            "discard_costs": (),
            "manual_attachment": route["attachment_serial"],
            "active": route["active_serial"],
            "opposing_target": route["target_serial"],
        },
        "search": {
            "source": "POKE_PAD",
            "exact_costs": (),
            "acceptable_result_roles": ("BASIC_DURALUDON",),
            "target_card_id": DURALUDON,
            "target_serial": _pfc_serial(target),
            "whiff_continuation": "fresh_parent_same_attack",
        },
        "evolution_target": backup["ex_alloy_route"]["evolution_serial"],
        "alloy_allocations": backup["ex_alloy_route"]["alloy_metal_serials"],
        "manual_attachment": {
            "energy_serial": route["attachment_serial"],
            "target_serial": route["active_serial"],
        },
        "attack": {
            "attacker_serial": route["active_serial"],
            "attack_id": route["attack_id"],
            "opposing_target_serial": route["target_serial"],
            "damage": route["attack_damage"],
            "ko": route["attack_damage"] >= route["target_hp"],
            "prize_result": route["prize_result"],
        },
        "end_active_serial": route["active_serial"],
        "accessible_backup": backup,
        "reserved": reserves,
        "contingencies": {
            "search_whiff": "fresh_parent_same_attack",
            "missing_bench_option": "fresh_parent_same_attack",
            "missing_attachment": "fresh_parent_from_actual_state",
            "missing_attack": "fresh_parent_from_actual_state",
            "reveal_dependent_choice": "only_exact_basic_duraludon",
        },
        "pareto_gates": {
            "known_steps_legal": True,
            "parent_attack_retained": True,
            "damage_no_worse": True,
            "prize_no_worse": True,
            "return_prize_no_better": True,
            "attachment_and_attack_accessible": True,
            "backup_executable": True,
            "ex_alloy_preserved": True,
            "boss_recovery_ace_preserved": True,
            "strict_improvement": "basic_backup_instead_of_nonfunctional_search",
            "hidden_card_required": False,
        },
        "route": route,
    }
    action = [position]
    _pfc_search_watch = None
    if _pfc_semantics(obs, action) == _pfc_semantics(obs, parent_action):
        return parent_action, ("pad_parent_already_basic", certificate)
    bindings = {
        "source_serial": watch["source_serial"],
        "basic_serial": _pfc_serial(target),
        "active_serial": route["active_serial"],
        "attachment_serial": route["attachment_serial"],
        "attack_id": route["attack_id"],
    }
    if not _pfc_begin_transaction(
            obs,
            "CREATE_BASIC_BACKUP",
            "PAD_SEARCH_EMITTED",
            certificate,
            bindings,
            action):
        return parent_action, "pad_transaction_binding_failure"
    return action, ("pad_basic_override", certificate)


def _pfc_projected_nonex(obs, active, evolution):
    damage = active.maxHp - active.hp
    data = CARD_DB.get(ARCHALUDON)
    if (
        damage < 0
        or damage % 10
        or data is None
        or getattr(data, "hp", None) != 180
    ):
        return None
    cape = any(
        getattr(tool, "id", None) == HERO_CAPE
        for tool in (getattr(active, "tools", None) or ())
    )
    max_hp = 180 + (100 if cape else 0)
    hp = max_hp - damage
    if hp <= 0:
        return None
    return {
        "card_id": ARCHALUDON,
        "serial": _pfc_serial(evolution),
        "hp": hp,
        "max_hp": max_hp,
        "damage": damage,
        "prize_value": 1,
    }


def _pfc_supported_ready_basic_attacks(obs, target_hp):
    opposing = opp_active_pokemon(obs)
    if opposing is None:
        return None
    data = CARD_DB.get(opposing.id)
    if data is None or not bool(getattr(data, "basic", False)):
        return None
    energies = tuple(int(value) for value in (opposing.energies or ()))
    ready = []
    for attack_id in tuple(getattr(data, "attacks", None) or ()):
        if not _pfc_can_pay(energies, attack_id):
            continue
        attack = ALL_ATTACKS.get(attack_id)
        if (
            attack is None
            or (getattr(attack, "text", "") or "") != ""
            or not isinstance(getattr(attack, "damage", None), int)
            or attack.damage <= 0
        ):
            return None
        ready.append({
            "attack_id": attack_id,
            "unprotected_damage": attack.damage,
            "coated_damage": 0,
            "would_damage": attack.damage > 0,
            "would_ko_projected_without_prevention": attack.damage >= target_hp,
        })
    return tuple(ready) if ready else None


def _pfc_nonex_backup(obs, active_serial):
    mine = my_state(obs)
    hand = _pfc_hand(obs)
    if hand is None:
        return None
    other_duraludon = [
        pokemon for pokemon in (mine.bench or ())
        if pokemon is not None
        and pokemon.id == DURALUDON
        and _pfc_serial(pokemon) != active_serial
        and _pfc_serial(pokemon) is not None
    ]
    ex_cards = sorted(
        (_pfc_serial(card) for card in hand if card.id == ARCHALUDON_EX)
    )
    discard_metal = sorted(
        _pfc_serial(card) for card in (mine.discard or ())
        if card is not None
        and card.id == METAL_ENERGY
        and _pfc_serial(card) is not None
    )
    hand_metal = sorted(
        _pfc_serial(card) for card in hand
        if card.id == METAL_ENERGY
    )
    if not other_duraludon or not ex_cards or not discard_metal or not hand_metal:
        return None
    backup = min(other_duraludon, key=lambda pokemon: _pfc_serial(pokemon))
    return {
        "duraludon_serial": _pfc_serial(backup),
        "promotion": "legal_bench_promotion",
        "payable_attack_route": {
            "attack_id": 223,
            "manual_metal_serial": hand_metal[0],
        },
        "ex_alloy_route": {
            "evolution_serial": ex_cards[0],
            "alloy_metal_serials": (discard_metal[0],),
            "manual_metal_serial": hand_metal[0],
        },
    }


def _pfc_build_nonex(obs, parent_action):
    parent_option = _pfc_parent_option(obs, parent_action)
    active = active_pokemon(obs)
    opposing = opp_active_pokemon(obs)
    if (
        not _pfc_fixed_card_semantics_supported()
        or parent_option is None
        or parent_option.type != OptionType.ATTACK
        or active is None
        or opposing is None
        or active.id != DURALUDON
        or getattr(parent_option, "attackId", None) is None
        or obs.current.energyAttached
        or not _pfc_status_allows_attack(obs)
        or _h2_has_precedent_terminal(obs)
    ):
        return None, "nonex_parent_or_terminal_gate"
    active_serial = _pfc_serial(active)
    if active_serial is None or not _pfc_can_pay(active.energies, COATED_ATTACK):
        return None, "coated_attack_not_payable_now"
    evolution_options = []
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.EVOLVE:
            continue
        card = option_card(obs, option)
        target = option_target(obs, option)
        if (
            card is not None
            and card.id == ARCHALUDON
            and _pfc_serial(card) is not None
            and target is not None
            and _pfc_serial(target) == active_serial
        ):
            evolution_options.append((position, card))
    if len(evolution_options) != 1:
        return None, "nonex_evolution_ambiguous_or_missing"
    position, evolution = evolution_options[0]
    backup = _pfc_nonex_backup(obs, active_serial)
    if backup is None:
        return None, "only_ex_capable_duraludon_or_lost_alloy_route"
    parent_damage = _pfc_attack_damage(obs, parent_option.attackId)
    candidate_damage = _pfc_attack_damage(obs, COATED_ATTACK)
    projected = _pfc_projected_nonex(obs, active, evolution)
    if (
        parent_damage is None
        or candidate_damage is None
        or candidate_damage < parent_damage
        or projected is None
    ):
        return None, "damage_or_projection_not_dominant"
    exact_ko = (
        candidate_damage >= opposing.hp
        and parent_damage < opposing.hp
    )
    ready_basic = None
    prize_clock = None
    prevention_positive = False
    if not exact_ko and parent_damage > 0 and candidate_damage > 0:
        ready_basic = _pfc_supported_ready_basic_attacks(obs, projected["hp"])
        parent_turns = math.ceil(opposing.hp / parent_damage)
        candidate_turns = math.ceil(opposing.hp / candidate_damage)
        prevention_positive = bool(
            ready_basic
            and candidate_turns < parent_turns
            and all(row["coated_damage"] == 0 for row in ready_basic)
        )
        prize_clock = {
            "parent_hits_to_active_prize": parent_turns,
            "candidate_hits_to_active_prize": candidate_turns,
            "strictly_better": candidate_turns < parent_turns,
        }
    if not exact_ko and not prevention_positive:
        return None, "no_exact_ko_or_supported_prevention_clock_gain"
    reserves = _pfc_reserved_resources(
        obs, consumed=(_pfc_serial(evolution),)
    )
    if reserves is None:
        return None, "reserve_binding_failure"
    purpose = (
        "NONEX_EXACT_120_KO"
        if exact_ko else "NONEX_BASIC_PREVENTION_PRIZE_CLOCK"
    )
    certificate = {
        "source_snapshot": _cum_public_snapshot_id(obs),
        "source_kind": "HAND_EVOLUTION",
        "source_serial": _pfc_serial(evolution),
        "purpose": purpose,
        "card_serials": {
            "evolution": _pfc_serial(evolution),
            "evolution_target": active_serial,
            "attacker_after_evolution": _pfc_serial(evolution),
            "opposing_target": _pfc_serial(opposing),
        },
        "search": None,
        "evolution_target": active_serial,
        "alloy_allocations": (),
        "manual_attachment": None,
        "attack": {
            "attacker_serial": _pfc_serial(evolution),
            "attack_id": COATED_ATTACK,
            "opposing_target_serial": _pfc_serial(opposing),
            "damage": candidate_damage,
            "ko": candidate_damage >= opposing.hp,
            "prize_result": (
                _h2_visible_prize_value(opposing)
                if candidate_damage >= opposing.hp else 0
            ),
            "parent_attack_id": parent_option.attackId,
            "parent_damage": parent_damage,
        },
        "end_active_serial": _pfc_serial(evolution),
        "accessible_backup": backup,
        "reserved": reserves,
        "projected_nonex": projected,
        "ready_basic_attacks_prevented": ready_basic,
        "exact_prize_clock": prize_clock,
        "contingencies": {
            "missing_evolution_transition": "fresh_parent_actual_state",
            "missing_coated_attack": "fresh_parent_actual_state",
        },
        "pareto_gates": {
            "known_steps_legal": True,
            "parent_attack_retained_this_turn": True,
            "no_parent_terminal_or_immediate_prize_lost": True,
            "damage_no_worse": candidate_damage >= parent_damage,
            "prize_no_worse": True,
            "return_prize_no_better": True,
            "current_attachment_and_attack_accessible": True,
            "backup_executable": True,
            "ex_alloy_route_preserved": True,
            "last_boss_recovery_ace_preserved": True,
            "strict_improvement": (
                "certain_immediate_prize"
                if exact_ko
                else "exact_prize_clock_and_basic_damage_prevention"
            ),
            "hidden_card_required": False,
        },
    }
    return (certificate, [position]), None


def _pfc_parent_forced(obs):
    options = len(obs.select.option)
    return bool(
        options == 0
        or (
            obs.select.minCount == obs.select.maxCount
            and obs.select.maxCount == options
        )
        or (
            options == 1
            and obs.select.minCount == 1
            and obs.select.maxCount == 1
        )
    )


def _pfc_clear_state_choose(obs, parent_action):
    parent_semantic = _pfc_semantics(obs, parent_action)
    nonex, nonex_reason = _pfc_build_nonex(obs, parent_action)
    if nonex is not None:
        certificate, action = nonex
        bindings = {
            "active_serial": certificate["evolution_target"],
            "evolution_serial": certificate["source_serial"],
            "attack_id": COATED_ATTACK,
        }
        if _pfc_begin_transaction(
                obs,
                certificate["purpose"],
                "NONEX_EVOLVE_EMITTED",
                certificate,
                bindings,
                action):
            return action, certificate, "nonex_pareto_dominance", {}
    formation = _pfc_build_direct_formation(obs, parent_action)
    if formation is not None:
        certificate, action = formation
        route = certificate["route"]
        bindings = {
            "basic_serial": certificate["card_serials"]["basic_duraludon"],
            "active_serial": route["active_serial"],
            "attachment_serial": route["attachment_serial"],
            "attack_id": route["attack_id"],
        }
        if _pfc_begin_transaction(
                obs,
                "CREATE_BASIC_BACKUP",
                "BENCH_EMITTED",
                certificate,
                bindings,
                action):
            return action, certificate, "formation_pareto_dominance", {}
    ultra, ultra_reason = _pfc_build_ultra_formation(obs, parent_action)
    if ultra is not None:
        certificate, action, costs = ultra
        route = certificate["route"]
        bindings = {
            "source_serial": certificate["source_serial"],
            "discard_serials": tuple(_pfc_serial(card) for card in costs),
            "basic_serial": certificate["card_serials"]["basic_duraludon"],
            "active_serial": route["active_serial"],
            "attachment_serial": route["attachment_serial"],
            "attack_id": route["attack_id"],
        }
        if _pfc_begin_transaction(
                obs,
                "CREATE_BASIC_BACKUP",
                "ULTRA_PLAY_EMITTED",
                certificate,
                bindings,
                action):
            return action, certificate, "ultra_pareto_dominance", {}
    pad_watch = _pfc_arm_pad_watch(obs, parent_action)
    return parent_action, None, "exact_parent_default", {
        "parent_semantic": parent_semantic,
        "nonex_rejection": nonex_reason,
        "ultra_rejection": ultra_reason,
        "pad_watch": pad_watch,
    }


def agent(obs_dict):
    global _pfc_parent_call_count
    parent_owner_before = _cum_active_transaction_owner
    parent_action = _pfc_parent_agent(obs_dict)
    _pfc_parent_call_count += 1
    obs = to_observation_class(obs_dict)
    if obs.select is None:
        _pfc_clear("deck_request")
        _pfc_emit_telemetry(
            None,
            parent_action,
            purpose="ENGINE_DECK_REQUEST",
            owner_before=parent_owner_before,
            owner_after=None,
            rejection_reason="rank0_deck_request_reset",
        )
        return parent_action
    if not _cum_valid_action(obs, parent_action):
        _pfc_clear("invalid_parent_action")
        emergency = _cum_emergency_action(obs)
        _pfc_emit_telemetry(
            obs,
            parent_action,
            candidate_action=emergency,
            purpose="ENGINE_EMERGENCY",
            owner_before=parent_owner_before,
            owner_after=None,
            rejection_reason="rank0_invalid_parent_action",
            rollback="invalid_parent_action",
            emergency=True,
        )
        return emergency
    owner_before = (
        _PFC_RULE_ID if _pfc_transaction is not None else None
    )
    try:
        if obs.current.result != -1:
            _pfc_clear("result")
            _pfc_emit_telemetry(
                obs,
                parent_action,
                purpose="RESULT_RESET",
                owner_before=owner_before,
                owner_after=None,
                rejection_reason="rank0_result_reset",
            )
            return parent_action
        setup_action = _pfc_setup_exception(obs, parent_action)
        if setup_action is not None:
            _pfc_clear("setup_exception")
            _pfc_emit_telemetry(
                obs,
                parent_action,
                candidate_action=setup_action,
                purpose="SETUP_EXACTLY_ONE_DURALUDON",
                gates={
                    "capacity": True,
                    "none_committed": True,
                    "exactly_one": len(setup_action) == 1,
                },
                owner_before=owner_before,
                owner_after=None,
                strict_improvement="one_backup_without_overcommitting_basics",
                rejection_reason=None,
            )
            return setup_action
        if _cum_parent_rank1_terminal(obs, parent_action):
            _pfc_clear("exact_parent_terminal")
            _pfc_emit_telemetry(
                obs,
                parent_action,
                purpose="EXACT_PARENT_TERMINAL",
                owner_before=owner_before,
                owner_after=None,
                rejection_reason="rank1_exact_parent_terminal",
            )
            return parent_action
        if _pfc_parent_forced(obs):
            _pfc_clear("exact_parent_forced")
            _pfc_emit_telemetry(
                obs,
                parent_action,
                purpose="EXACT_PARENT_FORCED",
                owner_before=owner_before,
                owner_after=None,
                rejection_reason="rank1_exact_parent_forced",
            )
            return parent_action
        parent_owner_after = _cum_active_transaction_owner
        if parent_owner_before is not None or parent_owner_after is not None:
            _pfc_clear("parent_transaction_priority")
            _pfc_emit_telemetry(
                obs,
                parent_action,
                purpose="EXACT_PARENT_TRANSACTION",
                owner_before=owner_before,
                owner_after=None,
                rejection_reason="rank2_parent_transaction_owner",
                rollback=(
                    "double_owner_cleared" if owner_before is not None else None
                ),
            )
            return parent_action
        if _pfc_transaction is not None:
            certificate = copy.deepcopy(_pfc_transaction["certificate"])
            purpose = _pfc_transaction["purpose"]
            action, transition = _pfc_resume_transaction(obs, parent_action)
            if action is None:
                action = parent_action
            duplicate = transition == "duplicate_retry"
            rollback = (
                transition
                if isinstance(transition, str)
                and transition not in (
                    "duplicate_retry",
                    "search_to_hand_confirmed",
                    "bench_confirmed",
                    "bench_and_attack_recertified",
                    "attachment_and_attack_recertified",
                    "evolution_and_attack_recertified",
                    "ultra_play_confirmed",
                    "ultra_costs_confirmed",
                )
                else None
            )
            _pfc_emit_telemetry(
                obs,
                parent_action,
                candidate_action=action,
                purpose=purpose,
                gates=certificate.get("pareto_gates", {}),
                certificate=certificate,
                owner_before=owner_before,
                owner_after=(
                    _PFC_RULE_ID if _pfc_transaction is not None else None
                ),
                strict_improvement=certificate.get(
                    "pareto_gates", {}
                ).get("strict_improvement"),
                rejection_reason=(
                    None if rollback is None else "fresh_parent_after_rollback"
                ),
                transition_confirmation=_cum_jsonable(transition),
                duplicate_retry=duplicate,
                rollback=rollback,
            )
            return action
        if _pfc_search_watch is not None:
            action, result = _pfc_resume_pad_watch(obs, parent_action)
            if action is None:
                action = parent_action
            certificate = (
                result[1]
                if isinstance(result, tuple) and len(result) == 2
                else None
            )
            _pfc_emit_telemetry(
                obs,
                parent_action,
                candidate_action=action,
                purpose="CREATE_BASIC_BACKUP",
                gates=(
                    {} if certificate is None
                    else certificate.get("pareto_gates", {})
                ),
                certificate=certificate,
                owner_before=None,
                owner_after=(
                    _PFC_RULE_ID if _pfc_transaction is not None else None
                ),
                strict_improvement=(
                    None if certificate is None
                    else certificate["pareto_gates"]["strict_improvement"]
                ),
                rejection_reason=(
                    result if isinstance(result, str) else None
                ),
                transition_confirmation=_cum_jsonable(result),
                rollback=(
                    result
                    if isinstance(result, str)
                    and result not in ("pad_whiff_safe_parent",)
                    else None
                ),
            )
            return action
        if obs.select.context != SelectContext.MAIN:
            _pfc_emit_telemetry(
                obs,
                parent_action,
                purpose="EXACT_PARENT_CALLBACK",
                owner_before=None,
                owner_after=None,
                rejection_reason="unsupported_or_mandatory_callback",
            )
            return parent_action
        action, certificate, reason, gates = _pfc_clear_state_choose(
            obs, parent_action
        )
        _pfc_emit_telemetry(
            obs,
            parent_action,
            candidate_action=action,
            purpose=(
                None if certificate is None else certificate["purpose"]
            ),
            gates=(
                gates if certificate is None
                else certificate.get("pareto_gates", {})
            ),
            certificate=certificate,
            owner_before=None,
            owner_after=(
                _PFC_RULE_ID if _pfc_transaction is not None else None
            ),
            strict_improvement=(
                None
                if certificate is None
                else certificate["pareto_gates"]["strict_improvement"]
            ),
            rejection_reason=(
                reason if certificate is None else None
            ),
        )
        return action
    except Exception as error:
        _pfc_clear("overlay_exception")
        _pfc_emit_telemetry(
            obs,
            parent_action,
            purpose="EXACT_PARENT_FAIL_CLOSED",
            owner_before=owner_before,
            owner_after=None,
            rejection_reason="overlay_exception_exact_parent",
            rollback="overlay_exception",
            exception={
                "type": type(error).__name__,
                "message": str(error),
            },
        )
        return parent_action


