def _pcrd_get(value, name, default=None):
    if isinstance(value, dict):
        return value.get(name, default)
    return getattr(value, name, default)


def _pcrd_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _pcrd_norm(value):
    text = "" if value is None else str(value)
    replacements = {
        "\u2018": "'",
        "\u2019": "'",
        "\u00e9": "e",
        "\u00c9": "e",
        "\ufffd": "",
    }
    for before, after in replacements.items():
        text = text.replace(before, after)
    text = text.replace("Pokﾃｩmon", "Pokemon").replace(
        "pokﾃｩmon", "pokemon"
    )
    return " ".join(text.casefold().strip().split())


def _pcrd_serial(value):
    serial = _pcrd_int(_pcrd_get(value, "serial"))
    return serial if serial is not None and serial > 0 else None


def _pcrd_card_ref(value):
    if value is None:
        return None
    return (_pcrd_get(value, "id"), _pcrd_serial(value))


def _pcrd_skill_key(skill):
    return (
        _pcrd_norm(_pcrd_get(skill, "name")),
        _pcrd_norm(_pcrd_get(skill, "text")),
    )


def _pcrd_attack_key(attack):
    if attack is None:
        return None
    damage = _pcrd_int(_pcrd_get(attack, "damage"))
    energies = tuple(
        _pcrd_int(value)
        for value in (_pcrd_get(attack, "energies", ()) or ())
    )
    if (
        damage is None
        or damage < 0
        or any(value is None or value not in range(10) for value in energies)
    ):
        return None
    return (
        _pcrd_norm(_pcrd_get(attack, "name")),
        _pcrd_norm(_pcrd_get(attack, "text")),
        damage,
        energies,
    )


def _pcrd_exact_trainer(card_id, name, text, *, ace_spec=False):
    data = CARD_DB.get(card_id)
    skills = tuple(_pcrd_get(data, "skills", ()) or ())
    return bool(
        data is not None
        and _pcrd_norm(_pcrd_get(data, "name")) == _pcrd_norm(name)
        and bool(_pcrd_get(data, "aceSpec", False)) is bool(ace_spec)
        and len(skills) == 1
        and _pcrd_norm(_pcrd_get(skills[0], "text")) == _pcrd_norm(text)
    )


