def _dper_normalize(value):
    """Stable catalog normalization; hashes are over this exact UTF-8 text."""
    text = _dper_unicodedata.normalize(
        "NFKD", _dper_unicodedata.normalize("NFKC", str(value or ""))
    )
    text = "".join(
        character for character in text
        if not _dper_unicodedata.combining(character)
    ).casefold()
    text = (
        text.replace("\u2018", "'")
        .replace("\u2019", "'")
        .replace("\u201c", '"')
        .replace("\u201d", '"')
        .replace("\u00a0", " ")
    )
    return re.sub(r"\s+", " ", text).strip()


def _dper_text_hash(value):
    return _dper_hashlib.sha256(
        _dper_normalize(value).encode("utf-8")
    ).hexdigest()


def _dper_binding(effect_id, handler, card_id, kind, entry_id,
                  card_name, entry_name, text_hash, consumers):
    return _DPERBinding(
        effect_id, _DPERHandlerType(handler), card_id, kind, entry_id,
        _dper_normalize(card_name), _dper_normalize(entry_name), text_hash,
        tuple(consumers),
    )


