def _dper_catalog_entry(binding):
    data = CARD_DB.get(binding.card_id)
    if data is None or _dper_normalize(_pcrd_get(data, "name")) != binding.card_name:
        return None
    if binding.entry_kind == "ATTACK":
        entry = ALL_ATTACKS.get(binding.entry_id)
        if entry is None or binding.entry_id not in tuple(_pcrd_get(data, "attacks", ()) or ()):
            return None
        candidates = (entry,)
    elif binding.entry_kind == "SKILL":
        candidates = tuple(
            skill for skill in tuple(_pcrd_get(data, "skills", ()) or ())
            if _dper_normalize(_pcrd_get(skill, "name")) == binding.entry_name
        )
    else:
        return None
    if len(candidates) != 1:
        return None
    entry = candidates[0]
    if (
        _dper_normalize(_pcrd_get(entry, "name")) != binding.entry_name
        or _dper_text_hash(_pcrd_get(entry, "text")) != binding.text_hash
    ):
        return None
    return entry


def _dper_binding_admitted(binding):
    return _dper_catalog_entry(binding) is not None


def _dper_effect_bindings(effect_id):
    return tuple(row for row in _DPER_BINDINGS if row.effect_id == effect_id)


def _dper_effect_admitted(effect_id, card_id=None, entry_id=None):
    rows = tuple(
        row for row in _dper_effect_bindings(effect_id)
        if (card_id is None or row.card_id == card_id)
        and (entry_id is None or row.entry_id == entry_id)
    )
    return bool(rows) and all(_dper_binding_admitted(row) for row in rows)


def _dper_manifest():
    return tuple(
        {
            "effect_id": row.effect_id,
            "handler_type": row.handler_type.value,
            "card_id": row.card_id,
            "entry_kind": row.entry_kind,
            "entry_id": row.entry_id,
            "card_name": row.card_name,
            "entry_name": row.entry_name,
            "normalized_text_hash": row.text_hash,
            "consumers": row.consumers,
            "admitted": _dper_binding_admitted(row),
        }
        for row in _DPER_BINDINGS
    )


def _dper_registry_status():
    manifest = _dper_manifest()
    effects = tuple(sorted({row["effect_id"] for row in manifest}))
    return {
        "rule_id": _DPER_RULE_ID,
        "binding_count": len(manifest),
        "effect_count": len(effects),
        "handler_types": tuple(sorted(kind.value for kind in _DPERHandlerType)),
        "all_admitted": all(row["admitted"] for row in manifest),
        "rejected_bindings": tuple(
            (row["effect_id"], row["card_id"], row["entry_id"])
            for row in manifest if not row["admitted"]
        ),
    }


def _dper_unknown(effect_id, reason, before=None, consumers=()):
    return {
        "status": "UNKNOWN", "effect_id": effect_id,
        "before": copy.deepcopy(before), "after": copy.deepcopy(before),
        "consumers_updated": tuple(consumers),
        "unsupported_reason": str(reason), "pipeline": (),
    }


def _dper_exact(effect_id, before, after, pipeline, consumers):
    return {
        "status": "EXACT", "effect_id": effect_id,
        "before": copy.deepcopy(before), "after": copy.deepcopy(after),
        "consumers_updated": tuple(consumers),
        "unsupported_reason": None, "pipeline": tuple(pipeline),
    }


def _dper_card_ids(cards):
    return tuple(_pcrd_get(card, "id") for card in tuple(cards or ()))


def _dper_energy_rows(pokemon):
    """Exact Basic/Special Energy rows; replaces PCRD's Basic-only reader."""
    energies = tuple(_pcrd_int(value) for value in (_pcrd_get(pokemon, "energies", ()) or ()))
    cards = tuple(
        _pcrd_get(pokemon, "energy_cards", None)
        or _pcrd_get(pokemon, "energyCards", ()) or ()
    )
    if len(energies) != len(cards) or any(value is None for value in energies):
        return None
    rows = []
    special = {11: "MIST_ENERGY", 14: "SPIKY_ENERGY", 18: "GROW_GRASS_ENERGY", 20: "ROCK_FIGHTING_ENERGY"}
    for energy_type, card in zip(energies, cards):
        if isinstance(card, tuple):
            if len(card) < 2:
                return None
            card_id, serial = card[:2]
        else:
            card_id, serial = _pcrd_get(card, "id"), _pcrd_serial(card)
        data = CARD_DB.get(card_id)
        if serial is None or data is None or _pcrd_int(_pcrd_get(data, "energyType")) != energy_type:
            return None
        card_type = _pcrd_int(_pcrd_get(data, "cardType"))
        if card_type == 5 and _pcrd_norm(_pcrd_get(data, "name")).startswith("basic "):
            pass
        elif card_type == 6 and card_id in special and _dper_effect_admitted(special[card_id], card_id):
            pass
        else:
            return None
        rows.append((energy_type, card_id, serial))
    if len({row[2] for row in rows}) != len(rows):
        return None
    return tuple(rows)


def _dper_attached_ids(pokemon, field):
    return tuple(
        _pcrd_get(card, "id") if not isinstance(card, tuple) else card[0]
        for card in tuple(_pcrd_get(pokemon, field, ()) or ())
    )


def _dper_expected_max_hp(pokemon):
    data = CARD_DB.get(_pcrd_get(pokemon, "id"))
    if data is None:
        return None
    maximum = _pcrd_int(_pcrd_get(data, "hp"))
    if maximum is None:
        return None
    energy_ids = _dper_attached_ids(
        {"energyCards": _pcrd_get(pokemon, "energy_cards", None) or _pcrd_get(pokemon, "energyCards", ())},
        "energyCards",
    )
    tool_ids = _dper_attached_ids(pokemon, "tools")
    target_type = _pcrd_int(_pcrd_get(data, "energyType"))
    if 18 in energy_ids:
        if not _dper_effect_admitted("GROW_GRASS_ENERGY", 18):
            return None
        if target_type == 1:
            maximum += 20 * energy_ids.count(18)
    if 1173 in tool_ids:
        if (
            tool_ids.count(1173) != 1
            or not _dper_effect_admitted("CYNTHIAS_POWER_WEIGHT", 1173)
        ):
            return None
        if "cynthia's " in _dper_normalize(_pcrd_get(data, "name")):
            maximum += 70
    if 1159 in tool_ids:
        if tool_ids.count(1159) != 1:
            return None
        maximum += 100
    known = {1173, 1159}
    if any(card_id not in known for card_id in tool_ids):
        return None
    return maximum


def _dper_attack_locked(source, attack_id, state):
    if attack_id not in (981, 983):
        return False
    effect = "ACCELERATING_STAB" if attack_id == 981 else "MEGA_BRAVE"
    origin_card_id = state.get("attack_origin_card_id", _pcrd_get(source, "id"))
    if not _dper_effect_admitted(effect, origin_card_id, attack_id):
        return None
    proof = state.get("public_log")
    if proof is None:
        return bool(_nacr_self_attack_locked(source, attack_id))
    required = ("attacker_serial", "attack_id", "attack_turn", "current_turn")
    if not isinstance(proof, dict) or any(not isinstance(proof.get(key), int) for key in required):
        return None
    return bool(
        proof["attacker_serial"] == _pcrd_serial(source)
        and proof["attack_id"] == attack_id
        and proof["current_turn"] == proof["attack_turn"] + 2
    )


def _dper_memory_dive_access(source, state):
    data = CARD_DB.get(_pcrd_get(source, "id"))
    if data is None or _pcrd_serial(source) is None:
        return _dper_unknown("MEMORY_DIVE", "source_identity_unknown", source, _DPER_READINESS_CONSUMERS)
    rows = [(attack_id, "PRINTED", _pcrd_serial(source), None) for attack_id in tuple(_pcrd_get(data, "attacks", ()) or ())]
    attack_origin_ids = {attack_id: _pcrd_get(source, "id") for attack_id in tuple(_pcrd_get(data, "attacks", ()) or ())}
    memory = tuple(state.get("memory_dive_sources", ()) or ())
    valid_sources = []
    for card in memory:
        if _pcrd_get(card, "id") != 57 or _pcrd_serial(card) is None or not _dper_effect_admitted("MEMORY_DIVE", 57):
            return _dper_unknown("MEMORY_DIVE", "memory_source_not_exact", source, _DPER_READINESS_CONSUMERS)
        valid_sources.append(_pcrd_serial(card))
    previous = tuple(_pcrd_get(source, "preEvolution", ()) or ())
    if valid_sources and previous:
        memory_serial = min(valid_sources)
        for prior in previous:
            prior_data = CARD_DB.get(_pcrd_get(prior, "id"))
            prior_serial = _pcrd_serial(prior)
            if prior_data is None or prior_serial is None:
                return _dper_unknown("MEMORY_DIVE", "visible_pre_evolution_unknown", source, _DPER_READINESS_CONSUMERS)
            prior_attacks = tuple(_pcrd_get(prior_data, "attacks", ()) or ())
            rows.extend((attack_id, "VISIBLE_PREVIOUS_EVOLUTION", prior_serial, memory_serial) for attack_id in prior_attacks)
            for attack_id in prior_attacks:
                attack_origin_ids.setdefault(attack_id, _pcrd_get(prior, "id"))
    unique = {}
    for row in rows:
        unique.setdefault(row[0], row)
    admitted_rows = []
    certificates = []
    for attack_id in sorted(unique):
        attack = ALL_ATTACKS.get(attack_id)
        if attack is None:
            return _dper_unknown("MEMORY_DIVE", "attack_catalog_missing", source, _DPER_READINESS_CONSUMERS)
        if state.get("require_payable", True) and _pcrd_attack_payment(source, attack) is None:
            continue
        lock_state = dict(state)
        lock_state["attack_origin_card_id"] = attack_origin_ids[attack_id]
        locked = _dper_attack_locked(source, attack_id, lock_state)
        if locked is None:
            return _dper_unknown("MEMORY_DIVE", "attack_lock_evidence_unknown", source, _DPER_READINESS_CONSUMERS)
        if locked:
            continue
        row = unique[attack_id]
        admitted_rows.append(row)
        certificates.append({
            "attack_id": attack_id,
            "provenance": row[1],
            "printed_energy_cost": tuple(_pcrd_int(value) for value in tuple(_pcrd_get(attack, "energies", ()) or ())),
            "normalized_attack_text": _dper_normalize(_pcrd_get(attack, "text")),
            "attack_text_hash": _dper_text_hash(_pcrd_get(attack, "text")),
        })
    after = {
        "attack_rows": tuple(admitted_rows),
        "attack_certificates": tuple(certificates),
    }
    return _dper_exact("MEMORY_DIVE", {"attack_rows": ()}, after, ({"step": "visible_attack_access"},), _DPER_READINESS_CONSUMERS)


def _dper_damage_counters(pokemon):
    hp = _pcrd_get(pokemon, "hp")
    maximum = _pcrd_get(pokemon, "maxHp")
    if not isinstance(hp, int) or not isinstance(maximum, int) or hp <= 0 or hp > maximum or (maximum - hp) % 10:
        return None
    return (maximum - hp) // 10


_dper_current_obs = None
_dper_seen_log_fingerprints = set()
_dper_current_turn_plays = {}
_dper_last_log_turn = None


def _dper_log_fingerprint(obs, entry, position):
    return (
        _pcrd_get(obs.current, "turn"), position,
        _pcrd_int(_pcrd_get(entry, "type")),
        _pcrd_int(_pcrd_get(entry, "playerIndex")),
        _pcrd_int(_pcrd_get(entry, "cardId")),
        _pcrd_int(_pcrd_get(entry, "serial")),
        _pcrd_int(_pcrd_get(entry, "attackId")),
    )


def _dper_update_public_log_evidence(obs):
    global _dper_seen_log_fingerprints, _dper_current_turn_plays
    global _dper_last_log_turn
    turn = _pcrd_get(obs.current, "turn")
    if not isinstance(turn, int):
        return
    if _dper_last_log_turn is not None and turn < _dper_last_log_turn:
        _dper_seen_log_fingerprints.clear()
        _dper_current_turn_plays.clear()
    _dper_last_log_turn = turn
    _dper_current_turn_plays = {
        key: value for key, value in _dper_current_turn_plays.items()
        if key[0] == turn
    }
    for position, entry in enumerate(tuple(obs.logs or ())):
        fingerprint = _dper_log_fingerprint(obs, entry, position)
        if fingerprint in _dper_seen_log_fingerprints:
            continue
        _dper_seen_log_fingerprints.add(fingerprint)
        if (
            entry.type == LogType.PLAY
            and isinstance(_pcrd_get(entry, "playerIndex"), int)
            and isinstance(_pcrd_get(entry, "cardId"), int)
            and isinstance(_pcrd_get(entry, "serial"), int)
        ):
            key = (turn, _pcrd_get(entry, "playerIndex"), _pcrd_get(entry, "cardId"))
            _dper_current_turn_plays.setdefault(key, set()).add(_pcrd_get(entry, "serial"))


def _dper_board_location(obs, pokemon):
    serial = _pcrd_serial(pokemon)
    if serial is None:
        return None
    matches = []
    for owner, player in enumerate(obs.current.players):
        for zone, cards in (("ACTIVE", player.active), ("BENCH", player.bench)):
            for card in tuple(cards or ()):
                if card is not None and _pcrd_serial(card) == serial:
                    matches.append((owner, zone))
    return matches[0] if len(matches) == 1 else None


def _dper_board_cards(obs, owner):
    if owner not in (0, 1):
        return ()
    player = obs.current.players[owner]
    return tuple(
        card for card in tuple(player.active or ()) + tuple(player.bench or ())
        if card is not None
    )


def _dper_augment_effect_state(source, target, effect_state):
    state = dict(effect_state or {})
    obs = _dper_current_obs
    if obs is None or obs.current is None:
        return state
    source_location = _dper_board_location(obs, source)
    target_location = _dper_board_location(obs, target)
    if source_location is not None:
        source_owner = source_location[0]
        source_player = obs.current.players[source_owner]
        state.setdefault("source_bench", tuple(card for card in tuple(source_player.bench or ()) if card is not None))
        state.setdefault("memory_dive_sources", tuple(card for card in _dper_board_cards(obs, source_owner) if _pcrd_get(card, "id") == 57))
        state.setdefault("cheer_on_sources", tuple(card for card in _dper_board_cards(obs, source_owner) if _pcrd_get(card, "id") == 342))
        turn = _pcrd_get(obs.current, "turn")
        premium_serials = _dper_current_turn_plays.get((turn, source_owner, 1141), set())
        if premium_serials:
            state.setdefault("premium_power_pro_proof", {
                "card_id": 1141,
                "card_serials": tuple(sorted(premium_serials)),
                "activated_turn": turn, "current_turn": turn,
            })
        state.setdefault("first_turn", bool(turn <= 1))
    if target_location is not None:
        target_owner, target_zone = target_location
        target_player = obs.current.players[target_owner]
        state.setdefault("target_zone", target_zone)
        state.setdefault("target_bench", tuple(card for card in tuple(target_player.bench or ()) if card is not None))
        state.setdefault("target_flower_curtain_sources", tuple(card for card in _dper_board_cards(obs, target_owner) if _pcrd_get(card, "id") == 343))
        state.setdefault("target_own_pokemon_count", len(_dper_board_cards(obs, target_owner)))
        state.setdefault("target_deck_count", _pcrd_get(target_player, "deckCount"))
        state.setdefault("run_away_available", _pcrd_get(target, "id") == 66)
        state.setdefault("run_away_once_unspent", True)
        state.setdefault("target_survives_in_play", True)
        if target_player.hand is not None:
            state.setdefault("target_public_hand", tuple(target_player.hand))
    stadium = tuple(obs.current.stadium or ())
    if len(stadium) == 1:
        if _pcrd_get(stadium[0], "id") == 1244 and _dper_effect_admitted("FULL_METAL_LAB", 1244):
            state.setdefault("full_metal_lab", True)
        if _pcrd_get(stadium[0], "id") == 1264 and _dper_effect_admitted("BATTLE_CAGE", 1264):
            state.setdefault("battle_cage", True)
    return state


def _dper_next_payable_attacks(source, post_energy_rows, state, used_attack_id):
    projected = _pcrd_project_pokemon(
        source,
        energies=tuple(row[0] for row in post_energy_rows),
        energy_cards=tuple((row[1], row[2]) for row in post_energy_rows),
    )
    access = _dper_memory_dive_access(projected, state)
    if access["status"] != "EXACT":
        return None
    payable = []
    for row in access["after"]["attack_rows"]:
        attack_id = row[0]
        attack = ALL_ATTACKS.get(attack_id)
        if attack is None:
            return None
        if attack_id == used_attack_id and used_attack_id in (981, 983):
            continue
        if _pcrd_attack_payment(projected, attack) is not None:
            payable.append(attack_id)
    return tuple(sorted(set(payable)))


def _dper_combat_oracle(source, attack_id, target, effect_state=None):
    """Typed rules-order combat/readiness certificate for phase-1 effects."""
    state = _dper_augment_effect_state(source, target, effect_state)
    unsupported = []
    pipeline = []
    source_data = CARD_DB.get(_pcrd_get(source, "id"))
    target_data = CARD_DB.get(_pcrd_get(target, "id"))
    attack = ALL_ATTACKS.get(attack_id)
    if source_data is None or target_data is None or attack is None:
        return _dper_unknown("COMBAT", "missing_catalog_identity", state, _DPER_COMBAT_CONSUMERS)
    attack_binding = next((row for row in _DPER_BINDINGS if row.entry_kind == "ATTACK" and row.card_id == _pcrd_get(source, "id") and row.entry_id == attack_id), None)
    printed = attack_id in tuple(_pcrd_get(source_data, "attacks", ()) or ())
    access = None
    if not printed:
        access_state = dict(state)
        access_state["require_payable"] = not bool(state.get("allow_unpayable_certificate"))
        access = _dper_memory_dive_access(source, access_state)
        if access["status"] != "EXACT" or attack_id not in tuple(row[0] for row in access["after"]["attack_rows"]):
            unsupported.append("attack_not_printed_or_visible_memory_dive")
    if attack_binding is not None and not _dper_binding_admitted(attack_binding):
        unsupported.append("attack_binding_mismatch")
    if "flip a coin" in _dper_normalize(_pcrd_get(attack, "text")):
        unsupported.append("coin_flip_out_of_scope")
    locked = _dper_attack_locked(source, attack_id, state)
    if locked is None:
        unsupported.append("attack_lock_log_unknown")
    elif locked:
        unsupported.append("same_attack_locked_this_turn")
    payment = _pcrd_attack_payment(source, attack)
    if payment is None and not state.get("allow_unpayable_certificate"):
        unsupported.append("attack_not_payable")
    source_hp = _pcrd_get(source, "hp")
    target_hp = state.get("target_hp", _pcrd_get(target, "hp"))
    source_max = _dper_expected_max_hp(source)
    target_max = _dper_expected_max_hp(target)
    if (
        _pcrd_serial(source) is None or _pcrd_serial(target) is None
        or source_max is None or target_max is None
        or not isinstance(source_hp, int) or not isinstance(target_hp, int)
        or _pcrd_get(source, "maxHp") != source_max
        or state.get("target_max_hp", _pcrd_get(target, "maxHp")) != target_max
        or source_hp <= 0 or source_hp > source_max
        or target_hp <= 0 or target_hp > target_max
    ):
        unsupported.append("public_hp_or_modifier_invariant_unknown")
    if unsupported:
        return _dper_unknown("COMBAT", ";".join(sorted(set(unsupported))), state, _DPER_COMBAT_CONSUMERS)

    skill_unsupported = []
    source_modes = _pcrd_supported_skill_modes(source, skill_unsupported)
    target_modes = _pcrd_supported_skill_modes(target, skill_unsupported)
    if source_modes is None or target_modes is None or skill_unsupported:
        return _dper_unknown("COMBAT", "public_skill_mode_unknown:" + ";".join(skill_unsupported), state, _DPER_COMBAT_CONSUMERS)

    source_rows = _dper_energy_rows(source)
    target_rows = _dper_energy_rows(target)
    if source_rows is None or target_rows is None:
        return _dper_unknown("COMBAT", "energy_identity_unknown", state, _DPER_COMBAT_CONSUMERS)
    if attack_binding is None:
        mode_unsupported = []
        mode = _pcrd_attack_mode(attack_id, attack, state, mode_unsupported)
        if mode is None or mode_unsupported:
            return _dper_unknown("COMBAT", "legacy_attack_mode_unknown:" + ";".join(mode_unsupported), state, _DPER_COMBAT_CONSUMERS)
    else:
        mode = attack_binding.effect_id
    attack_damage = mode not in ("POWERFUL_HAND_COUNTERS", "DAMAGE_COUNTER_PLACEMENT")
    if attack_id == 938:
        damage = 20 + 40 * sum(row[0] == 7 for row in source_rows)
        pipeline.append({"step": "spiky_wheel_darkness_formula", "damage": damage})
    elif attack_id == 540:
        bench = state.get("source_bench")
        if bench is None:
            return _dper_unknown("RAGING_CURSE", "visible_source_bench_required", state, _DPER_COMBAT_CONSUMERS)
        counters = 0
        for pokemon in tuple(bench):
            data = CARD_DB.get(_pcrd_get(pokemon, "id"))
            value = _dper_damage_counters(pokemon)
            if data is None or value is None or _pcrd_serial(pokemon) is None:
                return _dper_unknown("RAGING_CURSE", "bench_counter_identity_unknown", state, _DPER_COMBAT_CONSUMERS)
            if "cynthia's " in _dper_normalize(_pcrd_get(data, "name")):
                counters += value
        damage = counters * 10
        pipeline.append({"step": "raging_curse_visible_bench_counters", "damage_counters": counters, "damage": damage})
    elif mode == "RAGING_HAMMER":
        counters = _dper_damage_counters(source)
        if counters is None:
            return _dper_unknown("COMBAT", "raging_hammer_counters_unknown", state, _DPER_COMBAT_CONSUMERS)
        damage = 80 + 10 * counters
        pipeline.append({"step": "raging_hammer_formula", "damage_counters": counters, "damage": damage})
    elif mode == "POWERFUL_HAND_COUNTERS":
        hand_count = state.get("source_hand_count")
        if not isinstance(hand_count, int) or hand_count < 0:
            return _dper_unknown("COMBAT", "powerful_hand_count_unknown", state, _DPER_COMBAT_CONSUMERS)
        damage = 20 * hand_count
        pipeline.append({"step": "powerful_hand_counter_placement", "damage_counters": 2 * hand_count, "damage": damage})
    elif mode == "DAMAGE_COUNTER_PLACEMENT":
        counters = state.get("damage_counters")
        if not isinstance(counters, int) or counters < 0:
            return _dper_unknown("COMBAT", "damage_counter_count_unknown", state, _DPER_COMBAT_CONSUMERS)
        damage = 10 * counters
        pipeline.append({"step": "damage_counter_placement", "damage_counters": counters, "damage": damage})
    else:
        damage = _pcrd_int(_pcrd_get(attack, "damage"))
        pipeline.append({"step": "printed_damage", "damage": damage})
    if damage is None:
        return _dper_unknown("COMBAT", "nonexact_damage_formula", state, _DPER_COMBAT_CONSUMERS)

    source_type = _pcrd_int(_pcrd_get(source_data, "energyType"))
    target_type = _pcrd_int(_pcrd_get(target_data, "energyType"))
    premium = state.get("premium_power_pro_proof")
    if premium is not None:
        premium_serials = premium.get("card_serials")
        if premium_serials is None and isinstance(premium.get("card_serial"), int):
            premium_serials = (premium["card_serial"],)
        premium_serials = tuple(premium_serials or ())
        valid = bool(
            isinstance(premium, dict)
            and premium.get("card_id") == 1141
            and premium_serials
            and all(isinstance(serial, int) for serial in premium_serials)
            and len(premium_serials) == len(set(premium_serials))
            and isinstance(premium.get("activated_turn"), int)
            and premium.get("activated_turn") == premium.get("current_turn")
            and _dper_effect_admitted("PREMIUM_POWER_PRO", 1141)
        )
        if not valid:
            return _dper_unknown("PREMIUM_POWER_PRO", "current_turn_log_proof_unknown", state, _DPER_COMBAT_CONSUMERS)
        if source_type == 6:
            damage += 30 * len(premium_serials)
            pipeline.append({"step": "premium_power_pro_plus_30", "count": len(premium_serials), "damage": damage})
    cheers = tuple(state.get("cheer_on_sources", ()) or ())
    if cheers:
        serials = []
        for cheer in cheers:
            if _pcrd_get(cheer, "id") != 342 or _pcrd_serial(cheer) is None or not _dper_effect_admitted("CHEER_ON_TO_GLORY", 342):
                return _dper_unknown("CHEER_ON_TO_GLORY", "public_modifier_identity_unknown", state, _DPER_COMBAT_CONSUMERS)
            serials.append(_pcrd_serial(cheer))
        if len(serials) != len(set(serials)):
            return _dper_unknown("CHEER_ON_TO_GLORY", "duplicate_modifier_serial", state, _DPER_COMBAT_CONSUMERS)
        if "cynthia's " in _dper_normalize(_pcrd_get(source_data, "name")):
            damage += 30 * len(cheers)
            pipeline.append({"step": "cheer_on_to_glory", "count": len(cheers), "damage": damage})

    ignores_weakness = attack_id == 540 or bool(state.get("target_no_weakness"))
    ignores_target_effects = attack_id == 479
    weakness = _pcrd_int(_pcrd_get(target_data, "weakness"))
    resistance = _pcrd_int(_pcrd_get(target_data, "resistance"))
    if attack_damage and not ignores_weakness and weakness == source_type:
        damage *= 2
        pipeline.append({"step": "weakness_x2", "damage": damage})
    if attack_damage and resistance == source_type:
        damage = max(0, damage - 30)
        pipeline.append({"step": "resistance_minus_30", "damage": damage})

    if (
        _pcrd_get(target, "id") == 345
        and attack_damage and not ignores_target_effects
        and (bool(_pcrd_get(source_data, "ex", False)) or bool(_pcrd_get(source_data, "megaEx", False)))
    ):
        if not _dper_effect_admitted("MYSTERIOUS_ROCK_INN", 345):
            return _dper_unknown("MYSTERIOUS_ROCK_INN", "binding_mismatch", state, _DPER_COMBAT_CONSUMERS)
        damage = 0
        pipeline.append({"step": "mysterious_rock_inn_prevention", "damage": 0})
    if (
        attack_damage and state.get("full_metal_lab") and target_type == 8
        and not ignores_target_effects
    ):
        if not _dper_effect_admitted("FULL_METAL_LAB", 1244):
            return _dper_unknown("FULL_METAL_LAB", "binding_mismatch", state, _DPER_COMBAT_CONSUMERS)
        damage = max(0, damage - 30)
        pipeline.append({"step": "full_metal_lab_minus_30", "rules_order": "after_weakness_resistance", "damage": damage})
    if attack_damage and state.get("target_coated_prevention") and bool(_pcrd_get(source_data, "basic", False)) and not ignores_target_effects:
        damage = 0
        pipeline.append({"step": "coated_attack_damage_prevention", "damage": 0})

    effect_prevented = False
    target_energy_ids = tuple(row[1] for row in target_rows)
    if 11 in target_energy_ids:
        effect_prevented = _dper_effect_admitted("MIST_ENERGY", 11)
    if 20 in target_energy_ids and target_type == 6:
        effect_prevented = effect_prevented or _dper_effect_admitted("ROCK_FIGHTING_ENERGY", 20)
    if not attack_damage and effect_prevented:
        damage = 0
        pipeline.append({
            "step": "attached_energy_prevents_counter_placement",
            "placed_counters": 0,
        })

    remaining = target_hp - damage
    sturdy_applied = False
    if (
        attack_damage and "STURDY" in target_modes
        and target_hp == target_max and remaining <= 0
    ):
        sturdy_applied = True
        remaining = 10
        pipeline.append({"step": "sturdy_full_hp_survival", "remaining_hp": 10})
    ko = remaining <= 0
    prize = 3 if bool(_pcrd_get(target_data, "megaEx", False)) else 2 if bool(_pcrd_get(target_data, "ex", False)) else 1
    bench_components = []
    if attack_id == 937:
        bench = state.get("target_bench")
        if bench is None:
            return _dper_unknown("SHADOW_BULLET", "visible_target_bench_required", state, _DPER_COMBAT_CONSUMERS)
        flower_sources = tuple(state.get("target_flower_curtain_sources", ()) or ())
        for flower in flower_sources:
            if _pcrd_get(flower, "id") != 343 or _pcrd_serial(flower) is None or not _dper_effect_admitted("FLOWER_CURTAIN", 343):
                return _dper_unknown("FLOWER_CURTAIN", "public_source_identity_unknown", state, _DPER_COMBAT_CONSUMERS)
        for pokemon in tuple(bench):
            data = CARD_DB.get(_pcrd_get(pokemon, "id"))
            if data is None or _pcrd_serial(pokemon) is None:
                return _dper_unknown("SHADOW_BULLET", "bench_target_identity_unknown", state, _DPER_COMBAT_CONSUMERS)
            rule_box = bool(_pcrd_get(data, "ex", False) or _pcrd_get(data, "megaEx", False) or _pcrd_get(data, "ruleBox", False))
            component = 0 if flower_sources and not rule_box else 30
            bench_components.append({
                "target_serial": _pcrd_serial(pokemon), "damage": component,
                "prevented_by": "FLOWER_CURTAIN" if component == 0 else None,
                "choice_semantics": "ONE_BENCH_TARGET_ALTERNATIVE",
            })

    public_reply_routes = []
    run_away = False
    persistent_progress = True
    if (
        not ko and _pcrd_get(target, "id") == 66
        and "RUN_AWAY_DRAW" in target_modes
        and state.get("run_away_available")
    ):
        deck_count = state.get("target_deck_count")
        own_count = state.get("target_own_pokemon_count")
        target_bench = tuple(state.get("target_bench", ()) or ())
        if not isinstance(deck_count, int) or not isinstance(own_count, int):
            return _dper_unknown("RUN_AWAY_DRAW", "deck_or_board_count_unknown", state, _DPER_COMBAT_CONSUMERS)
        if deck_count > 0 and own_count > 1 and target_bench and state.get("run_away_once_unspent", True) and state.get("target_survives_in_play", True):
            routes = []
            for pokemon in target_bench:
                if _pcrd_serial(pokemon) is None:
                    return _dper_unknown("RUN_AWAY_DRAW", "promotion_serial_unknown", state, _DPER_COMBAT_CONSUMERS)
                routes.append({"kind": "RUN_AWAY_DRAW_PROMOTION", "new_active_serial": _pcrd_serial(pokemon), "new_active_id": _pcrd_get(pokemon, "id")})
            run_away = True
            persistent_progress = False
            public_reply_routes.extend(routes)
            pipeline.append({"step": "run_away_draw_exact_leave_play", "draw": min(3, deck_count), "promotion_routes": tuple(routes)})

    public_hand = tuple(state.get("target_public_hand", ()) or ())
    if not ko and public_hand:
        for card in public_hand:
            card_id = _pcrd_get(card, "id")
            if card_id not in (1147, 1229):
                continue
            transition_state = {
                "public_card_available": True,
                "target": target,
                "target_zone": state.get("target_zone", "ACTIVE"),
            }
            effect = "JUMBO_ICE_CREAM" if card_id == 1147 else "WALLYS_COMPASSION"
            transition = _dper_effect_transition(effect, transition_state)
            if transition["status"] == "EXACT":
                public_reply_routes.append({
                    "kind": effect,
                    "card_serial": _pcrd_serial(card),
                    "after": transition["after"],
                })

    post_return = 0
    if attack_damage and damage > 0 and 14 in target_energy_ids and state.get("target_zone", "ACTIVE") == "ACTIVE":
        if not _dper_effect_admitted("SPIKY_ENERGY", 14):
            return _dper_unknown("SPIKY_ENERGY", "binding_mismatch", state, _DPER_COMBAT_CONSUMERS)
        post_return = 2 * target_energy_ids.count(14)
        pipeline.append({"step": "spiky_energy_after_damage", "return_damage_counters": post_return, "target_ko": ko})

    post_energy = tuple(source_rows)
    if attack_id == 532:
        post_energy = ()
        pipeline.append({"step": "draconic_buster_discard_all_source_energy", "discarded_serials": tuple(row[2] for row in source_rows)})
    acceleration = ()
    if attack_id in (982, 965):
        effect = "AURA_JAB" if attack_id == 982 else "TURBO_FLARE"
        visible = state.get("post_callback_attachments")
        if visible is None:
            pipeline.append({"step": "post_attack_acceleration_pending_callback", "effect_id": effect})
        else:
            acceleration = tuple(sorted(tuple(row) for row in visible))
            pipeline.append({"step": "post_attack_visible_acceleration", "effect_id": effect, "attachments": acceleration})

    next_payable_ids = _dper_next_payable_attacks(source, post_energy, state, attack_id)
    if next_payable_ids is None:
        return _dper_unknown("COMBAT", "next_payable_attack_unknown", state, _DPER_COMBAT_CONSUMERS)

    persistent = {}
    if attack_id in (981, 983):
        persistent["same_attack_lock_next_turn"] = attack_id
    if attack_id == 965:
        persistent["turbo_flare_acceleration_callback"] = True
    if mode == "METAL_DEFENDER":
        persistent["no_weakness_next_opponent_turn"] = True
    if mode == "COATED_ATTACK":
        persistent["prevent_basic_attack_damage_next_opponent_turn"] = True

    result = {
        "status": "EXACT", "effect_id": attack_binding.effect_id if attack_binding else "COMBAT",
        "source_id": _pcrd_get(source, "id"), "source_serial": _pcrd_serial(source),
        "source_stage": "BASIC" if bool(_pcrd_get(source_data, "basic", False)) else "STAGE_1" if bool(_pcrd_get(source_data, "stage1", False)) else "STAGE_2",
        "source_type": source_type,
        "attack_id": attack_id, "attack_name": _pcrd_get(attack, "name"),
        "attack_mode": mode,
        "attack_damage": attack_damage,
        "payment": payment, "readiness": _PCRD_READY_NOW if payment is not None else "UNPAYABLE",
        "target_id": _pcrd_get(target, "id"), "target_serial": _pcrd_serial(target),
        "target_hp": target_hp, "target_max_hp": target_max,
        "weakness": weakness, "resistance": resistance,
        "weakness_suppressed": bool(state.get("target_no_weakness")) or attack_id == 540,
        "full_metal_lab": bool(state.get("full_metal_lab")),
        "cape_count": _dper_attached_ids(target, "tools").count(1159),
        "coated_prevention": bool(state.get("target_coated_prevention")),
        "printed_or_formula_damage": pipeline[0]["damage"], "final_damage": damage,
        "remaining_hp": max(0, remaining), "ko": ko,
        "sturdy_applied": sturdy_applied,
        "prize_yield": prize if ko else 0, "printed_prize_yield": prize,
        "bench_components": tuple(bench_components),
        "target_attack_effects_prevented": bool(effect_prevented and not ignores_target_effects),
        "post_damage_counter_return": post_return,
        "post_attack_resource_ledger": {"source_energy": post_energy, "visible_acceleration": acceleration},
        "post_reply_resource_ledger": {"return_damage_counters": post_return},
        "persistent_effects": persistent,
        "persistent_progress": persistent_progress,
        "run_away_draw_executable": run_away,
        "exact_public_reply_routes": tuple(public_reply_routes),
        "attacker_survival": source_hp - 10 * post_return > 0,
        "next_payable_attack": bool(next_payable_ids),
        "next_payable_attack_ids": next_payable_ids,
        "exact_backup_conversion": acceleration,
        "saved_callback_transaction": "PENDING" if attack_id in (982, 965) and not acceleration else None,
        "pipeline": tuple(pipeline), "unsupported_text": (), "assumptions": (),
        "consumers_updated": _DPER_COMBAT_CONSUMERS,
    }
    return result


def _dper_effect_transition(effect_id, state):
    """Pure public transition API used by readiness/callback consumers."""
    before = copy.deepcopy(state)
    rows = _dper_effect_bindings(effect_id)
    consumers = rows[0].consumers if rows else ()
    if not rows or not all(_dper_binding_admitted(row) for row in rows):
        return _dper_unknown(effect_id, "registry_binding_not_admitted", before, consumers)
    after = copy.deepcopy(before)
    pipeline = []
    if effect_id == "ADRENA_BRAIN":
        required = ("source_has_darkness", "source_damage_counters", "target_zone", "requested_counters", "unused_this_turn")
        if any(key not in state for key in required) or not state["source_has_darkness"] or not state["unused_this_turn"]:
            return _dper_unknown(effect_id, "activation_or_darkness_proof_missing", before, consumers)
        requested = state["requested_counters"]
        available = state["source_damage_counters"]
        if not isinstance(requested, int) or not isinstance(available, int) or requested not in (1, 2, 3) or available < requested:
            return _dper_unknown(effect_id, "counter_count_not_legal", before, consumers)
        if state["target_zone"] == "BENCH" and state.get("battle_cage"):
            return _dper_unknown(effect_id, "battle_cage_prevents_bench_counter_placement", before, consumers)
        after["source_damage_counters"] -= requested
        after["target_damage_counters"] = state.get("target_damage_counters", 0) + requested
        after["unused_this_turn"] = False
        pipeline.append({"step": "move_damage_counters", "count": requested})
    elif effect_id in ("PUNK_UP", "ASSEMBLE_ALLOY"):
        limit = 5 if effect_id == "PUNK_UP" else 2
        if not state.get("evolution_callback_resolved") or state.get("post_callback_attachments") is None:
            return _dper_unknown(effect_id, "resolved_callback_and_visible_attachments_required", before, consumers)
        attached = tuple(state["post_callback_attachments"])
        if len(attached) > limit or any(len(tuple(row)) < 3 for row in attached):
            return _dper_unknown(effect_id, "attachment_count_or_identity_invalid", before, consumers)
        after["following_turn_readiness"] = tuple(sorted(tuple(row) for row in attached))
        pipeline.append({"step": "visible_post_evolution_attachments", "count": len(attached)})
    elif effect_id in ("AURA_JAB", "TURBO_FLARE"):
        if not state.get("attack_resolved") or state.get("post_callback_attachments") is None:
            return _dper_unknown(effect_id, "resolved_attack_callback_required", before, consumers)
        attached = tuple(sorted(tuple(row) for row in state["post_callback_attachments"]))
        if len(attached) > 3:
            return _dper_unknown(effect_id, "too_many_visible_attachments", before, consumers)
        after["current_attack_payment_delta"] = 0
        after["following_turn_readiness"] = attached
        pipeline.append({"step": "post_attack_only_acceleration", "count": len(attached)})
    elif effect_id in ("RUN_AWAY_DRAW", "TRADING_PLACES", "TELEPORTATION_ATTACK", "SWITCH", "SURFER"):
        bench = tuple(state.get("legal_bench", ()) or ())
        if not bench:
            return _dper_unknown(effect_id, "no_legal_bench_target", before, consumers)
        if effect_id in ("SWITCH", "SURFER") and not state.get("public_card_available"):
            return _dper_unknown(effect_id, "switch_card_not_publicly_available", before, consumers)
        if effect_id == "SURFER":
            hand_count = state.get("source_hand_count_after_play")
            deck_count = state.get("source_deck_count")
            if (
                not isinstance(hand_count, int) or hand_count < 0
                or not isinstance(deck_count, int) or deck_count < 0
            ):
                return _dper_unknown(effect_id, "public_hand_and_deck_counts_required", before, consumers)
            draw_count = min(max(0, 5 - hand_count), deck_count)
            after["draw_count"] = draw_count
            after["source_hand_count"] = hand_count + draw_count
            after["source_deck_count"] = deck_count - draw_count
        if effect_id == "RUN_AWAY_DRAW" and state.get("own_pokemon_count", 0) <= 1:
            return _dper_unknown(effect_id, "cannot_remove_last_own_pokemon", before, consumers)
        routes = []
        for target in bench:
            serial = _pcrd_serial(target)
            if serial is None:
                return _dper_unknown(effect_id, "switch_target_serial_unknown", before, consumers)
            routes.append((serial, _pcrd_get(target, "id")))
        after["legal_active_routes"] = tuple(sorted(routes))
        pipeline.append({"step": "enumerate_legal_active_changes", "routes": after["legal_active_routes"]})
    elif effect_id in ("ASCENSION", "RARE_CANDY", "FOREST_OF_VITALITY"):
        source = state.get("source")
        candidates = tuple(state.get("public_evolutions", ()) or ())
        if source is None or not candidates:
            return _dper_unknown(effect_id, "public_source_or_evolution_missing", before, consumers)
        if state.get("first_turn"):
            return _dper_unknown(effect_id, "first_turn_evolution_forbidden", before, consumers)
        if effect_id == "RARE_CANDY" and state.get("appear_this_turn"):
            return _dper_unknown(effect_id, "rare_candy_appear_this_turn_forbidden", before, consumers)
        if effect_id not in ("ASCENSION", "FOREST_OF_VITALITY", "RARE_CANDY") and state.get("appear_this_turn"):
            return _dper_unknown(effect_id, "ordinary_evolution_appear_this_turn_forbidden", before, consumers)
        source_data = CARD_DB.get(_pcrd_get(source, "id"))
        routes = []
        for evolution in candidates:
            data = CARD_DB.get(_pcrd_get(evolution, "id"))
            if data is None or _pcrd_serial(evolution) is None or source_data is None:
                return _dper_unknown(effect_id, "evolution_identity_unknown", before, consumers)
            if effect_id == "RARE_CANDY":
                legal = _dper_rare_candy_stage2_legal(source_data, data)
            else:
                legal = _dper_normalize(_pcrd_get(data, "evolvesFrom")) == _dper_normalize(_pcrd_get(source_data, "name"))
                if effect_id == "FOREST_OF_VITALITY":
                    legal = bool(
                        legal
                        and _pcrd_int(_pcrd_get(source_data, "energyType")) == 1
                        and _pcrd_int(_pcrd_get(data, "energyType")) == 1
                    )
            if legal:
                routes.append((_pcrd_serial(evolution), _pcrd_get(evolution, "id")))
        if not routes:
            return _dper_unknown(effect_id, "no_stage_legal_evolution", before, consumers)
        after["legal_evolution_routes"] = tuple(sorted(routes))
        pipeline.append({"step": "enumerate_stage_turn_legal_evolutions", "routes": after["legal_evolution_routes"]})
    elif effect_id in ("WALLYS_COMPASSION", "JUMBO_ICE_CREAM"):
        target = state.get("target")
        if not state.get("public_card_available") or target is None:
            return _dper_unknown(effect_id, "public_card_and_target_required", before, consumers)
        hp = _pcrd_get(target, "hp")
        maximum = _pcrd_get(target, "maxHp")
        energy = tuple(_pcrd_get(target, "energyCards", ()) or ())
        data = CARD_DB.get(_pcrd_get(target, "id"))
        if not isinstance(hp, int) or not isinstance(maximum, int) or hp >= maximum or data is None:
            return _dper_unknown(effect_id, "damaged_eligible_target_required", before, consumers)
        if effect_id == "JUMBO_ICE_CREAM":
            if len(energy) < 3 or state.get("target_zone") != "ACTIVE":
                return _dper_unknown(effect_id, "active_with_three_energy_required", before, consumers)
            after["target_hp"] = min(maximum, hp + 80)
        else:
            if not bool(_pcrd_get(data, "megaEx", False)):
                return _dper_unknown(effect_id, "mega_evolution_ex_required", before, consumers)
            after["target_hp"] = maximum
            after["energy_returned_to_hand"] = tuple(sorted(_pcrd_serial(card) for card in energy))
        pipeline.append({"step": "public_legal_heal_or_return", "target_hp": after["target_hp"]})
    elif effect_id == "BATTLE_CAGE":
        if state.get("placement_kind") == "DAMAGE_COUNTERS" and state.get("target_zone") == "BENCH" and state.get("from_opponent_attack_or_ability"):
            after["placed_counters"] = 0
            pipeline.append({"step": "prevent_bench_damage_counter_placement"})
        else:
            after["placed_counters"] = state.get("requested_counters", 0)
            pipeline.append({"step": "damage_or_nonbench_counter_unaffected"})
    else:
        return _dper_unknown(effect_id, "use_combat_or_typed_access_consumer", before, consumers)
    return _dper_exact(effect_id, before, after, pipeline, consumers)


def _dper_begin_callback(effect_id, state):
    if effect_id not in ("PUNK_UP", "ASSEMBLE_ALLOY", "AURA_JAB", "TURBO_FLARE", "ASCENSION"):
        return _dper_unknown(effect_id, "not_a_phase1_callback_family", state)
    required = ("seat", "turn", "source_serial")
    if any(not isinstance(state.get(key), int) for key in required):
        return _dper_unknown(effect_id, "callback_identity_unknown", state)
    return {
        "rule_id": _DPER_RULE_ID, "effect_id": effect_id,
        "seat": state["seat"], "turn": state["turn"],
        "source_serial": state["source_serial"], "stage": "AWAITING_RESOLUTION",
        "before": copy.deepcopy(state), "last_fingerprint": None,
        "last_result": None, "emission_count": 1,
    }


def _dper_resume_callback(transaction, state):
    if not isinstance(transaction, dict) or transaction.get("rule_id") != _DPER_RULE_ID:
        return _dper_unknown("CALLBACK", "transaction_owner_mismatch", state)
    identity = (state.get("seat"), state.get("turn"), state.get("source_serial"))
    expected = (transaction.get("seat"), transaction.get("turn"), transaction.get("source_serial"))
    if identity != expected:
        return _dper_unknown(transaction.get("effect_id"), "stale_callback_identity", state)
    if transaction.get("effect_id") == "ASCENSION":
        evolutions = tuple(state.get("public_evolutions", ()) or ())
        fingerprint_rows = tuple(sorted(
            (_pcrd_serial(card), _pcrd_get(card, "id")) for card in evolutions
        ))
        fingerprint = (identity, fingerprint_rows, bool(state.get("resolved")))
    else:
        attachments = tuple(sorted(tuple(row) for row in tuple(state.get("post_callback_attachments", ()) or ())))
        fingerprint = (identity, attachments, bool(state.get("resolved")))
    if fingerprint == transaction.get("last_fingerprint"):
        duplicate = copy.deepcopy(transaction["last_result"])
        duplicate["duplicate"] = True
        return duplicate
    if transaction.get("effect_id") == "ASCENSION":
        effect_state = {
            "source": state.get("source"),
            "public_evolutions": tuple(state.get("public_evolutions", ()) or ()),
            "first_turn": bool(state.get("first_turn")),
            "appear_this_turn": bool(state.get("appear_this_turn")),
        }
    else:
        effect_state = {
            "evolution_callback_resolved": bool(state.get("resolved")),
            "attack_resolved": bool(state.get("resolved")),
            "post_callback_attachments": attachments,
        }
    result = _dper_effect_transition(transaction["effect_id"], effect_state)
    if result["status"] != "EXACT":
        return result
    transaction["stage"] = "COMPLETE"
    transaction["last_fingerprint"] = fingerprint
    transaction["last_result"] = copy.deepcopy(result)
    result["duplicate"] = False
    result["callback_stage"] = "COMPLETE"
    return result


# Gate legacy exact semantic sources through this registry.  Global lookup in
# the frozen parent means its PCRD consumers use these wrappers without a
# second parent-agent call.
_dper_legacy_energy_rows = _pcrd_energy_rows
_dper_legacy_supported_skill_modes = _pcrd_supported_skill_modes
_dper_legacy_tools_supported = _pcrd_tools_supported
_dper_legacy_combat_oracle = _pcrd_public_combat_oracle
_dper_legacy_stadium_state = _pcrd_stadium_state
_dper_legacy_ice_projection = _pcrd_ice_projection
_dper_legacy_static_metadata_supported = _pcrd_static_metadata_supported
_dper_legacy_public_effect_inventory = _pcrd_public_effect_inventory
_dper_legacy_reply_effect_state = _pcrd_reply_effect_state
_dper_legacy_attack_routes_for_source = _pcrd_attack_routes_for_source
_dper_legacy_known_evolution_routes = _pcrd_known_evolution_routes
_dper_legacy_threat_graph = _pcrd_threat_graph


def _pcrd_energy_rows(pokemon):
    rows = _dper_energy_rows(pokemon)
    return rows


def _pcrd_supported_skill_modes(pokemon, unsupported):
    legacy_unsupported = []
    legacy = _dper_legacy_supported_skill_modes(pokemon, legacy_unsupported)
    if legacy is not None:
        return legacy
    data = CARD_DB.get(_pcrd_get(pokemon, "id"))
    if data is None:
        unsupported.extend(legacy_unsupported)
        return None
    modes = []
    for skill in tuple(_pcrd_get(data, "skills", ()) or ()):
        matches = tuple(
            row for row in _DPER_BINDINGS
            if row.entry_kind == "SKILL" and row.card_id == _pcrd_get(pokemon, "id")
            and row.entry_name == _dper_normalize(_pcrd_get(skill, "name"))
        )
        if len(matches) != 1 or not _dper_binding_admitted(matches[0]):
            unsupported.extend(legacy_unsupported)
            return None
        modes.append("DPER:" + matches[0].effect_id)
    return tuple(modes)


def _pcrd_tools_supported(pokemon, unsupported, projected_cape=False):
    tools = tuple(_pcrd_get(pokemon, "tools", ()) or ())
    if any(_pcrd_get(tool, "id") == 1173 for tool in tools):
        if _dper_expected_max_hp(pokemon) is None:
            unsupported.append("dper_power_weight_invariant_unknown")
            return None
        remaining = tuple(tool for tool in tools if _pcrd_get(tool, "id") != 1173)
        projected = dict(_pcrd_project_pokemon(pokemon))
        projected["tools"] = list(remaining)
        return _dper_legacy_tools_supported(projected, unsupported, projected_cape)
    return _dper_legacy_tools_supported(pokemon, unsupported, projected_cape)


def _dper_has_phase1_combat_relevance(source, attack_id, target, state):
    attack_ids = {row.entry_id for row in _DPER_BINDINGS if row.entry_kind == "ATTACK"}
    attached = set(_dper_attached_ids(source, "energyCards") + _dper_attached_ids(target, "energyCards") + _dper_attached_ids(source, "tools") + _dper_attached_ids(target, "tools"))
    return bool(
        attack_id in attack_ids
        or attached & {11, 14, 18, 20, 1173}
        or _pcrd_get(target, "id") == 345
        or state.get("premium_power_pro_proof")
        or tuple(state.get("cheer_on_sources", ()) or ())
        or (attack_id == 937 and tuple(state.get("target_flower_curtain_sources", ()) or ()))
        or attack_id not in tuple(_pcrd_get(CARD_DB.get(_pcrd_get(source, "id")), "attacks", ()) or ())
    )


def _pcrd_public_combat_oracle(source, attack_id, target, effect_state=None):
    state = _dper_augment_effect_state(source, target, effect_state)
    if not _dper_has_phase1_combat_relevance(source, attack_id, target, state):
        return _dper_legacy_combat_oracle(source, attack_id, target, state)
    result = _dper_combat_oracle(source, attack_id, target, state)
    if result.get("status") == "UNKNOWN":
        return {
            "status": "UNKNOWN", "source_serial": _pcrd_serial(source),
            "target_serial": _pcrd_serial(target), "attack_id": attack_id,
            "unsupported_text": ("dper:" + str(result.get("unsupported_reason")),),
            "assumptions": (), "pipeline": result.get("pipeline", ()),
        }
    return result


def _pcrd_stadium_state(obs, projected_fml=False):
    result = _dper_legacy_stadium_state(obs, projected_fml)
    if result.get("status") == "EXACT":
        if result.get("full_metal_lab") and not _dper_effect_admitted("FULL_METAL_LAB", 1244):
            return {"status": "UNKNOWN", "full_metal_lab": False, "battle_cage": False, "forest_of_vitality": False, "serial": None}
        result = dict(result)
        result.setdefault("battle_cage", False)
        result.setdefault("forest_of_vitality", False)
        return result
    if projected_fml:
        return result
    stadium = tuple(obs.current.stadium or ())
    if len(stadium) != 1 or _pcrd_serial(stadium[0]) is None:
        return result
    card_id = _pcrd_get(stadium[0], "id")
    if card_id == 1264 and _dper_effect_admitted("BATTLE_CAGE", 1264):
        return {"status": "EXACT", "full_metal_lab": False, "battle_cage": True, "forest_of_vitality": False, "serial": _pcrd_serial(stadium[0])}
    if card_id == 1261 and _dper_effect_admitted("FOREST_OF_VITALITY", 1261):
        return {"status": "EXACT", "full_metal_lab": False, "battle_cage": False, "forest_of_vitality": True, "serial": _pcrd_serial(stadium[0])}
    return result


def _pcrd_reply_effect_state(*, stadium, our_attack_certificate, target_player):
    result = _dper_legacy_reply_effect_state(
        stadium=stadium,
        our_attack_certificate=our_attack_certificate,
        target_player=target_player,
    )
    result = dict(result)
    result["battle_cage"] = bool(stadium.get("battle_cage"))
    result["forest_of_vitality"] = bool(stadium.get("forest_of_vitality"))
    return result


def _pcrd_public_effect_inventory(
        obs, *, our_active, opponent_active, opponent_active_ko,
        projected_stadium):
    classifications = []
    unsupported = []
    for side, player in (("ours", my_state(obs)), ("opponent", opp_state(obs))):
        status = _pcrd_status_tuple(player)
        if status is None or any(status):
            unsupported.append("public_status_unknown:" + side)
        else:
            classifications.append({"side": side, "zone": "PLAYER", "kind": "STATUS", "classification": "EXACT_NONE"})
    current_stadium = _pcrd_stadium_state(obs)
    if current_stadium.get("status") != "EXACT":
        unsupported.append("unhandled_public_stadium")
    else:
        stadium_effect = "FULL_METAL_LAB" if current_stadium.get("full_metal_lab") else "BATTLE_CAGE" if current_stadium.get("battle_cage") else "FOREST_OF_VITALITY" if current_stadium.get("forest_of_vitality") else "EXACT_NONE"
        classifications.append({"side": "symmetric", "zone": "STADIUM", "kind": "STADIUM", "card_id": None if stadium_effect == "EXACT_NONE" else {"FULL_METAL_LAB": 1244, "BATTLE_CAGE": 1264, "FOREST_OF_VITALITY": 1261}[stadium_effect], "classification": "DPER:" + stadium_effect if stadium_effect != "EXACT_NONE" else stadium_effect})
    if not isinstance(projected_stadium, dict) or projected_stadium.get("status") != "EXACT":
        unsupported.append("projected_stadium_unknown")

    boards = (
        ("ours", (("active", our_active),) + tuple(("bench", card) for card in tuple(my_state(obs).bench or ()) if card is not None)),
        ("opponent", (("active", opponent_active),) + tuple(("bench", card) for card in tuple(opp_state(obs).bench or ()) if card is not None)),
    )
    for side, board in boards:
        for zone, pokemon in board:
            if pokemon is None:
                continue
            card_id = _pcrd_get(pokemon, "id")
            serial = _pcrd_serial(pokemon)
            data = CARD_DB.get(card_id)
            if data is None or serial is None:
                unsupported.append("malformed_public_pokemon:" + side + ":" + zone + ":" + str(card_id))
                continue
            if side == "opponent" and zone == "active" and opponent_active_ko:
                classifications.append({"side": side, "zone": zone, "kind": "POKEMON", "card_id": card_id, "serial": serial, "classification": "REMOVED_BY_EXACT_CURRENT_KO"})
                continue
            energy_rows = _dper_energy_rows(pokemon)
            if energy_rows is None:
                unsupported.append("unhandled_public_attached_energy:" + side + ":" + zone + ":" + str(card_id))
            else:
                classifications.append({
                    "side": side, "zone": zone, "kind": "ATTACHED_ENERGY",
                    "card_id": card_id, "serial": serial,
                    "classification": tuple(
                        "DPER:" + {11: "MIST_ENERGY", 14: "SPIKY_ENERGY", 18: "GROW_GRASS_ENERGY", 20: "ROCK_FIGHTING_ENERGY"}[row[1]]
                        if row[1] in (11, 14, 18, 20) else "EXACT_BASIC_ENERGY"
                        for row in energy_rows
                    ),
                })
            expected_max = _dper_expected_max_hp(pokemon)
            hp = _pcrd_get(pokemon, "hp")
            maximum = _pcrd_get(pokemon, "maxHp")
            if expected_max is None or maximum != expected_max or not isinstance(hp, int) or hp <= 0 or hp > maximum:
                unsupported.append("public_hp_or_modifier_invariant_unknown:" + side + ":" + zone + ":" + str(card_id))
            for tool in tuple(_pcrd_get(pokemon, "tools", ()) or ()):
                tool_id = _pcrd_get(tool, "id")
                if _pcrd_serial(tool) is None:
                    unsupported.append("public_tool_without_serial:" + str(tool_id))
                elif tool_id == 1173 and _dper_effect_admitted("CYNTHIAS_POWER_WEIGHT", 1173):
                    classifications.append({"side": side, "zone": zone, "kind": "TOOL", "card_id": 1173, "serial": _pcrd_serial(tool), "classification": "DPER:CYNTHIAS_POWER_WEIGHT"})
                elif tool_id == HERO_CAPE and _pcrd_exact_trainer(HERO_CAPE, "Hero's Cape", _PCRD_CAPE_TEXT, ace_spec=True):
                    classifications.append({"side": side, "zone": zone, "kind": "TOOL", "card_id": HERO_CAPE, "serial": _pcrd_serial(tool), "classification": "LEGACY:HERO_CAPE"})
                else:
                    unsupported.append("unhandled_public_tool:" + str(tool_id))
            for skill in tuple(_pcrd_get(data, "skills", ()) or ()):
                key = _pcrd_skill_key(skill)
                legacy = _PCRD_IN_PLAY_SKILL_CLASSIFICATIONS.get(key)
                matches = tuple(
                    row for row in _DPER_BINDINGS
                    if row.entry_kind == "SKILL" and row.card_id == card_id
                    and row.entry_name == _dper_normalize(_pcrd_get(skill, "name"))
                )
                if legacy is not None:
                    classification = "LEGACY:" + legacy
                elif len(matches) == 1 and _dper_binding_admitted(matches[0]):
                    classification = "DPER:" + matches[0].effect_id
                else:
                    unsupported.append(
                        "unclassified_public_skill:" + side + ":" + zone + ":"
                        + str(card_id) + ":" + key[0] + ":" + key[1]
                    )
                    continue
                classifications.append({"side": side, "zone": zone, "kind": "ABILITY", "card_id": card_id, "serial": serial, "classification": classification})
    return {
        "status": "EXACT" if not unsupported else "UNKNOWN",
        "classifications": tuple(classifications),
        "unsupported_text": tuple(sorted(set(unsupported))),
    }


def _pcrd_attack_routes_for_source(
        source, target, *, tier, sequence, effect_state,
        opponent_prizes, public_resource=None):
    """Production attack enumerator, including visible Memory Dive rows."""
    state = _dper_augment_effect_state(source, target, effect_state)
    access_state = dict(state)
    access_state["require_payable"] = False
    access = _dper_memory_dive_access(source, access_state)
    if access["status"] != "EXACT":
        return None
    routes = []
    for attack_row in access["after"]["attack_rows"]:
        attack_id = attack_row[0]
        attack = ALL_ATTACKS.get(attack_id)
        if attack is None:
            return None
        probe_state = dict(state)
        probe_state["allow_unpayable_certificate"] = True
        probe = _pcrd_public_combat_oracle(
            source, attack_id, target, probe_state
        )
        if probe["status"] != "EXACT":
            reasons = tuple(probe.get("unsupported_text", ()))
            if reasons and all(
                "same_attack_locked_this_turn" in reason
                or "attack_not_printed_or_visible_memory_dive" in reason
                for reason in reasons
            ):
                continue
            return None
        payment = _pcrd_attack_payment(source, attack)
        missing = _pcrd_missing_energy_count(source, attack)
        if tier in (_PCRD_READY_NOW, _PCRD_KNOWN_PUBLIC_RESOURCE):
            if payment is None:
                continue
        elif tier == _PCRD_ONE_ATTACH:
            if payment is not None or missing != 1:
                continue
        certificate = dict(probe)
        certificate["payment"] = payment
        certificate["readiness"] = tier
        certificate["_dper_source_snapshot"] = copy.deepcopy(source)
        certificate["_dper_effect_state"] = copy.deepcopy(probe_state)
        if attack_id in (423, 1231, 1070):
            switch_routes = tuple(sorted(
                (_pcrd_serial(card), _pcrd_get(card, "id"))
                for card in tuple(state.get("source_bench", ()) or ())
                if _pcrd_serial(card) is not None
                and _pcrd_serial(card) != _pcrd_serial(source)
            ))
            certificate["post_attack_switch_routes"] = switch_routes
            if switch_routes:
                certificate["saved_callback_transaction"] = {
                    "effect_id": (
                        "TRADING_PLACES"
                        if attack_id in (423, 1231)
                        else "TELEPORTATION_ATTACK"
                    ),
                    "stage": "AWAITING_SWITCH_TARGET",
                    "source_serial": _pcrd_serial(source),
                    "legal_target_serials": tuple(row[0] for row in switch_routes),
                }
        if attack_id in (39, 478, 1262):
            certificate["saved_callback_transaction"] = {
                "effect_id": "ASCENSION",
                "stage": "AWAITING_PUBLIC_DECK_SEARCH_OPTIONS",
                "source_serial": _pcrd_serial(source),
            }
            transition = _dper_effect_transition("ASCENSION", {
                "source": source,
                "public_evolutions": tuple(
                    state.get("public_evolutions", ()) or ()
                ),
                "first_turn": bool(state.get("first_turn")),
                "appear_this_turn": bool(
                    _pcrd_get(source, "appearThisTurn", False)
                ),
            })
            if transition["status"] == "EXACT":
                certificate["post_attack_evolution_routes"] = transition[
                    "after"
                ]["legal_evolution_routes"]
                certificate["saved_callback_transaction"]["stage"] = (
                    "AWAITING_EVOLUTION_TARGET"
                )
        certificate_variants = [(certificate, ())]
        if attack_id == 937 and certificate.get("bench_components"):
            certificate_variants = []
            public_bench = {
                _pcrd_serial(card): card
                for card in tuple(state.get("target_bench", ()) or ())
                if _pcrd_serial(card) is not None
            }
            for component in certificate["bench_components"]:
                bench_target = public_bench.get(component["target_serial"])
                if bench_target is None:
                    return None
                bench_hp = _pcrd_get(bench_target, "hp")
                if not isinstance(bench_hp, int):
                    return None
                bench_ko = bool(component["damage"] >= bench_hp and component["damage"] > 0)
                unsupported_prize = []
                bench_prize = _pcrd_prize_yield(
                    bench_target, {}, unsupported_prize
                ) if bench_ko else 0
                if unsupported_prize or bench_prize is None:
                    return None
                variant = copy.deepcopy(certificate)
                variant["bench_components"] = (copy.deepcopy(component),)
                variant["bench_components"][0]["remaining_hp"] = max(
                    0, bench_hp - component["damage"]
                )
                variant["bench_components"][0]["ko"] = bench_ko
                variant["bench_components"][0]["prize_yield"] = bench_prize
                variant["active_prize_yield"] = certificate["prize_yield"]
                variant["prize_yield"] = certificate["prize_yield"] + bench_prize
                certificate_variants.append((
                    variant,
                    (("BENCH_DAMAGE_TARGET", component["target_serial"]),),
                ))
        for variant, bench_sequence in certificate_variants:
            prize = variant["prize_yield"]
            routes.append(_pcrd_route(
                tier=tier,
                sequence=tuple(sequence) + ((
                    "ATTACK", attack_id, attack_row[1],
                    attack_row[2], attack_row[3],
                ),) + bench_sequence,
                source=source, target=target, attack_id=attack_id,
                certificate=variant, public_resource=public_resource,
                terminal=bool(prize >= opponent_prizes),
            ))
    return tuple(routes)


def _dper_rare_candy_stage2_legal(source_data, evolution_data):
    if (
        not bool(_pcrd_get(source_data, "basic", False))
        or not bool(_pcrd_get(evolution_data, "stage2", False))
    ):
        return False
    source_name = _dper_normalize(_pcrd_get(source_data, "name"))
    stage1_name = _dper_normalize(
        _pcrd_get(evolution_data, "evolvesFrom")
    )
    return any(
        bool(_pcrd_get(candidate, "stage1", False))
        and _dper_normalize(_pcrd_get(candidate, "name")) == stage1_name
        and _dper_normalize(_pcrd_get(candidate, "evolvesFrom"))
        == source_name
        for candidate in CARD_DB.values()
    )


def _pcrd_known_evolution_routes(
        obs, source, target, effect_state, opponent_prizes):
    """Preserve legacy routes; never consume hidden opponent hand identity."""
    legacy = _dper_legacy_known_evolution_routes(
        obs, source, target, effect_state, opponent_prizes
    )
    return legacy


def _dper_public_switch_and_heal_routes(
        obs, our_active, opponent_active, opponent_active_ko,
        effect_state, opponent_prizes):
    opponent = opp_state(obs)
    if opponent_active_ko or opponent_active is None:
        return ()
    bench = tuple(
        card for card in tuple(opponent.bench or ()) if card is not None
    )
    routes = []
    if _pcrd_get(opponent_active, "id") == 66 and bench:
        transition = _dper_effect_transition("RUN_AWAY_DRAW", {
            "legal_bench": bench,
            "own_pokemon_count": 1 + len(bench),
        })
        if (
            transition["status"] == "EXACT"
            and isinstance(_pcrd_get(opponent, "deckCount"), int)
            and _pcrd_get(opponent, "deckCount") > 0
        ):
            for source in bench:
                built = _pcrd_attack_routes_for_source(
                    source, our_active,
                    tier=_PCRD_KNOWN_PUBLIC_RESOURCE,
                    sequence=((
                        "RUN_AWAY_DRAW",
                        _pcrd_serial(opponent_active),
                        _pcrd_serial(source),
                    ),),
                    effect_state=effect_state,
                    opponent_prizes=opponent_prizes,
                    public_resource={
                        "effect_id": "RUN_AWAY_DRAW",
                        "source_serial": _pcrd_serial(opponent_active),
                        "promoted_serial": _pcrd_serial(source),
                        "draw_count": min(3, _pcrd_get(opponent, "deckCount")),
                    },
                )
                if built is None:
                    return None
                routes.extend(built)
    return tuple(routes)


def _dper_post_action_observation(
        obs, opponent_active, opponent_active_ko, attack_certificate):
    projected = copy.deepcopy(obs)
    opponent = opp_state(projected)
    if opponent_active_ko:
        opponent.active[:] = []
    else:
        opponent.active[:] = [copy.deepcopy(opponent_active)]
    components = tuple(attack_certificate.get("bench_components", ()) or ())
    if len(components) > 1:
        return {
            "status": "UNKNOWN",
            "reason": "unbound_shadow_bullet_bench_target",
        }
    component_by_serial = {
        row["target_serial"]: row for row in components
        if row.get("choice_semantics") == "ONE_BENCH_TARGET_ALTERNATIVE"
    }
    bench = []
    for card in tuple(opponent.bench or ()):
        if card is None:
            continue
        component = component_by_serial.get(_pcrd_serial(card))
        if component is None or component.get("damage", 0) == 0:
            bench.append(card)
            continue
        hp = _pcrd_get(card, "hp")
        damage = component.get("damage")
        if not isinstance(hp, int) or not isinstance(damage, int) or damage < 0:
            return {"status": "UNKNOWN", "reason": "shadow_bullet_bench_projection_unknown"}
        if hp > damage:
            projected_card = _pcrd_project_pokemon(card, hp=hp - damage)
            if projected_card is None:
                return {"status": "UNKNOWN", "reason": "shadow_bullet_bench_projection_unknown"}
            bench.append(projected_card)
    opponent.bench[:] = bench
    return {"status": "EXACT", "observation": projected}


def _dper_adrena_public_moves(obs, our_active, stadium):
    """Enumerate visible ability/donor/target allocations without reuse."""
    opponent = opp_state(obs)
    mine = my_state(obs)
    abilities = []
    opponent_board = _pcrd_board_pokemon(opponent)
    for ability_source in opponent_board:
        if _pcrd_get(ability_source, "id") != 112:
            continue
        rows = _dper_energy_rows(ability_source)
        if rows is None:
            return {"status": "UNKNOWN", "reason": "adrena_source_public_state_unknown"}
        if not any(row[0] == 7 for row in rows):
            continue
        abilities.append(ability_source)
    donor_counters = {}
    donors = {}
    for donor in opponent_board:
        serial = _pcrd_serial(donor)
        counters = _dper_damage_counters(donor)
        if serial is None or counters is None:
            return {"status": "UNKNOWN", "reason": "adrena_donor_public_state_unknown"}
        if counters > 0:
            donor_counters[serial] = counters
            donors[serial] = donor
    target_counters = _dper_damage_counters(our_active)
    if target_counters is None:
        return {"status": "UNKNOWN", "reason": "adrena_active_target_state_unknown"}
    targets = [our_active] + [card for card in tuple(mine.bench or ()) if card is not None]
    target_state = {}
    target_meta = {}
    for target in targets:
        serial = _pcrd_serial(target)
        counters = _dper_damage_counters(target)
        maximum = _pcrd_get(target, "maxHp")
        location = _dper_board_location(obs, target)
        zone = "ACTIVE" if serial == _pcrd_serial(our_active) else "BENCH"
        if serial is None or counters is None or not isinstance(maximum, int) or maximum % 10:
            return {"status": "UNKNOWN", "reason": "adrena_target_public_state_unknown"}
        target_state[serial] = counters
        target_meta[serial] = (target, zone, maximum // 10)

    move_sets = []
    cage_records = []

    def extend(position, remaining, target_counts, moves, transitions):
        if position == len(abilities):
            if moves:
                move_sets.append({
                    "moves": tuple(moves),
                    "transitions": tuple(transitions),
                    "donor_counters_after": tuple(sorted(remaining.items())),
                    "target_counters_after": tuple(sorted(target_counts.items())),
                    "placed_by_target": tuple(sorted(
                        (serial, target_counts[serial] - target_state[serial])
                        for serial in target_counts
                        if target_counts[serial] != target_state[serial]
                    )),
                })
            return
        ability_source = abilities[position]
        ability_serial = _pcrd_serial(ability_source)
        extend(position + 1, dict(remaining), dict(target_counts), moves, transitions)
        for donor_serial in sorted(remaining):
            maximum = min(3, remaining[donor_serial])
            for target_serial in sorted(target_counts):
                target, zone, maximum_target_counters = target_meta[target_serial]
                if target_counts[target_serial] >= maximum_target_counters:
                    continue
                for count in range(1, maximum + 1):
                    if stadium.get("battle_cage"):
                        cage = _dper_effect_transition("BATTLE_CAGE", {
                            "placement_kind": "DAMAGE_COUNTERS",
                            "target_zone": zone,
                            "from_opponent_attack_or_ability": True,
                            "requested_counters": count,
                        })
                        if cage["status"] != "EXACT":
                            return {"status": "UNKNOWN", "reason": "battle_cage_transition_unknown"}
                        if zone == "BENCH":
                            cage_records.append({
                                "ability_serial": ability_serial,
                                "donor_serial": donor_serial,
                                "donor_counters_before": remaining[donor_serial],
                                "donor_counters_after": remaining[donor_serial],
                                "target_serial": target_serial,
                                "requested_counters": count,
                                "placed_counters": 0,
                                "effect_id": "BATTLE_CAGE",
                            })
                            continue
                    transition = _dper_effect_transition("ADRENA_BRAIN", {
                        "source_has_darkness": True,
                        "source_damage_counters": remaining[donor_serial],
                        "target_damage_counters": target_counts[target_serial],
                        "target_zone": zone, "requested_counters": count,
                        "unused_this_turn": True,
                        "battle_cage": bool(stadium.get("battle_cage")),
                    })
                    if transition["status"] != "EXACT":
                        continue
                    projected_remaining = dict(remaining)
                    projected_remaining[donor_serial] -= count
                    projected_targets = dict(target_counts)
                    projected_targets[target_serial] += count
                    extend(
                        position + 1, projected_remaining, projected_targets,
                        moves + [(ability_serial, donor_serial, target_serial, count, zone)],
                        transitions + [transition],
                    )

    extend(0, dict(donor_counters), dict(target_state), [], [])
    return {
        "status": "EXACT", "move_sets": tuple(move_sets),
        "battle_cage_records": tuple(cage_records),
        "target_meta": tuple(
            (serial, target_meta[serial][1], target_meta[serial][0], target_meta[serial][2])
            for serial in sorted(target_meta)
        ),
    }


def _dper_lineage_serials(pokemon):
    serials = set()
    pending = [pokemon]
    while pending:
        card = pending.pop()
        serial = _pcrd_serial(card)
        if serial is not None:
            serials.add(serial)
        pending.extend(tuple(_pcrd_get(card, "preEvolution", ()) or ()))
    return serials


def _dper_adrena_route_variants(obs, routes, move_sets, our_active, own_prizes):
    variants = []
    unsupported_variants = 0
    ability_only = set()
    active_serial = _pcrd_serial(our_active)
    target_cards = {
        _pcrd_serial(card): card
        for card in (our_active,) + tuple(my_state(obs).bench or ())
        if card is not None and _pcrd_serial(card) is not None
    }
    if active_serial is None:
        return {"variants": (), "unsupported": len(move_sets)}
    for move_set in move_sets:
        placed_by_target = dict(move_set["placed_by_target"])
        target_after = dict(move_set["target_counters_after"])
        moved_by_donor = {}
        for _, donor_serial, _, count, _ in move_set["moves"]:
            moved_by_donor[donor_serial] = moved_by_donor.get(donor_serial, 0) + count
        prefix = tuple(
            (
                "ADRENA_BRAIN", ability_serial, donor_serial,
                target_serial, count, zone,
            )
            for ability_serial, donor_serial, target_serial, count, zone
            in move_set["moves"]
        )
        ko_targets = []
        ability_prize = 0
        outcomes = []
        invalid = False
        for target_serial, placed in sorted(placed_by_target.items()):
            card = target_cards.get(target_serial)
            maximum = _pcrd_get(card, "maxHp") if card is not None else None
            if card is None or not isinstance(maximum, int):
                invalid = True
                break
            remaining = max(0, maximum - 10 * target_after[target_serial])
            ko = remaining == 0
            prize = 0
            if ko:
                unsupported = []
                prize = _pcrd_prize_yield(card, {}, unsupported)
                if unsupported or prize is None:
                    invalid = True
                    break
                ko_targets.append(target_serial)
                ability_prize += prize
            outcomes.append({
                "target_serial": target_serial, "placed_counters": placed,
                "remaining_hp": remaining, "ko": ko, "prize_yield": prize,
            })
        if invalid:
            unsupported_variants += 1
            continue
        active_ko = active_serial in ko_targets
        if active_ko:
            key = tuple(move_set["moves"])
            if key in ability_only:
                continue
            ability_only.add(key)
            if ability_prize < own_prizes:
                unsupported_variants += 1
                continue
            certificate = {
                "status": "EXACT", "effect_id": "ADRENA_BRAIN",
                "attack_damage": False, "final_damage": 0,
                "damage_counters_placed": sum(placed_by_target.values()),
                "target_hp": _pcrd_get(our_active, "hp"),
                "remaining_hp": 0, "ko": True,
                "prize_yield": ability_prize,
                "printed_prize_yield": ability_prize,
                "adrena_target_outcomes": tuple(outcomes),
                "post_reply_resource_ledger": {
                    "pre_attack_damage_counters": tuple(sorted(placed_by_target.items())),
                    "donor_counters_after": move_set["donor_counters_after"],
                },
                "pipeline": tuple(
                    step for transition in move_set["transitions"]
                    for step in transition["pipeline"]
                ),
                "consumers_updated": _DPER_COMBAT_CONSUMERS,
            }
            first_source = next((
                card for card in _pcrd_board_pokemon(opp_state(obs))
                if _pcrd_serial(card) == move_set["moves"][0][0]
            ), None)
            if first_source is None:
                unsupported_variants += 1
                continue
            variants.append(_pcrd_route(
                tier=_PCRD_KNOWN_PUBLIC_RESOURCE,
                sequence=prefix + (("ABILITY_COUNTER_KO",),),
                source=first_source, target=our_active, attack_id=None,
                certificate=certificate,
                public_resource={"effect_id": "ADRENA_BRAIN", "moves": move_set["moves"]},
                terminal=True,
            ))
            continue
        active_card = target_cards[active_serial]
        active_remaining = next(
            (row["remaining_hp"] for row in outcomes if row["target_serial"] == active_serial),
            _pcrd_get(active_card, "hp"),
        )
        if not isinstance(active_remaining, int) or active_remaining <= 0:
            unsupported_variants += len(routes)
            continue
        projected_target = _pcrd_project_pokemon(our_active, hp=active_remaining)
        if projected_target is None:
            unsupported_variants += len(routes)
            continue
        for route in routes:
            old = route.get("certificate", {})
            source = old.get("_dper_source_snapshot")
            state = old.get("_dper_effect_state")
            attack_id = route.get("attack_id")
            if source is None or not isinstance(state, dict) or attack_id is None:
                unsupported_variants += 1
                continue
            healed_counters = sum(
                moved_by_donor.get(serial, 0)
                for serial in _dper_lineage_serials(source)
            )
            projected_source = source
            if healed_counters:
                source_hp = _pcrd_get(source, "hp")
                source_max = _pcrd_get(source, "maxHp")
                if not isinstance(source_hp, int) or not isinstance(source_max, int):
                    unsupported_variants += 1
                    continue
                projected_source = _pcrd_project_pokemon(
                    source, hp=min(source_max, source_hp + 10 * healed_counters)
                )
                if projected_source is None:
                    unsupported_variants += 1
                    continue
            recomputed = _pcrd_public_combat_oracle(
                projected_source, attack_id, projected_target, dict(state)
            )
            if recomputed.get("status") != "EXACT":
                unsupported_variants += 1
                continue
            certificate = dict(recomputed)
            certificate["payment"] = old.get("payment")
            certificate["readiness"] = old.get("readiness")
            certificate["_dper_source_snapshot"] = copy.deepcopy(projected_source)
            certificate["_dper_effect_state"] = copy.deepcopy(state)
            for key in (
                "post_attack_switch_routes", "post_attack_evolution_routes",
                "saved_callback_transaction",
            ):
                if key in old:
                    certificate[key] = copy.deepcopy(old[key])
            certificate["damage_counters_placed"] = sum(placed_by_target.values())
            certificate["adrena_target_outcomes"] = tuple(outcomes)
            certificate["adrena_transitions"] = move_set["transitions"]
            certificate["pipeline"] = tuple(
                step for transition in move_set["transitions"]
                for step in transition["pipeline"]
            ) + tuple(certificate.get("pipeline", ()))
            ledger = dict(certificate.get("post_reply_resource_ledger", {}))
            ledger["pre_attack_damage_counters"] = tuple(sorted(placed_by_target.items()))
            ledger["donor_counters_after"] = move_set["donor_counters_after"]
            certificate["post_reply_resource_ledger"] = ledger
            certificate["prize_yield"] += ability_prize
            variant = copy.deepcopy(route)
            variant["sequence"] = prefix + tuple(route["sequence"])
            variant["source_id"] = _pcrd_get(projected_source, "id")
            variant["source_serial"] = _pcrd_serial(projected_source)
            variant["certificate"] = certificate
            variant["prize_yield"] = certificate["prize_yield"]
            variant["terminal"] = bool(
                certificate["prize_yield"] >= own_prizes
            )
            variants.append(variant)
    return {"variants": tuple(variants), "unsupported": unsupported_variants}


def _pcrd_threat_graph(
        obs, *, our_active, opponent_active, opponent_active_ko,
        attack_certificate, stadium):
    return_counters = attack_certificate.get("post_damage_counter_return", 0)
    if not isinstance(return_counters, int) or return_counters < 0:
        return {"complete": False, "routes": (), "unsupported_text": ("dper_spiky_return_counter_unknown",)}
    reply_target = our_active
    if return_counters:
        hp = _pcrd_get(our_active, "hp")
        if not isinstance(hp, int):
            return {"complete": False, "routes": (), "unsupported_text": ("dper_spiky_return_hp_unknown",)}
        if hp - 10 * return_counters <= 0:
            return {"complete": False, "routes": (), "unsupported_text": ("dper_spiky_return_ko_requires_promotion_projection",)}
        reply_target = _pcrd_project_pokemon(our_active, hp=hp - 10 * return_counters)
        if reply_target is None:
            return {"complete": False, "routes": (), "unsupported_text": ("dper_spiky_return_projection_unknown",)}
    post_action = _dper_post_action_observation(
        obs, opponent_active, opponent_active_ko, attack_certificate
    )
    if post_action["status"] != "EXACT":
        return {"complete": False, "routes": (), "unsupported_text": ("dper:" + post_action["reason"],)}
    post_obs = post_action["observation"]
    graph = _dper_legacy_threat_graph(
        post_obs, our_active=reply_target,
        opponent_active=opponent_active,
        opponent_active_ko=opponent_active_ko,
        attack_certificate=attack_certificate, stadium=stadium,
    )
    if not isinstance(graph, dict):
        return graph
    effect_state = _pcrd_reply_effect_state(
        stadium=stadium,
        our_attack_certificate=attack_certificate,
        target_player=my_state(post_obs),
    )
    extra = _dper_public_switch_and_heal_routes(
        post_obs, reply_target, opponent_active, opponent_active_ko,
        effect_state, len(tuple(my_state(post_obs).prize or ())),
    )
    if extra is None:
        result = dict(graph)
        result["complete"] = False
        result["unsupported_text"] = tuple(sorted(set(
            tuple(graph.get("unsupported_text", ()))
            + ("dper_public_switch_or_heal_route_unknown",)
        )))
        return result
    routes = list(graph.get("routes", ())) + list(extra)
    adrena = _dper_adrena_public_moves(post_obs, reply_target, stadium)
    if adrena["status"] != "EXACT":
        result = dict(graph)
        result["complete"] = False
        result["unsupported_text"] = tuple(sorted(set(
            tuple(graph.get("unsupported_text", ()))
            + ("dper:" + adrena["reason"],)
        )))
        return result
    variant_result = _dper_adrena_route_variants(
        post_obs, routes, adrena["move_sets"], reply_target,
        len(tuple(my_state(post_obs).prize or ())),
    )
    variants = variant_result["variants"]
    routes.extend(variants)
    unique = {}
    for route in routes:
        key = (
            route.get("tier"), route.get("sequence"),
            route.get("source_serial"), route.get("attack_id"),
        )
        unique.setdefault(key, route)
    result = dict(graph)
    result["routes"] = tuple(
        unique[key] for key in sorted(unique, key=repr)
    )
    result["registry_routes_added"] = len(extra)
    result["registry_adrena_routes_added"] = len(variants)
    result["registry_adrena_variants_not_admitted"] = variant_result["unsupported"]
    result["registry_bench_counter_routes"] = adrena["battle_cage_records"]
    if variant_result["unsupported"]:
        result["complete"] = False
        result["unsupported_text"] = tuple(sorted(set(
            tuple(graph.get("unsupported_text", ()))
            + ("dper_adrena_variant_not_admitted",)
        )))
    return result


def _pcrd_ice_projection(pokemon):
    if not _dper_effect_admitted("JUMBO_ICE_CREAM", 1147):
        return None
    return _dper_legacy_ice_projection(pokemon)


def _pcrd_static_metadata_supported():
    return bool(
        _dper_legacy_static_metadata_supported()
        and _dper_registry_status()["all_admitted"]
    )


_dper_parent_agent = agent
_dper_parent_call_count = 0
_dper_counters = {
    "callbacks_started": 0, "callbacks_completed": 0,
    "duplicates": 0, "stale": 0, "exceptions": 0,
    "invalid_actions": 0, "fallbacks": 0,
}
_dper_last_telemetry = None
_dper_active_callback = None
_dper_last_completed_callback = None


def _dper_attachment_snapshot(obs, owner):
    if obs is None or obs.current is None or owner not in (0, 1):
        return None
    rows = []
    for pokemon in _dper_board_cards(obs, owner):
        target_serial = _pcrd_serial(pokemon)
        energy_rows = _dper_energy_rows(pokemon)
        if target_serial is None or energy_rows is None:
            return None
        rows.extend((target_serial, row[1], row[2]) for row in energy_rows)
    return tuple(sorted(rows))


def _dper_callback_identity(obs):
    if obs is None or obs.select is None or obs.current is None:
        return None
    context = obs.select.contextCard or obs.select.effect
    card_id = _pcrd_get(context, "id")
    source_serial = _pcrd_serial(context)
    if card_id == 190:
        effect_id = "ASSEMBLE_ALLOY"
    elif card_id == 648:
        effect_id = "PUNK_UP"
    elif card_id == 666:
        effect_id = "TURBO_FLARE"
    elif card_id == 678:
        effect_id = "AURA_JAB"
    elif card_id in (43, 344, 875):
        effect_id = "ASCENSION"
    else:
        return None
    if source_serial is None:
        return None
    return effect_id, obs.current.yourIndex, obs.current.turn, source_serial


def _dper_immediate_callback_preview(obs):
    """Type-check a visible current-player selection without owning its action."""
    if obs is None or obs.select is None or obs.current is None:
        return None
    context = obs.select.contextCard or obs.select.effect
    card_id = _pcrd_get(context, "id")
    effect_by_card = {
        1123: "SWITCH", 1203: "SURFER",
        1147: "JUMBO_ICE_CREAM", 1229: "WALLYS_COMPASSION",
        1079: "RARE_CANDY", 1261: "FOREST_OF_VITALITY",
    }
    effect_id = effect_by_card.get(card_id)
    if effect_id is None:
        return None
    player = my_state(obs)
    board = _pcrd_board_pokemon(player)
    if effect_id in ("SWITCH", "SURFER"):
        active_serials = {
            _pcrd_serial(card) for card in tuple(player.active or ())
            if card is not None
        }
        legal_bench = tuple(
            card for card in tuple(player.bench or ())
            if card is not None and _pcrd_serial(card) not in active_serials
        )
        state = {
            "legal_bench": legal_bench, "public_card_available": True,
        }
        if effect_id == "SURFER":
            state["source_hand_count_after_play"] = _pcrd_get(player, "handCount")
            state["source_deck_count"] = _pcrd_get(player, "deckCount")
        result = _dper_effect_transition(effect_id, state)
    elif effect_id in ("JUMBO_ICE_CREAM", "WALLYS_COMPASSION"):
        transitions = []
        for target in board:
            location = _dper_board_location(obs, target)
            transition = _dper_effect_transition(effect_id, {
                "public_card_available": True, "target": target,
                "target_zone": location[1] if location is not None else None,
            })
            if transition["status"] == "EXACT":
                transitions.append(transition)
        if not transitions:
            return _dper_unknown(effect_id, "no_public_legal_callback_target", {})
        result = copy.deepcopy(transitions[0])
        result["after"] = {
            "legal_target_transitions": tuple(transitions),
        }
    else:
        transitions = []
        options = tuple(obs.select.option or ())
        for option in options:
            evolution = option_card(obs, option)
            target = option_target(obs, option)
            if evolution is None or target is None:
                continue
            transition = _dper_effect_transition(effect_id, {
                "source": target, "public_evolutions": (evolution,),
                "first_turn": bool(obs.current.turn <= 1),
                "appear_this_turn": bool(
                    _pcrd_get(target, "appearThisTurn", False)
                ),
            })
            if transition["status"] == "EXACT":
                transitions.append(transition)
        if not transitions:
            return _dper_unknown(effect_id, "no_public_stage_legal_callback_pair", {})
        result = copy.deepcopy(transitions[0])
        result["after"] = {
            "legal_callback_transitions": tuple(transitions),
        }
    result["callback_stage"] = "VISIBLE_SELECTION_PREVIEW"
    return result


def _dper_before_parent_callback(obs):
    global _dper_active_callback
    immediate = _dper_immediate_callback_preview(obs)
    if immediate is not None:
        return immediate
    identity = _dper_callback_identity(obs)
    if identity is None:
        return None
    effect_id, seat, turn, source_serial = identity
    if _dper_active_callback is None:
        transaction = _dper_begin_callback(effect_id, {
            "seat": seat, "turn": turn, "source_serial": source_serial,
        })
        if transaction.get("status") == "UNKNOWN":
            return transaction
        transaction["before_attachments"] = _dper_attachment_snapshot(obs, seat)
        if effect_id == "ASCENSION":
            transaction["source"] = copy.deepcopy(
                obs.select.contextCard or obs.select.effect
            )
        transaction["owner_mode"] = (
            "LEGACY_PARITY" if effect_id in ("ASSEMBLE_ALLOY", "TURBO_FLARE")
            else "REGISTRY"
        )
        _dper_active_callback = transaction
        _dper_counters["callbacks_started"] += 1
    expected = (
        _dper_active_callback.get("effect_id"),
        _dper_active_callback.get("seat"),
        _dper_active_callback.get("turn"),
        _dper_active_callback.get("source_serial"),
    )
    if identity != expected:
        _dper_counters["stale"] += 1
        return _dper_unknown(effect_id, "callback_owner_collision", identity)
    return {"status": "ACTIVE", "effect_id": effect_id, "callback_stage": _dper_active_callback["stage"]}


def _dper_after_parent_callback(obs, parent_action):
    global _dper_active_callback, _dper_last_completed_callback
    if _dper_active_callback is None or obs is None or obs.current is None:
        return None
    identity = _dper_callback_identity(obs)
    if identity is not None:
        _dper_active_callback["last_parent_roles"] = (
            _pcrd_action_roles(obs, parent_action)
            if obs.select is not None and _cum_valid_action(obs, parent_action)
            else None
        )
        return {"status": "ACTIVE", "effect_id": _dper_active_callback["effect_id"], "callback_stage": _dper_active_callback["stage"]}
    seat = _dper_active_callback["seat"]
    if obs.current.turn != _dper_active_callback["turn"]:
        _dper_counters["stale"] += 1
        result = _dper_unknown(_dper_active_callback["effect_id"], "callback_turn_changed_before_completion", {})
        _dper_active_callback = None
        return result
    if _dper_active_callback["effect_id"] == "ASCENSION":
        source_serial = _dper_active_callback["source_serial"]
        evolutions = tuple(
            card for card in _dper_board_cards(obs, seat)
            if any(
                _pcrd_serial(prior) == source_serial
                for prior in tuple(_pcrd_get(card, "preEvolution", ()) or ())
            )
        )
        source = _dper_active_callback.get("source")
        if source is None or not evolutions:
            return _dper_unknown("ASCENSION", "resolved_evolution_board_proof_missing", {})
        state = {
            "seat": seat, "turn": obs.current.turn,
            "source_serial": source_serial, "resolved": True,
            "source": source, "public_evolutions": evolutions,
            "first_turn": False, "appear_this_turn": bool(
                _pcrd_get(source, "appearThisTurn", False)
            ),
        }
    else:
        after = _dper_attachment_snapshot(obs, seat)
        before = _dper_active_callback.get("before_attachments")
        if before is None or after is None:
            return _dper_unknown(_dper_active_callback["effect_id"], "attachment_snapshot_unknown", {})
        additions = tuple(row for row in after if row not in set(before))
        state = {
            "seat": seat, "turn": obs.current.turn,
            "source_serial": _dper_active_callback["source_serial"],
            "resolved": True,
            "post_callback_attachments": additions,
        }
    result = _dper_resume_callback(_dper_active_callback, state)
    if result["status"] == "EXACT":
        _dper_counters["callbacks_completed"] += 1
        _dper_last_completed_callback = copy.deepcopy(_dper_active_callback)
        _dper_active_callback = None
    return result


def _dper_reset_runtime(reason):
    global _dper_current_obs, _dper_active_callback
    global _dper_seen_log_fingerprints, _dper_current_turn_plays
    global _dper_last_log_turn
    _dper_current_obs = None
    _dper_active_callback = None
    _dper_seen_log_fingerprints.clear()
    _dper_current_turn_plays.clear()
    _dper_last_log_turn = None
    return reason


def agent(obs_dict):
    """Invoke frozen PCRD v2 exactly once; registry non-admission is silent."""
    global _dper_parent_call_count, _dper_last_telemetry, _dper_current_obs
    obs = None
    callback_before = None
    try:
        obs = to_observation_class(obs_dict)
        _dper_current_obs = obs
        if obs.select is None or obs.current is None:
            _dper_reset_runtime("deck_request_or_missing_current")
        elif obs.current.result != -1:
            _dper_reset_runtime("game_result")
        else:
            _dper_update_public_log_evidence(obs)
            callback_before = _dper_before_parent_callback(obs)
    except Exception:
        _dper_current_obs = None
    parent_action = _dper_parent_agent(obs_dict)
    _dper_parent_call_count += 1
    telemetry = {
        "rule_id": _DPER_RULE_ID,
        "parent_call_count": _dper_parent_call_count,
        "registry": _dper_registry_status(),
        "selected_source": "PCRD_V2",
        "fallback_reason": None,
        "effect_id": None, "handler_type": None,
        "normalized_text_hash": None, "before": None, "after": None,
        "consumers_updated": (), "callback_stage": None,
        "unsupported_reason": None,
    }
    try:
        if obs is None:
            obs = to_observation_class(obs_dict)
            _dper_current_obs = obs
        callback_after = _dper_after_parent_callback(obs, parent_action)
        callback_result = callback_after or callback_before
        if callback_result is not None:
            telemetry["effect_id"] = callback_result.get("effect_id")
            telemetry["callback_stage"] = callback_result.get("callback_stage")
            telemetry["before"] = callback_result.get("before")
            telemetry["after"] = callback_result.get("after")
            telemetry["consumers_updated"] = callback_result.get("consumers_updated", ())
            telemetry["unsupported_reason"] = callback_result.get("unsupported_reason")
            bindings = _dper_effect_bindings(callback_result.get("effect_id"))
            if bindings:
                telemetry["handler_type"] = bindings[0].handler_type.value
                telemetry["normalized_text_hash"] = bindings[0].text_hash
        if obs.select is not None and not _cum_valid_action(obs, parent_action):
            _dper_counters["invalid_actions"] += 1
            telemetry["unsupported_reason"] = "invalid_direct_parent_action"
        elif not telemetry["registry"]["all_admitted"]:
            _dper_counters["fallbacks"] += 1
            telemetry["fallback_reason"] = "registry_binding_non_admission"
            telemetry["unsupported_reason"] = str(telemetry["registry"]["rejected_bindings"])
        else:
            telemetry["fallback_reason"] = "exact_semantic_tie_returns_pcrd_v2"
    except Exception as error:
        _dper_counters["exceptions"] += 1
        _dper_counters["fallbacks"] += 1
        telemetry["fallback_reason"] = "registry_observation_exception_returns_pcrd_v2"
        telemetry["unsupported_reason"] = type(error).__name__ + ":" + str(error)
    _dper_last_telemetry = telemetry
    return parent_action


