def _pfgear_freeze(value):
    """Comparable, deterministic representation without scalar scoring."""
    if isinstance(value, dict):
        return tuple(
            (str(key), _pfgear_freeze(value[key]))
            for key in sorted(value, key=str)
        )
    if isinstance(value, (list, tuple, set, frozenset)):
        rows = tuple(_pfgear_freeze(row) for row in value)
        return tuple(sorted(rows, key=repr)) if isinstance(
            value, (set, frozenset)
        ) else rows
    if isinstance(value, _DPEREnum):
        return int(value.value)
    if hasattr(value, "__dict__"):
        return (
            type(value).__name__,
            _pfgear_freeze(vars(value)),
        )
    return value


def _pfgear_hash(value):
    return hashlib.sha256(
        repr(_pfgear_freeze(value)).encode("utf-8")
    ).hexdigest()


def _pfgear_card_ref(card):
    if card is None:
        return None
    return (_pcrd_get(card, "id"), _pcrd_serial(card))


def _pfgear_card_multiset(cards):
    rows = []
    for card in tuple(cards or ()):
        if card is None:
            continue
        reference = _pfgear_card_ref(card)
        if reference[0] is None or reference[1] is None:
            return None
        rows.append(reference)
    return tuple(sorted(rows))


def _pfgear_pokemon_fp(pokemon, *, physical=True):
    if pokemon is None:
        return None
    data = CARD_DB.get(_pcrd_get(pokemon, "id"))
    serial = _pcrd_serial(pokemon)
    energy_rows = _dper_energy_rows(pokemon)
    hp = _pcrd_get(pokemon, "hp")
    maximum = _pcrd_get(pokemon, "maxHp")
    if (
        data is None
        or serial is None
        or energy_rows is None
        or not isinstance(hp, int)
        or not isinstance(maximum, int)
        or hp <= 0
        or hp > maximum
    ):
        return None
    tools = _pfgear_card_multiset(_pcrd_get(pokemon, "tools", ()) or ())
    previous = _pfgear_card_multiset(
        _pcrd_get(pokemon, "preEvolution", ()) or ()
    )
    if tools is None or previous is None:
        return None
    if not physical:
        tools = tuple(card_id for card_id, _ in tools)
        previous = tuple(card_id for card_id, _ in previous)
        energy_rows = tuple((row[0], row[1]) for row in energy_rows)
    return (
        _pcrd_get(pokemon, "id"),
        serial if physical else None,
        hp,
        maximum,
        bool(_pcrd_get(pokemon, "appearThisTurn", False)),
        tuple(energy_rows),
        tools,
        previous,
    )


def _pfgear_board_fp(obs):
    if obs is None or obs.current is None or len(obs.current.players) != 2:
        return None
    rows = []
    for player in obs.current.players:
        active = tuple(
            _pfgear_pokemon_fp(card)
            for card in tuple(player.active or ())
            if card is not None
        )
        bench = tuple(
            sorted(
                (
                    _pfgear_pokemon_fp(card)
                    for card in tuple(player.bench or ())
                    if card is not None
                ),
                key=repr,
            )
        )
        if any(row is None for row in active + bench):
            return None
        rows.append((active, bench))
    return tuple(rows)


def _pfgear_logs_fp(obs):
    rows = []
    for entry in tuple(obs.logs or ()):
        rows.append(
            (
                _pcrd_int(_pcrd_get(entry, "type")),
                _pcrd_int(_pcrd_get(entry, "playerIndex")),
                _pcrd_int(_pcrd_get(entry, "cardId")),
                _pcrd_int(_pcrd_get(entry, "serial")),
                _pcrd_int(_pcrd_get(entry, "attackId")),
                _pcrd_int(_pcrd_get(entry, "fromArea")),
                _pcrd_int(_pcrd_get(entry, "toArea")),
                _pcrd_int(_pcrd_get(entry, "serialActive")),
                _pcrd_int(_pcrd_get(entry, "serialBench")),
            )
        )
    return tuple(rows)


def _pfgear_option_multiset(obs):
    if obs is None or obs.select is None:
        return None
    return tuple(
        sorted(
            (_pcrd_option_role(obs, option) for option in obs.select.option),
            key=repr,
        )
    )


def _pfgear_public_state_fp(obs):
    if obs is None or obs.current is None:
        return None
    board = _pfgear_board_fp(obs)
    if board is None:
        return None
    player_rows = []
    for owner, player in enumerate(obs.current.players):
        discard = _pfgear_card_multiset(player.discard)
        hand = (
            None
            if owner != obs.current.yourIndex or player.hand is None
            else _pfgear_card_multiset(player.hand)
        )
        prizes = tuple(
            None if card is None else _pfgear_card_ref(card)
            for card in tuple(player.prize or ())
        )
        if discard is None or (
            owner == obs.current.yourIndex
            and player.hand is not None
            and hand is None
        ):
            return None
        player_rows.append(
            (
                _pcrd_get(player, "deckCount"),
                _pcrd_get(player, "handCount"),
                hand,
                discard,
                prizes,
                _pcrd_status_tuple(player),
            )
        )
    looking = _pfgear_card_multiset(obs.current.looking)
    stadium = _pfgear_card_multiset(obs.current.stadium)
    if looking is None or stadium is None:
        return None
    return _pfgear_hash(
        (
            obs.current.yourIndex,
            obs.current.turn,
            obs.current.turnActionCount,
            obs.current.result,
            bool(obs.current.supporterPlayed),
            bool(obs.current.stadiumPlayed),
            bool(obs.current.energyAttached),
            bool(obs.current.retreated),
            board,
            tuple(player_rows),
            looking,
            stadium,
        )
    )


def _pfgear_callback_fp(obs):
    if obs is None or obs.current is None or obs.select is None:
        return None
    effect = obs.select.effect
    context = obs.select.contextCard
    return _pfgear_hash(
        (
            _pfgear_public_state_fp(obs),
            _pcrd_int(obs.select.context),
            obs.select.minCount,
            obs.select.maxCount,
            _pfgear_card_ref(effect),
            _pfgear_card_ref(context),
            _pfgear_option_multiset(obs),
            _pfgear_logs_fp(obs),
        )
    )


def _pfgear_metadata_hashes():
    registry = _dper_registry_status()
    return {
        "gear_text_hash": _dper_text_hash(
            _pcrd_get(CARD_DB.get(POKEGEAR).skills[0], "text")
        ) if CARD_DB.get(POKEGEAR) is not None else None,
        "boss_text_hash": _dper_text_hash(
            _pcrd_get(CARD_DB.get(BOSS).skills[0], "text")
        ) if CARD_DB.get(BOSS) is not None else None,
        "registry_binding_count": registry.get("binding_count"),
        "registry_effect_count": registry.get("effect_count"),
        "registry_all_admitted": registry.get("all_admitted"),
        "registry_rejected": tuple(registry.get("rejected_bindings", ())),
    }


def _pfgear_metadata_exact():
    gear = CARD_DB.get(POKEGEAR)
    boss = CARD_DB.get(BOSS)
    hashes = _pfgear_metadata_hashes()
    return bool(
        gear is not None
        and boss is not None
        and _pcrd_int(_pcrd_get(gear, "cardType")) == 1
        and _pcrd_int(_pcrd_get(boss, "cardType")) == 3
        and _pcrd_exact_trainer(
            POKEGEAR, "Pokégear 3.0", _PFGEAR_GEAR_TEXT
        )
        and _pcrd_exact_trainer(
            BOSS, "Boss’s Orders", _PFGEAR_BOSS_TEXT
        )
        and hashes["gear_text_hash"] == _PFGEAR_GEAR_TEXT_HASH
        and hashes["boss_text_hash"] == _PFGEAR_BOSS_TEXT_HASH
        and hashes["registry_all_admitted"]
        and not hashes["registry_rejected"]
    )


def _pfgear_inherited_owner_active():
    return bool(
        _pcrd_transaction is not None
        or _dper_active_callback is not None
        or _pcrd_inherited_owner_active()
    )


def _pfgear_adrena_present(obs):
    if obs is None or obs.current is None:
        return False
    opponent = obs.current.players[1 - obs.current.yourIndex]
    return any(
        _pcrd_get(card, "id") == 112
        for card in _pcrd_board_pokemon(opponent)
    )


def _pfgear_boundary(obs):
    if (
        obs is None
        or obs.current is None
        or obs.select is None
        or obs.current.result != -1
        or obs.select.context != SelectContext.MAIN
        or obs.select.minCount != 1
        or obs.select.maxCount != 1
        or obs.select.effect is not None
        or obs.select.contextCard is not None
        or obs.current.looking is not None
    ):
        return False
    if (
        obs.current.yourIndex not in (0, 1)
        or not isinstance(obs.current.turn, int)
        or not isinstance(obs.current.turnActionCount, int)
        or _pcrd_all_public_serials(obs) is None
        or _pfgear_public_state_fp(obs) is None
        or _pfgear_inherited_owner_active()
    ):
        return False
    return True


def _pfgear_attack_effect_state(obs, source, target):
    mine = my_state(obs)
    opponent = opp_state(obs)
    stadium = _pcrd_stadium_state(obs)
    target_board = _pcrd_board_pokemon(opponent)
    source_board = _pcrd_board_pokemon(mine)
    return {
        "full_metal_lab": bool(stadium.get("full_metal_lab")),
        **_pcrd_prior_defense_effect(target),
        "source_bench": tuple(
            card for card in tuple(mine.bench or ()) if card is not None
        ),
        "memory_dive_sources": tuple(
            card for card in source_board if _pcrd_get(card, "id") == 57
        ),
        "cheer_on_sources": tuple(
            card for card in source_board if _pcrd_get(card, "id") == 342
        ),
        "target_zone": "ACTIVE",
        "target_bench": tuple(
            card
            for card in target_board
            if _pcrd_serial(card) != _pcrd_serial(target)
        ),
        "target_flower_curtain_sources": tuple(
            card for card in target_board if _pcrd_get(card, "id") == 343
        ),
        "target_own_pokemon_count": len(target_board),
        "target_deck_count": _pcrd_get(opponent, "deckCount"),
        # Opponent hand identities are never an own-turn public input.  Even
        # checked-engine/full-state fixtures must not turn them into an oracle.
        "target_public_hand": (),
        "run_away_available": _pcrd_get(target, "id") == 66,
        "run_away_once_unspent": True,
        "target_survives_in_play": True,
        "first_turn": bool(obs.current.turn <= 1),
    }


def _pfgear_with_current_obs(obs, callback, *args, **kwargs):
    global _dper_current_obs
    previous = _dper_current_obs
    _dper_current_obs = obs
    try:
        return callback(*args, **kwargs)
    finally:
        _dper_current_obs = previous


def _pfgear_attack_certificate(obs, source, attack_id, target):
    attack = ALL_ATTACKS.get(attack_id)
    if attack is None or _pcrd_attack_payment(source, attack) is None:
        return None
    state = _pfgear_attack_effect_state(obs, source, target)
    certificate = _pfgear_with_current_obs(
        obs,
        _pcrd_public_combat_oracle,
        source,
        attack_id,
        target,
        state,
    )
    return (
        certificate
        if isinstance(certificate, dict)
        and certificate.get("status") == "EXACT"
        else None
    )


def _pfgear_threat_graph(obs, source, target, certificate):
    stadium = _pcrd_stadium_state(obs)
    if stadium.get("status") != "EXACT":
        return None
    public_obs = copy.deepcopy(obs)
    public_obs.current.players[1 - public_obs.current.yourIndex].hand = None
    public_source = _pfgear_find_board_pokemon(
        public_obs, public_obs.current.yourIndex, _pcrd_serial(source)
    )
    public_target = _pfgear_find_board_pokemon(
        public_obs, 1 - public_obs.current.yourIndex, _pcrd_serial(target)
    )
    if public_source is None or public_target is None:
        return None
    graph = _pfgear_with_current_obs(
        public_obs,
        _pcrd_threat_graph,
        public_obs,
        our_active=public_source,
        opponent_active=public_target,
        opponent_active_ko=bool(certificate.get("ko")),
        attack_certificate=certificate,
        stadium=stadium,
    )
    if not isinstance(graph, dict):
        return None
    if graph.get("registry_adrena_variants_not_admitted", 0):
        _pfgear_counters["adrena_quarantines"] += 1
        return None
    if not graph.get("complete"):
        return None
    return graph


def _pfgear_project_gust(obs, target_serial):
    projected = copy.deepcopy(obs)
    opponent = opp_state(projected)
    active = tuple(card for card in tuple(opponent.active or ()) if card)
    matches = [
        (position, card)
        for position, card in enumerate(tuple(opponent.bench or ()))
        if card is not None and _pcrd_serial(card) == target_serial
    ]
    if len(active) != 1 or len(matches) != 1:
        return None
    position, target = matches[0]
    bench = list(opponent.bench or ())
    bench[position] = active[0]
    opponent.active[:] = [target]
    opponent.bench[:] = bench
    return projected


def _pfgear_current_attack_rows(obs, *, allow_duplicate_ui=False):
    active = active_pokemon(obs)
    target = opp_active_pokemon(obs)
    if active is None or target is None:
        return None, "missing_active"
    access = _dper_memory_dive_access(
        active,
        {
            **_pfgear_attack_effect_state(obs, active, target),
            "require_payable": True,
        },
    )
    if access.get("status") != "EXACT":
        return None, "attack_access_unknown"
    accessible = {
        row[0] for row in access["after"].get("attack_rows", ())
    }
    positions_by_attack = {}
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.ATTACK:
            continue
        attack_id = _pcrd_int(option.attackId)
        if attack_id is None or attack_id not in accessible:
            return None, "legal_attack_not_exactly_accessible"
        positions_by_attack.setdefault(attack_id, []).append(position)
    if not positions_by_attack:
        return (), "no_payable_attack"
    rows = []
    for attack_id in sorted(positions_by_attack):
        positions = tuple(positions_by_attack[attack_id])
        roles = tuple(
            _pcrd_option_role(obs, obs.select.option[position])
            for position in positions
        )
        if len(set(roles)) != 1:
            return None, "attack_option_semantic_collision"
        if len(positions) != 1 and not allow_duplicate_ui:
            return None, "duplicate_attack_option"
        certificate = _pfgear_attack_certificate(
            obs, active, attack_id, target
        )
        if certificate is None:
            return None, "attack_certificate_unknown"
        payment = _pcrd_attack_payment(active, ALL_ATTACKS[attack_id])
        if payment is None:
            return None, "attack_payment_unknown"
        graph = _pfgear_threat_graph(obs, active, target, certificate)
        if graph is None:
            return None, "reply_graph_unknown"
        rows.append(
            {
                "attack_id": attack_id,
                "positions": positions,
                "role": roles[0],
                "payment": payment,
                "certificate": certificate,
                "threat_graph": graph,
            }
        )
    return tuple(rows), None


def _pfgear_semanticize(value, target_serial, key_name=None):
    if isinstance(value, dict):
        return tuple(
            (
                str(key),
                _pfgear_semanticize(value[key], target_serial, str(key)),
            )
            for key in sorted(value, key=str)
        )
    if isinstance(value, (list, tuple, set, frozenset)):
        rows = tuple(
            _pfgear_semanticize(row, target_serial, key_name)
            for row in value
        )
        return tuple(sorted(rows, key=repr)) if isinstance(
            value, (set, frozenset)
        ) else rows
    if (
        isinstance(value, int)
        and value == target_serial
        and key_name is not None
        and "serial" in key_name.casefold()
    ):
        return "BOUND_TARGET"
    return value


def _pfgear_strip_physical(value, key_name=None):
    if isinstance(value, dict):
        rows = []
        for key in sorted(value, key=str):
            name = str(key)
            lowered = name.casefold()
            if "serial" in lowered or lowered in {
                "sequence",
                "public_resource",
            }:
                continue
            rows.append((name, _pfgear_strip_physical(value[key], name)))
        return tuple(rows)
    if isinstance(value, (list, tuple, set, frozenset)):
        if key_name in {
            "payment",
            "source_energy",
            "post_energy",
            "energy_payment",
        }:
            normalized = []
            for row in value:
                if isinstance(row, (list, tuple)) and len(row) >= 2:
                    normalized.append(tuple(row[:2]))
                else:
                    normalized.append(_pfgear_strip_physical(row))
            return tuple(sorted(normalized, key=repr))
        rows = tuple(_pfgear_strip_physical(row, key_name) for row in value)
        return tuple(sorted(rows, key=repr)) if isinstance(
            value, (set, frozenset)
        ) else rows
    if hasattr(value, "id") and hasattr(value, "serial"):
        if hasattr(value, "hp"):
            return _pfgear_pokemon_fp(value, physical=False)
        return _pcrd_get(value, "id")
    if hasattr(value, "__dict__"):
        return (type(value).__name__, _pfgear_strip_physical(vars(value)))
    if isinstance(value, _DPEREnum):
        return int(value.value)
    return value


def _pfgear_exact_routes(graph):
    return tuple(
        route
        for route in tuple(graph.get("routes", ()) or ())
        if route.get("certain")
        and isinstance(route.get("certificate"), dict)
        and route["certificate"].get("status") == "EXACT"
    )


def _pfgear_find_board_pokemon(obs, owner, serial):
    matches = [
        card
        for card in _dper_board_cards(obs, owner)
        if _pcrd_serial(card) == serial
    ]
    return matches[0] if len(matches) == 1 else None


def _pfgear_ready_bench_set(obs, target):
    rows = []
    for source in tuple(my_state(obs).bench or ()):
        if source is None:
            continue
        access = _dper_memory_dive_access(
            source,
            {
                **_pfgear_attack_effect_state(obs, source, target),
                "require_payable": True,
            },
        )
        if access.get("status") != "EXACT":
            return None
        for access_row in tuple(access["after"].get("attack_rows", ())):
            attack_id = access_row[0]
            certificate = _pfgear_attack_certificate(
                obs, source, attack_id, target
            )
            if certificate is None:
                return None
            rows.append((_pcrd_serial(source), attack_id))
    return frozenset(rows)


def _pfgear_post_attack_readiness(obs, source, target, attack_id, certificate):
    ledger = certificate.get("post_attack_resource_ledger")
    if ledger is None:
        if attack_id not in {223, 224, 253, 1212}:
            return None
        energy_rows = _dper_energy_rows(source)
        if energy_rows is None:
            return None
        post_energy = tuple(energy_rows)
        projected_source = source
    else:
        post_energy = ledger.get("source_energy")
        if post_energy is None:
            return None
        projected_source = _pcrd_project_pokemon(
            source,
            energies=tuple(row[0] for row in post_energy),
            energy_cards=tuple((row[1], row[2]) for row in post_energy),
        )
        if projected_source is None:
            return None
    access = _dper_memory_dive_access(
        projected_source,
        {
            **_pfgear_attack_effect_state(obs, projected_source, target),
            "require_payable": True,
        },
    )
    if access.get("status") != "EXACT":
        return None
    payable = tuple(
        row[0] for row in access["after"].get("attack_rows", ())
    )
    return {
        "post_energy": post_energy,
        "payable_attack_ids": payable,
        "payable": bool(payable),
    }


def _pfgear_candidate_line(obs, attack_row, target):
    target_serial = _pcrd_serial(target)
    projected = _pfgear_project_gust(obs, target_serial)
    if projected is None:
        return None
    source = active_pokemon(projected)
    projected_target = opp_active_pokemon(projected)
    if (
        source is None
        or projected_target is None
        or _pcrd_serial(source) != _pcrd_serial(active_pokemon(obs))
        or _pcrd_serial(projected_target) != target_serial
    ):
        return None
    certificate = _pfgear_attack_certificate(
        projected, source, attack_row["attack_id"], projected_target
    )
    if certificate is None:
        return None
    payment = _pcrd_attack_payment(
        source, ALL_ATTACKS[attack_row["attack_id"]]
    )
    if payment != attack_row["payment"]:
        return None
    graph = _pfgear_threat_graph(
        projected, source, projected_target, certificate
    )
    if graph is None:
        return None
    semantic = (
        attack_row["attack_id"],
        tuple((row[0], row[1]) for row in payment),
        _pfgear_pokemon_fp(projected_target, physical=False),
        _pfgear_strip_physical(certificate),
        _pfgear_strip_physical(graph),
    )
    return {
        "projected": projected,
        "target_serial": target_serial,
        "target_fingerprint": _pfgear_pokemon_fp(target),
        "target_semantic_fingerprint": _pfgear_pokemon_fp(
            target, physical=False
        ),
        "certificate": certificate,
        "threat_graph": graph,
        "semantic_successor": semantic,
    }


def _pfgear_common_positive(obs):
    if not _pfgear_boundary(obs):
        return None, "not_live_transaction_free_main"
    if not _pfgear_metadata_exact():
        return None, "trainer_or_registry_metadata_unknown"
    if _pfgear_adrena_present(obs):
        _pfgear_counters["adrena_quarantines"] += 1
        return None, "public_adrena_quarantine"
    mine = my_state(obs)
    opponent = opp_state(obs)
    hand = _pcrd_hand(obs)
    if hand is None:
        return None, "own_hand_unknown"
    if (
        _pcrd_status_tuple(mine) != (False,) * 5
        or _pcrd_status_tuple(opponent) != (False,) * 5
    ):
        return None, "public_status_unknown_or_unsupported"
    if (
        not isinstance(mine.deckCount, int)
        or mine.deckCount <= 0
        or not isinstance(opponent.deckCount, int)
        or opponent.deckCount < 0
        or not isinstance(mine.handCount, int)
        or mine.handCount != len(hand)
        or not isinstance(obs.current.supporterPlayed, bool)
        or obs.current.supporterPlayed
        or not isinstance(obs.current.energyAttached, bool)
        or not isinstance(obs.current.retreated, bool)
        or BOSS in {_pcrd_get(card, "id") for card in hand}
    ):
        return None, "supporter_hand_or_deck_gate_failed"
    discarded_boss = _pcrd_cards(mine.discard, BOSS)
    if len(discarded_boss) >= 4:
        return None, "all_boss_copies_publicly_exhausted"
    gear_options = []
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        if option.type == OptionType.PLAY and _pcrd_get(card, "id") == POKEGEAR:
            gear_options.append((position, card))
    if len(gear_options) != 1:
        return None, "gear_absent_or_ambiguous"
    gear_position, gear = gear_options[0]
    gear_serial = _pcrd_serial(gear)
    if gear_serial is None:
        return None, "gear_serial_unknown"
    gear_role = _pcrd_option_role(obs, obs.select.option[gear_position])
    if sum(
        _pcrd_option_role(obs, option) == gear_role
        for option in obs.select.option
    ) != 1:
        return None, "duplicate_gear_option"
    attack_rows, attack_reason = _pfgear_current_attack_rows(obs)
    if attack_rows is None or not attack_rows:
        return None, attack_reason or "no_payable_attack"
    remaining_prizes = len(tuple(mine.prize or ()))
    if remaining_prizes <= 0:
        return None, "invalid_remaining_prizes"
    current_target = opp_active_pokemon(obs)
    opponent_bench = tuple(
        card for card in tuple(opponent.bench or ()) if card is not None
    )
    if current_target is None or not opponent_bench:
        return None, "no_benched_boss_target"
    for attack_row in attack_rows:
        certificate = attack_row["certificate"]
        if certificate["ko"] and (
            certificate["prize_yield"] >= remaining_prizes
            or not opponent_bench
        ):
            return None, "current_active_attack_already_wins"
    return {
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "turn_action_count": obs.current.turnActionCount,
        "gear_serial": gear_serial,
        "gear_role": gear_role,
        "attacker_id": _pcrd_get(active_pokemon(obs), "id"),
        "attacker_serial": _pcrd_serial(active_pokemon(obs)),
        "attacker_fingerprint": _pfgear_pokemon_fp(active_pokemon(obs)),
        "original_active_serial": _pcrd_serial(current_target),
        "original_active_fingerprint": _pfgear_pokemon_fp(current_target),
        "attack_rows": attack_rows,
        "remaining_prizes": remaining_prizes,
        "hand": _pfgear_card_multiset(hand),
        "discard": _pfgear_card_multiset(mine.discard),
        "opponent_discard": _pfgear_card_multiset(opponent.discard),
        "board": _pfgear_board_fp(obs),
        "prize_counts": (
            len(tuple(mine.prize or ())),
            len(tuple(opponent.prize or ())),
        ),
        "deck_counts": (mine.deckCount, opponent.deckCount),
        "gear_reveal_count": min(7, mine.deckCount),
        "supporter_played": obs.current.supporterPlayed,
        "energy_attached": obs.current.energyAttached,
        "retreated": obs.current.retreated,
        "metadata_hashes": _pfgear_metadata_hashes(),
        "option_multiset": _pfgear_option_multiset(obs),
        "public_state_fingerprint": _pfgear_public_state_fp(obs),
    }, None


def _pfgear_finish_candidates(obs, common):
    candidates = []
    for attack_row in common["attack_rows"]:
        for target in tuple(opp_state(obs).bench or ()):
            if target is None:
                continue
            line = _pfgear_candidate_line(obs, attack_row, target)
            if line is None:
                return None, "finish_successor_unknown"
            certificate = line["certificate"]
            if (
                certificate["ko"]
                and certificate["prize_yield"] >= common["remaining_prizes"]
            ):
                candidates.append(
                    {
                        "purpose": "FINISH_NOW",
                        "attack_row": attack_row,
                        "line": line,
                        "proof": {
                            "ko": True,
                            "prize_yield": certificate["prize_yield"],
                            "remaining_prizes": common["remaining_prizes"],
                        },
                    }
                )
    return tuple(candidates), None


def _pfgear_avoid_candidates(obs, common):
    candidates = []
    for attack_row in common["attack_rows"]:
        baseline_routes = _pfgear_exact_routes(attack_row["threat_graph"])
        terminal = tuple(route for route in baseline_routes if route["terminal"])
        if not terminal:
            continue
        for target in tuple(opp_state(obs).bench or ()):
            if target is None:
                continue
            target_serial = _pcrd_serial(target)
            if not all(route.get("source_serial") == target_serial for route in terminal):
                continue
            line = _pfgear_candidate_line(obs, attack_row, target)
            if line is None:
                return None, "avoid_successor_unknown"
            certificate = line["certificate"]
            candidate_routes = _pfgear_exact_routes(line["threat_graph"])
            if (
                not certificate["ko"]
                or certificate["prize_yield"]
                < attack_row["certificate"]["prize_yield"]
                or any(route["terminal"] for route in candidate_routes)
            ):
                continue
            candidates.append(
                {
                    "purpose": "AVOID_EXACT_LOSS",
                    "attack_row": attack_row,
                    "line": line,
                    "proof": {
                        "baseline_terminal_routes": tuple(terminal),
                        "candidate_terminal_routes": tuple(
                            route for route in candidate_routes
                            if route["terminal"]
                        ),
                        "unique_removed_source_serial": target_serial,
                        "baseline_prize_yield": attack_row["certificate"]["prize_yield"],
                        "candidate_prize_yield": certificate["prize_yield"],
                    },
                }
            )
    return tuple(candidates), None


def _pfgear_preserve_candidates(obs, common):
    candidates = []
    original_target = opp_active_pokemon(obs)
    initial_backup = _pfgear_ready_bench_set(obs, original_target)
    resources = _pcrd_resources(obs)
    if initial_backup is None or resources is None:
        return None, "continuity_resource_ledger_unknown"
    for attack_row in common["attack_rows"]:
        baseline_routes = _pfgear_exact_routes(attack_row["threat_graph"])
        if (
            not baseline_routes
            or any(route["terminal"] for route in baseline_routes)
            or not attack_row["certificate"]["ko"]
        ):
            continue
        for target in tuple(opp_state(obs).bench or ()):
            if target is None:
                continue
            target_serial = _pcrd_serial(target)
            if not all(
                route.get("tier") == _PCRD_READY_NOW
                and route.get("source_serial") == target_serial
                and route["certificate"].get("ko")
                for route in baseline_routes
            ):
                continue
            baseline_backup = _pfgear_ready_bench_set(obs, target)
            if baseline_backup is None or baseline_backup:
                continue
            line = _pfgear_candidate_line(obs, attack_row, target)
            if line is None:
                return None, "continuity_successor_unknown"
            certificate = line["certificate"]
            candidate_routes = _pfgear_exact_routes(line["threat_graph"])
            readiness = _pfgear_post_attack_readiness(
                line["projected"],
                active_pokemon(line["projected"]),
                opp_active_pokemon(line["projected"]),
                attack_row["attack_id"],
                certificate,
            )
            baseline_readiness = _pfgear_post_attack_readiness(
                obs,
                active_pokemon(obs),
                opp_active_pokemon(obs),
                attack_row["attack_id"],
                attack_row["certificate"],
            )
            if (
                not certificate["ko"]
                or certificate["prize_yield"]
                < attack_row["certificate"]["prize_yield"]
                or any(route["terminal"] for route in candidate_routes)
                or readiness is None
                or baseline_readiness is None
                or not readiness["payable"]
                or any(route["certificate"].get("ko") for route in candidate_routes)
                or readiness["post_energy"]
                != baseline_readiness["post_energy"]
            ):
                continue
            backup_preserved = True
            candidate_backup_sets = []
            for route in candidate_routes:
                reply_source = _pfgear_find_board_pokemon(
                    line["projected"],
                    1 - common["seat"],
                    route.get("source_serial"),
                )
                if reply_source is None:
                    backup_preserved = False
                    break
                ready = _pfgear_ready_bench_set(line["projected"], reply_source)
                if ready is None or not initial_backup.issubset(ready):
                    backup_preserved = False
                    break
                candidate_backup_sets.append(tuple(sorted(ready)))
            if not backup_preserved:
                continue
            candidates.append(
                {
                    "purpose": "PRESERVE_ATTACK_CHAIN",
                    "attack_row": attack_row,
                    "line": line,
                    "proof": {
                        "baseline_routes_all_break_chain": True,
                        "baseline_reply_routes": tuple(baseline_routes),
                        "candidate_reply_routes": tuple(candidate_routes),
                        "current_attacker_payable_after_every_reply": True,
                        "initial_ready_backup": tuple(sorted(initial_backup)),
                        "candidate_ready_backups": tuple(candidate_backup_sets),
                        "source_energy_ledger_equal": True,
                        "recovery_capacity": resources["recovery"],
                        "energy_attachment_capacity_unchanged": True,
                        "unique_removed_source_serial": target_serial,
                    },
                }
            )
    return tuple(candidates), None


def _pfgear_choose_candidate(candidates):
    if not candidates:
        return None, "no_candidate_for_purpose"
    signatures = {
        _pfgear_freeze(candidate["line"]["semantic_successor"])
        for candidate in candidates
    }
    if len(signatures) != 1:
        _pfgear_counters["semantic_ties"] += 1
        return None, "multiple_incomparable_successors"
    return min(
        candidates,
        key=lambda candidate: (
            candidate["line"]["target_serial"],
            candidate["attack_row"]["attack_id"],
        ),
    ), None


def _pfgear_positive_certificate(obs):
    common, reason = _pfgear_common_positive(obs)
    if common is None:
        return None, reason
    for builder in (
        _pfgear_finish_candidates,
        _pfgear_avoid_candidates,
        _pfgear_preserve_candidates,
    ):
        candidates, build_reason = builder(obs, common)
        if candidates is None:
            return None, build_reason
        if not candidates:
            continue
        chosen, choose_reason = _pfgear_choose_candidate(candidates)
        if chosen is None:
            return None, choose_reason
        attack_row = chosen["attack_row"]
        line = chosen["line"]
        certificate = {
            key: copy.deepcopy(value)
            for key, value in common.items()
            if key != "attack_rows"
        }
        certificate.update(
            {
                "purpose": chosen["purpose"],
                "attack_id": attack_row["attack_id"],
                "attack_role": attack_row["role"],
                "attack_payment": attack_row["payment"],
                "current_attack_certificate": copy.deepcopy(
                    attack_row["certificate"]
                ),
                "current_threat_graph": copy.deepcopy(
                    attack_row["threat_graph"]
                ),
                "target_serial": line["target_serial"],
                "target_fingerprint": line["target_fingerprint"],
                "target_semantic_fingerprint": line[
                    "target_semantic_fingerprint"
                ],
                "post_gust_attack_certificate": copy.deepcopy(
                    line["certificate"]
                ),
                "post_gust_threat_graph": copy.deepcopy(
                    line["threat_graph"]
                ),
                "purpose_proof": copy.deepcopy(chosen["proof"]),
                "semantic_successor": copy.deepcopy(
                    line["semantic_successor"]
                ),
            }
        )
        certificate["certificate_hash"] = _pfgear_hash(certificate)
        return certificate, None
    return None, "no_positive_gear_purpose"


def _pfgear_replace_card(rows, *, remove=(), add=()):
    values = list(tuple(rows or ()))
    for reference in tuple(remove):
        if reference not in values:
            return None
        values.remove(reference)
    values.extend(tuple(add))
    return tuple(sorted(values))


def _pfgear_expected_core(
        obs,
        transaction,
        *,
        action_count,
        deck_count,
        hand,
        discard,
        board,
        supporter_played):
    if obs is None or obs.current is None:
        return False
    certificate = transaction["certificate"]
    if (
        obs.current.yourIndex != certificate["seat"]
        or obs.current.turn != certificate["turn"]
        or obs.current.result != -1
        or obs.current.turnActionCount != action_count
        or obs.current.supporterPlayed is not supporter_played
        or obs.current.energyAttached is not certificate["energy_attached"]
        or obs.current.retreated is not certificate["retreated"]
        or _pfgear_metadata_hashes() != certificate["metadata_hashes"]
        or _pfgear_board_fp(obs) != board
    ):
        return False
    mine = my_state(obs)
    opponent = opp_state(obs)
    return bool(
        mine.deckCount == deck_count
        and opponent.deckCount == certificate["deck_counts"][1]
        and _pfgear_card_multiset(mine.hand) == hand
        and _pfgear_card_multiset(mine.discard) == discard
        and _pfgear_card_multiset(opponent.discard)
        == certificate["opponent_discard"]
        and (
            len(tuple(mine.prize or ())),
            len(tuple(opponent.prize or ())),
        ) == certificate["prize_counts"]
        and _pcrd_status_tuple(mine) == (False,) * 5
        and _pcrd_status_tuple(opponent) == (False,) * 5
    )


def _pfgear_bound_attack(obs, transaction, *, require_unique=True):
    certificate = transaction["certificate"]
    active = active_pokemon(obs)
    target = opp_active_pokemon(obs)
    if (
        active is None
        or target is None
        or _pfgear_pokemon_fp(active) != certificate["attacker_fingerprint"]
    ):
        return None
    positions = _pcrd_positions(
        obs,
        option_type=OptionType.ATTACK,
        attack_id=certificate["attack_id"],
    )
    if not positions or (require_unique and len(positions) != 1):
        return None
    roles = tuple(
        _pcrd_option_role(obs, obs.select.option[position])
        for position in positions
    )
    if len(set(roles)) != 1 or roles[0] != certificate["attack_role"]:
        return None
    payment = _pcrd_attack_payment(
        active, ALL_ATTACKS.get(certificate["attack_id"])
    )
    if payment != certificate["attack_payment"]:
        return None
    current = _pfgear_attack_certificate(
        obs, active, certificate["attack_id"], target
    )
    if current is None:
        return None
    return {
        "positions": positions,
        "role": roles[0],
        "certificate": current,
    }


def _pfgear_emit_roles(obs, transaction, roles):
    action = _pcrd_bind_roles(obs, roles)
    if action is None:
        return None
    transaction["last_fingerprint"] = _pfgear_callback_fp(obs)
    transaction["last_roles"] = tuple(roles)
    transaction["last_option_multiset"] = _pfgear_option_multiset(obs)
    return action


def _pfgear_parent_roles(obs, parent_action):
    if (
        obs is None
        or obs.select is None
        or not _cum_valid_action(obs, parent_action)
    ):
        return None
    return _pcrd_action_roles(obs, parent_action)


def _pfgear_record_transaction(transaction, rejection_reason=None):
    certificate = transaction.get("certificate", {}) if transaction else {}
    _pfgear_last_fields.update(
        {
            "stage": None if transaction is None else transaction.get("stage"),
            "rejection_reason": rejection_reason,
            "bound_gear_serial": certificate.get("gear_serial"),
            "bound_boss_serial": (
                None if transaction is None else transaction.get("boss_serial")
            ),
            "bound_target_serial": certificate.get("target_serial"),
            "bound_attacker_serial": certificate.get("attacker_serial"),
            "bound_attack_id": certificate.get("attack_id"),
            "secured_attack_legal_on_miss": (
                None
                if transaction is None
                else transaction.get("secured_attack_legal_on_miss")
            ),
            "purpose": certificate.get("purpose"),
            "certificate": copy.deepcopy(certificate) if certificate else None,
        }
    )


def _pfgear_clear(reason):
    global _pfgear_transaction
    transaction = _pfgear_transaction
    if transaction is not None:
        _pfgear_record_transaction(transaction, reason)
    _pfgear_transaction = None
    return reason


def _pfgear_abort(obs, parent_action, reason):
    global _pfgear_transaction
    transaction = _pfgear_transaction
    if transaction is None:
        return parent_action
    if transaction.get("stage") != "ABORT_TO_PARENT":
        _pfgear_counters["aborts_to_parent"] += 1
        if "collision" in reason:
            _pfgear_counters["owner_collisions"] += 1
        else:
            _pfgear_counters["stale_transitions"] += 1
    transaction["stage"] = "ABORT_TO_PARENT"
    transaction["abort_reason"] = reason
    transaction["last_fingerprint"] = _pfgear_callback_fp(obs)
    transaction["last_roles"] = _pfgear_parent_roles(obs, parent_action)
    transaction["last_option_multiset"] = _pfgear_option_multiset(obs)
    _pfgear_record_transaction(transaction, reason)
    if transaction["last_fingerprint"] is None:
        _pfgear_transaction = None
    return parent_action


def _pfgear_begin(obs, certificate):
    global _pfgear_transaction
    projected = _pfgear_project_gust(obs, certificate["target_serial"])
    if projected is None:
        return None
    transaction = {
        "rule_id": _PFGEAR_RULE_ID,
        "stage": "GEAR_PLAY_EMITTED",
        "certificate": copy.deepcopy(certificate),
        "boss_serial": None,
        "boss_fingerprint": None,
        "expected_post_gust_board": _pfgear_board_fp(projected),
        "last_fingerprint": None,
        "last_roles": None,
        "last_option_multiset": None,
        "secured_attack_legal_on_miss": None,
        "abort_reason": None,
    }
    if transaction["expected_post_gust_board"] is None:
        return None
    _pfgear_transaction = transaction
    purpose = certificate["purpose"]
    _pfgear_counters[
        {
            "FINISH_NOW": "starts_finish_now",
            "AVOID_EXACT_LOSS": "starts_avoid_exact_loss",
            "PRESERVE_ATTACK_CHAIN": "starts_preserve_attack_chain",
        }[purpose]
    ] += 1
    action = _pfgear_emit_roles(obs, transaction, (certificate["gear_role"],))
    if action is None:
        _pfgear_transaction = None
        return None
    _pfgear_record_transaction(transaction)
    return action


def _pfgear_reveal_mapping(obs, transaction):
    certificate = transaction["certificate"]
    effect = obs.select.effect
    looking = tuple(obs.current.looking or ())
    if (
        obs.select.context != SelectContext.TO_HAND
        or obs.select.minCount != 0
        or obs.select.maxCount != 1
        or obs.select.contextCard is not None
        or _pcrd_get(effect, "id") != POKEGEAR
        or _pcrd_serial(effect) != certificate["gear_serial"]
        or len(looking) != certificate["gear_reveal_count"]
        or _pfgear_card_multiset(looking) is None
        or len({_pcrd_serial(card) for card in looking})
        != certificate["gear_reveal_count"]
    ):
        return None, "gear_reveal_identity_mismatch"
    option_rows = []
    seen = set()
    for position, option in enumerate(obs.select.option):
        card = option_card(obs, option)
        serial = _pcrd_serial(card)
        data = CARD_DB.get(_pcrd_get(card, "id"))
        if (
            option.type != OptionType.CARD
            or option.area != AreaType.LOOKING
            or option.playerIndex != certificate["seat"]
            or not isinstance(option.index, int)
            or option.index < 0
            or option.index >= len(looking)
            or card is not looking[option.index]
            or serial is None
            or serial in seen
            or data is None
            or _pcrd_int(_pcrd_get(data, "cardType")) != 3
        ):
            return None, "gear_reveal_transient_mapping_unknown"
        seen.add(serial)
        option_rows.append((position, card, _pcrd_option_role(obs, option)))
    return tuple(option_rows), None


def _pfgear_attack_logged(obs, transaction):
    certificate = transaction["certificate"]
    return any(
        entry.type == LogType.ATTACK
        and _pcrd_get(entry, "playerIndex") == certificate["seat"]
        and _pcrd_get(entry, "serial") == certificate["attacker_serial"]
        and _pcrd_get(entry, "attackId") == certificate["attack_id"]
        for entry in tuple(obs.logs or ())
    )


def _pfgear_resume(obs, parent_action):
    global _pfgear_transaction
    transaction = _pfgear_transaction
    if transaction is None:
        return None
    fingerprint = _pfgear_callback_fp(obs)
    if fingerprint is not None and fingerprint == transaction.get("last_fingerprint"):
        roles = transaction.get("last_roles")
        rebound = _pcrd_bind_roles(obs, roles) if roles is not None else None
        if rebound is not None:
            _pfgear_counters["duplicates"] += 1
            return rebound
        return _pfgear_abort(obs, parent_action, "duplicate_callback_binding_stale")
    if transaction.get("stage") == "ABORT_TO_PARENT":
        _pfgear_clear(transaction.get("abort_reason") or "abort_safe_boundary")
        return parent_action
    stage = transaction["stage"]
    if stage == "ATTACK_EMITTED":
        if (
            obs is not None
            and obs.current is not None
            and (
                obs.current.result != -1
                or _pfgear_attack_logged(obs, transaction)
            )
        ):
            _pfgear_counters["completes"] += 1
            _pfgear_clear("attack_confirmed_complete")
            return parent_action
        return _pfgear_abort(obs, parent_action, "attack_transition_not_confirmed")
    certificate = transaction["certificate"]
    if (
        obs is None
        or obs.current is None
        or obs.select is None
        or obs.current.yourIndex != certificate["seat"]
        or obs.current.turn != certificate["turn"]
    ):
        return _pfgear_abort(obs, parent_action, "seat_or_turn_stale")
    if obs.current.result != -1:
        return _pfgear_abort(obs, parent_action, "result_before_bound_attack")
    if _pfgear_inherited_owner_active():
        return _pfgear_abort(obs, parent_action, "inherited_owner_collision")
    if _pfgear_metadata_hashes() != certificate["metadata_hashes"]:
        return _pfgear_abort(obs, parent_action, "metadata_stale")

    gear_ref = (POKEGEAR, certificate["gear_serial"])
    base_hand = certificate["hand"]
    base_discard = certificate["discard"]
    hand_without_gear = _pfgear_replace_card(base_hand, remove=(gear_ref,))
    discard_with_gear = _pfgear_replace_card(base_discard, add=(gear_ref,))
    if hand_without_gear is None or discard_with_gear is None:
        return _pfgear_abort(obs, parent_action, "bound_gear_ledger_invalid")

    if stage == "GEAR_PLAY_EMITTED":
        if not _pfgear_expected_core(
            obs,
            transaction,
            action_count=certificate["turn_action_count"] + 1,
            deck_count=(
                certificate["deck_counts"][0]
                - certificate["gear_reveal_count"]
            ),
            hand=hand_without_gear,
            discard=base_discard,
            board=certificate["board"],
            supporter_played=False,
        ):
            return _pfgear_abort(obs, parent_action, "gear_play_transition_stale")
        options, reason = _pfgear_reveal_mapping(obs, transaction)
        if options is None:
            return _pfgear_abort(obs, parent_action, reason)
        boss_rows = tuple(
            row for row in options if _pcrd_get(row[1], "id") == BOSS
        )
        if not boss_rows:
            transaction["stage"] = "MISS_EMPTY_EMITTED"
            transaction["secured_attack_legal_on_miss"] = None
            _pfgear_counters["gear_misses"] += 1
            action = _pfgear_emit_roles(obs, transaction, ())
            if action is None:
                return _pfgear_abort(obs, parent_action, "empty_miss_selection_invalid")
            _pfgear_record_transaction(transaction)
            return action
        selected = min(boss_rows, key=lambda row: _pcrd_serial(row[1]))
        transaction["boss_serial"] = _pcrd_serial(selected[1])
        transaction["boss_fingerprint"] = _pfgear_card_ref(selected[1])
        transaction["stage"] = "GEAR_HIT_EMITTED"
        _pfgear_counters["gear_hits"] += 1
        action = _pfgear_emit_roles(obs, transaction, (selected[2],))
        if action is None:
            return _pfgear_abort(obs, parent_action, "boss_reveal_binding_invalid")
        _pfgear_record_transaction(transaction)
        return action

    if stage == "MISS_EMPTY_EMITTED":
        if (
            obs.select.context != SelectContext.MAIN
            or obs.select.effect is not None
            or obs.select.contextCard is not None
            or obs.current.looking is not None
            or not _pfgear_expected_core(
                obs,
                transaction,
                action_count=certificate["turn_action_count"] + 2,
                deck_count=certificate["deck_counts"][0],
                hand=hand_without_gear,
                discard=discard_with_gear,
                board=certificate["board"],
                supporter_played=False,
            )
        ):
            transaction["secured_attack_legal_on_miss"] = False
            return _pfgear_abort(obs, parent_action, "gear_miss_transition_stale")
        bound = _pfgear_bound_attack(obs, transaction)
        if bound is None:
            transaction["secured_attack_legal_on_miss"] = False
            return _pfgear_abort(obs, parent_action, "secured_attack_lost_on_miss")
        transaction["secured_attack_legal_on_miss"] = True
        _pfgear_counters["miss_completes"] += 1
        _pfgear_clear("gear_miss_confirmed")
        return parent_action

    if stage == "GEAR_HIT_EMITTED":
        boss_ref = (BOSS, transaction["boss_serial"])
        acquired_hand = _pfgear_replace_card(
            hand_without_gear, add=(boss_ref,)
        )
        if (
            acquired_hand is None
            or obs.select.context != SelectContext.MAIN
            or obs.select.effect is not None
            or obs.select.contextCard is not None
            or obs.current.looking is not None
            or not _pfgear_expected_core(
                obs,
                transaction,
                action_count=certificate["turn_action_count"] + 2,
                deck_count=certificate["deck_counts"][0] - 1,
                hand=acquired_hand,
                discard=discard_with_gear,
                board=certificate["board"],
                supporter_played=False,
            )
        ):
            return _pfgear_abort(obs, parent_action, "boss_acquisition_transition_stale")
        bound_attack = _pfgear_bound_attack(obs, transaction)
        target = _pfgear_find_board_pokemon(
            obs, 1 - certificate["seat"], certificate["target_serial"]
        )
        boss_positions = _pcrd_positions(
            obs,
            option_type=OptionType.PLAY,
            card_id=BOSS,
            card_serial=transaction["boss_serial"],
        )
        if (
            bound_attack is None
            or target is None
            or _pfgear_pokemon_fp(target) != certificate["target_fingerprint"]
            or len(boss_positions) != 1
        ):
            return _pfgear_abort(obs, parent_action, "boss_play_precondition_stale")
        role = _pcrd_option_role(obs, obs.select.option[boss_positions[0]])
        transaction["stage"] = "BOSS_PLAY_EMITTED"
        _pfgear_counters["boss_plays"] += 1
        action = _pfgear_emit_roles(obs, transaction, (role,))
        if action is None:
            return _pfgear_abort(obs, parent_action, "boss_play_binding_invalid")
        _pfgear_record_transaction(transaction)
        return action

    if stage == "BOSS_PLAY_EMITTED":
        boss_ref = (BOSS, transaction["boss_serial"])
        if (
            obs.select.context != SelectContext.SWITCH
            or obs.select.minCount != 1
            or obs.select.maxCount != 1
            or obs.select.contextCard is not None
            or _pcrd_get(obs.select.effect, "id") != BOSS
            or _pcrd_serial(obs.select.effect) != transaction["boss_serial"]
            or not _pfgear_expected_core(
                obs,
                transaction,
                action_count=certificate["turn_action_count"] + 3,
                deck_count=certificate["deck_counts"][0] - 1,
                hand=hand_without_gear,
                discard=discard_with_gear,
                board=certificate["board"],
                supporter_played=True,
            )
        ):
            return _pfgear_abort(obs, parent_action, "boss_target_callback_stale")
        target_positions = []
        seen = set()
        for position, option in enumerate(obs.select.option):
            card = option_card(obs, option)
            serial = _pcrd_serial(card)
            if (
                option.type != OptionType.CARD
                or option.area != AreaType.BENCH
                or option.playerIndex != 1 - certificate["seat"]
                or serial is None
                or serial in seen
            ):
                return _pfgear_abort(obs, parent_action, "boss_target_mapping_unknown")
            seen.add(serial)
            if serial == certificate["target_serial"]:
                target_positions.append(position)
        if len(target_positions) != 1:
            return _pfgear_abort(obs, parent_action, "bound_boss_target_missing_or_duplicate")
        target = option_card(obs, obs.select.option[target_positions[0]])
        if _pfgear_pokemon_fp(target) != certificate["target_fingerprint"]:
            return _pfgear_abort(obs, parent_action, "bound_boss_target_fingerprint_stale")
        role = _pcrd_option_role(obs, obs.select.option[target_positions[0]])
        transaction["stage"] = "TARGET_EMITTED"
        action = _pfgear_emit_roles(obs, transaction, (role,))
        if action is None:
            return _pfgear_abort(obs, parent_action, "boss_target_binding_invalid")
        _pfgear_record_transaction(transaction)
        return action

    if stage == "TARGET_EMITTED":
        boss_ref = (BOSS, transaction["boss_serial"])
        discard_with_boss = _pfgear_replace_card(
            discard_with_gear, add=(boss_ref,)
        )
        if (
            discard_with_boss is None
            or obs.select.context != SelectContext.MAIN
            or obs.select.effect is not None
            or obs.select.contextCard is not None
            or obs.current.looking is not None
            or not _pfgear_expected_core(
                obs,
                transaction,
                action_count=certificate["turn_action_count"] + 4,
                deck_count=certificate["deck_counts"][0] - 1,
                hand=hand_without_gear,
                discard=discard_with_boss,
                board=transaction["expected_post_gust_board"],
                supporter_played=True,
            )
        ):
            return _pfgear_abort(obs, parent_action, "gust_transition_stale")
        target = opp_active_pokemon(obs)
        original = _pfgear_find_board_pokemon(
            obs, 1 - certificate["seat"], certificate["original_active_serial"]
        )
        if (
            target is None
            or _pcrd_serial(target) != certificate["target_serial"]
            or _pfgear_pokemon_fp(target) != certificate["target_fingerprint"]
            or original is None
            or _pfgear_pokemon_fp(original)
            != certificate["original_active_fingerprint"]
        ):
            return _pfgear_abort(obs, parent_action, "gust_movement_proof_failed")
        bound = _pfgear_bound_attack(obs, transaction)
        if (
            bound is None
            or _pfgear_freeze(bound["certificate"])
            != _pfgear_freeze(certificate["post_gust_attack_certificate"])
        ):
            return _pfgear_abort(obs, parent_action, "post_gust_attack_certificate_stale")
        transaction["stage"] = "ATTACK_EMITTED"
        _pfgear_counters["target_confirmations"] += 1
        _pfgear_counters["attacks"] += 1
        action = _pfgear_emit_roles(obs, transaction, (bound["role"],))
        if action is None:
            return _pfgear_abort(obs, parent_action, "bound_attack_binding_invalid")
        _pfgear_record_transaction(transaction)
        return action

    return _pfgear_abort(obs, parent_action, "unknown_child_stage")


def _pfgear_parent_gear(obs, parent_action):
    if (
        obs is None
        or obs.select is None
        or not _cum_valid_action(obs, parent_action)
        or len(parent_action) != 1
    ):
        return None
    position = parent_action[0]
    option = obs.select.option[position]
    card = option_card(obs, option)
    if option.type != OptionType.PLAY or _pcrd_get(card, "id") != POKEGEAR:
        return None
    serial = _pcrd_serial(card)
    role = _pcrd_option_role(obs, option)
    if serial is None:
        return {"serial": None, "role": role, "unique": False}
    matches = tuple(
        index
        for index, candidate in enumerate(obs.select.option)
        if _pcrd_option_role(obs, candidate) == role
    )
    return {"serial": serial, "role": role, "unique": len(matches) == 1}


def _pfgear_bind_collapsed_role(obs, role):
    matches = tuple(
        position
        for position, option in enumerate(obs.select.option)
        if _pcrd_option_role(obs, option) == tuple(role)
    )
    if not matches:
        return None
    action = [min(matches)]
    return action if _cum_valid_action(obs, action) else None


def _pfgear_unfinished_turn_opportunity(obs, gear_serial):
    for option in obs.select.option:
        if option.type in (OptionType.ATTACK, OptionType.END):
            continue
        card = option_card(obs, option)
        if (
            option.type == OptionType.PLAY
            and _pcrd_get(card, "id") == POKEGEAR
        ):
            continue
        return True
    return False


def _pfgear_route_signature(route):
    certificate = route["certificate"]
    return (
        route.get("tier"),
        route.get("source_id"),
        route.get("source_serial"),
        route.get("attack_id"),
        route.get("target_id"),
        route.get("target_serial"),
        bool(route.get("terminal")),
        certificate.get("final_damage"),
        bool(certificate.get("ko")),
        certificate.get("prize_yield"),
        _pfgear_freeze(certificate.get("persistent_effects", {})),
    )


def _pfgear_veto_successor(obs, attack_row):
    certificate = attack_row["certificate"]
    target = opp_active_pokemon(obs)
    source = active_pokemon(obs)
    if certificate["ko"] or target is None or source is None:
        return None
    projected_target = _pcrd_project_pokemon(
        target, hp=certificate["remaining_hp"]
    )
    if projected_target is None:
        return None
    backup = _pfgear_ready_bench_set(obs, projected_target)
    if backup is None:
        return None
    source_before = _dper_energy_rows(source)
    if source_before is None:
        return None
    resource_ledger = certificate.get("post_attack_resource_ledger")
    if resource_ledger is None:
        # Combat-irrelevant printed attacks are delegated to the exact legacy
        # oracle.  Only these audited no-resource-cost attacks may inherit an
        # unchanged attachment ledger in the veto certificate.
        if attack_row["attack_id"] not in {223, 224, 253, 1212}:
            return None
        source_after = tuple(source_before)
    else:
        source_after = resource_ledger.get("source_energy")
        if source_after is None:
            return None
    next_ids = certificate.get("next_payable_attack_ids")
    if next_ids is None:
        next_access = _dper_memory_dive_access(
            source,
            {
                **_pfgear_attack_effect_state(obs, source, projected_target),
                "require_payable": True,
            },
        )
        if next_access.get("status") != "EXACT":
            return None
        next_ids = tuple(
            row[0] for row in next_access["after"].get("attack_rows", ())
        )
    next_current = frozenset(
        (
            certificate["source_serial"],
            attack_id,
        )
        for attack_id in tuple(next_ids)
    )
    ready = frozenset(set(next_current) | set(backup))
    other_energy = []
    for pokemon in _pcrd_board_pokemon(my_state(obs)):
        if _pcrd_serial(pokemon) == _pcrd_serial(source):
            continue
        rows = _dper_energy_rows(pokemon)
        if rows is None:
            return None
        other_energy.extend(
            (_pcrd_serial(pokemon), row[0], row[1], row[2]) for row in rows
        )
    retained_energy = frozenset(
        tuple(other_energy)
        + tuple(
            (
                _pcrd_serial(source),
                row[0],
                row[1],
                row[2],
            )
            for row in source_after
        )
    )
    before_serials = {row[2] for row in source_before}
    after_serials = {row[2] for row in source_after}
    discarded_energy = frozenset(before_serials - after_serials)
    routes = _pfgear_exact_routes(attack_row["threat_graph"])
    terminal_replies = frozenset(
        _pfgear_route_signature(route) for route in routes if route["terminal"]
    )
    reply_attack_locks = frozenset(
        (
            route.get("source_serial"),
            route.get("attack_id"),
            route["certificate"].get("persistent_effects", {}).get(
                "same_attack_lock_next_turn"
            ),
        )
        for route in routes
        if route["certificate"].get("persistent_effects", {}).get(
            "same_attack_lock_next_turn"
        ) is not None
    )
    self_lock = frozenset(
        value
        for value in (
            certificate.get("persistent_effects", {}).get(
                "same_attack_lock_next_turn"
            ),
        )
        if value is not None
    )
    resources = _pcrd_resources(obs)
    hand = _pcrd_hand(obs)
    if resources is None or hand is None:
        return None
    special_consequence = (
        certificate.get("saved_callback_transaction"),
        tuple(certificate.get("exact_public_reply_routes", ())),
        tuple(
            certificate.get("post_attack_resource_ledger", {}).get(
                "visible_acceleration", ()
            )
        ),
    )
    if any(special_consequence):
        return None
    return {
        "attack_id": attack_row["attack_id"],
        "role": attack_row["role"],
        "payment": attack_row["payment"],
        "certificate": copy.deepcopy(certificate),
        "immediate_prize_yield": certificate["prize_yield"],
        "ready_attackers": ready,
        "retained_energy": retained_energy,
        "hand": _pfgear_card_multiset(hand),
        "deck_count": my_state(obs).deckCount,
        "recovery": resources["recovery"],
        "attachment_capacity": not obs.current.energyAttached,
        "terminal_replies": terminal_replies,
        "reply_attack_locks": reply_attack_locks,
        "continuity": ready,
        "post_damage_counter_return": certificate.get(
            "post_damage_counter_return", 0
        ),
        "self_lock": self_lock,
        "discarded_energy": discarded_energy,
        "special_consequence": special_consequence,
    }


def _pfgear_componentwise_nonworse(candidate, other):
    exact_equal = (
        candidate["hand"] == other["hand"]
        and candidate["deck_count"] == other["deck_count"]
        and candidate["recovery"] == other["recovery"]
        and candidate["attachment_capacity"] == other["attachment_capacity"]
        and candidate["special_consequence"] == other["special_consequence"]
    )
    nonworse = bool(
        candidate["immediate_prize_yield"]
        >= other["immediate_prize_yield"]
        and candidate["ready_attackers"].issuperset(other["ready_attackers"])
        and candidate["retained_energy"].issuperset(other["retained_energy"])
        and exact_equal
        and candidate["terminal_replies"].issubset(other["terminal_replies"])
        and candidate["reply_attack_locks"].issubset(other["reply_attack_locks"])
        and candidate["continuity"].issuperset(other["continuity"])
        and isinstance(candidate["post_damage_counter_return"], int)
        and isinstance(other["post_damage_counter_return"], int)
        and candidate["post_damage_counter_return"]
        <= other["post_damage_counter_return"]
        and candidate["self_lock"].issubset(other["self_lock"])
        and candidate["discarded_energy"].issubset(other["discarded_energy"])
    )
    if not nonworse:
        return False, False
    strict = bool(
        candidate["immediate_prize_yield"]
        > other["immediate_prize_yield"]
        or candidate["ready_attackers"] > other["ready_attackers"]
        or candidate["retained_energy"] > other["retained_energy"]
        or candidate["terminal_replies"] < other["terminal_replies"]
        or candidate["reply_attack_locks"] < other["reply_attack_locks"]
        or candidate["continuity"] > other["continuity"]
        or candidate["post_damage_counter_return"]
        < other["post_damage_counter_return"]
        or candidate["self_lock"] < other["self_lock"]
        or candidate["discarded_energy"] < other["discarded_energy"]
    )
    return True, strict


def _pfgear_veto_certificate(obs, parent_gear, purpose_rejection_reason):
    if (
        not _pfgear_boundary(obs)
        or not _pfgear_metadata_exact()
        or not parent_gear.get("unique")
        or parent_gear.get("serial") is None
        or purpose_rejection_reason is None
    ):
        return None, "veto_boundary_or_parent_gear_unknown"
    if _pfgear_adrena_present(obs):
        _pfgear_counters["adrena_quarantines"] += 1
        return None, "veto_public_adrena_quarantine"
    if (
        _pcrd_hand(obs) is None
        or _pcrd_status_tuple(my_state(obs)) != (False,) * 5
        or _pcrd_status_tuple(opp_state(obs)) != (False,) * 5
        or _pfgear_public_state_fp(obs) is None
    ):
        return None, "veto_public_state_unknown"
    attack_rows, reason = _pfgear_current_attack_rows(
        obs, allow_duplicate_ui=True
    )
    if attack_rows is None:
        return None, reason or "veto_attack_enumeration_unknown"
    if not attack_rows:
        return None, "veto_no_payable_attack"
    remaining = len(tuple(my_state(obs).prize or ()))
    direct = tuple(
        row
        for row in attack_rows
        if row["certificate"]["ko"]
        and row["certificate"]["prize_yield"] >= remaining
    )
    if len(direct) == 1:
        chosen = direct[0]
        certificate = {
            "kind": "DIRECT_FINISH",
            "seat": obs.current.yourIndex,
            "turn": obs.current.turn,
            "attacker_id": _pcrd_get(active_pokemon(obs), "id"),
            "attacker_serial": _pcrd_serial(active_pokemon(obs)),
            "attacker_fingerprint": _pfgear_pokemon_fp(active_pokemon(obs)),
            "attack_id": chosen["attack_id"],
            "attack_role": chosen["role"],
            "attack_payment": chosen["payment"],
            "gear_serial": parent_gear["serial"],
            "option_multiset": _pfgear_option_multiset(obs),
            "public_state_fingerprint": _pfgear_public_state_fp(obs),
            "purpose_rejection_reason": purpose_rejection_reason,
            "dominance_certificate": copy.deepcopy(chosen["certificate"]),
        }
        certificate["certificate_hash"] = _pfgear_hash(certificate)
        return certificate, None
    if len(direct) > 1:
        return None, "veto_multiple_direct_finish_attacks"
    if _pfgear_unfinished_turn_opportunity(obs, parent_gear["serial"]):
        return None, "veto_unfinished_turn_purpose"
    successors = []
    for attack_row in attack_rows:
        successor = _pfgear_veto_successor(obs, attack_row)
        if successor is None:
            return None, "veto_successor_unknown_or_unsupported"
        successors.append(successor)
    chosen = []
    for candidate in successors:
        comparisons = [
            _pfgear_componentwise_nonworse(candidate, other)
            for other in successors
            if other is not candidate
        ]
        if all(row[0] for row in comparisons) and (
            len(successors) == 1 or any(row[1] for row in comparisons)
        ):
            chosen.append(candidate)
    if len(chosen) != 1:
        return None, "veto_incomparable_attacks"
    winner = chosen[0]
    certificate = {
        "kind": "SECURED_NONWORSE_ATTACK",
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "attacker_id": _pcrd_get(active_pokemon(obs), "id"),
        "attacker_serial": _pcrd_serial(active_pokemon(obs)),
        "attacker_fingerprint": _pfgear_pokemon_fp(active_pokemon(obs)),
        "attack_id": winner["attack_id"],
        "attack_role": winner["role"],
        "attack_payment": winner["payment"],
        "gear_serial": parent_gear["serial"],
        "option_multiset": _pfgear_option_multiset(obs),
        "public_state_fingerprint": _pfgear_public_state_fp(obs),
        "purpose_rejection_reason": purpose_rejection_reason,
        "dominance_certificate": copy.deepcopy(winner),
        "all_successors": copy.deepcopy(tuple(successors)),
    }
    certificate["certificate_hash"] = _pfgear_hash(certificate)
    return certificate, None


def _pfgear_record_veto(certificate, reason=None):
    _pfgear_last_fields.update(
        {
            "stage": "PARENT_GEAR_VETO",
            "rejection_reason": reason,
            "bound_gear_serial": certificate.get("gear_serial"),
            "bound_boss_serial": None,
            "bound_target_serial": None,
            "bound_attacker_serial": certificate.get("attacker_serial"),
            "bound_attack_id": certificate.get("attack_id"),
            "secured_attack_legal_on_miss": None,
            "purpose": certificate.get("kind"),
            "certificate": copy.deepcopy(certificate),
        }
    )


def _pfgear_classify_veto_passthrough(reason):
    if "no_payable" in reason:
        _pfgear_counters["gear_veto_no_payable_attack"] += 1
    elif "incomparable" in reason or "multiple_direct" in reason:
        _pfgear_counters["gear_veto_incomparable_attacks"] += 1
    elif "unfinished" in reason:
        _pfgear_counters["gear_veto_unfinished_turn_purpose"] += 1
    else:
        _pfgear_counters["gear_veto_unknown_or_unsupported"] += 1
    _pfgear_counters["blind_parent_gear_passthrough"] += 1
    _pfgear_last_fields["rejection_reason"] = reason


def _pfgear_emit_veto(obs, certificate):
    global _pfgear_veto_watch
    action = _pfgear_bind_collapsed_role(obs, certificate["attack_role"])
    if action is None:
        return None
    _pfgear_veto_watch = {
        "fingerprint": _pfgear_callback_fp(obs),
        "role": certificate["attack_role"],
        "certificate": copy.deepcopy(certificate),
    }
    _pfgear_record_veto(certificate)
    return action


def _pfgear_resume_veto_watch(obs):
    global _pfgear_veto_watch
    watch = _pfgear_veto_watch
    if watch is None:
        return None
    fingerprint = _pfgear_callback_fp(obs)
    if fingerprint == watch["fingerprint"]:
        action = _pfgear_bind_collapsed_role(obs, watch["role"])
        if action is not None:
            _pfgear_counters["duplicates"] += 1
            return action
        _pfgear_counters["gear_veto_stale"] += 1
        _pfgear_veto_watch = None
        return None
    if (
        obs is not None
        and obs.current is not None
        and (
            obs.current.result != -1
            or any(
                entry.type == LogType.ATTACK
                and _pcrd_get(entry, "playerIndex")
                == watch["certificate"]["seat"]
                and _pcrd_get(entry, "serial")
                == watch["certificate"]["attacker_serial"]
                and _pcrd_get(entry, "attackId")
                == watch["certificate"]["attack_id"]
                for entry in tuple(obs.logs or ())
            )
        )
    ):
        _pfgear_counters["veto_confirmed"] += 1
    _pfgear_veto_watch = None
    return None


def _pfgear_reset_active(reason):
    global _pfgear_transaction, _pfgear_veto_watch
    if _pfgear_transaction is not None:
        if _pfgear_transaction.get("stage") != "ABORT_TO_PARENT":
            _pfgear_counters["aborts_to_parent"] += 1
            _pfgear_counters["stale_transitions"] += 1
        _pfgear_record_transaction(_pfgear_transaction, reason)
    _pfgear_transaction = None
    _pfgear_veto_watch = None


def _pfgear_conservation():
    starts = sum(
        _pfgear_counters[key]
        for key in (
            "starts_finish_now",
            "starts_avoid_exact_loss",
            "starts_preserve_attack_chain",
        )
    )
    live = int(
        _pfgear_transaction is not None
        and _pfgear_transaction.get("stage") != "ABORT_TO_PARENT"
    )
    positive = {
        "starts": starts,
        "settled": (
            _pfgear_counters["completes"]
            + _pfgear_counters["miss_completes"]
            + _pfgear_counters["aborts_to_parent"]
            + live
        ),
        "live_transactions": live,
    }
    veto = {
        "parent_gear_selected": _pfgear_counters["parent_gear_selected"],
        "classified": (
            _pfgear_counters["positive_gear_purpose_found"]
            + _pfgear_counters["gear_veto_direct_finish"]
            + _pfgear_counters["gear_veto_secured_nonworse_attack"]
            + _pfgear_counters["blind_parent_gear_passthrough"]
        ),
    }
    positive["holds"] = positive["starts"] == positive["settled"]
    veto["holds"] = veto["parent_gear_selected"] == veto["classified"]
    return {"positive": positive, "parent_gear": veto}


def agent(obs_dict):
    """Call the repaired registry parent once, then apply PF_GEAR_BOSS_TX_V1."""
    global _pfgear_last_telemetry
    parent_action = _pfgear_parent_agent(obs_dict)
    _pfgear_counters["direct_parent_calls"] += 1
    obs = None
    selected_action = parent_action
    selected_source = "DIRECT_PARENT"
    rejection_reason = None
    try:
        obs = to_observation_class(obs_dict)
        if obs.select is None or obs.current is None:
            _pfgear_reset_active("deck_request_or_malformed_observation")
            rejection_reason = "deck_request_or_malformed_observation"
        elif not _cum_valid_action(obs, parent_action):
            _pfgear_counters["invalid_actions"] += 1
            rejection_reason = "invalid_direct_parent_action"
            if _pfgear_transaction is not None:
                selected_action = _pfgear_abort(
                    obs, parent_action, rejection_reason
                )
        else:
            watched = _pfgear_resume_veto_watch(obs)
            if watched is not None:
                selected_action = watched
                selected_source = "REPEATED_GEAR_VETO"
            elif _pfgear_transaction is not None:
                resumed = _pfgear_resume(obs, parent_action)
                selected_action = parent_action if resumed is None else resumed
                selected_source = (
                    "DIRECT_PARENT"
                    if selected_action == parent_action
                    else "POSITIVE_GEAR_TRANSACTION"
                )
            elif obs.current.result != -1:
                rejection_reason = "completed_game"
            elif not _pfgear_boundary(obs):
                rejection_reason = "not_live_transaction_free_main"
            else:
                positive, rejection_reason = _pfgear_positive_certificate(obs)
                parent_gear = _pfgear_parent_gear(obs, parent_action)
                if positive is not None:
                    action = _pfgear_begin(obs, positive)
                    if action is not None:
                        selected_action = action
                        selected_source = "POSITIVE_GEAR_TRANSACTION"
                        if parent_gear is not None:
                            _pfgear_counters["parent_gear_selected"] += 1
                            _pfgear_counters[
                                "positive_gear_purpose_found"
                            ] += 1
                    else:
                        rejection_reason = "positive_transaction_binding_failed"
                elif parent_gear is not None:
                    _pfgear_counters["parent_gear_selected"] += 1
                    _pfgear_counters["parent_gear_without_purpose"] += 1
                    veto, veto_reason = _pfgear_veto_certificate(
                        obs, parent_gear, rejection_reason
                    )
                    if veto is None:
                        _pfgear_classify_veto_passthrough(veto_reason)
                        rejection_reason = veto_reason
                    else:
                        revalidated, stale_reason = _pfgear_veto_certificate(
                            obs, parent_gear, rejection_reason
                        )
                        if (
                            revalidated is None
                            or _pfgear_freeze(revalidated)
                            != _pfgear_freeze(veto)
                        ):
                            _pfgear_counters["gear_veto_stale"] += 1
                            _pfgear_counters[
                                "blind_parent_gear_passthrough"
                            ] += 1
                            rejection_reason = (
                                stale_reason or "veto_revalidation_stale"
                            )
                        else:
                            action = _pfgear_emit_veto(obs, veto)
                            if action is None:
                                _pfgear_counters["gear_veto_stale"] += 1
                                _pfgear_counters[
                                    "blind_parent_gear_passthrough"
                                ] += 1
                                rejection_reason = "veto_emission_stale"
                            else:
                                selected_action = action
                                selected_source = veto["kind"]
                                _pfgear_counters[
                                    (
                                        "gear_veto_direct_finish"
                                        if veto["kind"] == "DIRECT_FINISH"
                                        else "gear_veto_secured_nonworse_attack"
                                    )
                                ] += 1
                elif rejection_reason and any(
                    token in rejection_reason
                    for token in ("unknown", "unsupported", "registry")
                ):
                    _pfgear_counters[
                        "unknown_registry_effect_rejections"
                    ] += 1
    except Exception as error:
        _pfgear_counters["exceptions"] += 1
        rejection_reason = type(error).__name__ + ":" + str(error)
        selected_action = parent_action
        selected_source = "DIRECT_PARENT_EXCEPTION_FALLBACK"
        if _pfgear_transaction is not None:
            _pfgear_reset_active("child_exception_abort")
    if (
        obs is not None
        and obs.select is not None
        and not _cum_valid_action(obs, selected_action)
    ):
        _pfgear_counters["invalid_actions"] += 1
        selected_action = parent_action
        selected_source = "DIRECT_PARENT_INVALID_OVERRIDE_FALLBACK"
    _pfgear_last_telemetry = {
        "rule_id": _PFGEAR_RULE_ID,
        "selected_source": selected_source,
        "rejection_reason": rejection_reason,
        "counters": dict(_pfgear_counters),
        "conservation": _pfgear_conservation(),
        "last_certificate_fields": copy.deepcopy(_pfgear_last_fields),
        "transaction_stage": (
            None
            if _pfgear_transaction is None
            else _pfgear_transaction.get("stage")
        ),
        "veto_watch_live": _pfgear_veto_watch is not None,
    }
    return selected_action


# EXPLORER_CERTIFIED_ATTACK_DEADLINE_PRODUCTIVE_PREFIX_V1
#
# Append-only policy layer.  Everything above this marker is the exact direct
# behavioral parent.  This layer never chooses an Explorer reveal or an
# Explorer-created resource route.  Once Explorer has resolved, it may retain
# one exact, already-payable attack as a same-turn deadline while admitting a
# bounded sequence of independently certified productive parent actions.
# ---------------------------------------------------------------------------

_eadp_parent_agent = agent

