def _eadp_freeze(value):
    if isinstance(value, dict):
        return tuple(
            sorted(
                ((key, _eadp_freeze(item)) for key, item in value.items()),
                key=repr,
            )
        )
    if isinstance(value, (list, tuple, set)):
        rows = tuple(_eadp_freeze(item) for item in value)
        return tuple(sorted(rows, key=repr)) if isinstance(value, set) else rows
    return value


def _eadp_owner_snapshot():
    return {
        "carriers": {
            name: copy.deepcopy(globals().get(name))
            for name in _EADP_ALL_CARRIERS
        },
        "cum_owner": copy.deepcopy(
            globals().get("_cum_active_transaction_owner")
        ),
        "cum_meta": copy.deepcopy(globals().get("_cum_owner_meta")),
    }


def _eadp_owner_records(snapshot):
    rows = []
    owner = snapshot.get("cum_owner")
    meta = snapshot.get("cum_meta") or {}
    if owner is not None:
        rows.append(("CUM", owner, meta.get("transaction_id")))
    for name in _EADP_OUTER_CARRIERS:
        value = snapshot.get("carriers", {}).get(name)
        if value is not None:
            identity = None
            if isinstance(value, dict):
                identity = (
                    value.get("transaction_id"),
                    value.get("seat"),
                    value.get("turn"),
                    value.get("stage"),
                    value.get("explorer_serial"),
                )
            rows.append((name, _pfgear_hash(identity or _eadp_freeze(value))))
    return tuple(rows)


def _eadp_restore_overridden_owners(before, after):
    """Restore the exact pre-call owner state for an unexecuted action."""
    del after
    globals()["_cum_active_transaction_owner"] = copy.deepcopy(
        before.get("cum_owner")
    )
    globals()["_cum_owner_meta"] = copy.deepcopy(before.get("cum_meta"))
    for name in _EADP_ALL_CARRIERS:
        globals()[name] = copy.deepcopy(
            before.get("carriers", {}).get(name)
        )


def _eadp_deadline_public(deadline):
    if deadline is None:
        return None
    certificate = deadline.get("attack") or {}
    productive = deadline.get("productive") or {}
    return {
        "state": deadline.get("state"),
        "epoch": deadline.get("epoch"),
        "seat": deadline.get("seat"),
        "turn": deadline.get("turn"),
        "attacker_serial": certificate.get("attacker_serial"),
        "target_serial": certificate.get("target_serial"),
        "attack_id": certificate.get("attack_id"),
        "terminal": certificate.get("terminal"),
        "prefix_count": len(deadline.get("fingerprints", ())),
        "productive_kind": productive.get("kind"),
        "suspended_owner": copy.deepcopy(deadline.get("suspended_owner")),
    }


def _eadp_conservation():
    live_deadlines = int(_eadp_deadline is not None)
    live_parent_subtx = int(
        _eadp_deadline is not None
        and _eadp_deadline.get("state") == "PARENT_SUBTX_ACTIVE"
    )
    deadline = {
        "locks": _eadp_counters["deadline_locks"],
        "settled": (
            _eadp_counters["attacks_confirmed"]
            + live_deadlines
            + _eadp_counters["actual_state_fallbacks"]
            + _eadp_counters["deadline_releases"]
        ),
        "attacks_confirmed": _eadp_counters["attacks_confirmed"],
        "live_deadlines": live_deadlines,
        "actual_state_fallbacks": _eadp_counters[
            "actual_state_fallbacks"
        ],
        "deadline_releases": _eadp_counters["deadline_releases"],
    }
    subtx = {
        "starts": _eadp_counters["parent_subtx_starts"],
        "settled": (
            _eadp_counters["parent_subtx_completes"]
            + live_parent_subtx
            + _eadp_counters["parent_subtx_failures"]
            + _eadp_counters["parent_subtx_releases"]
        ),
        "completes": _eadp_counters["parent_subtx_completes"],
        "live_parent_subtx": live_parent_subtx,
        "failures": _eadp_counters["parent_subtx_failures"],
        "releases": _eadp_counters["parent_subtx_releases"],
    }
    deadline["holds"] = deadline["locks"] == deadline["settled"]
    subtx["holds"] = subtx["starts"] == subtx["settled"]
    return {"deadline": deadline, "parent_subtx": subtx}


def _eadp_update_telemetry(source, reason=None):
    global _eadp_last_telemetry
    _eadp_last_telemetry = {
        "rule_id": _EADP_RULE_ID,
        "contract_sha256": _EADP_CONTRACT_SHA256,
        "amendment_sha256": _EADP_AMENDMENT_SHA256,
        "release_amendment_sha256": _EADP_RELEASE_AMENDMENT_SHA256,
        "direct_parent_sha256": _EADP_DIRECT_PARENT_SHA256,
        "selected_source": source,
        "rejection_reason": reason,
        "counters": dict(_eadp_counters),
        "conservation": _eadp_conservation(),
        "deadline": _eadp_deadline_public(_eadp_deadline),
        "last_finalized": copy.deepcopy(_eadp_last_finalized),
        "parent_call_count": _eadp_parent_call_count,
    }


def _eadp_finalize(
    reason, *, confirmed=False, actual_fallback=False, released=False
):
    global _eadp_deadline, _eadp_last_finalized
    deadline = _eadp_deadline
    if deadline is None:
        return
    if deadline.get("state") == "PARENT_SUBTX_ACTIVE" and not confirmed:
        if released:
            _eadp_counters["parent_subtx_releases"] += 1
        else:
            _eadp_counters["parent_subtx_failures"] += 1
    if confirmed:
        _eadp_counters["attacks_confirmed"] += 1
    elif actual_fallback:
        _eadp_counters["actual_state_fallbacks"] += 1
    _eadp_last_finalized = {
        **(_eadp_deadline_public(deadline) or {}),
        "reason": reason,
        "confirmed": bool(confirmed),
        "actual_state_fallback": bool(actual_fallback),
        "released": bool(released),
    }
    _eadp_finalized.append(copy.deepcopy(_eadp_last_finalized))
    _eadp_deadline = None


def _eadp_observe_explorer_resolution(obs):
    if obs is None or obs.current is None:
        return
    epoch = globals().get("_cum_game_epoch")
    seat = obs.current.yourIndex
    for entry in tuple(obs.logs or ()):
        if (
            entry.type == LogType.PLAY
            and _pcrd_get(entry, "cardId") == EXPLORER
            and _pcrd_get(entry, "playerIndex") == seat
            and _pcrd_serial(entry) is not None
        ):
            serial_key = (epoch, seat, _pcrd_serial(entry))
            if serial_key not in _eadp_seen_explorer_logs:
                _eadp_seen_explorer_logs.add(serial_key)
                _eadp_seen_explorer_logs.add(
                    (epoch, seat, obs.current.turn, _pcrd_serial(entry))
                )
                _eadp_counters["explorer_resolutions_observed"] += 1


def _eadp_explorer_resolved_this_turn(obs):
    epoch = globals().get("_cum_game_epoch")
    return bool(
        obs.current.supporterPlayed
        and any(
            isinstance(key, tuple)
            and len(key) == 4
            and key[0] == epoch
            and key[1] == obs.current.yourIndex
            and key[2] == obs.current.turn
            for key in _eadp_seen_explorer_logs
        )
    )


def _eadp_attack_rows(obs):
    active = active_pokemon(obs)
    target = opp_active_pokemon(obs)
    if active is None or target is None:
        return ()
    rows = []
    for position, option in enumerate(obs.select.option):
        if option.type != OptionType.ATTACK:
            continue
        attack_id = _pcrd_int(_pcrd_get(option, "attackId"))
        payment = _pcrd_attack_payment(active, ALL_ATTACKS.get(attack_id))
        combat = _pfgear_attack_certificate(obs, active, attack_id, target)
        role = _pcrd_option_role(obs, option)
        if attack_id is None or payment is None or combat is None:
            return ()
        rows.append(
            {
                "position": position,
                "role": role,
                "attacker_id": _pcrd_get(active, "id"),
                "attacker_serial": _pcrd_serial(active),
                "target_id": _pcrd_get(target, "id"),
                "target_serial": _pcrd_serial(target),
                "attack_id": attack_id,
                "payment": tuple(payment),
                "combat": copy.deepcopy(combat),
            }
        )
    return tuple(rows)


def _eadp_exact_attack(obs):
    if (
        obs.select.context != SelectContext.MAIN
        or obs.select.minCount != 1
        or obs.select.maxCount != 1
        or obs.select.effect is not None
        or obs.select.contextCard is not None
    ):
        return None
    rows = _eadp_attack_rows(obs)
    if len(rows) != 1:
        return None
    row = rows[0]
    combat = row["combat"]
    if (
        combat.get("status") != "EXACT"
        or not isinstance(combat.get("final_damage"), int)
        or combat["final_damage"] <= 0
        or not isinstance(combat.get("prize_yield"), int)
        or combat["prize_yield"] <= 0
        or not combat.get("persistent_progress", True)
        or tuple(combat.get("unsupported_text", ()))
    ):
        return None
    remaining = len(tuple(my_state(obs).prize or ()))
    if remaining <= 0:
        return None
    row["remaining_prizes"] = remaining
    row["terminal"] = bool(
        combat.get("prize_yield", 0) >= remaining
        or (
            combat.get("ko")
            and not tuple(
                card
                for card in tuple(opp_state(obs).bench or ())
                if card is not None
            )
        )
    )
    return row


def _eadp_attack_nonworse(saved, current):
    old = saved.get("combat") or {}
    new = current.get("combat") or {}
    if (
        current.get("attacker_serial") != saved.get("attacker_serial")
        or current.get("target_serial") != saved.get("target_serial")
        or current.get("attack_id") != saved.get("attack_id")
        or tuple(current.get("payment", ())) != tuple(saved.get("payment", ()))
        or new.get("status") != "EXACT"
        or tuple(new.get("unsupported_text", ()))
        or new.get("source_id") != old.get("source_id")
        or new.get("target_id") != old.get("target_id")
        or new.get("attack_mode") != old.get("attack_mode")
        or new.get("persistent_effects") != old.get("persistent_effects")
        or not isinstance(new.get("final_damage"), int)
        or new["final_damage"] < old.get("final_damage", 0)
        or not isinstance(new.get("prize_yield"), int)
        or new["prize_yield"] < old.get("prize_yield", 0)
        or (bool(old.get("ko")) and not bool(new.get("ko")))
        or (
            bool(old.get("persistent_progress", True))
            and not bool(new.get("persistent_progress", True))
        )
    ):
        return False
    return True


def _eadp_reprove_attack(obs):
    deadline = _eadp_deadline
    saved = (deadline or {}).get("attack") or {}
    matches = tuple(
        row
        for row in _eadp_attack_rows(obs)
        if row.get("role") == saved.get("role")
        and row.get("attacker_serial") == saved.get("attacker_serial")
        and row.get("target_serial") == saved.get("target_serial")
        and row.get("attack_id") == saved.get("attack_id")
    )
    current = matches[0] if len(matches) == 1 else None
    if (
        deadline is None
        or current is None
        or len(tuple(my_state(obs).prize or ()))
        != deadline["attack"]["remaining_prizes"]
        or not _eadp_attack_nonworse(deadline["attack"], current)
    ):
        _eadp_counters["attack_reproof_fail"] += 1
        return None
    current["remaining_prizes"] = len(tuple(my_state(obs).prize or ()))
    current["terminal"] = bool(
        current["combat"].get("prize_yield", 0)
        >= current["remaining_prizes"]
        or (
            current["combat"].get("ko")
            and not tuple(
                card
                for card in tuple(opp_state(obs).bench or ())
                if card is not None
            )
        )
    )
    _eadp_counters["attack_reproof_pass"] += 1
    return current


def _eadp_attack_logged(obs, deadline):
    saved = (deadline or {}).get("attack") or {}
    return any(
        entry.type == LogType.ATTACK
        and _pcrd_get(entry, "playerIndex") == deadline.get("seat")
        and _pcrd_serial(entry) == saved.get("attacker_serial")
        and _pcrd_get(entry, "attackId") == saved.get("attack_id")
        for entry in tuple(obs.logs or ())
    )


