def _eadp_card_absent_from_hand(obs, serial):
    return not any(
        _pcrd_serial(card) == serial
        for card in tuple(my_state(obs).hand or ())
        if card is not None
    )


def _eadp_find_own_pokemon(obs, serial):
    rows = [
        pokemon
        for pokemon in _pcrd_board_pokemon(my_state(obs))
        if _pcrd_serial(pokemon) == serial
    ]
    return rows[0] if len(rows) == 1 else None


def _eadp_attachment_owner(obs, serial, *, tool=False):
    rows = []
    for pokemon in _pcrd_board_pokemon(my_state(obs)):
        cards = (
            tuple(_pcrd_get(pokemon, "tools", ()) or ())
            if tool
            else tuple(
                _pcrd_get(pokemon, "energyCards", None)
                or _pcrd_get(pokemon, "energy_cards", ())
                or ()
            )
        )
        if any(_pcrd_serial(card) == serial for card in cards):
            rows.append(_pcrd_serial(pokemon))
    return rows[0] if len(rows) == 1 else None


def _eadp_exact_trainer(card_id):
    expected = _EADP_SEARCH_TRAINERS.get(card_id)
    return bool(
        expected is not None
        and _pcrd_exact_trainer(card_id, expected[0], expected[1])
    )


def _eadp_missing_profile(pokemon):
    data = CARD_DB.get(_pcrd_get(pokemon, "id"))
    rows = []
    for attack_id in tuple(_pcrd_get(data, "attacks", ()) or ()):
        missing = _pcrd_missing_energy_count(
            pokemon, ALL_ATTACKS.get(attack_id)
        )
        if isinstance(missing, int):
            rows.append((attack_id, missing))
    return tuple(rows)


def _eadp_basic_safe(card):
    data = CARD_DB.get(_pcrd_get(card, "id"))
    skills = tuple(_pcrd_get(data, "skills", ()) or ())
    return bool(
        data is not None
        and bool(_pcrd_get(data, "basic", False))
        and all(
            "when you play" not in _pcrd_norm(_pcrd_get(skill, "text"))
            for skill in skills
        )
    )


def _eadp_basic_productive(obs, card):
    if not _eadp_basic_safe(card):
        return False
    card_id = _pcrd_get(card, "id")
    if card_id == DURALUDON:
        mine = my_state(obs)
        return len(tuple(mine.bench or ())) < mine.benchMax
    evolutions = tuple(
        candidate
        for candidate in tuple(my_state(obs).hand or ())
        if candidate is not None
        and _pcrd_get(CARD_DB.get(_pcrd_get(candidate, "id")), "evolvesFrom")
        == _pcrd_get(CARD_DB.get(card_id), "name")
    )
    if evolutions:
        return True
    projected = _pcrd_project_pokemon(
        {
            "id": card_id,
            "serial": _pcrd_serial(card),
            "hp": _pcrd_get(CARD_DB.get(card_id), "hp"),
            "maxHp": _pcrd_get(CARD_DB.get(card_id), "hp"),
            "appearThisTurn": True,
            "energies": (),
            "energy_cards": (),
            "tools": (),
            "preEvolution": (),
        }
    )
    metal = next(
        (
            energy
            for energy in tuple(my_state(obs).hand or ())
            if energy is not None and _pcrd_get(energy, "id") == METAL_ENERGY
        ),
        None,
    )
    after = None if metal is None else _pcrd_add_energy_projection(projected, metal)
    return bool(
        projected is not None
        and after is not None
        and any(missing == 0 for _, missing in _eadp_missing_profile(after))
    )


def _eadp_metal_recovery_route(obs, metal_serial):
    eligible_duraludon = any(
        _pcrd_get(pokemon, "id") == DURALUDON
        and not bool(_pcrd_get(pokemon, "appearThisTurn", False))
        and not tuple(_pcrd_get(pokemon, "preEvolution", ()) or ())
        for pokemon in _pcrd_board_pokemon(my_state(obs))
    )
    alloy_in_hand = any(
        _pcrd_get(card, "id") == ARCHALUDON_EX
        for card in tuple(my_state(obs).hand or ())
        if card is not None and _pcrd_serial(card) != metal_serial
    )
    return bool(eligible_duraludon and alloy_in_hand)


def _eadp_cinderace_role_dead(obs, card):
    if (
        _pcrd_get(card, "id") != CINDERACE
        or obs.current.turn <= 1
        or _pcrd_get(CARD_DB.get(CINDERACE), "basic", False)
    ):
        return False
    serial = _pcrd_serial(card)
    for option in obs.select.option:
        option_card_value = option_card(obs, option)
        if (
            _pcrd_serial(option_card_value) == serial
            and option.type in (OptionType.PLAY, OptionType.EVOLVE)
        ):
            return False
    evolves_from = _pcrd_get(CARD_DB.get(CINDERACE), "evolvesFrom")
    if evolves_from and any(
        _pcrd_get(CARD_DB.get(_pcrd_get(pokemon, "id")), "name")
        == evolves_from
        for pokemon in _pcrd_board_pokemon(my_state(obs))
    ):
        return False
    return True


def _eadp_ultra_cost_proof(obs, card):
    card_id = _pcrd_get(card, "id")
    serial = _pcrd_serial(card)
    if card_id == METAL_ENERGY and _eadp_metal_recovery_route(obs, serial):
        return "DISCARD_TO_PUBLIC_ASSEMBLE_ALLOY_RECOVERY"
    if card_id == CINDERACE and _eadp_cinderace_role_dead(obs, card):
        return "POST_SETUP_UNPLAYABLE_CINDERACE_COPY"
    return None


def _eadp_ultra_preflight(obs, ultra_serial):
    proofs = {}
    for card in tuple(my_state(obs).hand or ()):
        serial = _pcrd_serial(card)
        if card is None or serial is None or serial == ultra_serial:
            continue
        proof = _eadp_ultra_cost_proof(obs, card)
        if proof is not None:
            proofs[serial] = proof
    return proofs if len(proofs) >= 2 else None


def _eadp_projected_saved_attack(obs, *, source=None, stadium=None):
    saved = _eadp_deadline["attack"]
    projected_obs = copy.deepcopy(obs)
    if stadium is not None:
        projected_obs.current.stadium[:] = [copy.deepcopy(stadium)]
    projected_source = source
    if projected_source is None:
        projected_source = active_pokemon(projected_obs)
    projected_target = opp_active_pokemon(projected_obs)
    payment = _pcrd_attack_payment(
        projected_source, ALL_ATTACKS.get(saved["attack_id"])
    )
    combat = _pfgear_attack_certificate(
        projected_obs,
        projected_source,
        saved["attack_id"],
        projected_target,
    )
    if payment is None or combat is None:
        return None
    return {
        "attacker_serial": _pcrd_serial(projected_source),
        "target_serial": _pcrd_serial(projected_target),
        "attack_id": saved["attack_id"],
        "payment": tuple(payment),
        "combat": combat,
    }


def _eadp_evolution_safe(obs, evolution, target):
    if (
        _pcrd_get(evolution, "id") != ARCHALUDON_EX
        or _pcrd_get(target, "id") != DURALUDON
        or _pcrd_serial(evolution) is None
        or _pcrd_serial(target) is None
        or _pcrd_serial(target) == _eadp_deadline["attack"]["attacker_serial"]
        or bool(_pcrd_get(target, "appearThisTurn", False))
        or tuple(_pcrd_get(target, "preEvolution", ()) or ())
        or not _pcrd_static_metadata_supported()
        or not _dper_effect_admitted("ASSEMBLE_ALLOY", ARCHALUDON_EX)
    ):
        return False
    return _pcrd_evolve_projection(target, evolution) is not None


def _eadp_classify_parent_action(obs, parent_action):
    if not _cum_valid_action(obs, parent_action) or len(parent_action) != 1:
        return None, "unknown"
    option = obs.select.option[parent_action[0]]
    if option.type == OptionType.ATTACK:
        return None, "attack"
    if option.type == OptionType.END:
        return None, "end"
    if option.type == OptionType.RETREAT:
        return None, "unsafe"
    card = option_card(obs, option)
    target = option_target(obs, option)
    card_id = _pcrd_get(card, "id")
    card_serial = _pcrd_serial(card)
    target_serial = _pcrd_serial(target)
    roles = _pcrd_action_roles(obs, parent_action)
    if roles is None or card_serial is None:
        return None, "unknown"
    certificate = {
        "roles": tuple(roles),
        "card_id": card_id,
        "card_serial": card_serial,
        "target_serial": target_serial,
        "before": _eadp_public_snapshot(obs),
    }
    if option.type == OptionType.EVOLVE:
        if not _eadp_evolution_safe(obs, card, target):
            return None, "unsafe"
        certificate.update(
            {
                "kind": "evolve",
                "multi": True,
                "evolution_source_serial": target_serial,
            }
        )
        return certificate, None
    if option.type == OptionType.PLAY and card_id in _EADP_SEARCH_TRAINERS:
        if not _eadp_exact_trainer(card_id):
            return None, "unknown"
        if card_id == ULTRA_BALL:
            cost_proofs = _eadp_ultra_preflight(obs, card_serial)
            if cost_proofs is None:
                return None, "unsafe"
            certificate["ultra_safe_costs"] = cost_proofs
        certificate.update({"kind": "trainer", "multi": True})
        return certificate, None
    if option.type == OptionType.PLAY and card_id == JUMBO_ICE_CREAM:
        active = active_pokemon(obs)
        projected_source = _pcrd_ice_projection(active)
        projected_attack = (
            None
            if projected_source is None
            else _eadp_projected_saved_attack(obs, source=projected_source)
        )
        if not (
            _pcrd_exact_trainer(
                JUMBO_ICE_CREAM, "Jumbo Ice Cream", _PCRD_ICE_TEXT
            )
            and projected_attack is not None
            and _eadp_attack_nonworse(
                _eadp_deadline["attack"], projected_attack
            )
        ):
            return None, "unsafe"
        certificate.update(
            {
                "kind": "heal",
                "multi": False,
                "target_serial": _pcrd_serial(active),
                "hp_before": _pcrd_get(active, "hp"),
            }
        )
        return certificate, None
    if option.type == OptionType.PLAY and card_id == FULL_METAL_LAB:
        projected_attack = _eadp_projected_saved_attack(
            obs, stadium=card
        )
        if not (
            _dper_effect_admitted("FULL_METAL_LAB", FULL_METAL_LAB)
            and _pcrd_exact_trainer(
                FULL_METAL_LAB, "Full Metal Lab", _PCRD_FML_TEXT
            )
            and any(
                _pcrd_int(
                    _pcrd_get(CARD_DB.get(_pcrd_get(pokemon, "id")), "energyType")
                )
                == METAL_ENERGY
                for pokemon in _pcrd_board_pokemon(my_state(obs))
            )
            and projected_attack is not None
            and _eadp_attack_nonworse(
                _eadp_deadline["attack"], projected_attack
            )
        ):
            return None, "unsafe"
        certificate.update({"kind": "stadium", "multi": False})
        return certificate, None
    if option.type == OptionType.PLAY and _eadp_basic_productive(obs, card):
        certificate.update({"kind": "basic", "multi": False})
        return certificate, None
    if option.type == OptionType.ATTACH and card_id == METAL_ENERGY:
        pokemon = _eadp_find_own_pokemon(obs, target_serial)
        projected = _pcrd_add_energy_projection(pokemon, card)
        before_profile = _eadp_missing_profile(pokemon)
        after_profile = _eadp_missing_profile(projected)
        saved_attack_id = _eadp_deadline["attack"]["attack_id"]
        another_attack_improved = any(
            before_id == after_id
            and before_id != saved_attack_id
            and before_missing > after_missing
            for before_id, before_missing in before_profile
            for after_id, after_missing in after_profile
        )
        current_projection = (
            None
            if target_serial != _eadp_deadline["attack"]["attacker_serial"]
            else _eadp_projected_saved_attack(obs, source=projected)
        )
        if (
            pokemon is None
            or projected is None
            or not (
                (
                    target_serial
                    == _eadp_deadline["attack"]["attacker_serial"]
                    and another_attack_improved
                    and current_projection is not None
                    and _eadp_attack_nonworse(
                        _eadp_deadline["attack"], current_projection
                    )
                )
                or (
                    target_serial
                    != _eadp_deadline["attack"]["attacker_serial"]
                    and any(
                        before_id == after_id
                        and before_missing > after_missing
                        for before_id, before_missing in before_profile
                        for after_id, after_missing in after_profile
                    )
                )
            )
        ):
            return None, "unsafe"
        certificate.update({"kind": "attach", "multi": False})
        return certificate, None
    if option.type == OptionType.ATTACH and card_id == HERO_CAPE:
        pokemon = _eadp_find_own_pokemon(obs, target_serial)
        if not (
            _pcrd_exact_trainer(
                HERO_CAPE, "Hero's Cape", _PCRD_CAPE_TEXT, ace_spec=True
            )
            and _pcrd_cape_projection(pokemon, card) is not None
        ):
            return None, "unsafe"
        certificate.update({"kind": "tool", "multi": False})
        return certificate, None
    return None, "unknown"


def _eadp_postcondition(obs, productive):
    kind = productive.get("kind")
    card_serial = productive.get("card_serial")
    target_serial = productive.get("target_serial")
    if kind == "basic":
        return bool(
            _eadp_card_absent_from_hand(obs, card_serial)
            and any(
                _pcrd_serial(card) == card_serial
                for card in tuple(my_state(obs).bench or ())
                if card is not None
            )
        )
    if kind == "attach":
        return _eadp_attachment_owner(obs, card_serial) == target_serial
    if kind == "tool":
        return (
            _eadp_attachment_owner(obs, card_serial, tool=True)
            == target_serial
        )
    if kind == "heal":
        active = active_pokemon(obs)
        return bool(
            _pcrd_serial(active) == target_serial
            and isinstance(_pcrd_get(active, "hp"), int)
            and _pcrd_get(active, "hp") > productive.get("hp_before", 0)
            and _eadp_card_absent_from_hand(obs, card_serial)
        )
    if kind == "stadium":
        return any(
            _pcrd_serial(card) == card_serial
            and _pcrd_get(card, "id") == FULL_METAL_LAB
            for card in tuple(obs.current.stadium or ())
            if card is not None
        )
    if kind == "trainer":
        return _eadp_card_absent_from_hand(obs, card_serial)
    if kind == "evolve":
        pokemon = _eadp_find_own_pokemon(obs, card_serial)
        return bool(
            pokemon is not None
            and _pcrd_get(pokemon, "id") == ARCHALUDON_EX
            and any(
                _pcrd_serial(card) == productive.get("evolution_source_serial")
                for card in tuple(_pcrd_get(pokemon, "preEvolution", ()) or ())
            )
            and _eadp_card_absent_from_hand(obs, card_serial)
        )
    return False


def _eadp_callback_safe_action(obs, parent_action):
    effect_id = _pcrd_get(obs.select.effect, "id")
    productive = ((_eadp_deadline or {}).get("productive") or {})
    if productive.get("kind") == "evolve":
        if not _cum_valid_action(obs, parent_action):
            return None, "invalid_evolution_callback"
        if (
            effect_id == ARCHALUDON_EX
            and _pcrd_get(obs.select.contextCard, "id") == METAL_ENERGY
        ):
            attacker_serial = _eadp_deadline["attack"]["attacker_serial"]
            energy = obs.select.contextCard
            for position in parent_action:
                target = option_target(obs, obs.select.option[position])
                if _pcrd_serial(target) != attacker_serial:
                    continue
                projected = _pcrd_add_energy_projection(target, energy)
                projected_attack = (
                    None
                    if projected is None
                    else _eadp_projected_saved_attack(obs, source=projected)
                )
                if (
                    projected_attack is None
                    or not _eadp_attack_nonworse(
                        _eadp_deadline["attack"], projected_attack
                    )
                ):
                    return None, "unsafe_alloy_target"
            return parent_action, None
        if effect_id == ARCHALUDON_EX:
            selected_cards = [
                option_card(obs, obs.select.option[position])
                for position in parent_action
            ]
            if all(
                card is None or _pcrd_get(card, "id") == METAL_ENERGY
                for card in selected_cards
            ):
                return parent_action, None
            if obs.select.minCount == 0:
                _eadp_counters["callback_safe_cancels"] += 1
                return [], "cancel"
            return None, "unsafe_alloy_energy"
        if (
            _pcrd_get(obs.select.contextCard, "id") == ARCHALUDON_EX
            and all(
                obs.select.option[position].type
                not in {
                    OptionType.ATTACK,
                    OptionType.END,
                    OptionType.EVOLVE,
                    OptionType.RETREAT,
                }
                for position in parent_action
            )
        ):
            return parent_action, None
        if obs.select.minCount == 0:
            _eadp_counters["callback_safe_cancels"] += 1
            return [], "cancel"
        return None, "unknown_evolution_callback"
    if effect_id not in _EADP_SEARCH_TRAINERS:
        if obs.select.minCount == 0:
            _eadp_counters["callback_safe_cancels"] += 1
            return [], "cancel"
        return None, "unsupported_callback"
    if effect_id == ULTRA_BALL and obs.select.minCount == 2:
        allowed_serials = set(
            ((_eadp_deadline or {}).get("productive") or {}).get(
                "ultra_safe_costs", {}
            )
        )
        selected = [
            option_card(obs, obs.select.option[position])
            for position in parent_action
        ]
        if (
            len(selected) == 2
            and all(
                card is not None
                and _pcrd_serial(card) in allowed_serials
                for card in selected
            )
        ):
            return parent_action, None
        safe_positions = [
            position
            for position, option in enumerate(obs.select.option)
            if (
                (card := option_card(obs, option)) is not None
                and _pcrd_serial(card) in allowed_serials
            )
        ]
        safe_positions.sort(
            key=lambda position: repr(
                _pcrd_option_role(obs, obs.select.option[position])
            )
        )
        substitute = safe_positions[:2]
        if _cum_valid_action(obs, substitute):
            _eadp_counters["callback_safe_substitutions"] += 1
            return substitute, "substitution"
        if obs.select.minCount == 0:
            _eadp_counters["callback_safe_cancels"] += 1
            return [], "cancel"
        return None, "no_safe_ultra_cost"
    if _cum_valid_action(obs, parent_action):
        forbidden = {
            OptionType.ATTACK,
            OptionType.END,
            OptionType.EVOLVE,
            OptionType.RETREAT,
        }
        if all(
            obs.select.option[position].type not in forbidden
            for position in parent_action
        ):
            return parent_action, None
    if obs.select.minCount == 0:
        _eadp_counters["callback_safe_cancels"] += 1
        return [], "cancel"
    return None, "unsafe_callback_action"


def _eadp_callback_key(obs, owner_before):
    return (
        globals().get("_cum_game_epoch"),
        obs.current.yourIndex,
        obs.current.turn,
        _pcrd_int(obs.select.context),
        _pfgear_card_ref(obs.select.effect),
        _pfgear_card_ref(obs.select.contextCard),
        _pfgear_option_multiset(obs),
        _eadp_owner_records(owner_before),
    )


def _eadp_emit(obs, action, source, owner_before):
    deadline = _eadp_deadline
    roles = _pcrd_action_roles(obs, action)
    if deadline is not None and roles is not None:
        deadline["last_key"] = _eadp_callback_key(obs, owner_before)
        deadline["last_roles"] = tuple(roles)
        deadline["last_source"] = source
    return action


def _eadp_begin(obs, attack):
    global _eadp_deadline
    _eadp_deadline = {
        "rule_id": _EADP_RULE_ID,
        "state": "DEADLINE_READY",
        "epoch": globals().get("_cum_game_epoch"),
        "seat": obs.current.yourIndex,
        "turn": obs.current.turn,
        "attack": copy.deepcopy(attack),
        "start_snapshot": _eadp_public_snapshot(obs),
        "fingerprints": set(),
        "productive": None,
        "suspended_owner": None,
        "last_key": None,
        "last_roles": None,
        "last_source": None,
        "duplicate_keys": set(),
    }
    _eadp_counters["deadline_locks"] += 1


def _eadp_emit_attack(obs, reason, owner_before):
    deadline = _eadp_deadline
    current = _eadp_reprove_attack(obs)
    if current is None:
        _eadp_finalize(
            "saved_attack_reproof_failed:" + reason,
            actual_fallback=True,
        )
        return None
    action = _pcrd_bind_roles(obs, (deadline["attack"]["role"],))
    if action is None:
        _eadp_counters["attack_reproof_fail"] += 1
        _eadp_finalize(
            "saved_attack_semantic_rebind_failed:" + reason,
            actual_fallback=True,
        )
        return None
    deadline["state"] = "ATTACK_EMITTED"
    deadline["productive"] = None
    deadline["suspended_owner"] = None
    _eadp_counters["attacks_emitted"] += 1
    return _eadp_emit(obs, action, "SAVED_ATTACK:" + reason, owner_before)


def _eadp_allow_productive(
    obs, parent_action, productive, owner_before, owner_after
):
    deadline = _eadp_deadline
    fingerprint = _pfgear_hash(
        (productive["kind"], tuple(productive["roles"]))
    )
    if fingerprint in deadline["fingerprints"]:
        return None, "repeat_fingerprint"
    after_records = _eadp_owner_records(owner_after)
    before_records = _eadp_owner_records(owner_before)
    new_records = tuple(row for row in after_records if row not in before_records)
    if len(after_records) > 1 or len(new_records) > 1:
        _eadp_counters["owner_collisions"] += 1
        return None, "owner_collision"
    deadline["fingerprints"].add(fingerprint)
    deadline["productive"] = copy.deepcopy(productive)
    deadline["suspended_owner"] = (
        copy.deepcopy(new_records[0]) if new_records else None
    )
    if new_records:
        _eadp_counters["owner_suspensions"] += 1
    if productive["multi"]:
        deadline["state"] = "PARENT_SUBTX_ACTIVE"
        _eadp_counters["parent_subtx_starts"] += 1
    else:
        deadline["state"] = "AWAIT_POSTCONDITION"
    _eadp_counters["safe_prefix_allowed_" + productive["kind"]] += 1
    return _eadp_emit(
        obs, parent_action, "PRODUCTIVE:" + productive["kind"], owner_before
    ), None


def _eadp_duplicate_action(obs, owner_before):
    deadline = _eadp_deadline
    if deadline is None or deadline.get("last_key") is None:
        return None
    key = _eadp_callback_key(obs, owner_before)
    if key != deadline["last_key"]:
        return None
    action = _pcrd_bind_roles(obs, deadline.get("last_roles"))
    if action is None:
        return None
    if key not in deadline["duplicate_keys"]:
        deadline["duplicate_keys"].add(key)
        _eadp_counters["duplicates"] += 1
    return action


def _eadp_release_class(obs, parent_action):
    if not _cum_valid_action(obs, parent_action) or len(parent_action) != 1:
        return "UNKNOWN"
    option = obs.select.option[parent_action[0]]
    if option.type == OptionType.RETREAT:
        return "RETREAT"
    card = option_card(obs, option)
    target = option_target(obs, option)
    if option.type == OptionType.PLAY and _pcrd_get(card, "id") == ULTRA_BALL:
        return "ULTRA_UNPROVED"
    if (
        option.type == OptionType.EVOLVE
        and _pcrd_serial(target)
        == _eadp_deadline["attack"]["attacker_serial"]
    ):
        return "SAVED_ATTACKER_EVOLVE"
    return "UNKNOWN"


def _eadp_release_to_parent(parent_action, owner_after, release_class):
    deadline = _eadp_deadline
    prefix_count = len((deadline or {}).get("fingerprints", ()))
    _eadp_counters["deadline_releases"] += 1
    release_counter = {
        "RETREAT": "deadline_release_retreat",
        "ULTRA_UNPROVED": "deadline_release_ultra_unproved",
        "SAVED_ATTACKER_EVOLVE": (
            "deadline_release_saved_attacker_evolve"
        ),
    }.get(release_class, "deadline_release_unknown")
    _eadp_counters[release_counter] += 1
    if prefix_count:
        _eadp_counters["release_after_prefix_count"] += 1
    _eadp_finalize(
        "RELEASED_TO_PARENT_" + release_class,
        released=True,
    )
    if _eadp_freeze(_eadp_owner_snapshot()) == _eadp_freeze(owner_after):
        _eadp_counters["parent_owner_preserved_on_release"] += 1
    else:
        _eadp_counters["invariant_breaches"] += 1
    return parent_action, "PARENT_RELEASE_" + release_class


def _eadp_parent_attack_row(obs, parent_action):
    if not _cum_valid_action(obs, parent_action) or len(parent_action) != 1:
        return None
    option = obs.select.option[parent_action[0]]
    if option.type != OptionType.ATTACK:
        return None
    role = _pcrd_option_role(obs, option)
    matches = tuple(row for row in _eadp_attack_rows(obs) if row["role"] == role)
    if len(matches) != 1:
        return None
    row = copy.deepcopy(matches[0])
    row["remaining_prizes"] = len(tuple(my_state(obs).prize or ()))
    row["terminal"] = bool(
        row["combat"].get("prize_yield", 0) >= row["remaining_prizes"]
        or (
            row["combat"].get("ko")
            and not tuple(
                card
                for card in tuple(opp_state(obs).bench or ())
                if card is not None
            )
        )
    )
    return row


def _eadp_attack_outcome_vector(row):
    combat = (row or {}).get("combat") or {}
    if (
        combat.get("status") != "EXACT"
        or tuple(combat.get("unsupported_text", ()))
        or not isinstance(combat.get("final_damage"), int)
        or not isinstance(combat.get("prize_yield"), int)
        or not isinstance(combat.get("ko"), bool)
        or not isinstance(combat.get("persistent_progress"), bool)
        or not isinstance(row.get("terminal"), bool)
    ):
        return None
    return (
        int(row["terminal"]),
        combat["prize_yield"],
        int(combat["ko"]),
        combat["final_damage"],
        int(combat["persistent_progress"]),
    )


def _eadp_compare_alternative_attack(saved, parent):
    if saved is None or parent is None:
        return "UNKNOWN"
    if parent.get("role") == saved.get("role"):
        return "SAME"
    saved_combat = saved.get("combat") or {}
    parent_combat = parent.get("combat") or {}
    saved_vector = _eadp_attack_outcome_vector(saved)
    parent_vector = _eadp_attack_outcome_vector(parent)
    if (
        saved_vector is None
        or parent_vector is None
        or saved.get("attacker_serial") != parent.get("attacker_serial")
        or saved.get("target_serial") != parent.get("target_serial")
        or saved_combat.get("source_id") != parent_combat.get("source_id")
        or saved_combat.get("target_id") != parent_combat.get("target_id")
    ):
        return "UNKNOWN"
    if parent["terminal"]:
        return "PARENT_DOMINATES"
    exact_resource_fields = (
        "persistent_effects",
        "post_attack_resource_ledger",
        "post_reply_resource_ledger",
        "bench_components",
        "target_attack_effects_prevented",
        "run_away_draw_executable",
        "next_payable_attack",
        "next_payable_attack_ids",
        "exact_backup_conversion",
        "saved_callback_transaction",
        "post_damage_counter_return",
        "attacker_survival",
        "exact_public_reply_routes",
    )
    if any(
        field not in saved_combat
        or field not in parent_combat
        or _eadp_freeze(saved_combat[field])
        != _eadp_freeze(parent_combat[field])
        for field in exact_resource_fields
    ) or tuple(saved_combat.get("assumptions", ())) != tuple(
        parent_combat.get("assumptions", ())
    ):
        return "INCOMPARABLE"
    saved_nonworse = all(
        saved_value >= parent_value
        for saved_value, parent_value in zip(saved_vector, parent_vector)
    )
    parent_nonworse = all(
        parent_value >= saved_value
        for saved_value, parent_value in zip(saved_vector, parent_vector)
    )
    if saved_nonworse and saved_vector != parent_vector:
        return "SAVED_DOMINATES"
    if parent_nonworse and saved_vector != parent_vector:
        return "PARENT_DOMINATES"
    return "INCOMPARABLE"


def _eadp_accept_same_parent_attack(obs, parent_action, owner_after):
    deadline = _eadp_deadline
    deadline["state"] = "ATTACK_EMITTED"
    deadline["productive"] = None
    deadline["suspended_owner"] = None
    _eadp_counters["attacks_emitted"] += 1
    return _eadp_emit(
        obs, parent_action, "PARENT_SAME_SAVED_ATTACK", owner_after
    )


def _eadp_arbitrate_main(
    obs, parent_action, owner_before, owner_after, *, just_locked=False
):
    deadline = _eadp_deadline
    saved_current = _eadp_reprove_attack(obs)
    if saved_current is None:
        return _eadp_release_to_parent(
            parent_action, owner_after, "UNKNOWN"
        )
    if deadline["attack"]["terminal"]:
        _eadp_restore_overridden_owners(owner_before, owner_after)
        action = _eadp_emit_attack(obs, "terminal", owner_before)
        if action is not None:
            if just_locked:
                _eadp_counters["terminal_attacks_immediate"] += 1
            return action, "TERMINAL_ATTACK_IMMEDIATE"
        return parent_action, "DIRECT_PARENT_ACTUAL_STATE_FALLBACK"
    productive, rejection = _eadp_classify_parent_action(obs, parent_action)
    reason = rejection
    if reason == "attack":
        parent_attack = _eadp_parent_attack_row(obs, parent_action)
        comparison = _eadp_compare_alternative_attack(
            saved_current, parent_attack
        )
        if comparison == "SAME":
            _eadp_counters["alternative_attack_same"] += 1
            return (
                _eadp_accept_same_parent_attack(
                    obs, parent_action, owner_after
                ),
                "PARENT_SAME_SAVED_ATTACK",
            )
        if comparison == "SAVED_DOMINATES":
            _eadp_counters["alternative_attack_saved_dominates"] += 1
            _eadp_counters["forced_attack_on_dominated_attack"] += 1
            _eadp_restore_overridden_owners(owner_before, owner_after)
            action = _eadp_emit_attack(
                obs, "strictly_dominated_alternative_attack", owner_before
            )
            if action is not None:
                return action, "FORCED_SAVED_ATTACK"
            return parent_action, "DIRECT_PARENT_ACTUAL_STATE_FALLBACK"
        alternative_counter = {
            "PARENT_DOMINATES": "alternative_attack_parent_dominates",
            "INCOMPARABLE": "alternative_attack_incomparable",
            "UNKNOWN": "alternative_attack_unknown",
        }.get(comparison, "alternative_attack_unknown")
        _eadp_counters[alternative_counter] += 1
        return _eadp_release_to_parent(
            parent_action,
            owner_after,
            "ALTERNATIVE_ATTACK_" + comparison,
        )
    if len(deadline["fingerprints"]) >= _EADP_MAX_PREFIXES:
        reason = "cap"
    elif productive is not None:
        fingerprint = _pfgear_hash(
            (productive["kind"], tuple(productive["roles"]))
        )
        if fingerprint in deadline["fingerprints"]:
            reason = "cap"
        else:
            action, allow_reason = _eadp_allow_productive(
                obs, parent_action, productive, owner_before, owner_after
            )
            if action is not None:
                return action, "PRODUCTIVE_PREFIX"
            reason = "unsafe" if allow_reason == "owner_collision" else "cap"
    if reason not in {"end", "cap"}:
        return _eadp_release_to_parent(
            parent_action,
            owner_after,
            _eadp_release_class(obs, parent_action),
        )
    counter = {
        "end": "forced_attack_on_end",
        "cap": "forced_attack_on_cap",
    }[reason]
    _eadp_counters[counter] += 1
    _eadp_restore_overridden_owners(owner_before, owner_after)
    action = _eadp_emit_attack(obs, reason or "unknown", owner_before)
    if action is None:
        return parent_action, "DIRECT_PARENT_ACTUAL_STATE_FALLBACK"
    return action, "FORCED_SAVED_ATTACK"


def _eadp_resume(
    obs, parent_action, owner_before, owner_after
):
    deadline = _eadp_deadline
    if deadline is None:
        return None, None
    duplicate = _eadp_duplicate_action(obs, owner_before)
    if duplicate is not None:
        return duplicate, "DUPLICATE_SEMANTIC_REBIND"
    if deadline["state"] == "ATTACK_EMITTED":
        if _eadp_attack_logged(obs, deadline):
            _eadp_finalize("saved_attack_confirmed", confirmed=True)
            return parent_action, "ATTACK_CONFIRMED"
        _eadp_counters["stale"] += 1
        _eadp_finalize("attack_emission_not_confirmed", actual_fallback=True)
        return parent_action, "DIRECT_PARENT_ACTUAL_STATE_FALLBACK"
    if (
        obs.current.yourIndex != deadline["seat"]
        or obs.current.turn != deadline["turn"]
        or globals().get("_cum_game_epoch") != deadline["epoch"]
        or obs.current.result != -1
    ):
        _eadp_counters["stale"] += 1
        _eadp_finalize("deadline_epoch_seat_turn_stale", actual_fallback=True)
        return parent_action, "DIRECT_PARENT_ACTUAL_STATE_FALLBACK"
    if deadline["state"] == "PARENT_SUBTX_ACTIVE":
        if obs.select.context != SelectContext.MAIN:
            before_records = _eadp_owner_records(owner_before)
            after_records = _eadp_owner_records(owner_after)
            suspended = deadline.get("suspended_owner")
            if (
                len(before_records) > 1
                or len(after_records) > 1
                or (
                    suspended is not None
                    and before_records
                    and suspended not in before_records
                )
            ):
                _eadp_counters["owner_collisions"] += 1
                _eadp_counters["invariant_breaches"] += 1
                return _eadp_release_to_parent(
                    parent_action, owner_after, "UNKNOWN"
                )
            callback, callback_reason = _eadp_callback_safe_action(
                obs, parent_action
            )
            if callback is None:
                return _eadp_release_to_parent(
                    parent_action, owner_after, "UNKNOWN"
                )
            _eadp_counters["parent_subtx_callbacks"] += 1
            return (
                _eadp_emit(
                    obs,
                    callback,
                    "PARENT_SUBTX_CALLBACK",
                    owner_before,
                ),
                "PARENT_SUBTX_CALLBACK",
            )
        if not _eadp_postcondition(obs, deadline["productive"]):
            _eadp_counters["postcondition_reproof_fail"] += 1
            return _eadp_release_to_parent(
                parent_action, owner_after, "UNKNOWN"
            )
        _eadp_counters["postcondition_reproof_pass"] += 1
        _eadp_counters["parent_subtx_completes"] += 1
        deadline["state"] = "DEADLINE_READY"
        deadline["productive"] = None
        deadline["suspended_owner"] = None
        if _eadp_reprove_attack(obs) is None:
            return _eadp_release_to_parent(
                parent_action, owner_after, "UNKNOWN"
            )
        return _eadp_arbitrate_main(
            obs, parent_action, owner_before, owner_after
        )
    if deadline["state"] == "AWAIT_POSTCONDITION":
        if (
            obs.select.context != SelectContext.MAIN
            or not _eadp_postcondition(obs, deadline["productive"])
        ):
            _eadp_counters["postcondition_reproof_fail"] += 1
            return _eadp_release_to_parent(
                parent_action, owner_after, "UNKNOWN"
            )
        _eadp_counters["postcondition_reproof_pass"] += 1
        deadline["state"] = "DEADLINE_READY"
        deadline["productive"] = None
        if _eadp_reprove_attack(obs) is None:
            return _eadp_release_to_parent(
                parent_action, owner_after, "UNKNOWN"
            )
        return _eadp_arbitrate_main(
            obs, parent_action, owner_before, owner_after
        )
    if deadline["state"] == "DEADLINE_READY":
        if obs.select.context != SelectContext.MAIN:
            return _eadp_release_to_parent(
                parent_action, owner_after, "UNKNOWN"
            )
        return _eadp_arbitrate_main(
            obs, parent_action, owner_before, owner_after
        )
    return _eadp_release_to_parent(parent_action, owner_after, "UNKNOWN")


def agent(obs_dict):
    """Call the exact direct parent once, then enforce the saved deadline."""
    global _eadp_parent_call_count
    owner_before = _eadp_owner_snapshot()
    parent_action = _eadp_parent_agent(obs_dict)
    _eadp_parent_call_count += 1
    _eadp_counters["direct_parent_calls"] += 1
    owner_after = _eadp_owner_snapshot()
    selected = parent_action
    selected_source = "DIRECT_PARENT"
    rejection_reason = None
    obs = None
    try:
        obs = to_observation_class(obs_dict)
        if obs.select is None or obs.current is None:
            if _eadp_deadline is not None:
                _eadp_finalize(
                    "deck_request_or_missing_current", actual_fallback=True
                )
            _eadp_update_telemetry(
                "DIRECT_PARENT", "deck_request_or_missing_current"
            )
            return parent_action
        _eadp_observe_explorer_resolution(obs)
        if not _cum_valid_action(obs, parent_action):
            _eadp_counters["invalid_actions"] += 1
            if _eadp_deadline is not None:
                _eadp_finalize("invalid_parent_action", actual_fallback=True)
            emergency = _cum_emergency_action(obs)
            _eadp_update_telemetry(
                "PARENT_EMERGENCY", "invalid_parent_action"
            )
            return emergency
        if _eadp_deadline is not None:
            selected, transition = _eadp_resume(
                obs, parent_action, owner_before, owner_after
            )
            selected_source = transition or "DIRECT_PARENT"
        elif (
            obs.current.result == -1
            and obs.select.context == SelectContext.MAIN
            and _eadp_explorer_resolved_this_turn(obs)
            and (attack := _eadp_exact_attack(obs)) is not None
        ):
            _eadp_begin(obs, attack)
            selected, selected_source = _eadp_arbitrate_main(
                obs,
                parent_action,
                owner_before,
                owner_after,
                just_locked=True,
            )
        if not _cum_valid_action(obs, selected):
            _eadp_counters["invalid_actions"] += 1
            if _eadp_deadline is not None:
                _eadp_finalize(
                    "invalid_candidate_action", actual_fallback=True
                )
            selected = parent_action
            selected_source = "DIRECT_PARENT_INVALID_OVERRIDE_FALLBACK"
            rejection_reason = "invalid_candidate_action"
    except Exception as error:
        _eadp_counters["exceptions"] += 1
        rejection_reason = type(error).__name__ + ":" + str(error)
        if _eadp_deadline is not None:
            _eadp_finalize(
                "exception:" + type(error).__name__, actual_fallback=True
            )
        selected = parent_action
        selected_source = "DIRECT_PARENT_EXCEPTION_FALLBACK"
    _eadp_update_telemetry(selected_source, rejection_reason)
    return selected
